    def ensure_actor_content_pack(
        pack_id: str,
        version: str,
        builder: Callable[[Path], list[dict[str, Any]]],
        source: str,
        *,
        title: str,
        edition: str,
    ) -> None:
        """Install bundled actor-card.v3 values as one preset package."""

        if not config.dnd_skills_dir.exists():
            return
        try:
            existing = rule_packs.get_version(pack_id, version)
            if existing.status == "installed":
                return
        except LookupError:
            pass
        actors = builder(config.dnd_skills_dir)
        if not actors:
            return
        package, _blobs = build_preset_content_package(
            package_id=pack_id,
            version=version,
            system_id=DND5E.id,
            title=title,
            cards=actors,
            metadata={
                "title": title,
                "edition": edition,
                "distribution": "shareable",
                "license": "CC-BY-4.0",
                "attribution": (
                    "Includes material from the Dungeons & Dragons System Reference "
                    "Document by Wizards of the Coast LLC, licensed under CC-BY-4.0."
                ),
                "content_kinds": ["npc", "monster"],
            },
        )
        manifest, artifacts = content_actor_catalog_definition(package)
        manifest["id"] = pack_id
        manifest["namespace"] = pack_id
        manifest["editions"] = [edition]
        result = rule_packs.save_draft(
            manifest=manifest,
            artifacts=artifacts,
            provenance={
                "source": source,
                "structured": True,
                "content_package_checksum": package["checksum"],
                "license": package["metadata"].get("license"),
                "attribution": package["metadata"].get("attribution"),
            },
        )
        if result.status == "validated":
            rule_packs.install(pack_id, version)

    ensure_core_content_pack()
    ensure_standard2014_content_pack()
    ensure_core2024_content_pack()
    ensure_actor_content_pack(
        SRD2014_PRESET_PACK_ID,
        SRD2014_PRESET_PACK_VERSION,
        build_srd2014_preset_actors,
        "bundled-srd2014-actor-presets",
        title="D&D 5e SRD 5.1 Actor Presets",
        edition="2014",
    )
    ensure_actor_content_pack(
        SRD2024_PRESET_PACK_ID,
        SRD2024_PRESET_PACK_VERSION,
        build_srd2024_preset_actors,
        "bundled-srd2024-actor-presets",
        title="D&D 5e SRD 5.2.1 Actor Presets",
        edition="2024",
    )

    def default_preset_actor_card(artifact_id: str) -> dict[str, Any]:
        """Resolve one installed bundled preset without requiring campaign activation."""

        identifier = str(artifact_id).strip()
        matches: list[dict[str, Any]] = []
        for pack in rule_packs.list_versions():
            if pack.status != "installed":
                continue
            for artifact in pack.artifacts:
                if str(artifact.get("id") or "") != identifier:
                    continue
                card = dict(artifact.get("card") or {})
                content_actor = dict(card.get("content_actor") or {})
                if content_actor:
                    matches.append(content_actor)
                    continue
        if len(matches) != 1:
            raise ValueError("artifact_id must resolve to exactly one installed actor preset")
        return validate_dnd_content_actor(matches[0])

    def refresh_portable_resolution_plans(value: Any) -> Any:
        """Re-fingerprint plans after stable/local source locators are remapped."""

        fingerprints: dict[str, str] = {}

        def refresh(item: Any) -> Any:
            if isinstance(item, list):
                return [refresh(child) for child in item]
            if not isinstance(item, dict):
                return deepcopy(item)
            if "resolution_solution" in item:
                raise ValueError(
                    "rule packs cannot carry campaign-compiled resolution_solution state"
                )
            result = {key: refresh(child) for key, child in item.items()}
            required_plan_fields = {
                "schema_version",
                "id",
                "source_card_id",
                "source_card_kind",
                "trigger",
                "steps",
                "citations",
            }
            if required_plan_fields.issubset(result):
                candidate = dict(result)
                candidate.pop("fingerprint", None)
                compiled = compile_resolution_plan(candidate)
                fingerprints[compiled.id] = compiled.fingerprint
                return resolution_plan_template(compiled)
            return result

        def refresh_references(item: Any, *, parent: str = "") -> Any:
            if isinstance(item, list):
                return [refresh_references(child, parent=parent) for child in item]
            if not isinstance(item, dict):
                return item
            if (
                parent == "resolution_plan"
                and set(item).issubset({"id", "fingerprint"})
                and str(item.get("id") or "") in fingerprints
            ):
                plan_id = str(item["id"])
                return {"id": plan_id, "fingerprint": fingerprints[plan_id]}
            return {key: refresh_references(child, parent=key) for key, child in item.items()}

        return refresh_references(refresh(value))

    def rule_content_descriptor(
        pack_id: str,
        version: str,
        *,
        metadata: dict[str, Any] | None = None,
        _dependency_stack: tuple[tuple[str, str], ...] = (),
    ) -> dict[str, Any]:
        """Export one rule definition with stable source locators for a v2 Pack."""

        identity = (pack_id, version)
        if identity in _dependency_stack:
            chain = " -> ".join(
                f"{item_id}@{item_version}"
                for item_id, item_version in (*_dependency_stack, identity)
            )
            raise ValueError(f"rule-pack dependency cycle is not portable: {chain}")
        dependency_stack = (*_dependency_stack, identity)
        pack = rule_packs.get_version(pack_id, version)
        provenance = rule_packs.provenance(pack_id, version)
        definition: dict[str, Any] = {
            "artifacts": [deepcopy(item) for item in pack.artifacts],
            "mechanics": [deepcopy(item) for item in pack.mechanics],
            "provenance": deepcopy(provenance),
        }
        definition["artifacts"] = _strip_artifact_authoring_state(definition["artifacts"])
        definition["provenance"].pop("import_job_id", None)
        source_ids: set[str] = set()
        chunk_ids: set[str] = set()
        uuid_pattern = re.compile(
            r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
            r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
        )
        rule_source_chunk_pattern = re.compile(rf"rule-source-chunk:({uuid_pattern.pattern})")

        def collect(item: Any, *, field: str = "") -> None:
            if isinstance(item, dict):
                for key, child in item.items():
                    if key == "source_id" and isinstance(child, str):
                        source_ids.add(child)
                    elif key == "chunk_id" and isinstance(child, str):
                        chunk_ids.add(child)
                    collect(child, field=key)
                return
            if isinstance(item, list):
                for child in item:
                    collect(child, field=field)
                return
            if isinstance(item, str):
                if field in {"rule_refs", "source_chunk_ids"}:
                    chunk_ids.update(uuid_pattern.findall(item))
                chunk_ids.update(rule_source_chunk_pattern.findall(item))

        collect(definition)
        for chunk_id in sorted(chunk_ids):
            try:
                source_ids.add(str(rules.expand(chunk_id)["source"]["id"]))
            except (LookupError, NoResultFound) as error:
                raise ValueError(
                    f"rule pack references unavailable source chunk {chunk_id}"
                ) from error

        source_exports: list[tuple[str, dict[str, Any]]] = []
        source_key_by_id: dict[str, str] = {}
        chunk_key_by_id: dict[str, str] = {}
        for source_id in source_ids:
            try:
                source = rules.export_indexed_source(source_id)
            except LookupError as error:
                raise ValueError(
                    f"rule pack references unavailable rule source {source_id}"
                ) from error
            source_exports.append((source_id, source))
        portable_sources: list[dict[str, Any]] = []
        for source_id, source in sorted(source_exports, key=lambda item: item[1]["source_key"]):
            portable_sources.append(source)
            source_key_by_id[source_id] = source["source_key"]
            portable_chunks = {
                (section["ordinal"], chunk["ordinal"]): chunk
                for section in source["sections"]
                for chunk in section["chunks"]
            }
            for local_chunk in rules.source_chunks(source_id):
                portable_chunk = portable_chunks.get(
                    (
                        local_chunk["section_ordinal"],
                        local_chunk["ordinal"],
                    )
                )
                if portable_chunk is None or portable_chunk["content"] != local_chunk["content"]:
                    raise ValueError("rule source changed while building its portable package")
                chunk_key_by_id[local_chunk["id"]] = portable_chunk["key"]

        def make_portable(item: Any) -> Any:
            if isinstance(item, list):
                return [make_portable(child) for child in item]
            if isinstance(item, str):
                if item in chunk_key_by_id:
                    return chunk_key_by_id[item]
                result = item
                for local_id, stable_key in chunk_key_by_id.items():
                    result = result.replace(f"#chunk:{local_id}", f"#chunk:{stable_key}")
                    result = result.replace(
                        f"rule-source-chunk:{local_id}",
                        f"rule-source-chunk:{stable_key}",
                    )
                return result
            if not isinstance(item, dict):
                return deepcopy(item)
            result = {
                key: make_portable(child)
                for key, child in item.items()
                if key not in {"source_id", "chunk_id"}
            }
            source_id = item.get("source_id")
            if source_id is not None:
                source_key = source_key_by_id.get(str(source_id))
                if source_key is None:
                    raise ValueError(f"rule pack source_id is not portable: {source_id}")
                if result.get("source_key") not in {None, source_key}:
                    raise ValueError("rule citation source_id/source_key mismatch")
                result["source_key"] = source_key
            chunk_id = item.get("chunk_id")
            if chunk_id is not None:
                chunk_key = chunk_key_by_id.get(str(chunk_id))
                if chunk_key is None:
                    raise ValueError(f"rule pack chunk_id is not portable: {chunk_id}")
                result["chunk_key"] = chunk_key
            return result

        def canonicalize_portable_evidence(
            item: Any,
            *,
            field: str = "",
            parent: str = "",
        ) -> Any:
            """Sort only evidence collections whose order has no semantics."""

            if isinstance(item, list):
                normalized = [
                    canonicalize_portable_evidence(
                        child,
                        field=field,
                        parent=parent,
                    )
                    for child in item
                ]
                if field in {"rule_refs", "source_chunk_ids"} or (
                    field == "references" and parent == "selection_contract"
                ):
                    return sorted(dict.fromkeys(str(child) for child in normalized))
                if field == "source_citations":
                    return sorted(
                        normalized,
                        key=lambda child: json.dumps(
                            child,
                            ensure_ascii=False,
                            sort_keys=True,
                            separators=(",", ":"),
                        ),
                    )
                return normalized
            if not isinstance(item, dict):
                return deepcopy(item)
            return {
                key: canonicalize_portable_evidence(
                    child,
                    field=key,
                    parent=field,
                )
                for key, child in item.items()
            }

        portable_definition = refresh_portable_resolution_plans(
            canonicalize_portable_evidence(make_portable(definition))
        )
        portable_definition["artifacts"] = _strip_artifact_authoring_state(
            list(portable_definition["artifacts"])
        )
        semantic_validation = audit_release_semantic_validation(
            list(portable_definition["artifacts"]),
            settled_mechanic_ids=_rule_payload_settled_mechanic_ids(
                {
                    "manifest": pack.manifest,
                    "mechanics": portable_definition["mechanics"],
                }
            ),
        )
        portable_manifest = deepcopy(pack.manifest)
        portable_manifest["resolution_policy"] = "compiled_or_agent"
        portable_manifest["semantic_validation"] = deepcopy(semantic_validation)
        package_dependencies: list[dict[str, Any]] = []
        pinned_dependencies: list[dict[str, Any]] = []
        for dependency in portable_manifest.get("dependencies", []):
            if not isinstance(dependency, dict) or not dependency.get("version"):
                raise ValueError("rule Pack dependencies must pin a version")
            dependency_id = str(dependency.get("id") or "")
            dependency_version = str(dependency.get("version") or "")
            dependency_pack = rule_packs.get_version(dependency_id, dependency_version)
            dependency_provenance = rule_packs.provenance(dependency_id, dependency_version)
            content_dependency = dict(dependency_provenance.get("content_definition") or {})
            stored_definition_checksum = str(content_dependency.get("definition_checksum") or "")
            dependency_descriptor = rule_content_descriptor(
                dependency_id,
                dependency_version,
                _dependency_stack=dependency_stack,
            )
            dependency_definition_checksum = content_definition_checksum(
                manifest=dependency_descriptor["manifest"],
                artifacts=dependency_descriptor["artifacts"],
                mechanics=dependency_descriptor["mechanics"],
            )
            if stored_definition_checksum:
                dependency_definition_checksum = stored_definition_checksum
            expected_checksum = str(dependency.get("checksum") or "")
            accepted_existing_checksums = {
                dependency_pack.checksum,
                dependency_definition_checksum,
                str(content_dependency.get("definition_checksum") or ""),
            }
            if expected_checksum and expected_checksum not in accepted_existing_checksums:
                raise ValueError(
                    f"rule dependency checksum mismatch for {dependency_id}@{dependency_version}"
                )
            pinned = {
                "id": dependency_id,
                "version": dependency_version,
                "checksum": dependency_definition_checksum,
            }
            pinned_dependencies.append(pinned)
            package_dependencies.append(
                {
                    "kind": "core_rules",
                    "id": dependency_id,
                    "version": dependency_version,
                    "checksum": dependency_definition_checksum,
                    "optional": False,
                }
            )
        portable_manifest["dependencies"] = pinned_dependencies
        requested_metadata = deepcopy(metadata or {})
        declared_license = str(
            requested_metadata.get("license")
            or provenance.get("license")
            or portable_manifest.get("license")
            or ""
        ).strip()
        package_metadata = {
            "title": str(portable_manifest.get("title") or pack_id),
            "license": declared_license or "user-supplied",
            "attribution": str(
                provenance.get("attribution") or portable_manifest.get("attribution") or ""
            ),
            "distribution": "private",
            **requested_metadata,
        }
        distribution = str(package_metadata.get("distribution") or "")
        if distribution not in {"private", "shareable"}:
            raise ValueError(
                "portable rule pack metadata.distribution must be private or shareable"
            )
        if distribution == "shareable" and (
            not declared_license
            or not str(package_metadata.get("license") or "").strip()
            or not str(package_metadata.get("attribution") or "").strip()
        ):
            raise ValueError("shareable rule packs require explicit license and attribution")
        return {
            "id": pack_id,
            "version": version,
            "system_id": DND5E.id,
            "manifest": portable_manifest,
            "artifacts": portable_definition["artifacts"],
            "mechanics": portable_definition["mechanics"],
            "provenance": portable_definition["provenance"],
            "sources": portable_sources,
            "metadata": package_metadata,
            "dependencies": package_dependencies,
        }

    def runtime_actor_with_portrait(
        actor: dict[str, Any],
        package: dict[str, Any],
        blobs: dict[str, bytes],
    ) -> dict[str, Any]:
        """Retain a package actor's immutable image as non-mechanical runtime notes."""

        value = deepcopy(actor)
        image = value.get("image")
        if not isinstance(image, dict):
            return value
        asset_key = str(image.get("asset_key") or "")
        assets = {
            str(item.get("asset_key") or ""): dict(item)
            for item in package.get("assets", [])
            if isinstance(item, dict)
        }
        asset = assets.get(asset_key)
        if asset is None or str(asset.get("kind") or "") != "actor_image":
            raise ValueError("content actor image does not resolve to an actor_image asset")
        checksum = str(asset.get("checksum") or "")
        content = blobs.get(checksum)
        if content is None:
            raise ValueError("content actor image blob is missing from its package")
        stored = storage.store_actor_image(asset, content)
        notes = deepcopy(dict(value.get("notes") or {}))
        profile = deepcopy(dict(notes.get("profile") or {}))
        profile["portrait_ref"] = {
            "asset_key": asset_key,
            "checksum": stored["checksum"],
            "media_type": stored["media_type"],
            "alt": str(image.get("alt") or f"{value.get('name') or 'Actor'} portrait"),
            "source": {
                "kind": "content_pack",
                "package_id": str(package["id"]),
                "package_version": str(package["version"]),
                "package_checksum": str(package["checksum"]),
            },
        }
        notes["profile"] = profile
        value["notes"] = validate_character_notes(
            notes,
            character_type=str(value.get("actor_type") or "") or None,
        )
        return value

    def import_content_module_package(
        campaign_id: str,
        package: dict[str, Any],
        blobs: dict[str, bytes],
        *,
        principal_id: str,
        idempotency_key: str,
        activate: bool,
        progress_remaps: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        """Import a unified module through module and character service boundaries."""

        normalized = validate_dnd_content_package(package)
        if normalized["system_id"] != DND5E.id or normalized["kind"] != "module":
            raise ValueError("content package must be a dnd5e module")
        campaign_edition = campaign_rules_edition(campaign_id)
        supported_editions = list(
            dict(normalized["content"].get("compatibility") or {}).get("editions") or []
        )
        if supported_editions and campaign_edition not in supported_editions:
            raise ValueError(f"module does not support campaign edition {campaign_edition}")
        validated_actors = [validate_dnd_content_actor(actor) for actor in normalized["actors"]]
        mismatched = [
            actor["id"]
            for actor in validated_actors
            if actor["sheet"]["edition"] != campaign_edition
        ]
        if mismatched:
            raise ValueError(
                "module actor cards do not match the campaign edition: " + ", ".join(mismatched)
            )
        managed_archive = storage.write_content_archive(normalized, blobs)
        assets_by_key = {str(item["asset_key"]): item for item in normalized["assets"]}
        result = modules.import_content_package(
            campaign_id,
            normalized,
            blobs,
            activate=False,
            asset_writer=storage.store_content_module_asset,
        )
        modules.register_asset(
            campaign_id=campaign_id,
            module_id=result["module_id"],
            source_path=str((config.content_packages_dir / managed_archive["artifact"]).resolve()),
            media_type="application/vnd.sagasmith.content-package+zip",
            checksum=str(managed_archive["archive_checksum"]),
            metadata={
                "asset_kind": "content_package_archive",
                "content_package_id": normalized["id"],
                "content_package_version": normalized["version"],
                "content_package_checksum": normalized["checksum"],
                "content_archive_artifact": managed_archive["artifact"],
            },
        )
        actor_map: dict[str, str] = {}
        binding_ids = []
        module_key = str(normalized["sources"][0]["source_key"])
        for source_actor in validated_actors:
            actor = runtime_actor_with_portrait(source_actor, normalized, blobs)
            bindings = list(actor["bindings"])
            preset_pc = (
                any(str(binding.get("binding_kind") or "") == "preset_pc" for binding in bindings)
                or actor["actor_type"] == "pc"
            )
            character = characters.import_content_actor(
                actor,
                campaign_id=None if preset_pc else campaign_id,
                assets_by_key=assets_by_key,
                principal_id=principal_id,
                idempotency_key=f"content-module:{idempotency_key}:{actor['id']}",
            )
            actor_map[actor["id"]] = character.id
            effective_bindings = bindings or [
                {
                    "kind": "module",
                    "module_key": module_key,
                    "binding_kind": "preset_pc" if preset_pc else "cast",
                    "role": "",
                }
            ]
            for binding in effective_bindings:
                scene_key = str(binding.get("scene_key") or "")
                saved = modules.bind_actor(
                    campaign_id=campaign_id,
                    module_id=result["module_id"],
                    character_id=character.id,
                    actor_card_id=actor["id"],
                    binding_kind=str(
                        binding.get("binding_kind") or ("preset_pc" if preset_pc else "cast")
                    ),
                    role=str(binding.get("role") or ""),
                    scene_id=result["scene_map"].get(scene_key) if scene_key else None,
                    metadata={
                        **dict(binding.get("metadata") or {}),
                        "content_package_checksum": normalized["checksum"],
                        "content_actor_version": actor["version"],
                        "content_actor_provenance": deepcopy(actor.get("provenance") or {}),
                        "content_actor_metadata": deepcopy(actor.get("metadata") or {}),
                    },
                )
                binding_ids.append(saved["id"])
        result["actor_map"] = actor_map
        result["actor_binding_ids"] = binding_ids
        result.pop("actors", None)
        result["dependencies"] = list(normalized["dependencies"])
        result["artifact"] = managed_archive
        result["activated"] = False
        if activate:
            normalized_remaps: list[dict[str, str]] = []
            remap_targets: dict[str, str] = {}
            for index, raw in enumerate(progress_remaps or []):
                if not isinstance(raw, dict):
                    raise ValueError(f"progress_remaps[{index}] must be an object")
                unknown = set(raw) - {"from_scene_id", "to_scene_key", "reason"}
                if unknown:
                    raise ValueError(
                        f"progress_remaps[{index}] has unsupported fields: {sorted(unknown)}"
                    )
                source_scene_id = str(raw.get("from_scene_id") or "").strip()
                target_scene_key = str(raw.get("to_scene_key") or "").strip()
                reason = str(raw.get("reason") or "").strip()
                if not source_scene_id or not target_scene_key:
                    raise ValueError(
                        f"progress_remaps[{index}] requires from_scene_id and to_scene_key"
                    )
                if target_scene_key not in result["scene_map"]:
                    raise ValueError(
                        f"progress_remaps[{index}].to_scene_key is not in the finalized Pack"
                    )
                if not reason or len(reason) > 1000:
                    raise ValueError(
                        f"progress_remaps[{index}].reason must contain 1 to 1000 characters"
                    )
                if source_scene_id in remap_targets:
                    raise ValueError("progress_remaps contains duplicate from_scene_id values")
                target_scene_id = str(result["scene_map"][target_scene_key])
                remap_targets[source_scene_id] = target_scene_id
                normalized_remaps.append(
                    {
                        "from_scene_id": source_scene_id,
                        "to_scene_key": target_scene_key,
                        "to_scene_id": target_scene_id,
                        "reason": reason,
                        "resolver": "agent",
                    }
                )
            activation_scope = f"content-module-activation:{campaign_id}"
            activation_key = f"content-module-activate:{idempotency_key}"
            activation_payload = {
                "checksum": normalized["checksum"],
                "module_id": result["module_id"],
                "operation": "activate",
                "progress_remaps": normalized_remaps,
            }
            activation_replay = idempotency.lookup(
                activation_scope,
                activation_key,
                activation_payload,
            )
            result["activation"] = (
                dict(activation_replay.response or {}).get("activation")
                if activation_replay is not None
                else modules.activate_candidate(
                    campaign_id,
                    result["module_id"],
                    progress_remaps=remap_targets,
                    idempotency_key=activation_key,
                    idempotency_write=IdempotencyWrite(
                        scope=activation_scope,
                        payload=activation_payload,
                        response=lambda value: {"activation": value},
                    ),
                )
            )
            result["activation"] = {
                **dict(result["activation"] or {}),
                "progress_remap_rulings": normalized_remaps,
            }
            result["activated"] = True
        return result

    def import_content_rules_package(
        campaign_id: str,
        package: dict[str, Any],
        blobs: dict[str, bytes],
        *,
        principal_id: str,
        idempotency_key: str,
    ) -> dict[str, Any]:
        """Install one unified addon/core-rules/preset archive."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_facade_phase(campaign_id, "content_pack(import)", PROFILE_LOBBY)
        value = validate_dnd_content_package(package)
        if value["system_id"] != DND5E.id or value["kind"] not in {
            "addon",
            "core_rules",
            "preset",
        }:
            raise ValueError("content package must be a dnd5e addon, core_rules, or preset")
        request = {"operation": "import_content", "package_checksum": value["checksum"]}
        scope = f"content-package-import:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request)
        if replay is not None:
            return replay
        managed_archive = storage.write_content_archive(value, blobs)

        assets = {str(item["asset_key"]): item for item in value["assets"]}
        source_map: dict[str, str] = {}
        chunk_map: dict[str, str] = {}
        source_results = []
        embedder, _vectors = storage.dense_components()
        for source in value["sources"]:
            asset = assets[str(source["normalized_document_asset_key"])]
            imported = rules.import_content_source(
                source,
                blobs[str(asset["checksum"])],
                system_id=DND5E.id,
                embedder=embedder,
            )
            source_map[str(source["source_key"])] = str(imported["source_id"])
            chunk_map.update({str(key): str(item) for key, item in imported["chunk_map"].items()})
            source_results.append(
                {key: deepcopy(item) for key, item in imported.items() if key != "chunk_map"}
            )

        def localize(item: Any) -> Any:
            if isinstance(item, list):
                return [localize(child) for child in item]
            if isinstance(item, str):
                if item in chunk_map:
                    return chunk_map[item]
                result = item
                for stable_key, local_id in chunk_map.items():
                    result = result.replace(f"#chunk:{stable_key}", f"#chunk:{local_id}")
                return result
            if not isinstance(item, dict):
                return deepcopy(item)
            result = {
                key: localize(child)
                for key, child in item.items()
                if key not in {"source_key", "chunk_key", "rule_definition_id"}
            }
            source_key = item.get("source_key")
            if source_key is not None:
                result["source_key"] = str(source_key)
                if str(source_key) in source_map:
                    result["source_id"] = source_map[str(source_key)]
            chunk_key = item.get("chunk_key")
            if chunk_key is not None:
                if str(chunk_key) not in chunk_map:
                    raise ValueError(f"content citation references unknown chunk {chunk_key}")
                result["chunk_id"] = chunk_map[str(chunk_key)]
            return result

        definitions = list(value["content"].get("rule_definitions") or [])
        pending = {str(item["id"]): dict(item) for item in definitions}
        component_results = []
        while pending:
            progressed = False
            for definition_id, definition in list(pending.items()):
                manifest = deepcopy(dict(definition["manifest"]))
                dependencies_ready = True
                for dependency in manifest.get("dependencies") or []:
                    try:
                        dependency_row = rule_packs.get_version(
                            str(dependency["id"]), str(dependency["version"])
                        )
                    except LookupError:
                        dependencies_ready = False
                        break
                    if dependency_row.status != "installed":
                        dependencies_ready = False
                        break
                if not dependencies_ready:
                    continue
                try:
                    existing = rule_packs.get_version(definition_id, str(definition["version"]))
                except LookupError:
                    existing = None
                if existing is not None and existing.status == "installed":
                    provenance = rule_packs.provenance(definition_id, str(definition["version"]))
                    recorded = str(
                        dict(provenance.get("content_definition") or {}).get("definition_checksum")
                        or ""
                    )
                    if not recorded:
                        recorded = content_definition_checksum(
                            manifest=existing.manifest,
                            artifacts=existing.artifacts,
                            mechanics=existing.mechanics,
                        )
                    if recorded != str(definition["definition_checksum"]):
                        raise ValueError(f"content rule definition conflict: {definition_id}")
                else:
                    artifacts = [
                        {
                            key: child
                            for key, child in localize(item).items()
                            if key != "rule_definition_id"
                        }
                        for item in value["content"].get("artifacts") or []
                        if str(item.get("rule_definition_id") or "") == definition_id
                    ]
                    mechanics = [
                        {
                            key: child
                            for key, child in localize(item).items()
                            if key != "rule_definition_id"
                        }
                        for item in value["content"].get("mechanics") or []
                        if str(item.get("rule_definition_id") or "") == definition_id
                    ]
                    localized_artifacts = _strip_artifact_authoring_state(
                        refresh_portable_resolution_plans(artifacts)
                    )
                    localized_mechanics = _strip_artifact_authoring_state(
                        refresh_portable_resolution_plans(mechanics)
                    )
                    draft = save_rule_pack_draft(
                        manifest=manifest,
                        artifacts=localized_artifacts,
                        mechanics=localized_mechanics,
                        provenance={
                            "source": f"content-package:{value['id']}",
                            "structured": True,
                            "content_definition": {
                                "package_id": value["id"],
                                "package_version": value["version"],
                                "package_checksum": value["checksum"],
                                "definition_checksum": definition["definition_checksum"],
                            },
                            "content_package_kind": value["kind"],
                            "content_package_id": value["id"],
                            "content_package_version": value["version"],
                            "content_package_checksum": value["checksum"],
                            "content_archive_artifact": managed_archive["artifact"],
                            "license": value["metadata"].get("license"),
                            "attribution": value["metadata"].get("attribution"),
                        },
                    )
                    if draft["status"] != "validated":
                        raise ValueError(f"content rule definition was rejected: {definition_id}")
                    rule_packs.install(definition_id, str(definition["version"]))
                component_results.append(
                    {
                        "kind": "rule_pack",
                        "id": definition_id,
                        "version": definition["version"],
                        "checksum": definition["definition_checksum"],
                        "status": "stored",
                    }
                )
                del pending[definition_id]
                progressed = True
            if not progressed:
                raise ValueError(
                    "content rule dependencies are unavailable or cyclic: "
                    + ", ".join(sorted(pending))
                )

        actor_result = None
        if value["actors"]:
            actor_manifest, actor_artifacts = content_actor_catalog_definition(value)
            for artifact in actor_artifacts:
                card = dict(artifact.get("card") or {})
                content_actor = card.get("content_actor")
                if isinstance(content_actor, dict):
                    card["content_actor"] = runtime_actor_with_portrait(
                        content_actor,
                        value,
                        blobs,
                    )
                    artifact["card"] = card
            try:
                actor_pack = rule_packs.get_version(actor_manifest["id"], actor_manifest["version"])
            except LookupError:
                actor_pack = rule_packs.save_draft(
                    manifest=actor_manifest,
                    artifacts=actor_artifacts,
                    provenance={
                        "source": f"content-package:{value['id']}",
                        "structured": True,
                        "content_package_checksum": value["checksum"],
                        "content_package_kind": value["kind"],
                        "content_package_id": value["id"],
                        "content_package_version": value["version"],
                        "content_package_editions": list(
                            value["manifest"].get("editions")
                            or (
                                [value["metadata"]["edition"]]
                                if value["metadata"].get("edition")
                                else []
                            )
                        ),
                        "content_archive_artifact": managed_archive["artifact"],
                        "license": value["metadata"].get("license"),
                        "attribution": value["metadata"].get("attribution"),
                    },
                )
            if actor_pack.status == "validated":
                actor_pack = rule_packs.install(actor_manifest["id"], actor_manifest["version"])
            if actor_pack.status != "installed":
                raise ValueError(
                    "content actor catalog is not installable: "
                    + "; ".join(
                        str(item) for item in dict(actor_pack.validation_report).get("errors", [])
                    )
                )
            actor_result = {
                "id": actor_manifest["id"],
                "version": actor_manifest["version"],
                "actors": len(actor_artifacts),
                "status": "stored",
            }

        addon_result = None
        if value["kind"] == "addon":
            imported_addon = addons.import_package(
                value,
                provenance={
                    "import_campaign_id": campaign_id,
                    "content_archive_artifact": managed_archive["artifact"],
                },
            )
            installed_addon = asdict(
                addons.install(imported_addon.addon_id, imported_addon.version)
            )
            addon_result = {**installed_addon, "status": "stored"}
        response = {
            "package": {
                "kind": value["kind"],
                "id": value["id"],
                "version": value["version"],
                "checksum": value["checksum"],
            },
            "sources": source_results,
            "components": component_results,
            "actor_catalog": actor_result,
            "addon": addon_result,
            "artifact": managed_archive,
            "stored": True,
            "activated": False,
        }
        return remember_idempotent(
            scope, idempotency_key, request, response, campaign_id=campaign_id
        )

    def managed_module_asset_bytes(source_path: str) -> bytes:
        path = Path(source_path).expanduser().resolve()
        if not path.is_file() or not path.is_relative_to(config.artifacts_dir.resolve()):
            raise LookupError("module asset is not available in managed MCP storage")
        return path.read_bytes()

    def checked_rule_facts(value: dict[str, Any] | None) -> dict[str, Any]:
        facts = dict(value or {})
        reserved = {"actor_id", "kind", "ability", "dc"} & facts.keys()
        if reserved:
            raise ValueError("rule_facts cannot override: " + ", ".join(sorted(reserved)))
        if len(facts) > 32 or len(repr(facts)) > 8192:
            raise ValueError("rule_facts exceed the safe settlement limit")
        if any(not isinstance(key, str) or not key.strip() for key in facts):
            raise ValueError("rule_facts keys must be non-empty strings")
        return facts

    def assert_snapshot_core_available(document: dict[str, Any]) -> None:
        """Fail before materialization when a save's exact built-in core is unavailable."""
        profile = dict(document.get("payload", {}).get("rule_profile") or {})
        options = dict(profile.get("options") or {})
        locked = dict(options.get("_core_rule_pack_lock") or {})
        if not locked:
            raise RulesetUnavailableError(
                "snapshot has no locked built-in core rule pack; "
                "it cannot be restored without explicit conversion"
            )
        edition = str(profile.get("edition") or "")
        try:
            core_pack = get_core_rule_pack(edition)
        except (KeyError, ValueError) as error:
            raise RulesetUnavailableError(
                f"snapshot requires unsupported D&D edition {edition!r}"
            ) from error
        available = {
            "id": core_pack.id,
            "version": core_pack.version,
            "fingerprint": core_pack.fingerprint,
        }
        if locked != available:
            raise RulesetUnavailableError(
                "snapshot's locked built-in core rule pack is unavailable; "
                "runtime upgrade needs an explicit conversion before restore"
            )

    def bundled_rule_seed_status() -> dict[str, Any]:
        root = config.dnd_skills_dir / "full" / "skills" / "dnd-dm" / "srd"
        if not root.is_dir():
            return {
                "status": "unavailable",
                "complete": False,
                "expected_sources": 0,
                "indexed_sources": 0,
                "missing_source_keys": [],
                "stale_source_keys": [],
                "corpus": None,
                "required_path": str(root),
            }
        catalog = build_bundled_rule_sources(root)
        inventory = bundled_rule_corpus_inventory(root, catalog)
        existing = {str(item["source_key"]): item for item in rules.sources(system_id=DND5E.id)}
        expected = {source.source_key: source for source in catalog}
        missing = sorted(set(expected) - set(existing))
        stale = sorted(
            source_key
            for source_key, source in expected.items()
            if source_key in existing
            and str(existing[source_key].get("checksum") or "") != source.checksum
        )
        return {
            "status": "ready" if not missing and not stale else "incomplete",
            "complete": not missing and not stale,
            "expected_sources": len(expected),
            "indexed_sources": len(expected) - len(missing) - len(stale),
            "missing_source_keys": missing,
            "stale_source_keys": stale,
            "corpus": inventory,
        }

    def seed_bundled_rules(*, max_files: int | None = None) -> dict[str, Any]:
        """Idempotently index every bundled SRD partition without silent truncation."""

        root = config.dnd_skills_dir / "full" / "skills" / "dnd-dm" / "srd"
        if not root.is_dir():
            return bundled_rule_seed_status()
        catalog = list(build_bundled_rule_sources(root))
        if max_files is not None:
            if (
                isinstance(max_files, bool)
                or not isinstance(max_files, int)
                or not 1 <= max_files <= len(catalog)
            ):
                raise ValueError(f"max_files must be an integer from 1 through {len(catalog)}")
            catalog = catalog[:max_files]
        seeded = 0
        skipped = 0
        for source in catalog:
            result = rules.ingest(
                system_id=DND5E.id,
                source_key=source.source_key,
                title=source.title,
                content=source.content,
                locale=source.locale,
                edition=source.edition,
                version=source.version,
                publication_id=source.publication_id,
                authority="core",
                metadata=source.metadata(),
            )
            skipped += int(result.skipped)
            seeded += int(not result.skipped)
        coverage = bundled_rule_seed_status()
        complete = coverage["complete"]
        return {
            **coverage,
            "status": "ready" if complete else "partial",
            "seeded": seeded,
            "skipped": skipped,
            "requested_sources": len(catalog),
        }

    if config.auto_seed_rules:
        seed_bundled_rules()

    def authoritative_phase(campaign_id: str) -> str:
        campaign = campaigns.get(campaign_id)
        return campaign_phase(campaign.state)

    def preparation_setup_closed(campaign: Any) -> bool:
        """Return whether this campaign has ever crossed into live play."""
        state = dict(campaign.state or {})
        if bool(state.get("adventure_started", False)):
            return True
        manifest = state.get("playthrough_manifest")
        return isinstance(manifest, dict) and str(manifest.get("status") or "") in {
            "in_progress",
            "completed",
        }

    def initial_preparation_allowed_for_new_actor(
        campaign: Any,
        character: Any,
    ) -> bool:
        """Allow one setup list for an actor introduced after live play began."""

        preparation = dict(
            dict(character.sheet or {}).get("spellcasting", {}).get("preparation", {})
        )
        if list(preparation.get("selected_spell_ids") or []):
            return False
        state = dict(campaign.state or {})
        participated = {
            str(actor_id)
            for actor_id in state.get("adventure_started_actor_ids", [])
            if str(actor_id)
        }
        manifest = state.get("playthrough_manifest")
        if isinstance(manifest, dict):
            party = dict(manifest.get("party") or {})
            participated.update(
                str(member.get("actor_id") or "")
                for member in party.get("members", [])
                if isinstance(member, dict)
            )
            for replacement in party.get("replacements", []):
                if not isinstance(replacement, dict):
                    continue
                participated.update(
                    {
                        str(replacement.get("predecessor_actor_id") or ""),
                        str(replacement.get("replacement_actor_id") or ""),
                    }
                )
        participated.discard("")
        return bool(participated) and str(character.id) not in participated

    def validate_exposure_scope(
        exposure: Exposure, tool_id: str, arguments: dict[str, Any]
    ) -> None:
        """Prevent one campaign's phase exposure from being reused for another campaign."""
        policy = policy_for_tool(tool_id)
        protected_roles = policy.roles(exposure.phase) if policy is not None else frozenset()
        if protected_roles:
            if exposure.campaign_id is None:
                raise ExposureError(f"Tool {tool_id!r} requires a campaign-bound exposure.")
            access.require_campaign(
                exposure.campaign_id,
                exposure.principal_id,
                roles=set(protected_roles),
            )
        if exposure.campaign_id is None:
            return

        campaign_ids: set[str] = set()
        character_ids: set[str] = set()

        def collect(value: Any) -> None:
            if isinstance(value, dict):
                for key, item in value.items():
                    if key == "campaign_id" and item:
                        campaign_ids.add(str(item))
                    elif (key == "character_id" or key.endswith("_character_id")) and item:
                        character_ids.add(str(item))
                    elif key == "actor_id" and item:
                        character_ids.add(str(item))
                    collect(item)
            elif isinstance(value, list):
                for item in value:
                    collect(item)

        collect(arguments)
        owner = str(arguments.get("owner") or "")
        owner_id = arguments.get("owner_id")
        if owner == "party" and owner_id:
            campaign_ids.add(str(owner_id))
        elif owner == "character" and owner_id:
            character_ids.add(str(owner_id))
        if tool_id == "module_expand" and arguments.get("chunk_id"):
            expanded = modules.expand(str(arguments["chunk_id"]))
            if expanded.get("campaign_id"):
                campaign_ids.add(str(expanded["campaign_id"]))

        for character_id in character_ids:
            try:
                character = characters.get(character_id)
            except LookupError:
                continue
            if character.campaign_id:
                campaign_ids.add(str(character.campaign_id))

        mismatched = sorted(item for item in campaign_ids if item != exposure.campaign_id)
        if mismatched:
            raise ExposureError(
                f"Tool {tool_id!r} targets campaign {mismatched[0]!r}, but this exposure is "
                f"bound to {exposure.campaign_id!r}. Open a separate exposure for that campaign."
            )

    exposures = ExposureRegistry()

    def allowed_tools_for_exposure(exposure: Exposure, phase: str) -> set[str]:
        """Return tools the bound principal may still load in the current phase."""

        allowed = set(tools_for_phase(phase))
        membership = (
            access.membership(exposure.campaign_id, exposure.principal_id)
            if exposure.campaign_id is not None
            else None
        )
        for tool_id in tuple(allowed):
            policy = policy_for_tool(tool_id)
            if policy is None:
                continue
            if policy.local_only and exposure.principal_id != LOCAL_SYSTEM_PRINCIPAL_ID:
                allowed.discard(tool_id)
                continue
            if policy.requires_campaign and membership is None:
                allowed.discard(tool_id)
                continue
            roles = policy.roles(phase)
            if not roles:
                continue
            if membership is None or membership.role not in roles:
                allowed.discard(tool_id)
        return allowed

    def campaign_random_context(
        campaign_id: str,
        tool_id: str,
        arguments: dict[str, Any],
    ):
        campaign = campaigns.get(campaign_id)
        stream = CampaignRandomStream.from_campaign_state(
            campaign_id,
            campaign.state,
            operation=tool_id,
            idempotency_key=str(arguments.get("idempotency_key") or ""),
        )
        return use_random_stream(stream)

    mcp = SessionExposureFastMCP(
        "SagaSmith D&D",
        instructions=(
            "SagaSmith is a source-bound D&D 5e campaign runtime. Cold start: call "
            "skill_query(kind='skill', action='read', identifier='dnd.full'), then use "
            "outline/section/search for task-specific depth. Call "
            "storage_status and server_capabilities. "
            "Call campaign_query to find a campaign. Open exactly one exposure with "
            "exposure(action='open', campaign_id?, principal_id?), then search and set the "
            "needed tool ids through that same facade. Reopen with campaign_id after creating "
            "a campaign. The server sends tools/list_changed and loaded tools are called "
            "directly. Never invent a successful write, "
            "bypass phase/role/revision/idempotency requirements, or treat module search "
            "summaries as exact evidence. Read sagasmith://bootstrap for the compact "
            "host-independent workflow. Standard mechanics are engine-owned; unstructured "
            "module semantics default to Agent DM reasoning from exact source evidence; "
            "player choices, permission/owner approvals, and missing/conflicting sources "
            "remain external boundaries."
        ),
        exposure_registry=exposures,
        phase_lookup=authoritative_phase,
        allowed_tools_lookup=allowed_tools_for_exposure,
        scope_validator=validate_exposure_scope,
        random_context_factory=campaign_random_context,
        context_binding_factory=lambda campaign_id, principal_id, arguments: (
            authoritative_host_context_binding(campaign_id, principal_id, arguments)
        ),
        authorization_fingerprint_lookup=access.authorization_fingerprint,
        bound_principal_id=config.bound_principal_id,
        host=config.http_host,
        port=config.http_port,
        streamable_http_path=config.http_path,
    )

    def public_tool() -> Callable[[Callable[..., Any]], Callable[..., Any]]:
        """Register one public MCP tool."""

        def decorate(function: Callable[..., Any]) -> Callable[..., Any]:
            return mcp.tool()(function)

        return decorate

    rules_context_unset = object()
    context_receipt_secret = uuid4().bytes + uuid4().bytes
    context_receipt_ttl_ns = 60 * 60 * 1_000_000_000

    def receipt_principal_fingerprint(principal_id: str) -> str:
        return hashlib.sha256(principal_id.encode("utf-8")).hexdigest()

    def host_context_binding(
        *,
        campaign_id: str,
        branch_id: str,
        principal_id: str,
        role: str,
        audience: str,
        authorization_fingerprint: str | None = None,
    ) -> dict[str, str]:
        """Return the exact host replay boundary without exposing principal identity."""

        principal_hash = receipt_principal_fingerprint(principal_id)
        value = {
            "domain": "sagasmith-dnd",
            "campaign_id": campaign_id,
            "principal_fingerprint": principal_hash,
            "role": role,
            "audience": audience,
            "branch_id": branch_id,
            "authorization_fingerprint": (
                authorization_fingerprint
                or access.authorization_fingerprint(campaign_id, principal_id)
            ),
            "memory_policy": "domain_authoritative",
        }
        return {
            **value,
            "context_epoch": hashlib.sha256(
                canonical_json(
                    {
                        key: value[key]
                        for key in (
                            "domain",
                            "campaign_id",
                            "principal_fingerprint",
                            "role",
                            "audience",
                            "branch_id",
                            "authorization_fingerprint",
                        )
                    }
                ).encode("utf-8")
            ).hexdigest(),
        }

    def managed_module_source_digests(value: Any) -> set[str]:
        """Collect stable identities for exact managed module citations."""

        result: set[str] = set()
        if isinstance(value, list):
            for item in value:
                result.update(managed_module_source_digests(item))
            return result
        if not isinstance(value, dict):
            return result
        for key, item in value.items():
            if key in {"source_ref", "source_refs"}:
                candidates = item if key == "source_refs" and isinstance(item, list) else [item]
                for candidate in candidates:
                    if not isinstance(candidate, dict):
                        continue
                    if not (MANAGED_MODULE_SOURCE_FIELDS & set(candidate)):
                        continue
                    exact = {name: candidate.get(name) for name in EXACT_MODULE_SOURCE_FIELD_ORDER}
                    result.add(hashlib.sha256(canonical_json(exact).encode("utf-8")).hexdigest())
                continue
            result.update(managed_module_source_digests(item))
        return result

    def anchored_source_digests(
        campaign_id: str,
        branch_id: str | None,
    ) -> set[str]:
        """Return active module sources whose context was deliberately pinned."""

        result: set[str] = set()
        for fact in memories.list(campaign_id, branch_id=branch_id):
            if str(fact.kind) != "context_anchor":
                continue
            metadata = dict(fact.metadata or {})
            result.update(
                managed_module_source_digests(
                    [
                        {"source_ref": dict(binding or {}).get("source_ref")}
                        for binding in list(metadata.get("source_bindings") or [])
                    ]
                )
            )
        return result

    def issue_context_receipt(
        *,
        campaign_id: str,
        branch_id: str | None,
        principal_id: str,
        audience: str,
        actor_id: str | None,
        scope_id: str,
        related_refs: list[str],
        context: dict[str, Any],
    ) -> dict[str, Any]:
        """Sign proof that exact continuity context was read at this revision."""

        issued_ns = time.monotonic_ns()
        payload = {
            "schema_version": 1,
            "campaign_id": campaign_id,
            "branch_id": branch_id,
            "campaign_revision": campaigns.get(campaign_id).revision,
            "principal_fingerprint": receipt_principal_fingerprint(principal_id),
            "audience": audience,
            "actor_id": actor_id,
            "scope_id": scope_id,
            "related_refs": sorted(related_refs),
            "module_source_ref_digests": sorted(
                managed_module_source_digests(
                    [
                        {"source_ref": dict(item or {}).get("source_ref")}
                        for item in list(context.get("module_evidence") or [])
                    ]
                )
            ),
            "issued_monotonic_ns": issued_ns,
            "expires_monotonic_ns": issued_ns + context_receipt_ttl_ns,
        }
        return sign_receipt(payload, context_receipt_secret)

    def verify_context_receipt(
        receipt: Any,
        *,
        campaign_id: str,
        branch_id: str | None,
        principal_id: str,
        required_source_digests: set[str],
    ) -> None:
        """Verify a source-bound narrative commit used current pinned context."""

        payload = verify_receipt_signature(
            receipt,
            context_receipt_secret,
            missing_error=(
                "payload.context_receipt is required when a continuity commit cites "
                "a pinned context-anchor source"
            ),
            invalid_error="payload.context_receipt signature is invalid",
        )
        if payload.get("campaign_id") != campaign_id:
            raise ValueError("payload.context_receipt belongs to another campaign")
        if payload.get("branch_id") != branch_id:
            raise ValueError("payload.context_receipt belongs to another branch")
        if payload.get("principal_fingerprint") != receipt_principal_fingerprint(principal_id):
            raise ValueError("payload.context_receipt belongs to another principal")
        if int(payload.get("expires_monotonic_ns") or 0) < time.monotonic_ns():
            raise ValueError("payload.context_receipt expired; read continuity_context again")
        campaign_revision = campaigns.get(campaign_id).revision
        if int(payload.get("campaign_revision", -1)) != campaign_revision:
            raise ValueError(
                "payload.context_receipt is stale; read continuity_context again at "
                f"campaign revision {campaign_revision}"
            )
        received_source_digests = {
            str(item) for item in list(payload.get("module_source_ref_digests") or [])
        }
        missing = sorted(required_source_digests - received_source_digests)
        if missing:
            raise ValueError(
                "payload.context_receipt did not include every cited pinned module source; "
                "read continuity_context with the relevant related_refs"
            )

    npc_turn_receipt_ttl_ns = 10 * 60 * 1_000_000_000

    def npc_turn_latest_event_sequence(campaign_id: str, branch_id: str | None) -> int:
        values = events.list(campaign_id, limit=1, branch_id=branch_id)
        return int(values[-1].sequence) if values else 0

    def npc_turn_actor_state(
        campaign_id: str,
        branch_id: str | None,
        actor_id: str,
    ) -> tuple[list[dict[str, Any]], dict[str, str], dict[str, str]]:
        actor_ref = f"actor:{actor_id}"
        state_facts = [
            asdict(item)
            for item in memories.list_for_subject_refs(
                campaign_id,
                subject_refs={actor_ref},
                predicates={"relationship_to", "goal"},
                kinds={"actor_state"},
                branch_id=branch_id,
            )
        ]
        fact_heads = {str(item["fact_key"]): str(item["revision_id"]) for item in state_facts}
        knowledge_heads = {
            str(item.knowledge_key): str(item.revision_id)
            for item in knowledge.list(
                campaign_id,
                actor_id=actor_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        return state_facts, fact_heads, knowledge_heads

    def npc_turn_scene_projection(scene: dict[str, Any] | None) -> dict[str, Any] | None:
        if not isinstance(scene, dict):
            return None
        progress = dict(scene.get("progress") or {})
        return {
            "scene_id": str(scene.get("scene_id") or ""),
            "title": str(scene.get("title") or ""),
            "module_id": str(scene.get("module_id") or ""),
            "chapter_id": str(scene.get("chapter_id") or ""),
            "scope_id": str(scene.get("scope_id") or "party"),
            "current_room": str(progress.get("current_room") or ""),
            "current_location_key": str(progress.get("current_location_key") or ""),
            "state_version": int(progress.get("state_version") or 0),
        }

    def npc_turn_perception_projection(
        campaign: Any,
        *,
        actor_id: str,
        interlocutors: list[dict[str, Any]],
        scene: dict[str, Any] | None,
    ) -> list[dict[str, Any]]:
        """Project only immediate, outwardly observable turn context."""

        result: list[dict[str, Any]] = [
            {
                "basis_ref": f"perception:actor:{item['id']}:presence",
                "kind": "interlocutor_presence",
                "actor_id": str(item["id"]),
                "name": str(item["name"]),
                "character_type": str(item["character_type"]),
            }
            for item in interlocutors
        ]
        if scene is not None and scene.get("scene_id"):
            result.append(
                {
                    "basis_ref": f"perception:scene:{scene['scene_id']}:location",
                    "kind": "current_location",
                    "scene_id": str(scene["scene_id"]),
                    "title": str(scene.get("title") or ""),
                    "current_room": str(scene.get("current_room") or ""),
                    "current_location_key": str(scene.get("current_location_key") or ""),
                }
            )
        combat = dict(dict(campaign.state or {}).get("combat") or {})
        if combat.get("active", False):
            allowed_actor_ids = {actor_id, *(str(item["id"]) for item in interlocutors)}
            for raw in [
                *list(combat.get("combatants") or []),
                *list(combat.get("reinforcements") or []),
            ]:
                item = dict(raw or {})
                observed_actor_id = str(item.get("actor_id") or "")
                if observed_actor_id not in allowed_actor_ids:
                    continue
                result.append(
                    {
                        "basis_ref": f"perception:combat:{observed_actor_id}:position",
                        "kind": "combat_position",
                        "actor_id": observed_actor_id,
                        **{
                            key: deepcopy(item[key])
                            for key in ("position", "location", "x", "y", "zone", "status")
                            if key in item
                        },
                    }
                )
        return result

    def npc_turn_actor_projection(actor: Any) -> dict[str, Any]:
        notes = canonical_character_notes(
            actor.notes,
            character_type=actor.character_type,
            name=actor.name,
            summary=actor.summary,
        )
        profile = dict(notes.get("profile") or {})
        profile.pop("dm_notes", None)
        sheet = validate_character_sheet(actor.sheet)
        return {
            "id": actor.id,
            "name": actor.name,
            "character_type": actor.character_type,
            "summary": actor.summary,
            "revision": actor.revision,
            "profile": profile,
            "self_state": {
                "identity": deepcopy(sheet.get("identity") or {}),
                "progression": deepcopy(sheet.get("progression") or {}),
                "abilities": deepcopy(sheet.get("abilities") or {}),
                "skills": deepcopy(sheet.get("skills") or {}),
                "combat": deepcopy(sheet.get("combat") or {}),
                "traits": deepcopy(sheet.get("traits") or {}),
                "conditions": deepcopy(sheet.get("conditions") or []),
                "effects": deepcopy(sheet.get("effects") or []),
                "status_tags": deepcopy(
                    dict(sheet.get("adventure_state") or {}).get("status_tags") or []
                ),
            },
        }

    def issue_npc_turn_receipt(
        *,
        bundle: dict[str, Any],
        campaign_id: str,
        branch_id: str | None,
        principal_id: str,
        actor_id: str,
        actor_revision: int,
        interlocutor_actor_ids: list[str],
        scene: dict[str, Any] | None,
        fact_heads: dict[str, str],
        context_fact_heads: dict[str, str],
        knowledge_heads: dict[str, str],
        allowed_basis_refs: list[str],
        stimulus: dict[str, Any],
        module_evidence: list[dict[str, Any]],
    ) -> dict[str, Any]:
        issued_ns = time.monotonic_ns()
        branch = (
            branches.get(campaign_id, branch_id) if branch_id else branches.current(campaign_id)
        )
        payload = {
            "schema_version": 2,
            "purpose": "npc_turn",
            "bundle_id": str(bundle["bundle_id"]),
            "bundle_digest": hashlib.sha256(canonical_json(bundle).encode("utf-8")).hexdigest(),
            "campaign_id": campaign_id,
            "branch_id": branch.id,
            "head_snapshot_id": branch.head_snapshot_id,
            "campaign_revision": campaigns.get(campaign_id).revision,
            "latest_event_sequence": npc_turn_latest_event_sequence(campaign_id, branch.id),
            "principal_fingerprint": receipt_principal_fingerprint(principal_id),
            "actor_id": actor_id,
            "actor_revision": actor_revision,
            "interlocutor_actor_ids": list(interlocutor_actor_ids),
            "scene_id": str((scene or {}).get("scene_id") or ""),
            "scope_id": str((scene or {}).get("scope_id") or "party"),
            "scene_state_version": int((scene or {}).get("state_version") or 0),
            "fact_heads": dict(sorted(fact_heads.items())),
            "context_fact_heads": dict(sorted(context_fact_heads.items())),
            "knowledge_heads": dict(sorted(knowledge_heads.items())),
            "allowed_basis_refs": sorted(allowed_basis_refs),
            "stimulus_digest": hashlib.sha256(canonical_json(stimulus).encode("utf-8")).hexdigest(),
            "module_source_ref_digests": sorted(
                managed_module_source_digests(
                    [{"source_ref": dict(item or {}).get("source_ref")} for item in module_evidence]
                )
            ),
            "issued_monotonic_ns": issued_ns,
            "expires_monotonic_ns": issued_ns + npc_turn_receipt_ttl_ns,
        }
        return sign_receipt(payload, context_receipt_secret)

    def verify_npc_turn_receipt(
        receipt: Any,
        *,
        campaign_id: str,
        branch_id: str | None,
        principal_id: str,
        required_source_digests: set[str] | None = None,
        require_fresh: bool = True,
    ) -> dict[str, Any]:
        payload = verify_receipt_signature(
            receipt,
            context_receipt_secret,
            missing_error="npc_turn.bundle_receipt is required",
            invalid_error="npc_turn.bundle_receipt signature is invalid",
        )
        if payload.get("schema_version") != 2 or payload.get("purpose") != "npc_turn":
            raise ValueError("npc_turn.bundle_receipt has the wrong purpose or schema")
        if payload.get("campaign_id") != campaign_id:
            raise ValueError("npc_turn.bundle_receipt belongs to another campaign")
        if payload.get("branch_id") != branch_id:
            raise ValueError("npc_turn.bundle_receipt belongs to another branch")
        if payload.get("principal_fingerprint") != receipt_principal_fingerprint(principal_id):
            raise ValueError("npc_turn.bundle_receipt belongs to another principal")
        required = set(required_source_digests or set())
        received = {str(item) for item in payload.get("module_source_ref_digests") or []}
        if missing := sorted(required - received):
            raise ValueError(
                "npc_turn.bundle_receipt did not include cited module sources: "
                + ", ".join(missing)
            )
        if not require_fresh:
            return payload
        if int(payload.get("expires_monotonic_ns") or 0) < time.monotonic_ns():
            raise ValueError("npc_turn.bundle_receipt expired; read the NPC turn bundle again")
        if int(payload.get("campaign_revision") or -1) != campaigns.get(campaign_id).revision:
            raise ValueError("npc_turn.bundle_receipt is stale at the campaign revision")
        branch = branches.current(campaign_id)
        if branch.id != branch_id or payload.get("head_snapshot_id") != branch.head_snapshot_id:
            raise ValueError("npc_turn.bundle_receipt is stale after branch or snapshot change")
        if int(payload.get("latest_event_sequence") or 0) != npc_turn_latest_event_sequence(
            campaign_id, branch_id
        ):
            raise ValueError("npc_turn.bundle_receipt is stale after a continuity event")
        actor_id = str(payload.get("actor_id") or "")
        actor = characters.get(actor_id)
        if actor.campaign_id != campaign_id or actor.revision != int(
            payload.get("actor_revision") or -1
        ):
            raise ValueError("npc_turn.bundle_receipt is stale at the actor revision")
        scene_scope_id = str(payload.get("scope_id") or "party")
        scene = npc_turn_scene_projection(
            modules.current_scene(campaign_id, scope_id=scene_scope_id)
        )
        if str((scene or {}).get("scene_id") or "") != str(payload.get("scene_id") or ""):
            raise ValueError("npc_turn.bundle_receipt is stale after a scene change")
        if int((scene or {}).get("state_version") or 0) != int(
            payload.get("scene_state_version") or 0
        ):
            raise ValueError("npc_turn.bundle_receipt is stale at the scene revision")
        _state, fact_heads, knowledge_heads = npc_turn_actor_state(
            campaign_id,
            branch_id,
            actor_id,
        )
        if dict(payload.get("fact_heads") or {}) != fact_heads:
            raise ValueError("npc_turn.bundle_receipt is stale at an actor-state fact")
        current_memory_heads = {
            str(item.id): str(item.revision_id)
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        if any(
            current_memory_heads.get(str(memory_id)) != str(revision_id)
            for memory_id, revision_id in dict(payload.get("context_fact_heads") or {}).items()
        ):
            raise ValueError("npc_turn.bundle_receipt is stale at a context fact")
        if dict(payload.get("knowledge_heads") or {}) != knowledge_heads:
            raise ValueError("npc_turn.bundle_receipt is stale at ActorKnowledge")
        return payload

    bounded_evaluation_receipt_ttl_ns = 10 * 60 * 1_000_000_000

    def bounded_memory_epoch_digest(campaign_id: str, branch_id: str) -> str:
        heads = [
            (str(item.id), str(item.revision_id))
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        ]
        return hashlib.sha256(canonical_json(sorted(heads)).encode("utf-8")).hexdigest()

    def bounded_knowledge_epoch_digest(
        campaign_id: str,
        branch_id: str,
        actor_ids: list[str],
    ) -> str:
        heads = [
            (actor_id, str(item.id), str(item.revision_id))
            for actor_id in sorted(set(actor_ids))
            for item in knowledge.list(
                campaign_id,
                actor_id=actor_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        ]
        return hashlib.sha256(canonical_json(sorted(heads)).encode("utf-8")).hexdigest()

    def issue_bounded_evaluation_receipt(
        *,
        bundle: dict[str, Any],
        campaign_id: str,
        branch_id: str,
        principal_id: str,
        purpose: str,
        subject_ref: str,
        allowed_basis_refs: list[str],
        allowed_claim_basis_refs: list[str],
        allowed_target_refs: list[str],
        context_heads: dict[str, str],
        knowledge_heads: dict[str, str],
        knowledge_actor_ids: list[str],
        actor_revision: int | None,
        scene: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Sign a purpose, principal, branch, and revision-bound semantic bundle."""

        issued_ns = time.monotonic_ns()
        branch = branches.get(campaign_id, branch_id)
        payload = {
            "schema_version": 1,
            "purpose": purpose,
            "bundle_id": str(bundle["bundle_id"]),
            "bundle_digest": hashlib.sha256(canonical_json(bundle).encode("utf-8")).hexdigest(),
            "campaign_id": campaign_id,
            "branch_id": branch.id,
            "head_snapshot_id": branch.head_snapshot_id,
            "campaign_revision": campaigns.get(campaign_id).revision,
            "latest_event_sequence": npc_turn_latest_event_sequence(campaign_id, branch.id),
            "principal_fingerprint": receipt_principal_fingerprint(principal_id),
            "subject_ref": subject_ref,
            "allowed_basis_refs": sorted(allowed_basis_refs),
            "allowed_claim_basis_refs": sorted(allowed_claim_basis_refs),
            "allowed_target_refs": sorted(allowed_target_refs),
            "question_digest": hashlib.sha256(
                str(dict(bundle.get("context") or {}).get("question") or "").strip().encode("utf-8")
            ).hexdigest(),
            "context_heads": dict(sorted(context_heads.items())),
            "knowledge_heads": dict(sorted(knowledge_heads.items())),
            "memory_epoch_digest": bounded_memory_epoch_digest(campaign_id, branch.id),
            "knowledge_actor_ids": sorted(set(knowledge_actor_ids)),
            "knowledge_epoch_digest": bounded_knowledge_epoch_digest(
                campaign_id,
                branch.id,
                knowledge_actor_ids,
            ),
            "actor_revision": actor_revision,
            "scene_id": str((scene or {}).get("scene_id") or ""),
            "scene_scope_id": str((scene or {}).get("scope_id") or "party"),
            "scene_state_version": int((scene or {}).get("state_version") or 0),
            "issued_monotonic_ns": issued_ns,
            "expires_monotonic_ns": issued_ns + bounded_evaluation_receipt_ttl_ns,
        }
        return sign_receipt(payload, context_receipt_secret)

    def verify_bounded_evaluation_receipt(
        receipt: Any,
        *,
        campaign_id: str,
        branch_id: str,
        principal_id: str,
        purpose: str | None = None,
    ) -> dict[str, Any]:
        """Verify a bounded proposal still belongs to the live epistemic epoch."""

        payload = verify_receipt_signature(
            receipt,
            context_receipt_secret,
            missing_error="bounded evaluation bundle_receipt is required",
            invalid_error="bounded evaluation bundle_receipt signature is invalid",
        )
        receipt_purpose = str(payload.get("purpose") or "")
        if payload.get("schema_version") != 1 or receipt_purpose not in BOUNDED_EVALUATION_PURPOSES:
            raise ValueError("bounded evaluation bundle_receipt has the wrong purpose or schema")
        if purpose is not None and receipt_purpose != purpose:
            raise ValueError("bounded evaluation bundle_receipt has the wrong purpose")
        if payload.get("campaign_id") != campaign_id:
            raise ValueError("bounded evaluation bundle_receipt belongs to another campaign")
        if payload.get("branch_id") != branch_id:
            raise ValueError("bounded evaluation bundle_receipt belongs to another branch")
        if payload.get("principal_fingerprint") != receipt_principal_fingerprint(principal_id):
            raise ValueError("bounded evaluation bundle_receipt belongs to another principal")
        if int(payload.get("expires_monotonic_ns") or 0) < time.monotonic_ns():
            raise ValueError("bounded evaluation bundle_receipt expired; read a new bundle")
        if int(payload.get("campaign_revision") or -1) != campaigns.get(campaign_id).revision:
            raise ValueError("bounded evaluation bundle_receipt is stale at campaign revision")
        branch = branches.current(campaign_id)
        if branch.id != branch_id or payload.get("head_snapshot_id") != branch.head_snapshot_id:
            raise ValueError(
                "bounded evaluation bundle_receipt is stale after branch or snapshot change"
            )
        if int(payload.get("latest_event_sequence") or 0) != npc_turn_latest_event_sequence(
            campaign_id, branch_id
        ):
            raise ValueError("bounded evaluation bundle_receipt is stale after a continuity event")
        if payload.get("memory_epoch_digest") != bounded_memory_epoch_digest(
            campaign_id, branch_id
        ):
            raise ValueError("bounded evaluation bundle_receipt is stale at campaign memory")
        current_heads = {
            str(item.id): str(item.revision_id)
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        if any(
            current_heads.get(str(memory_id)) != str(revision_id)
            for memory_id, revision_id in dict(payload.get("context_heads") or {}).items()
        ):
            raise ValueError("bounded evaluation bundle_receipt is stale at a context fact")
        for knowledge_id, revision_id in dict(payload.get("knowledge_heads") or {}).items():
            try:
                current = knowledge.get(str(knowledge_id), branch_id=branch_id)
            except LookupError as exc:
                raise ValueError(
                    "bounded evaluation bundle_receipt is stale at ActorKnowledge"
                ) from exc
            if str(current.revision_id) != str(revision_id):
                raise ValueError("bounded evaluation bundle_receipt is stale at ActorKnowledge")
        knowledge_actor_ids = [str(item) for item in list(payload.get("knowledge_actor_ids") or [])]
        if payload.get("knowledge_epoch_digest") != bounded_knowledge_epoch_digest(
            campaign_id,
            branch_id,
            knowledge_actor_ids,
        ):
            raise ValueError("bounded evaluation bundle_receipt is stale at ActorKnowledge")
        subject_ref = str(payload.get("subject_ref") or "")
        actor_revision = payload.get("actor_revision")
        if actor_revision is not None and subject_ref.startswith("actor:"):
            actor = characters.get(subject_ref.removeprefix("actor:"))
            if actor.campaign_id != campaign_id or actor.revision != int(actor_revision):
                raise ValueError("bounded evaluation bundle_receipt is stale at actor revision")
        scene = npc_turn_scene_projection(
            modules.current_scene(
                campaign_id,
                scope_id=str(payload.get("scene_scope_id") or "party"),
            )
        )
        if str((scene or {}).get("scene_id") or "") != str(payload.get("scene_id") or "") or int(
            (scene or {}).get("state_version") or 0
        ) != int(payload.get("scene_state_version") or 0):
            raise ValueError("bounded evaluation bundle_receipt is stale at scene revision")
        return payload

    def bounded_evaluation_bundle(
        *,
        purpose: str,
        campaign_id: str,
        branch_id: str,
        principal_id: str,
        role: str,
        audience: str,
        actor_id: str | None,
        subject_ref: str | None,
        target_refs: list[str],
        query: str,
        result: dict[str, Any],
        related_refs: set[str],
        interlocutor_actor_ids: list[str],
        stimulus: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Project one least-authority context envelope for host-side reasoning."""

        if purpose not in BOUNDED_EVALUATION_PURPOSES:
            raise ValueError(f"unsupported bounded evaluation purpose: {purpose}")
        facts = [dict(item) for item in list(result.get("facts") or [])]
        events_context = [dict(item) for item in list(result.get("events") or [])]
        actor_knowledge = [dict(item) for item in list(result.get("actor_knowledge") or [])]
        source_evidence = [dict(item) for item in list(result.get("module_evidence") or [])]
        scene = deepcopy(result.get("scoped_scene"))
        subject: dict[str, Any]
        normalized_stimulus: dict[str, Any] | None = None
        actor_projection: dict[str, Any] | None = None
        actor_revision: int | None = None
        interlocutors: list[dict[str, Any]] = []

        if purpose == "actor_turn":
            if not actor_id:
                raise ValueError("actor_id is required for actor_turn")
            actor = characters.get(actor_id)
            if actor.campaign_id != campaign_id:
                raise ValueError("actor_turn actor belongs to another campaign")
            require_agent_decidable_character_type(actor.character_type)
            subject_ref = f"actor:{actor_id}"
            subject = {"kind": "actor", "id": actor_id, "name": actor.name}
            actor_projection = npc_turn_actor_projection(actor)
            actor_revision = actor.revision
            normalized_stimulus = normalize_npc_stimulus(stimulus)
            for interlocutor_id in interlocutor_actor_ids:
                if interlocutor_id == actor_id:
                    raise ValueError("actor_turn subject cannot also be an interlocutor")
                interlocutor = characters.get(interlocutor_id)
                if interlocutor.campaign_id != campaign_id:
                    raise ValueError("actor_turn interlocutors must belong to the campaign")
                interlocutors.append(
                    {
                        "id": interlocutor.id,
                        "name": interlocutor.name,
                        "character_type": interlocutor.character_type,
                    }
                )
            actor_state, _fact_heads, _knowledge_heads = npc_turn_actor_state(
                campaign_id, branch_id, actor_id
            )
            facts = actor_state
            actor_projection["perception"] = npc_turn_perception_projection(
                campaigns.get(campaign_id),
                actor_id=actor_id,
                interlocutors=interlocutors,
                scene=npc_turn_scene_projection(scene),
            )
            scene = npc_turn_scene_projection(scene)
            events_context = [
                {
                    "id": event.id,
                    "sequence": event.sequence,
                    "event_type": event.event_type,
                    "summary": event.summary,
                    "participants": [dict(item) for item in event.participants],
                }
                for event in events.list_for_actor(
                    campaign_id,
                    actor_id=actor_id,
                    branch_id=branch_id,
                    limit=20,
                )
            ]
            target_refs = sorted(
                {f"actor:{actor_id}", *(f"actor:{item}" for item in interlocutor_actor_ids)}
            )
        elif purpose == "faction_turn":
            normalized_subject_ref = normalize_context_entity_ref(subject_ref, field="subject_ref")
            if not normalized_subject_ref.startswith("faction:"):
                raise ValueError("faction_turn subject_ref must use faction:<id>")
            subject_ref = normalized_subject_ref
            faction_id = normalized_subject_ref.removeprefix("faction:")
            subject = {"kind": "faction", "id": faction_id, "name": faction_id}
            facts = [
                asdict(item)
                for item in subject_contexts.list(
                    campaign_id,
                    subject_ref=normalized_subject_ref,
                    branch_id=branch_id,
                )
            ]
            if not facts:
                raise ValueError("faction_turn subject has no faction_state or faction_knowledge")
            events_context = []
            actor_knowledge = []
        elif purpose == "audience_render":
            subject_id = actor_id or audience or "party"
            subject_ref = f"audience:{subject_id}"
            subject = {"kind": "audience", "id": subject_id, "name": audience}
            source_evidence = []
            target_refs = []
        elif purpose == "source_interpretation":
            if not query.strip():
                raise ValueError("query is required for source_interpretation")
            if not source_evidence:
                raise ValueError(
                    "source_interpretation requires pinned module evidence; provide "
                    "related_refs for a current context_anchor"
                )
            source_id = hashlib.sha256(canonical_json(source_evidence).encode("utf-8")).hexdigest()
            subject_ref = f"source:{source_id}"
            subject = {"kind": "source", "id": source_id, "name": "module evidence"}
            facts = []
            events_context = []
            actor_knowledge = []
            target_refs = []
        else:
            if not query.strip():
                raise ValueError("query is required for bounded_ruling")
            ruling_id = hashlib.sha256(query.strip().encode("utf-8")).hexdigest()
            subject_ref = f"ruling:{ruling_id}"
            subject = {"kind": "ruling", "id": ruling_id, "name": "DM ruling"}

        fact_context: list[dict[str, Any]] = []
        event_context: list[dict[str, Any]] = []
        knowledge_context: list[dict[str, Any]] = []
        source_context: list[dict[str, Any]] = []
        allowed_basis_refs: set[str] = set()
        claim_basis_refs: set[str] = set()
        decision_only_basis_refs: set[str] = set()
        context_heads: dict[str, str] = {}
        knowledge_heads: dict[str, str] = {}
        knowledge_actor_ids: set[str] = set()
        if actor_id and purpose in {"actor_turn", "audience_render", "bounded_ruling"}:
            # Bind even an empty knowledge set. Otherwise the first fact learned
            # after bundle issuance would not invalidate an actor-scoped proposal.
            knowledge_actor_ids.add(actor_id)

        for item in facts:
            memory_id = str(item.get("id") or "")
            revision_id = str(item.get("revision_id") or "")
            if not memory_id or not revision_id:
                continue
            basis_ref = f"fact:{memory_id}:{revision_id}"
            fact_context.append({**item, "basis_ref": basis_ref})
            allowed_basis_refs.add(basis_ref)
            claim_basis_refs.add(basis_ref)
            context_heads[memory_id] = revision_id
        for item in actor_knowledge:
            knowledge_id = str(item.get("id") or "")
            revision_id = str(item.get("revision_id") or "")
            if not knowledge_id or not revision_id:
                continue
            basis_ref = f"knowledge:{knowledge_id}:{revision_id}"
            knowledge_context.append({**item, "basis_ref": basis_ref})
            allowed_basis_refs.add(basis_ref)
            claim_basis_refs.add(basis_ref)
            knowledge_heads[knowledge_id] = revision_id
            knowledge_actor_id = str(item.get("actor_id") or "")
            if knowledge_actor_id:
                knowledge_actor_ids.add(knowledge_actor_id)
        for item in events_context:
            event_id = str(item.get("id") or "")
            if not event_id:
                continue
            basis_ref = f"event:{event_id}"
            event_context.append({**item, "basis_ref": basis_ref})
            allowed_basis_refs.add(basis_ref)
            claim_basis_refs.add(basis_ref)
        for item in source_evidence:
            basis_ref = (
                "source:"
                + hashlib.sha256(
                    canonical_json(
                        {
                            "source_ref": item.get("source_ref"),
                            "source_excerpt": item.get("source_excerpt"),
                        }
                    ).encode("utf-8")
                ).hexdigest()
            )
            source_context.append(
                {
                    **item,
                    "basis_ref": basis_ref,
                    "context_role": (
                        "decision_only" if purpose in {"actor_turn", "faction_turn"} else "evidence"
                    ),
                }
            )
            allowed_basis_refs.add(basis_ref)
            if purpose in {"actor_turn", "faction_turn"}:
                decision_only_basis_refs.add(basis_ref)
            else:
                claim_basis_refs.add(basis_ref)
        question_ref = "question:" + hashlib.sha256(query.encode("utf-8")).hexdigest()
        if query:
            allowed_basis_refs.add(question_ref)
            decision_only_basis_refs.add(question_ref)
        if actor_projection is not None:
            for suffix in ("identity", "self_state"):
                basis_ref = f"actor:{actor_id}:{suffix}"
                allowed_basis_refs.add(basis_ref)
                claim_basis_refs.add(basis_ref)
        if normalized_stimulus is not None and normalized_stimulus.get("kind") != "none":
            stimulus_ref = (
                "stimulus:"
                + hashlib.sha256(canonical_json(normalized_stimulus).encode("utf-8")).hexdigest()
            )
            normalized_stimulus = {**normalized_stimulus, "basis_ref": stimulus_ref}
            allowed_basis_refs.add(stimulus_ref)
            claim_basis_refs.add(stimulus_ref)
        for anchor in memories.list(
            campaign_id,
            kind="context_anchor",
            branch_id=branch_id,
        ):
            metadata = dict(anchor.metadata or {})
            if related_refs & {str(ref) for ref in metadata.get("related_refs") or []}:
                context_heads[str(anchor.id)] = str(anchor.revision_id)

        bundle: dict[str, Any] = {
            "schema_version": BOUNDED_EVALUATION_SCHEMA_VERSION,
            "bundle_id": str(uuid4()),
            "purpose": purpose,
            "authority": {
                "campaign_id": campaign_id,
                "branch_id": branch_id,
                "head_snapshot_id": branches.get(campaign_id, branch_id).head_snapshot_id,
                "campaign_revision": campaigns.get(campaign_id).revision,
                "latest_event_sequence": npc_turn_latest_event_sequence(campaign_id, branch_id),
                "host_context_binding": host_context_binding(
                    campaign_id=campaign_id,
                    branch_id=branch_id,
                    principal_id=principal_id,
                    role=role,
                    audience=audience,
                ),
            },
            "subject": subject,
            "context": {
                "question": query,
                "question_basis_ref": question_ref if query else "",
                "actor": actor_projection,
                "interlocutors": interlocutors,
                "stimulus": normalized_stimulus,
                "facts": fact_context,
                "actor_knowledge": knowledge_context,
                "events": event_context,
                "scene": scene,
                "source_evidence": source_context,
                "audience": audience,
            },
            "constraints": {
                "allowed_basis_refs": sorted(allowed_basis_refs),
                "allowed_claim_basis_refs": sorted(claim_basis_refs),
                "decision_only_basis_refs": sorted(decision_only_basis_refs),
                "allowed_target_refs": sorted(set(target_refs)),
                "may_roll_dice": False,
                "may_call_tools": False,
                "may_write_state": False,
                "output_contract": BOUNDED_OUTPUT_CONTRACTS[purpose],
            },
        }
        bundle["bundle_receipt"] = issue_bounded_evaluation_receipt(
            bundle=bundle,
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            purpose=purpose,
            subject_ref=str(subject_ref),
            allowed_basis_refs=sorted(allowed_basis_refs),
            allowed_claim_basis_refs=sorted(claim_basis_refs),
            allowed_target_refs=sorted(set(target_refs)),
            context_heads=context_heads,
            knowledge_heads=knowledge_heads,
            knowledge_actor_ids=sorted(knowledge_actor_ids),
            actor_revision=actor_revision,
            scene=npc_turn_scene_projection(scene),
        )
        return bundle

    def character_view(
        character: Any,
        *,
        rules_context: Any = rules_context_unset,
    ) -> dict[str, Any]:
        """Return a raw validated sheet together with its non-persisted derived view."""
        value = asdict(character)
        try:
            resolved_rules = rules_context
            if resolved_rules is rules_context_unset:
                resolved_rules = (
                    effective_rule_context(character.campaign_id) if character.campaign_id else None
                )
            value["derived"] = derive_character_sheet(value["sheet"], rules=resolved_rules)
        except RulesetUnavailableError as error:
            value["derived"] = derive_character_sheet(value["sheet"])
            value["derived"]["unresolved_rules"] = sorted(
                {*value["derived"].get("unresolved_rules", []), "ruleset_unavailable"}
            )
            value["ruleset_error"] = str(error)
        return value

    def public_character_view(character: Any) -> dict[str, Any]:
        """Return the campaign-safe card for actors a player does not control."""
        return {
            "id": character.id,
            "campaign_id": character.campaign_id,
            "system_id": character.system_id,
            "character_type": character.character_type,
            "name": character.name,
            "summary": character.summary,
            "revision": character.revision,
        }

    def canonical_character_notes(
        notes: dict[str, Any] | None,
        *,
        character_type: str,
        name: str,
        summary: str = "",
    ) -> dict[str, Any]:
        """Normalize actor notes and supply the required NPC summary."""

        value = validate_character_notes(notes or default_character_notes())
        if character_type in NON_PLAYER_CHARACTER_TYPES and not value["profile"]["summary"]:
            value["profile"]["summary"] = str(summary).strip() or str(name).strip()
        return validate_character_notes(value, character_type=character_type)

    def library_character_view(character: Any, principal_id: str) -> dict[str, Any]:
        """Keep reusable sheets usable without exposing campaign-less private notes."""
        if principal_id == LOCAL_SYSTEM_PRINCIPAL_ID:
            return character_view(character)
        value = character_view(character)
        value.pop("notes", None)
        value.pop("player_name", None)
        value["notes_redacted"] = True
        return value

    def is_dm(campaign_id: str, principal_id: str) -> bool:
        return access.require_campaign(campaign_id, principal_id).role in CAMPAIGN_DM_ROLES

    def normalized_advancement_mode(mode: Any) -> str:
        value = str(mode or "").strip().casefold()
        if value not in ADVANCEMENT_MODES:
            raise ValueError("advancement mode must be milestone or xp")
        return value

    def campaign_advancement_mode(campaign: Any) -> str:
        advancement = dict((campaign.settings or {}).get("advancement") or {})
        try:
            return normalized_advancement_mode(advancement.get("mode"))
        except ValueError as error:
            raise CombatEngineError(
                "campaign advancement mode is not configured; "
                "use campaign_change(action='advancement_configure') in lobby"
            ) from error

    def require_character_control(character: Any, principal_id: str) -> None:
        if character.campaign_id is None:
            if principal_id != LOCAL_SYSTEM_PRINCIPAL_ID:
                raise PermissionError("only the local service may modify library characters")
            return
        access.require_actor(character.campaign_id, character.id, principal_id, control=True)

    def require_outside_active_combat(character: Any, operation: str) -> None:
        """Keep direct card mutations from bypassing encounter action economy."""
        if character.campaign_id is None:
            return
        combat = dict(campaigns.get(character.campaign_id).state or {}).get("combat")
        if isinstance(combat, dict) and combat.get("active", False):
            raise CombatEngineError(f"{operation} is not allowed while combat is active")

    def visible_character_view(character: Any, principal_id: str) -> dict[str, Any]:
        if character.campaign_id is None:
            if principal_id != LOCAL_SYSTEM_PRINCIPAL_ID:
                return public_character_view(character)
            return character_view(character)
        if is_dm(character.campaign_id, principal_id):
            return character_view(character)
        try:
            access.require_actor(character.campaign_id, character.id, principal_id, private=True)
        except PermissionError:
            return public_character_view(character)
        return character_view(character)

    def combat_actor_snapshot(character_id: str) -> dict[str, Any]:
        """Build the pure engine input from the canonical Character row."""
        return character_view(characters.get(character_id))

    def require_campaign_actor(campaign_id: str, character_id: str) -> Any:
        character = characters.get(character_id)
        if character.campaign_id != campaign_id:
            raise ValueError("actor does not belong to the campaign")
        return character

    def narrative_only_actor(character: Any) -> bool:
        tags = {
            str(item).strip().casefold()
            for item in dict(character.sheet.get("adventure_state") or {}).get("status_tags", [])
        }
        return "narrative_only" in tags

    def combat_card_analysis(character: Any) -> dict[str, Any]:
        """Separate card validity, actor state, and capability-local restrictions."""
        view = character_view(character)
        derived = dict(view.get("derived") or {})
        sheet = dict(view.get("sheet") or {})
        attacks = list(dict(derived.get("inventory") or {}).get("weapon_attacks") or [])
        multiattacks = list(derived.get("multiattack_options") or [])
        spellcasting = dict(derived.get("spellcasting") or {})
        prepared_spells = list(spellcasting.get("prepared_spell_ids") or [])
        unresolved = list(derived.get("unresolved_rules") or [])
        hit_points = int(dict(derived.get("hit_points") or {}).get("value", 0) or 0)
        conditions = {str(item).strip().casefold() for item in sheet.get("conditions", [])}
        hard_blockers: list[str] = []
        state_flags: list[str] = []
        disabled_capabilities: list[dict[str, str]] = [
            {
                "id": f"rule:{index + 1}",
                "kind": "rule",
                "reason": str(reason),
            }
            for index, reason in enumerate(unresolved)
        ]
        if narrative_only_actor(character):
            hard_blockers.append("narrative_only_noncombat")
        if hit_points <= 0:
            state_flags.append("zero_hit_points")
        if "dead" in conditions:
            state_flags.append("dead")
        dm_notes = str(
            dict(dict(view.get("notes") or {}).get("profile") or {}).get("dm_notes") or ""
        )
        note_lines = dm_notes.splitlines()
        statblock_provenance_prefixes = (
            "Statblock import:",
            "Reviewed rule statblock:",
            "Reviewed module statblock:",
        )
        provenance_indices = [
            index
            for index, line in enumerate(note_lines)
            if line.strip().startswith(statblock_provenance_prefixes)
        ]
        if provenance_indices:
            note_lines = note_lines[provenance_indices[-1] :]
        manual_rulings: list[str] = []
        normalization_notes: list[str] = []
        for line in note_lines:
            if "Manual rulings:" in line:
                value = line.split("Manual rulings:", 1)[1].strip().rstrip(".")
                value = value.partition(" Variant source:")[0].rstrip(". ")
                manual_rulings.extend(item.strip() for item in value.split(";") if item.strip())
            if "Normalization notes:" in line:
                value = line.split("Normalization notes:", 1)[1].strip().rstrip(".")
                normalization_notes.extend(
                    item.strip() for item in value.split(";") if item.strip()
                )
        manual_rulings = list(dict.fromkeys(manual_rulings))
        normalization_notes = list(dict.fromkeys(normalization_notes))
        specific_multiattacks = {
            item.split(":", 1)[0]
            for item in manual_rulings
            if item.endswith("Multiattack composition requires a DM ruling")
        }
        manual_rulings = [
            item
            for item in manual_rulings
            if not (
                item.endswith("descriptive action is not automatically settled")
                and item.split(":", 1)[0] in specific_multiattacks
            )
        ]
        incomplete_spellcasting = any(
            item.endswith("no active spell artifact or complete statblock action exists")
            or (
                item.startswith("Spellcasting:")
                and item.endswith("descriptive passive is not automatically settled")
            )
            for item in manual_rulings
        )
        if incomplete_spellcasting:
            disabled_capabilities.append(
                {
                    "id": "spellcasting",
                    "kind": "spellcasting",
                    "reason": "incomplete_statblock_spell_hydration",
                }
            )
        inventory_items = {
            str(item.get("id") or ""): item
            for item in dict(sheet.get("inventory") or {}).get("items", [])
        }
        for attack in attacks:
            attack_id = str(attack.get("item_id") or "")
            attack_name = str(attack.get("name") or attack_id or "Weapon")
            attack_item = dict(inventory_items.get(attack_id) or {})
            properties = {str(item).strip().casefold() for item in attack.get("properties", [])}
            if (
                str(attack.get("attack_type") or "melee").casefold() == "ranged"
                and int(dict(attack.get("range_ft") or {}).get("normal", 0) or 0) <= 0
            ):
                if _has_source_defined_positional_targeting(attack_item.get("description")):
                    reason = (
                        f"{attack_name}: source-defined positional targeting requires a DM ruling"
                    )
                else:
                    reason = f"{attack_name}: ranged weapon range is missing"
                    disabled_capabilities.append(
                        {"id": attack_id, "kind": "attack", "reason": reason}
                    )
                manual_rulings.append(reason)
            if (
                "thrown" in properties
                and int(dict(attack.get("thrown_range_ft") or {}).get("normal", 0) or 0) <= 0
            ):
                reason = f"{attack_name}: thrown weapon range is missing"
                manual_rulings.append(reason)
                disabled_capabilities.append({"id": attack_id, "kind": "attack", "reason": reason})
            ammunition_id = str(attack.get("ammunition_item_id") or "")
            if (
                ammunition_id
                and int(dict(inventory_items.get(ammunition_id) or {}).get("quantity", 0) or 0) <= 0
            ):
                disabled_capabilities.append(
                    {
                        "id": attack_id,
                        "kind": "attack",
                        "reason": f"ammunition {ammunition_id} is unavailable",
                    }
                )

        spell_resolution_audit = audit_spell_resolution_paths(sheet)
        automatic_spell_ids: list[str] = []
        ruling_spell_ids: list[str] = []
        incomplete_spell_ids: list[str] = []
        for entry in spell_resolution_audit["entries"]:
            if not entry["available"]:
                continue
            spell_id = str(entry["spell_id"])
            path = str(entry["resolution_path"])
            if path in {
                "engine_mechanic",
                "semantic_plan",
                "structured_resolution",
            }:
                automatic_spell_ids.append(spell_id)
            elif path == "agent_ruling":
                ruling_spell_ids.append(spell_id)
            else:
                incomplete_spell_ids.append(spell_id)
        if ruling_spell_ids:
            manual_rulings.append(
                "Available spells require Agent effect settlement: " + ", ".join(ruling_spell_ids)
            )
        if incomplete_spell_ids:
            manual_rulings.append(
                "Available spells lack a recorded settlement path: "
                + ", ".join(incomplete_spell_ids)
            )
            disabled_capabilities.extend(
                {
                    "id": spell_id,
                    "kind": "spell",
                    "reason": "spell lacks a recorded settlement path",
                }
                for spell_id in incomplete_spell_ids
            )
        manual_rulings = list(dict.fromkeys(manual_rulings))
        character_type = str(view.get("character_type") or "")
        ruling_requirements = [
            *[
                _ruling_requirement(
                    str(rule),
                    "missing_or_conflicting_source_review",
                )
                for rule in unresolved
            ],
            *[
                _ruling_requirement(
                    reason,
                    statblock_ruling_kind(
                        reason,
                        character_type=character_type,
                    ),
                )
                for reason in manual_rulings
            ],
        ]
        settlement = (
            "source_review_required" if unresolved else "mixed" if manual_rulings else "automatic"
        )
        disabled_capabilities = list(
            {
                (item["id"], item["kind"], item["reason"]): item for item in disabled_capabilities
            }.values()
        )
        disabled_ids = {item["id"] for item in disabled_capabilities}
        available_capabilities = [
            {"id": "unarmed-strike", "kind": "attack"},
            *[
                {"id": str(item.get("item_id") or ""), "kind": "attack"}
                for item in attacks
                if str(item.get("item_id") or "") not in disabled_ids
            ],
            *[
                {"id": spell_id, "kind": "spell"}
                for spell_id in [*automatic_spell_ids, *ruling_spell_ids]
                if spell_id not in disabled_ids and not incomplete_spellcasting
            ],
        ]
        return {
            "card_valid": not hard_blockers,
            "hard_blockers": sorted(set(hard_blockers)),
            "state_flags": sorted(set(state_flags)),
            "can_take_turn": not state_flags,
            "disabled_capabilities": disabled_capabilities,
            "available_capabilities": available_capabilities,
            "settlement": settlement,
            "default_dm_resolver": "agent",
            "unresolved_rules": unresolved,
            "manual_rulings": manual_rulings,
            "normalization_notes": normalization_notes,
            "ruling_requirements": ruling_requirements,
            "agent_rulings": [
                item["reason"]
                for item in ruling_requirements
                if item["default_resolver"] == "agent"
            ],
            "external_source_gaps": [
                item["reason"]
                for item in ruling_requirements
                if item["default_resolver"] == "external_input"
            ],
            "hit_points": hit_points,
            "maximum_hit_points": int(dict(derived.get("hit_points") or {}).get("max", 0) or 0),
            "armor_class": int(derived.get("armor_class", 10) or 10),
            "weapon_attack_ids": [str(item.get("item_id") or "") for item in attacks],
            "multiattack_option_ids": [str(item.get("id") or "") for item in multiattacks],
            "prepared_spell_ids": prepared_spells,
            "available_spell_ids": spell_resolution_audit["available_spell_ids"],
            "cantrip_spell_ids": spell_resolution_audit["cantrip_spell_ids"],
            "spell_resolution_audit": spell_resolution_audit,
            "automatic_spell_ids": automatic_spell_ids,
            "ruling_spell_ids": ruling_spell_ids,
            "incomplete_spell_ids": incomplete_spell_ids,
            "unarmed_fallback": True,
            "unarmed_attack_id": "unarmed-strike",
        }

    def statblock_variant_evidence(
        campaign_id: str,
        variant: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Resolve every variant citation instead of trusting free-form source labels."""
        if variant is None:
            return None
        if not isinstance(variant, dict):
            raise ValueError("statblock variant must be an object")
        source_refs = []
        source_ref = str(variant.get("source_ref") or "").strip()
        if source_ref:
            source_refs.append(source_ref)
        additional_source_refs = variant.get("source_refs", [])
        if not isinstance(additional_source_refs, list):
            raise ValueError("statblock variant source_refs must be a list")
        source_refs.extend(str(item).strip() for item in additional_source_refs)
        if any(not item for item in source_refs) or not source_refs:
            raise ValueError(
                "statblock variant source_ref or source_refs must identify managed sources"
            )
        if len(source_refs) != len(set(source_refs)):
            raise ValueError("statblock variant source refs must be unique")

        def resolve(source: str) -> dict[str, Any]:
            kind, separator, identifier = source.partition(":")
            if not separator or not identifier:
                raise ValueError("statblock variant source refs must identify managed sources")
            if kind == "module-chunk":
                try:
                    expanded = modules.expand(identifier)
                except (LookupError, NoResultFound) as error:
                    raise ValueError(
                        "statblock variant module chunk is unavailable; call "
                        "module_search and module_expand, then copy the exact returned "
                        "chunk id instead of a route label, heading, page, or scene id"
                    ) from error
                if str(expanded.get("campaign_id") or "") != campaign_id:
                    raise ValueError("statblock variant module chunk does not belong to campaign")
                return {
                    "source_ref": source,
                    "kind": kind,
                    "id": identifier,
                    "module_id": expanded["module"]["id"],
                    "scene_id": expanded["scene"]["id"],
                    "page_start": expanded.get("page_start"),
                    "page_end": expanded.get("page_end"),
                }
            if kind == "module-review":
                review = modules.get_content_review(campaign_id, identifier)
                return {
                    "source_ref": source,
                    "kind": kind,
                    "id": identifier,
                    "module_id": review["module_id"],
                    "scene_id": review["scene_id"],
                    "evidence": deepcopy(review.get("evidence") or {}),
                }
            if kind == "rule-chunk":
                expanded = rules.expand(identifier)
                rule_source = rules.source(str(expanded["source"]["id"]))
                campaign_edition = campaign_rules_edition(campaign_id)
                if str(rule_source.get("system_id") or "") != DND5E.id:
                    raise ValueError("statblock variant rule chunk must belong to D&D")
                if str(rule_source.get("edition") or "") != campaign_edition:
                    raise ValueError("statblock variant rule chunk edition does not match campaign")
                return {
                    "source_ref": source,
                    "kind": kind,
                    "id": identifier,
                    "source_id": rule_source["id"],
                    "source_key": rule_source["source_key"],
                    "checksum": rule_source["checksum"],
                }
            raise ValueError(
                "statblock variant source refs must use module-chunk, module-review, or rule-chunk"
            )

        sources = [resolve(item) for item in source_refs]
        if len(sources) == 1:
            return sources[0]
        return {
            "kind": "multiple",
            "source_refs": source_refs,
            "sources": sources,
        }

    def statblock_variant_source_label(variant: dict[str, Any]) -> str:
        source_refs = []
        source_ref = str(variant.get("source_ref") or "").strip()
        if source_ref:
            source_refs.append(source_ref)
        source_refs.extend(str(item).strip() for item in variant.get("source_refs", []))
        return ", ".join(source_refs)

    def reviewed_statblock_fill_evidence(
        campaign_id: str,
        agent_fill: dict[str, Any] | None,
        *,
        rule_source_id: str | None = None,
        module_id: str | None = None,
        page_number: int | None = None,
    ) -> list[dict[str, Any]]:
        """Verify every Agent-added attack against one managed source excerpt."""

        if not isinstance(agent_fill, dict):
            return []
        declarations = agent_fill.get("additional_actions", [])
        if not isinstance(declarations, list):
            raise ValueError("reviewed additional_actions must be a list")
        evidence: list[dict[str, Any]] = []
        for index, declaration in enumerate(declarations):
            if not isinstance(declaration, dict):
                raise ValueError(f"reviewed additional action {index} must be an object")
            source_ref = str(declaration.get("source_ref") or "").strip()
            source_excerpt = " ".join(str(declaration.get("source_excerpt") or "").split())
            kind, separator, identifier = source_ref.partition(":")
            if not separator or not identifier or not source_excerpt:
                raise ValueError(
                    f"reviewed additional action {index} requires managed source "
                    "evidence and an exact excerpt"
                )
            if rule_source_id is not None:
                if kind != "rule-chunk":
                    raise ValueError(
                        "reviewed rule-statblock additional actions must cite rule-chunk"
                    )
                expanded = rules.expand(identifier)
                expanded_source_id = str(dict(expanded.get("source") or {}).get("id") or "")
                if expanded_source_id != rule_source_id:
                    raise ValueError(
                        "reviewed additional action rule chunk does not belong to "
                        "the reviewed statblock source"
                    )
            elif module_id is not None:
                if kind != "module-chunk":
                    raise ValueError(
                        "reviewed module-statblock additional actions must cite module-chunk"
                    )
                expanded = modules.expand(identifier)
                if str(dict(expanded.get("module") or {}).get("id") or "") != module_id:
                    raise ValueError(
                        "reviewed additional action module chunk does not belong "
                        "to the reviewed module"
                    )
            else:
                raise RuntimeError("reviewed additional action validation has no source boundary")
            source_content = str(expanded.get("content") or "")
            compact_excerpt = _compact_agent_evidence(source_excerpt)
            compact_content = _compact_agent_evidence(source_content)
            if not compact_excerpt or not _agent_evidence_supports_fact(
                compact_excerpt,
                compact_content,
                max_edits=min(12, max(2, len(compact_excerpt) // 75)),
            ):
                raise ValueError(
                    "reviewed additional action source_excerpt is absent from "
                    f"managed source {source_ref}"
                )
            page_start = expanded.get("page_start")
            page_end = expanded.get("page_end")
            if (
                page_number is not None
                and page_start is not None
                and page_end is not None
                and not int(page_start) <= page_number <= int(page_end)
            ):
                raise ValueError(
                    "reviewed additional action source evidence is not on the "
                    "reviewed statblock page"
                )
            evidence.append(
                {
                    "source_ref": source_ref,
                    "kind": kind,
                    "id": identifier,
                    "page_start": page_start,
                    "page_end": page_end,
                    "content_sha256": hashlib.sha256(source_content.encode("utf-8")).hexdigest(),
                    "source_excerpt_sha256": hashlib.sha256(
                        source_excerpt.encode("utf-8")
                    ).hexdigest(),
                }
            )
        return evidence

    def reviewed_statblock_fill_labels(fill: dict[str, Any]) -> list[str]:
        return [
            *[
                str(item.get("activity_id") or "")
                for item in fill.get("multiattack_options", [])
                if isinstance(item, dict)
            ],
            *[
                str(item.get("id") or item.get("name") or "")
                for item in fill.get("additional_actions", [])
                if isinstance(item, dict)
            ],
        ]

    def retained_statblock_warnings(
        warnings: list[str],
        variant: dict[str, Any] | None,
    ) -> list[str]:
        if variant is None:
            return warnings
        removed_subjects = {
            "-".join(str(item).strip().casefold().split())
            for field in ("remove_actions", "remove_items", "remove_activities")
            for item in variant.get(field, [])
        }
        removed_subjects.update(
            "-".join(str(action_id).strip().casefold().split())
            for action_id, override in dict(variant.get("action_overrides") or {}).items()
            if isinstance(override, dict) and override.get("remove_on_hit_effect") is True
        )
        return [
            warning
            for warning in warnings
            if "-".join(warning.partition(":")[0].strip().casefold().split())
            not in removed_subjects
        ]

    def statblock_agent_fill_requirements(
        sheet: dict[str, Any],
    ) -> dict[str, Any]:
        """Describe semantic statblock fields that the Agent must review.

        The text parser may propose a Multiattack composition, but reviewed source
        text is not allowed to make that lexical proposal authoritative.
        The Agent receives the exact activity prose plus the already-transcribed
        weapon ids and must submit the canonical composition explicitly.
        """

        activities = [
            activity
            for activity in dict(sheet.get("content") or {}).get("activities", [])
            if str(activity.get("name") or "").strip().casefold() == "multiattack"
        ]
        weapons = []
        for item in dict(sheet.get("inventory") or {}).get("items", []):
            if str(item.get("kind") or "") != "weapon":
                continue
            mechanics = dict(item.get("mechanics") or {})
            weapons.append(
                {
                    "weapon_id": str(item.get("id") or ""),
                    "name": str(item.get("name") or ""),
                    "attack_type": str(mechanics.get("attack_type") or "melee"),
                    "properties": sorted(str(value) for value in mechanics.get("properties") or []),
                }
            )
        return {
            "required": bool(activities),
            "default_resolver": "agent",
            "ruling_kind": "module_specific_procedure",
            "parser_authoritative": False,
            "allowed_resolutions": ["structured", "agent_ruling"],
            "submission_schema": {
                "root_fields": ["multiattack_options"],
                "declaration_fields": [
                    "activity_id",
                    "source_excerpt",
                    "reason",
                    "resolution",
                    "options",
                ],
                "structured_option_fields": ["id", "attacks"],
                "attack_fields": ["weapon_id", "attack_mode", "count"],
                "constraints": [
                    "activity_id and source_excerpt must copy one returned multiattack option",
                    "reason must contain 1 to 500 characters",
                    "structured resolution requires one or more options",
                    "option id must be a unique lowercase slug",
                    "weapon_id must copy one returned available weapon id",
                    "attack_mode must be melee or ranged and count must be positive",
                    "agent_ruling resolution must omit options",
                ],
            },
            "multiattack_options": [
                {
                    "activity_id": str(activity.get("id") or ""),
                    "source_excerpt": " ".join(str(activity.get("description") or "").split()),
                }
                for activity in activities
            ],
            "available_weapons": weapons,
        }

    def require_complete_statblock_agent_fill(
        sheet: dict[str, Any],
        agent_fill: dict[str, Any] | None,
    ) -> dict[str, Any]:
        requirements = statblock_agent_fill_requirements(sheet)
        if not requirements["required"]:
            return requirements
        if not isinstance(agent_fill, dict):
            raise ValueError(
                "reviewed statblock Multiattack requires an Agent statblock fill; "
                "the text parser is not authoritative for reviewed composition"
            )
        declarations = agent_fill.get("multiattack_options")
        if not isinstance(declarations, list):
            raise ValueError("reviewed statblock Agent fill must contain multiattack_options")
        expected_ids = {str(item["activity_id"]) for item in requirements["multiattack_options"]}
        submitted_ids = {
            str(item.get("activity_id") or "") for item in declarations if isinstance(item, dict)
        }
        if submitted_ids != expected_ids or len(declarations) != len(expected_ids):
            raise ValueError(
                "reviewed statblock Agent fill must cover every source Multiattack "
                "activity exactly once; expected "
                f"{sorted(expected_ids)}, received {sorted(submitted_ids)}"
            )
        return requirements

    def require_standard_statblock_engine_support(
        sheet: dict[str, Any],
        agent_fill: dict[str, Any] | None,
        *,
        statblock_warnings: list[str] | tuple[str, ...] = (),
        spell_warnings: list[str] | tuple[str, ...] = (),
    ) -> dict[str, Any]:
        """Keep canonical rulebook mechanics authoritative in the engine.

        An Agent may transcribe a damaged text layer, but it must not redefine
        standard mechanics while doing so. Structured Multiattack choices
        produced by the D&D parser are therefore authoritative. A creature's
        genuinely open, conditional, or special-action composition is content,
        however, rather than another implementation of action economy. Such a
        composition is accepted only when the parser already persisted the
        exact excerpt as a direct Agent-as-DM ruling boundary; no first-use
        semantic authoring is permitted.
        """

        if agent_fill is not None:
            raise ValueError(
                "standard rule statblocks do not accept Agent semantic fills; "
                "implement the printed mechanic in the D&D engine"
            )
        multiattacks = [
            activity
            for activity in dict(sheet.get("content") or {}).get("activities", [])
            if is_multiattack_source_name(activity.get("name"))
            or dict(dict(activity.get("choices") or {}).get("manual_ruling") or {}).get("kind")
            == "multiattack_composition"
        ]
        unresolved = [
            activity
            for activity in multiattacks
            if not isinstance(
                dict(activity.get("choices") or {}).get("multiattack_options"),
                list,
            )
            or not dict(activity.get("choices") or {}).get("multiattack_options")
        ]
        invalid_unresolved = []
        for activity in unresolved:
            manual_ruling = dict(dict(activity.get("choices") or {}).get("manual_ruling") or {})
            source_excerpt = " ".join(str(manual_ruling.get("source_excerpt") or "").split())
            description = " ".join(str(activity.get("description") or "").split())
            if (
                manual_ruling.get("kind") != "multiattack_composition"
                or manual_ruling.get("default_resolver") != "agent"
                or not source_excerpt
                or source_excerpt != description
                or bool(activity.get("mechanic_refs"))
            ):
                invalid_unresolved.append(activity)
        if invalid_unresolved:
            names = sorted(
                str(activity.get("name") or "Multiattack") for activity in invalid_unresolved
            )
            raise ValueError(
                "standard rule Multiattack lacks a complete engine option or "
                "non-executable direct source-bound ruling: " + ", ".join(names)
            )
        # A creature-specific activity or passive is content, not a new copy of
        # the standard action economy.  The parser deliberately records such a
        # card as an evidence-bound Agent ruling until a reusable resolution
        # plan is reviewed.  Only unresolved common mechanics below (such as a
        # Multiattack composition, required spell hydration, or parser warning)
        # are engine gaps that block a canonical rulebook card.
        unresolved_statblock_mechanics = sorted(
            str(warning).strip()
            for warning in statblock_warnings
            if str(warning).strip()
            and not is_statblock_normalization_note(str(warning).strip())
            and statblock_ruling_kind(str(warning).strip()) != "agent_dm_adjudication"
        )
        if unresolved_statblock_mechanics:
            raise ValueError(
                "standard rule statblock requires engine implementation: "
                + "; ".join(unresolved_statblock_mechanics)
            )
        incomplete_spells = sorted(
            warning
            for warning in spell_warnings
            if warning.endswith(
                (
                    "no active spell artifact or complete statblock action exists",
                    "multiple active spell artifacts match the statblock entry",
                )
            )
        )
        if incomplete_spells:
            raise ValueError(
                "standard rule spell list requires source recovery: " + "; ".join(incomplete_spells)
            )
        source_bound_rulings = sorted(
            str(warning).strip()
            for warning in statblock_warnings
            if str(warning).strip()
            and not is_statblock_normalization_note(str(warning).strip())
            and statblock_ruling_kind(str(warning).strip()) == "agent_dm_adjudication"
        )
        return {
            "required": False,
            "default_resolver": "agent" if source_bound_rulings else "engine",
            "ruling_kind": ("agent_dm_adjudication" if source_bound_rulings else "standard_rule"),
            "parser_authoritative": True,
            "allowed_resolutions": [
                "engine",
                *(["agent_dm_adjudication"] if source_bound_rulings else []),
            ],
            "source_bound_rulings": source_bound_rulings,
            "multiattack_options": [
                {
                    "activity_id": str(activity.get("id") or ""),
                    "source_excerpt": " ".join(str(activity.get("description") or "").split()),
                    "options": deepcopy(
                        dict(activity.get("choices") or {}).get("multiattack_options", [])
                    ),
                }
                for activity in multiattacks
            ],
            "available_weapons": [],
        }

    def is_canonical_standard_rule_source(source: dict[str, Any]) -> bool:
        """Identify rule corpora whose printed mechanics must be engine-owned."""

        publication_id = (
            str(source.get("publication_id") or "")
            .strip()
            .casefold()
            .replace("-", "")
            .replace("_", "")
        )
        return publication_id in {
            "srd",
            "srd2014",
            "mm2014",
            "monstermanual2014",
            "phb2014",
            "playershandbook2014",
            "dmg2014",
            "dungeonmastersguide2014",
        }

    def is_statblock_normalization_note(reason: str) -> bool:
        """Return whether a parser diagnostic proves safe exclusion, not a rule gap."""

        return reason.endswith(
            (
                "trailing creature prose excluded from action settlement",
                "trailing page furniture excluded from action settlement",
            )
        )

    def statblock_ruling_kind(reason: str, *, character_type: str = "") -> str:
        """Classify a card boundary without treating absent source facts as DM fiat."""

        if (
            reason.endswith("ranged weapon range is missing")
            or reason.endswith("thrown weapon range is missing")
            or reason.endswith("no active spell artifact or complete statblock action exists")
            or (
                reason.startswith("Spellcasting:")
                and reason.endswith("descriptive passive is not automatically settled")
            )
        ):
            return "missing_or_conflicting_source_review"
        if character_type == "pc" and reason.endswith("requires a reaction decision"):
            return "player_owned_choice"
        return "agent_dm_adjudication"

    def statblock_ruling_requirements(
        warnings: list[str],
        *,
        character_type: str = "",
    ) -> list[dict[str, Any]]:
        return [
            _ruling_requirement(
                reason,
                statblock_ruling_kind(reason, character_type=character_type),
            )
            for reason in warnings
        ]

    def statblock_settlement(
        warnings: list[str],
        *,
        normalization_notes: list[str] | None = None,
        character_type: str = "",
    ) -> dict[str, Any]:
        ruling_warnings = [
            warning for warning in warnings if not is_statblock_normalization_note(warning)
        ]
        notes = list(
            dict.fromkeys(
                [
                    *(normalization_notes or []),
                    *(warning for warning in warnings if is_statblock_normalization_note(warning)),
                ]
            )
        )
        requirements = statblock_ruling_requirements(
            ruling_warnings,
            character_type=character_type,
        )
        has_source_review = any(
            item["default_resolver"] == "external_input" for item in requirements
        )
        return {
            "warnings": ruling_warnings,
            "normalization_notes": notes,
            "settlement": (
                "automatic"
                if not requirements
                else "source_review_required"
                if has_source_review
                else "mixed"
            ),
            "ruling_requirements": requirements,
            "default_dm_resolver": "agent",
        }

    def append_statblock_diagnostics(
        provenance: str,
        *,
        warnings: list[str],
        normalization_notes: list[str],
    ) -> str:
        """Persist executable boundaries separately from successful normalization."""

        if warnings:
            provenance += "\nManual rulings: " + "; ".join(warnings) + "."
        if normalization_notes:
            provenance += "\nNormalization notes: " + "; ".join(normalization_notes) + "."
        return provenance

    def persist_source_bound_statblock(
        *,
        data: dict[str, Any],
        campaign_id: str,
        character_type: str,
        name: str,
        summary: str,
        sheet: dict[str, Any],
        notes: dict[str, Any],
        principal_id: str,
        idempotency_key: str | None,
    ) -> dict[str, Any]:
        replace_character_id = str(data.get("replace_character_id") or "").strip()
        if not replace_character_id:
            return character_create(
                name,
                campaign_id,
                character_type,
                data.get("player_name"),
                summary,
                sheet,
                notes,
                principal_id,
                idempotency_key,
            )
        existing = characters.get(replace_character_id)
        if existing.campaign_id != campaign_id:
            raise ValueError("replacement statblock actor belongs to another campaign")
        if existing.character_type != character_type:
            raise ValueError("replacement statblock actor type must remain unchanged")
        expected_revision = data.get("expected_revision")
        if (
            not isinstance(expected_revision, int)
            or isinstance(expected_revision, bool)
            or expected_revision < 1
        ):
            raise ValueError("replacement statblock actor requires a positive expected_revision")
        if not idempotency_key:
            raise ValueError("replacement statblock actor requires idempotency_key")
        if name != existing.name:
            raise ValueError("replacement statblock must preserve the existing actor name")
        if summary != str(existing.summary or ""):
            raise ValueError("replacement statblock must preserve the existing actor summary")
        return update_character(
            existing,
            operation="character.statblock.replace",
            sheet=finalize_actor_sheet_rulings(sheet, campaign_id),
            notes=notes,
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=f"{idempotency_key}:replace-statblock",
            payload={
                "mode": "source_bound_statblock",
                "request": deepcopy(data),
            },
        )

    def source_bound_statblock_notes(
        *,
        data: dict[str, Any],
        campaign_id: str,
        character_type: str,
    ) -> dict[str, Any]:
        """Preserve an in-place actor's provenance unless notes are explicit."""

        if data.get("notes") is not None:
            return deepcopy(data["notes"])
        replace_character_id = str(data.get("replace_character_id") or "").strip()
        if not replace_character_id:
            return default_character_notes()
        existing = characters.get(replace_character_id)
        if existing.campaign_id != campaign_id:
            raise ValueError("replacement statblock actor belongs to another campaign")
        if existing.character_type != character_type:
            raise ValueError("replacement statblock actor type must remain unchanged")
        return deepcopy(existing.notes)

    def source_bound_statblock_summary(
        *,
        data: dict[str, Any],
        campaign_id: str,
        character_type: str,
        fallback: str,
    ) -> str:
        """Keep narrative identity text while attaching authoritative mechanics."""

        explicit = str(data.get("summary") or "").strip()
        if explicit:
            return explicit
        replace_character_id = str(data.get("replace_character_id") or "").strip()
        if not replace_character_id:
            return fallback
        existing = characters.get(replace_character_id)
        if existing.campaign_id != campaign_id:
            raise ValueError("replacement statblock actor belongs to another campaign")
        if existing.character_type != character_type:
            raise ValueError("replacement statblock actor type must remain unchanged")
        return str(existing.summary or "").strip() or fallback

    def combat_audience_view(
        campaign_id: str,
        principal_id: str,
        encounter: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Project a specific encounter revision without replacing it with live state."""

        if encounter is None:
            return None
        membership = access.require_campaign(campaign_id, principal_id)
        value = deepcopy(dict(encounter))
        if bool(encounter.get("active", False)):
            value["snapshot_role"] = "live_encounter"
            value["combatant_state_is_current"] = True
            value["current_character_state_source"] = "combat_and_character_query"
        else:
            value["snapshot_role"] = "historical_final_encounter"
            value["combatant_state_is_current"] = False
            value["current_character_state_source"] = "character_query"
        if membership.role not in CAMPAIGN_DM_ROLES:
            viewer_actor_ids: set[str] = set()
            for item in encounter.get("combatants", []):
                actor_id_value = str(item.get("actor_id") or "")
                try:
                    access.require_actor(
                        campaign_id,
                        actor_id_value,
                        principal_id,
                        private=True,
                    )
                except PermissionError:
                    continue
                viewer_actor_ids.add(actor_id_value)

            def player_can_see(item: dict[str, Any]) -> bool:
                actor_id_value = str(item.get("actor_id") or "")
                if actor_id_value in viewer_actor_ids:
                    return True
                concealed = bool(item.get("hidden", False)) or "invisible" in {
                    str(condition).casefold() for condition in item.get("conditions", [])
                }
                if not concealed:
                    return True
                visible_to = item.get("visible_to_actor_ids")
                return isinstance(visible_to, list) and bool(
                    viewer_actor_ids & {str(actor_id) for actor_id in visible_to}
                )

            visible_combatants = [
                {
                    key: item[key]
                    for key in ("actor_id", "token_id", "name", "initiative", "position")
                    if key in item
                }
                for item in encounter.get("combatants", [])
                if player_can_see(item)
            ]
            current = current_combatant(encounter)
            current_id = str(current.get("actor_id")) if current is not None else None
            visible_ids = [str(item.get("actor_id")) for item in visible_combatants]
            value["combatants"] = visible_combatants
            value["turn_index"] = (
                visible_ids.index(current_id) if current_id in visible_ids else None
            )
            value.pop("log", None)
            value.pop("rulings", None)
            value.pop("pending", None)
            value.pop("readied", None)
            value.pop("effects", None)
            value.pop("reinforcements", None)
            value.pop("participant_manifest", None)
            battle_map = value.get("battle_map")
            if isinstance(battle_map, dict):
                value["battle_map"] = {
                    key: deepcopy(battle_map[key])
                    for key in (
                        "id",
                        "schema_version",
                        "lifecycle",
                        "source",
                        "grid",
                        "bounds",
                    )
                    if key in battle_map
                }
        return value

    def combat_view(campaign_id: str, principal_id: str) -> dict[str, Any] | None:
        campaign = campaigns.get(campaign_id)
        encounter = dict(campaign.state or {}).get("combat")
        return combat_audience_view(campaign_id, principal_id, encounter)

    def party_public_combat_view(
        campaign_id: str,
        principal_id: str,
    ) -> dict[str, Any] | None:
        """Return a shared-party projection that cannot elevate the caller's view."""

        caller_view = combat_view(campaign_id, principal_id)
        if caller_view is None:
            return None
        value = deepcopy(caller_view)
        combatants = [
            dict(item)
            for item in value.get("combatants", [])
            if isinstance(item, dict)
            and not bool(item.get("hidden", False))
            and "invisible" not in condition_ids(item.get("conditions", []))
        ]
        current = current_combatant(caller_view)
        current_id = str(current.get("actor_id")) if current is not None else None
        visible_combatants = [
            {
                key: item[key]
                for key in ("actor_id", "token_id", "name", "initiative", "position")
                if key in item
            }
            for item in combatants
        ]
        visible_ids = [str(item.get("actor_id")) for item in visible_combatants]
        value["combatants"] = visible_combatants
        value["turn_index"] = visible_ids.index(current_id) if current_id in visible_ids else None
        for key in (
            "log",
            "rulings",
            "pending",
            "readied",
            "effects",
            "reinforcements",
            "participant_manifest",
        ):
            value.pop(key, None)
        battle_map = value.get("battle_map")
        if isinstance(battle_map, dict):
            value["battle_map"] = {
                key: deepcopy(battle_map[key])
                for key in ("id", "schema_version", "lifecycle", "source", "grid", "bounds")
                if key in battle_map
            }
        return value

    def render_combat_snapshot(
        campaign_id: str,
        principal_id: str,
        audience_projection: Literal["caller", "party_public"],
    ) -> list[Any]:
        """Render a read-only audience projection without affecting combat readiness."""

        if audience_projection == "party_public":
            encounter = party_public_combat_view(campaign_id, principal_id)
        else:
            encounter = combat_view(campaign_id, principal_id)
        if encounter is None:
            raise CombatEngineError("campaign has no combat snapshot to render")
        portraits: dict[str, bytes] = {}
        for combatant in encounter.get("combatants", []):
            if not isinstance(combatant, dict):
                continue
            actor_id_value = str(combatant.get("actor_id") or "")
            if not actor_id_value:
                continue
            character = characters.get(actor_id_value)
            portrait_ref = dict(
                dict(dict(character.notes or {}).get("profile") or {}).get("portrait_ref") or {}
            )
            portrait = storage.read_actor_image(str(portrait_ref.get("checksum") or ""))
            if portrait is not None:
                portraits[actor_id_value] = portrait
            if audience_projection != "caller":
                continue
            try:
                access.require_actor(campaign_id, actor_id_value, principal_id, private=True)
            except PermissionError:
                continue
            hp = dict(dict(character.sheet or {}).get("combat") or {}).get("hp")
            if isinstance(hp, dict):
                combatant["hp"] = {
                    "current": hp.get("value"),
                    "max": hp.get("max"),
                    "temporary": hp.get("temp"),
                }
        metadata, content = render_combat_png(
            encounter,
            portraits=portraits,
            audience_projection=audience_projection,
        )
        campaign = campaigns.get(campaign_id)
        metadata.update(
            {
                "campaign_id": campaign_id,
                "campaign_revision": campaign.revision,
                "view": "render",
                "render_is_authoritative": False,
                "combat_state_is_authoritative": True,
            }
        )
        return [metadata, Image(data=content, format="png")]

    def combat_response(
        campaign_id: str, principal_id: str, response: dict[str, Any]
    ) -> dict[str, Any]:
        """Project every combat write result through the same audience boundary."""
        value = dict(response)
        if "combat" in value:
            encounter = value.get("combat")
            value["combat"] = combat_audience_view(
                campaign_id,
                principal_id,
                dict(encounter) if isinstance(encounter, dict) else None,
            )
        if is_dm(campaign_id, principal_id):
            return value
        result = value.get("result")
        if isinstance(result, dict):
            allowed = {
                "kind",
                "attacker_id",
                "target_id",
                "hit",
                "critical",
                "fumble",
                "natural",
                "rolls",
                "rerolls",
                "total",
                "bonus",
                "success",
                "successes",
                "failures",
                "outcome",
                "amount",
                "applied_amount",
                "hp_damage",
                "healed",
                "after_hp",
                "effects_active",
                "conditions",
                "parts",
                "activity_id",
                "content_type",
                "name",
                "payment",
                "requires_ruling",
                "declaration",
                "defense",
                "reaction_defense",
                "pending_reaction",
                "spell_id",
                "cast_level",
                "resolution_id",
                "attack_count",
                "remaining_attacks",
                "spell_resolution",
            }
            value["result"] = {key: item for key, item in result.items() if key in allowed}
        value.pop("revisions", None)
        return value

    def resolution_rolls(resolution_id: str, result: dict[str, Any]) -> list[dict[str, Any]]:
        """Normalize trusted engine output without exposing arbitrary result fields."""

        normalized: list[dict[str, Any]] = []
        seen: set[int] = set()

        def visit(value: Any) -> None:
            if len(normalized) >= 32:
                return
            if isinstance(value, dict):
                dice = value.get("rolls")
                if not isinstance(dice, list) or not dice or not all(
                    isinstance(item, int) and not isinstance(item, bool) for item in dice
                ):
                    dice = value.get("dice")
                total = value.get("total")
                if (
                    isinstance(dice, list)
                    and dice
                    and all(isinstance(item, int) and not isinstance(item, bool) for item in dice)
                    and isinstance(total, int)
                    and not isinstance(total, bool)
                ):
                    identity = id(value)
                    if identity not in seen:
                        seen.add(identity)
                        natural = value.get("natural")
                        kept = [natural] if isinstance(natural, int) else list(dice)
                        modifier = value.get("modifier")
                        if not isinstance(modifier, int) or isinstance(modifier, bool):
                            modifier = int(total) - int(kept[0]) if len(kept) == 1 else 0
                        normalized.append(
                            {
                                "roll_id": f"{resolution_id}:roll:{len(normalized) + 1}",
                                "expression": str(value.get("expression") or "d20"),
                                "dice": list(dice),
                                "kept": kept,
                                "modifier": int(modifier),
                                "total": int(total),
                            }
                        )
                for child in value.values():
                    visit(child)
            elif isinstance(value, list):
                for child in value:
                    visit(child)

        visit(result)
        return normalized

    def resolution_outcome(result: dict[str, Any]) -> dict[str, Any]:
        allowed = {
            "kind",
            "success",
            "critical",
            "fumble",
            "hit",
            "successes",
            "failures",
            "outcome",
            "damage",
            "applied_amount",
            "hp_damage",
            "healed",
            "after_hp",
            "dc",
            "difficulty",
        }
        return {
            key: deepcopy(value)
            for key, value in result.items()
            if key in allowed and isinstance(value, (str, int, float, bool, type(None)))
        }

    def resolution_presentation_view(
        campaign_id: str,
        resolution_id: str,
        principal_id: str,
    ) -> dict[str, Any]:
        membership = access.require_campaign(campaign_id, principal_id)
        campaign = campaigns.get(campaign_id)
        events = [
            item
            for key in ("resolution_presentation_log", "resolution_log")
            for item in list(dict(campaign.state or {}).get(key) or [])
            if isinstance(item, dict) and str(item.get("id") or "") == resolution_id
        ]
        if len(events) != 1:
            raise LookupError("resolution presentation not found")
        event = deepcopy(events[0])
        audience = dict(event.get("audience") or {})
        actor_refs = [str(item) for item in audience.get("actor_refs") or []]
        scope = str(audience.get("scope") or ("actors" if actor_refs else "dm"))
        if scope == "dm" and membership.role not in CAMPAIGN_DM_ROLES:
            raise LookupError("resolution presentation not found")
        if scope == "principal" and (
            membership.role not in CAMPAIGN_DM_ROLES
            and str(event.get("principal_id") or "") != principal_id
        ):
            raise LookupError("resolution presentation not found")
        if scope == "actors" and membership.role not in CAMPAIGN_DM_ROLES:
            authorized = False
            for actor_ref in actor_refs:
                try:
                    access.require_actor(campaign_id, actor_ref, principal_id, private=True)
                except (LookupError, PermissionError):
                    continue
                authorized = True
                break
            if not authorized:
                raise LookupError("resolution presentation not found")
        result = deepcopy(dict(event.get("result") or {}))
        event_sequence = int(event.get("event_sequence") or 1)
        return {
            "schema": "sagasmith.resolution-presentation/v1",
            "resolution_id": resolution_id,
            "thread_id": str(event.get("thread_id") or resolution_id),
            "event_sequence": event_sequence,
            "system_id": DND5E.id,
            "campaign_id": campaign_id,
            "branch_id": event.get("branch_id"),
            "operation": str(event.get("operation") or event.get("type") or "resolution"),
            "status": str(event.get("status") or "settled"),
            "audience": {
                "scope": scope,
                "actor_refs": actor_refs if scope == "actors" else [],
                "disclosure": str(
                    audience.get("disclosure") or ("private" if scope == "actors" else "hidden")
                ),
            },
            "actor_refs": actor_refs,
            "rolls": resolution_rolls(resolution_id, result),
            "outcome": resolution_outcome(result),
            "pending_choice": deepcopy(event.get("pending_choice")),
            "campaign_revision": int(
                event.get("campaign_revision") or campaign.revision
            ),
            "random_stream_receipt": {
                key: deepcopy(value)
                for key, value in dict(event.get("random_stream_receipt") or {}).items()
                if key
                in {
                    "operation",
                    "cursor_before",
                    "cursor_after",
                    "position_before",
                    "position_after",
                    "draw_count",
                    "receipt_digest",
                }
            },
        }

    def current_branch_id(campaign_id: str) -> str | None:
        current = branches.current(campaign_id)
        return current.id if current is not None else None

    def authoritative_host_context_binding(
        campaign_id: str,
        principal_id: str,
        arguments: dict[str, Any] | None = None,
    ) -> dict[str, str] | None:
        """Resolve the current replay boundary from server-owned authorization state."""

        try:
            membership = access.require_campaign(campaign_id, principal_id)
        except (LookupError, PermissionError):
            return None
        branch_id = current_branch_id(campaign_id)
        if branch_id is None:
            return None
        values = dict(arguments or {})
        payload = values.get("payload")
        if isinstance(payload, dict):
            values = {**payload, **values}
        requested_audience = str(values.get("audience") or "").strip().casefold()
        if membership.role not in CAMPAIGN_DM_ROLES:
            audience = "player"
        elif requested_audience in {"dm", "player"}:
            audience = requested_audience
        else:
            audience = "dm"
        return host_context_binding(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            role=str(membership.role),
            audience=audience,
            authorization_fingerprint=access.authorization_fingerprint(
                campaign_id, principal_id
            ),
        )

    def active_encounter(campaign_id: str) -> tuple[Any, dict[str, Any]]:
        campaign = campaigns.get(campaign_id)
        encounter = dict(campaign.state or {}).get("combat")
        if not isinstance(encounter, dict) or not encounter.get("active", False):
            raise CombatEngineError("combat is not active")
        encounter_rules_edition(campaign_id, encounter)
        return campaign, encounter

    def encounter_rules_edition(
        campaign_id: str,
        encounter: dict[str, Any],
    ) -> str:
        """Verify the immutable encounter projection against the campaign profile."""

        authoritative = campaign_rules_edition(campaign_id)
        projected = str(encounter.get("ruleset") or "")
        if not projected:
            raise RuntimeError("active encounter has no ruleset projection")
        if projected != authoritative:
            raise RuntimeError("active encounter ruleset diverges from the campaign rule profile")
        return authoritative

    def require_encounter_combatant(
        encounter: dict[str, Any], actor_id: str, *, role: str = "actor"
    ) -> dict[str, Any]:
        """Return one encounter participant or reject cross-boundary settlement."""
        combatant = next(
            (
                item
                for item in encounter.get("combatants", [])
                if str(item.get("actor_id") or "") == actor_id
            ),
            None,
        )
        if combatant is None:
            raise CombatEngineError(f"{role} is not a combatant in the active encounter")
        return combatant

    def mutation_revision(campaign_id: str) -> int:
        """Read the committed campaign revision after mixed entity writes."""
        return int(campaigns.get(campaign_id).revision)

    def require_current_branch(campaign_id: str, branch_id: str | None) -> str | None:
        current = current_branch_id(campaign_id)
        if branch_id is not None and current is not None and branch_id != current:
            raise ValueError("branch_id must match the campaign's checked-out branch")
        return current if branch_id is None else branch_id

    def readable_branch(campaign_id: str, branch_id: str | None, principal_id: str) -> str | None:
        """Players can read only the checked-out timeline; DM roles may inspect alternatives."""
        current = current_branch_id(campaign_id)
        if not is_dm(campaign_id, principal_id) and branch_id not in {None, current}:
            raise PermissionError("players may only inspect the checked-out branch")
        return current if branch_id is None else branch_id

    def readable_scene_scope(campaign_id: str, scope_id: str, principal_id: str) -> str:
        """Prevent one player from reading another split-party progress ledger."""
        if is_dm(campaign_id, principal_id) or scope_id == "party":
            return scope_id
        if scope_id.startswith("player:"):
            actor_id_value = scope_id.split(":", 1)[1]
            try:
                access.require_actor(campaign_id, actor_id_value, principal_id, private=True)
            except PermissionError as error:
                raise PermissionError(
                    "players may read only party or an owned player scene scope"
                ) from error
            return scope_id
        raise PermissionError("players may read only party or an owned player scene scope")

    def player_module_scene_view(
        campaign_id: str,
        scene: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Project a module scene without arbitrary GM progress metadata."""

        if scene is None:
            return None
        if scene.get("visibility", "restricted") not in PLAYER_MODULE_VISIBILITY_SCOPES:
            return {
                "campaign_id": campaign_id,
                "scene_id": scene.get("scene_id"),
                "redacted": True,
                "content": "[DM-only scene content hidden]",
            }
        projected = deepcopy(scene)
        if isinstance(projected.get("progress"), dict):
            progress = dict(projected["progress"])
            progress.pop("state", None)
            projected["progress"] = progress
        spatial = dict(projected.get("spatial") or {})
        spatial.pop("review", None)
        projected["spatial"] = spatial
        return projected

    def require_import_job(campaign_id: str, job_id: str, kind: str | None = None) -> Any:
        job = import_jobs.get(job_id)
        if job.campaign_id != campaign_id:
            raise LookupError(job_id)
        if kind is not None and job.kind != kind:
            raise ValueError(f"import job is not a {kind} job")
        return job

    def import_candidate_view(candidate: dict[str, Any]) -> dict[str, Any]:
        """Name the resolver for a live candidate review without changing stored evidence."""

        value = deepcopy(dict(candidate))
        if str(value.get("review_status") or "") not in {"pending", "needs_revision"}:
            return value
        requirement = value.get("ruling_requirement")
        if not isinstance(requirement, dict):
            requirement = _ruling_requirement(
                "Review the extracted candidate against its exact source evidence.",
                "source_or_scene_fact",
            )
            value["ruling_requirement"] = requirement
        return value

    def import_job_view(job: Any) -> dict[str, Any]:
        """Expose ordinary import review as Agent-owned and preserve source exceptions."""

        value = asdict(job)
        candidates = [
            import_candidate_view(item)
            for item in value.get("candidates", [])
            if isinstance(item, dict)
        ]
        value["candidates"] = candidates
        if candidates:
            issues = [
                deepcopy(issue)
                for candidate in candidates
                for issue in candidate.get("draft_issues") or []
                if isinstance(issue, dict)
            ]
            value["draft_workspace"] = {
                "status": (
                    "finalized" if str(value.get("state") or "") != "review_required" else "editing"
                ),
                "candidate_revision": int(value.get("revision") or 0),
                "issue_count": len(issues),
                "blocker_count": sum(
                    1 for issue in issues if str(issue.get("severity") or "") == "blocker"
                ),
                "issues": issues,
            }
        if str(value.get("state") or "") != "review_required":
            return value
        requirements = [
            deepcopy(item["ruling_requirement"])
            for item in candidates
            if isinstance(item.get("ruling_requirement"), dict)
        ]
        ruling_kind = _pending_result_ruling_kind(
            {
                "status": "pending_ruling",
                "ruling_requirements": requirements,
            },
            fallback="source_or_scene_fact",
        )
        value["review_resolution"] = _ruling_resolution_for_kind(ruling_kind)
        value["review_requirements"] = requirements
        return value

    def module_draft_handle_view(job: Any) -> dict[str, Any]:
        """Return the bounded public identity needed to resume one module draft."""

        value = asdict(job)
        payload = dict(value.get("payload") or {})
        result = dict(value.get("result") or {})
        finalized = dict(result.get("finalized_package") or {})
        pack_draft = dict(result.get("pack_draft") or {})
        return {
            "job_id": str(value.get("id") or ""),
            "state": str(value.get("state") or ""),
            "resumable": not bool(finalized),
            "artifact": str(value.get("artifact") or ""),
            "artifact_checksum": str(value.get("artifact_checksum") or ""),
            "source_key": str(payload.get("source_key") or value.get("artifact") or ""),
            "title": str(payload.get("title") or ""),
            "module_id": str(value.get("module_id") or ""),
            "revision": int(value.get("revision") or 0),
            "created_at": value.get("created_at"),
            "updated_at": value.get("updated_at"),
            "pack_decision_fields": sorted(pack_draft),
            "statblock_review_count": len(result.get("statblock_reviews") or []),
            "finalized_artifact": str(finalized.get("artifact") or ""),
            "finalized_pack_id": str(
                dict(finalized.get("summary") or {}).get("id")
                or dict(finalized.get("summary") or {}).get("package_id")
                or ""
            ),
        }

    def require_write_contract(expected_revision: int | None, idempotency_key: str | None) -> None:
        if expected_revision is None:
            raise ValueError("expected_revision is required for this mutation")
        if not idempotency_key:
            raise ValueError("idempotency_key is required for this mutation")

    def sanitize_attack_action(
        campaign_id: str, principal_id: str, action: dict[str, Any]
    ) -> dict[str, Any]:
        membership = access.require_campaign(campaign_id, principal_id)
        value = dict(action)
        if "use_weapon_mastery" in value and not isinstance(value["use_weapon_mastery"], bool):
            raise CombatEngineError("use_weapon_mastery must be boolean")
        for field, allowed in (
            ("light_extra_attack", {"bonus_action", "nick"}),
            ("weapon_mastery_followup", {"cleave"}),
        ):
            if field not in value:
                continue
            normalized = str(value[field] or "").strip().casefold()
            if normalized not in allowed:
                raise CombatEngineError(f"{field} must be one of: {', '.join(sorted(allowed))}")
            value[field] = normalized
        if "mastery_secondary_target_id" in value:
            secondary_target_id = str(value["mastery_secondary_target_id"] or "").strip()
            if not secondary_target_id:
                raise CombatEngineError("mastery_secondary_target_id must be non-empty")
            value["mastery_secondary_target_id"] = secondary_target_id
        if membership.role not in CAMPAIGN_DM_ROLES:
            # Tactical context (cover, advantage, concealment and reach) is a
            # scene/DM fact, not a client-controlled modifier.
            value["context"] = {}
            value["rulings"] = [
                item
                for item in value.get("rulings", [])
                if isinstance(item, dict) and item.get("source") == "dm_ruling"
            ]
        return value

    def validate_current_scene_agent_ruling(
        campaign_id: str,
        raw_ruling: Any,
        *,
        encounter: dict[str, Any],
        field: str,
        allowed_ruling_kinds: set[str] | frozenset[str],
    ) -> dict[str, Any]:
        """Validate one immutable source-bound Agent decision for this scene."""

        if not isinstance(raw_ruling, dict):
            raise CombatEngineError(f"{field} agent_ruling must be an object")
        allowed = {
            "application_id",
            "default_resolver",
            "ruling_kind",
            "decision",
            "reason",
            "source_ref",
            "source_excerpt",
        }
        unknown = set(raw_ruling) - allowed
        application_id = str(raw_ruling.get("application_id") or "").strip()
        decision = " ".join(str(raw_ruling.get("decision") or "").split())
        reason = " ".join(str(raw_ruling.get("reason") or "").split())
        source_ref = raw_ruling.get("source_ref")
        source_excerpt = str(raw_ruling.get("source_excerpt") or "")
        scene_id = str(encounter.get("scene_id") or "").strip()
        if (
            unknown
            or not application_id
            or raw_ruling.get("default_resolver") != "agent"
            or raw_ruling.get("ruling_kind") not in allowed_ruling_kinds
            or not 10 <= len(decision) <= 1000
            or not 10 <= len(reason) <= 500
            or not isinstance(source_ref, dict)
            or not scene_id
        ):
            raise CombatEngineError(
                f"{field} requires a bounded source-bound Agent ruling "
                "for the active encounter scene"
            )
        try:
            _normalized, _source, expanded = managed_module_source_ref(
                campaign_id,
                source_ref,
                require_exact=True,
                expected_scene_id=scene_id,
                require_active_module=True,
            )
            assert expanded is not None
            managed_module_source_excerpt(
                expanded,
                source_excerpt,
                field=f"{field} source_excerpt",
                minimum_length=10,
            )
        except (LookupError, ValueError) as error:
            raise CombatEngineError(str(error)) from error
        return {
            "application_id": application_id,
            "default_resolver": "agent",
            "ruling_kind": str(raw_ruling["ruling_kind"]),
            "decision": decision,
            "reason": reason,
            "source_ref": deepcopy(source_ref),
            "source_excerpt": source_excerpt,
        }

    def character_source_card(
        sheet: dict[str, Any],
        source_card_id: str,
        source_card_kind: str,
    ) -> dict[str, Any]:
        """Resolve exactly one durable source card from a character sheet."""
        try:
            return source_cards.character_source_card(sheet, source_card_id, source_card_kind)
        except source_cards.CharacterSourceCardError as error:
            raise CombatEngineError(str(error)) from error

    def character_resolution_plan(
        sheet: dict[str, Any],
        source_card_id: str,
        source_card_kind: str,
    ) -> tuple[dict[str, Any], Any]:
        """Resolve one executable plan from the exact recorded character card."""

