    def validate_authored_content_plan(
        campaign_id: str,
        raw_plan: Any,
        *,
        source_card: dict[str, Any],
        source_card_id: str,
        source_card_kind: str,
    ) -> Any:
        """Validate one build-time custom recipe against exact managed evidence."""

        try:
            compiled = compile_resolution_plan(raw_plan)
        except ResolutionPlanCompilationError as error:
            raise CombatEngineError(f"authored resolution plan is invalid: {error}") from error
        if (
            compiled.schema_version != 2
            or compiled.source_card_id != source_card_id
            or compiled.source_card_kind != source_card_kind
        ):
            raise CombatEngineError(
                "authored solutions require a schema v2 plan for the exact source card"
            )
        evidence_texts = source_card_evidence_texts(source_card)
        if not evidence_texts:
            raise CombatEngineError("authored solution requires recorded original effect text")
        relevant_citation = False
        for index, citation in enumerate(compiled.citations):
            source_ref = citation["source_ref"]
            try:
                if set(source_ref) == {"chunk_id"}:
                    chunk_id = str(source_ref["chunk_id"] or "")
                    canonical_citation = rules.citation(chunk_id)
                    expanded = rules.expand(chunk_id)
                    rule_source = rules.source(
                        str(dict(expanded.get("source") or {}).get("id") or "")
                    )
                    if (
                        citation["source"] != canonical_citation["source"]
                        or str(rule_source.get("system_id") or "") != DND5E.id
                        or str(rule_source.get("edition") or "")
                        != campaign_rules_edition(campaign_id)
                        or rule_source.get("active") is not True
                    ):
                        raise ValueError(
                            "resolution plan rule citation does not match the active campaign rules"
                        )
                    excerpt = clean_source_evidence_text(citation["source_excerpt"])
                    chunk_content = _normalize_source_evidence_text(
                        dict(expanded.get("chunk") or {}).get("content")
                    )
                    if not 10 <= len(excerpt) <= 4000 or excerpt.casefold() not in chunk_content:
                        raise ValueError(
                            "resolution plan source_excerpt is not present in its cited rule chunk"
                        )
                elif MANAGED_MODULE_SOURCE_FIELDS & set(source_ref):
                    _normalized, _source, expanded = managed_module_source_ref(
                        campaign_id,
                        source_ref,
                        require_exact=True,
                        require_active_module=True,
                    )
                    assert expanded is not None
                    excerpt = managed_module_source_excerpt(
                        expanded,
                        citation["source_excerpt"],
                        field=(f"resolution_plan.citations[{index}].source_excerpt"),
                        minimum_length=10,
                        maximum_length=4000,
                    )
                else:
                    raise ValueError(
                        "resolution plan citation must identify one exact module or rule chunk"
                    )
            except (LookupError, ValueError) as error:
                raise CombatEngineError(str(error)) from error
            normalized_excerpt = _normalize_source_evidence_text(excerpt)
            if any(
                normalized_excerpt in evidence or evidence in normalized_excerpt
                for evidence in evidence_texts
            ):
                relevant_citation = True
        if not relevant_citation:
            raise CombatEngineError(
                "authored resolution plan must cite the exact recorded card effect"
            )
        return compiled

    def sheet_with_content_solution(
        sheet: dict[str, Any],
        *,
        source_card_id: str,
        source_card_kind: str,
        compiled_plan: Any,
        solution: dict[str, Any],
    ) -> dict[str, Any]:
        """Attach one compiled recipe to exactly one durable source card."""

        updated = deepcopy(sheet)
        collections = {
            "activity": ("activities",),
            "feature": ("features", "feats"),
            "monster_action": ("activities",),
            "spell": ("spells",),
            "trait": ("features",),
        }.get(source_card_kind)
        if source_card_kind == "item":
            matches = [
                item
                for item in dict(updated.get("inventory") or {}).get(
                    "items",
                    [],
                )
                if isinstance(item, dict) and str(item.get("id") or "") == source_card_id
            ]
        elif collections is not None:
            matches = [
                item
                for collection in collections
                for item in dict(updated.get("content") or {}).get(
                    collection,
                    [],
                )
                if isinstance(item, dict) and str(item.get("id") or "") == source_card_id
            ]
        else:
            raise CombatEngineError("unsupported character source card kind")
        if len(matches) != 1:
            raise CombatEngineError("source card must resolve exactly once before solution storage")
        matches[0]["resolution_plan"] = resolution_plan_template(compiled_plan)
        matches[0]["resolution_solution"] = deepcopy(solution)
        return validate_character_sheet(updated)

    def agent_resolution_commitment(
        *,
        application_id: str,
        plan_id: str,
        plan_fingerprint: str,
        bound_plan_fingerprint: str,
        source_card_id: str,
        source_card_kind: str,
        bindings: dict[str, Any],
        agent_ruling: dict[str, Any],
    ) -> dict[str, Any]:
        """Build the immutable payment contract for one bound semantic plan."""

        return {
            "application_id": application_id,
            "plan_id": plan_id,
            "plan_fingerprint": plan_fingerprint,
            "bound_plan_fingerprint": bound_plan_fingerprint,
            "source_card_id": source_card_id,
            "source_card_kind": source_card_kind,
            "bindings": deepcopy(bindings),
            "agent_ruling": deepcopy(agent_ruling),
        }

    def validate_agent_resolution_commitment(
        campaign_id: str,
        raw_commitment: Any,
        *,
        encounter: dict[str, Any],
        source_actor_id: str,
        source_card_id: str,
        source_card_kind: str,
        compiled_plan: Any,
    ) -> tuple[dict[str, Any], BoundResolutionPlan]:
        """Bind an Agent decision only to slots declared by its recorded rule card."""

        if not isinstance(raw_commitment, dict):
            raise CombatEngineError("agent_resolution_commitment must be an object")
        required_fields = {
            "application_id",
            "plan_id",
            "plan_fingerprint",
            "source_card_id",
            "source_card_kind",
            "bindings",
            "agent_ruling",
        }
        supplied_fields = set(raw_commitment)
        if supplied_fields != required_fields and supplied_fields != {
            *required_fields,
            "bound_plan_fingerprint",
        }:
            raise CombatEngineError(
                "agent_resolution_commitment requires the exact plan-binding contract"
            )
        normalized_ruling = validate_current_scene_agent_ruling(
            campaign_id,
            raw_commitment.get("agent_ruling"),
            encounter=encounter,
            field="semantic plan commitment",
            allowed_ruling_kinds={
                "agent_dm_adjudication",
                "environmental_consequence",
                "generic_spell_effect",
                "module_specific_procedure",
                "source_or_scene_fact",
            },
        )
        if any(
            definition.get("owner") == "external_input"
            for definition in compiled_plan.slots.values()
        ):
            raise NeedsRulingError(
                "semantic plan contains player-owned slots that require an "
                "external choice receipt before Agent settlement",
                missing=tuple(
                    f"player_choice:{slot_name}"
                    for slot_name, definition in compiled_plan.slots.items()
                    if definition.get("owner") == "external_input"
                ),
                ruling_kind="player_owned_choice",
            )
        try:
            bound = bind_resolution_plan(
                compiled_plan,
                raw_commitment.get("bindings"),
                agent_ruling=normalized_ruling,
            )
        except ResolutionPlanBindingError as error:
            raise CombatEngineError(f"agent_resolution_commitment is invalid: {error}") from error
        normalized = agent_resolution_commitment(
            application_id=str(raw_commitment.get("application_id") or "").strip(),
            plan_id=str(raw_commitment.get("plan_id") or "").strip(),
            plan_fingerprint=str(raw_commitment.get("plan_fingerprint") or "").strip(),
            bound_plan_fingerprint=bound.fingerprint,
            source_card_id=str(raw_commitment.get("source_card_id") or "").strip(),
            source_card_kind=str(raw_commitment.get("source_card_kind") or "").strip(),
            bindings=bound.bindings,
            agent_ruling=normalized_ruling,
        )
        supplied_bound_fingerprint = str(raw_commitment.get("bound_plan_fingerprint") or "")
        if (
            not normalized["application_id"]
            or normalized["application_id"] != normalized_ruling["application_id"]
            or normalized["plan_id"] != compiled_plan.id
            or normalized["plan_fingerprint"] != compiled_plan.fingerprint
            or (supplied_bound_fingerprint and supplied_bound_fingerprint != bound.fingerprint)
            or normalized["source_card_id"] != source_card_id
            or normalized["source_card_kind"] != source_card_kind
        ):
            raise CombatEngineError("agent_resolution_commitment does not match the recorded plan")
        for slot_name, definition in compiled_plan.slots.items():
            if definition.get("kind") not in {
                "actor_id",
                "actor_ids",
            }:
                continue
            raw_actor_ids = bound.bindings[slot_name]
            actor_ids = [raw_actor_ids] if isinstance(raw_actor_ids, str) else list(raw_actor_ids)
            for target_id in actor_ids:
                require_campaign_actor(campaign_id, str(target_id))
                require_encounter_combatant(
                    encounter,
                    str(target_id),
                    role=f"semantic plan slot {slot_name}",
                )
        for step in bound.steps:
            step_source_actor_id = dict(step.get("args") or {}).get("source_actor_id")
            if step_source_actor_id is not None and str(step_source_actor_id) != source_actor_id:
                raise CombatEngineError(
                    "semantic plan source_actor_id must match the actor paying for the source card"
                )
        require_campaign_actor(campaign_id, source_actor_id)
        require_encounter_combatant(
            encounter,
            source_actor_id,
            role="semantic plan source",
        )
        return normalized, bound

    def require_agent_resolution_payment(
        encounter: dict[str, Any],
        *,
        campaign_id: str,
        branch_id: str,
        source_actor_id: str,
        source_card_id: str,
        source_card_kind: str,
        commitment: dict[str, Any],
        bound_plan: BoundResolutionPlan,
    ) -> dict[str, Any]:
        """Require the exact paid current-turn declaration before plan execution."""

        current = current_combatant(encounter)
        current_round = int(encounter.get("round", 1) or 1)
        current_turn_index = int(encounter.get("turn_index", 0) or 0)
        if current is None or str(current.get("actor_id") or "") != source_actor_id:
            raise CombatEngineError("semantic plan must settle during its source actor's paid turn")
        if source_card_kind == "item":
            window = next(
                (
                    item
                    for item in encounter.get("pending", [])
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == str(commitment.get("application_id") or "")
                ),
                None,
            )
            if (
                not isinstance(window, dict)
                or window.get("trigger") not in {"attack_semantic_plan", "attack_on_hit_effect"}
                or str(window.get("attacker_id") or "") != source_actor_id
                or str(window.get("weapon_id") or "") != source_card_id
                or (
                    window.get("trigger") == "attack_semantic_plan"
                    and str(window.get("plan_fingerprint") or "") != bound_plan.compiled.fingerprint
                )
            ):
                raise CombatEngineError(
                    "item semantic plan requires its exact pending on-hit event"
                )
            target_id = str(window.get("target_id") or "")
            trigger_event = {
                "trigger": "attack.after_hit",
                "application_id": str(window["id"]),
                "attack_ref": str(window.get("attack_ref") or ""),
                "branch_id": str(window.get("branch_id") or branch_id),
                "campaign_id": str(window.get("campaign_id") or campaign_id),
                "critical": bool(window.get("critical", False)),
                "hit": True,
                "round": current_round,
                "source_actor_id": source_actor_id,
                "target_actor_id": target_id,
                "turn": current_turn_index,
                "weapon_id": source_card_id,
            }
            try:
                require_resolution_plan_trigger(
                    bound_plan,
                    trigger_event,
                )
            except ResolutionPlanExecutionError as error:
                raise CombatEngineError(str(error)) from error
            return {
                "type": "attack_after_hit",
                "application_id": str(window["id"]),
                "actor_id": source_actor_id,
                "target_id": target_id,
                "weapon_id": source_card_id,
                "round": current_round,
                "turn_index": current_turn_index,
                "trigger_event": trigger_event,
            }
        for entry in reversed(list(encounter.get("log") or [])):
            if not isinstance(entry, dict):
                continue
            if (
                int(entry.get("round", -1)) != current_round
                or int(entry.get("turn_index", -1)) != current_turn_index
                or str(entry.get("actor_id") or "") != source_actor_id
            ):
                continue
            declaration: Any = None
            if (
                source_card_kind in {"activity", "feature", "monster_action", "trait"}
                and entry.get("type") == "activity"
                and str(entry.get("activity_id") or "") == source_card_id
            ):
                declaration = dict(entry.get("declaration") or {}).get(
                    "agent_resolution_commitment"
                )
            elif (
                source_card_kind == "spell"
                and entry.get("type") == "common_action"
                and entry.get("action") == "cast"
                and str(dict(entry.get("payload") or {}).get("spell_id") or "") == source_card_id
            ):
                declaration = dict(entry.get("payload") or {}).get("agent_resolution_commitment")
            elif (
                source_card_kind == "scene_procedure"
                and entry.get("type") == "common_action"
                and entry.get("action") == "improvise"
                and str(dict(entry.get("payload") or {}).get("procedure_id") or "")
                == source_card_id
            ):
                declaration = dict(entry.get("payload") or {}).get("agent_resolution_commitment")
            if declaration == commitment:
                payment = deepcopy(entry)
                if bound_plan.compiled.schema_version >= 2:
                    trigger_event = {
                        "trigger": "action",
                        "action_kind": (
                            str(entry.get("activity_id") or "")
                            if entry.get("type") == "activity"
                            else str(entry.get("action") or "")
                        ),
                        "action_ref": source_card_id,
                        "actor_id": source_actor_id,
                        "branch_id": branch_id,
                        "campaign_id": campaign_id,
                        "round": current_round,
                        "turn": current_turn_index,
                    }
                    try:
                        require_resolution_plan_trigger(
                            bound_plan,
                            trigger_event,
                        )
                    except ResolutionPlanExecutionError as error:
                        raise CombatEngineError(str(error)) from error
                    payment["trigger_event"] = trigger_event
                return payment
        raise CombatEngineError(
            "semantic plan requires its exact current-turn commitment to be "
            "paid by the source activity, item hit, spell, or scene procedure"
        )

    def agent_save_damage_commitment(
        *,
        application_id: str,
        source_card_id: str,
        source_card_kind: str,
        target_ids: list[str],
        save_ability: str,
        save_dc: int,
        save_advantage: bool,
        save_disadvantage: bool,
        damage_expression: str,
        damage_type: str,
        half_on_success: bool,
        mechanic_source_excerpt: str,
        agent_ruling: dict[str, Any],
    ) -> dict[str, Any]:
        """Build the immutable semantic contract paid by a descriptive action."""

        return {
            "application_id": application_id,
            "source_card_id": source_card_id,
            "source_card_kind": source_card_kind,
            "target_ids": list(target_ids),
            "save_ability": save_ability,
            "save_dc": save_dc,
            "save_advantage": save_advantage,
            "save_disadvantage": save_disadvantage,
            "damage_expression": damage_expression,
            "damage_type": damage_type,
            "half_on_success": half_on_success,
            "mechanic_source_excerpt": mechanic_source_excerpt,
            "agent_ruling": deepcopy(agent_ruling),
        }

    def validate_agent_save_damage_commitment(
        campaign_id: str,
        raw_commitment: Any,
        *,
        encounter: dict[str, Any],
        source_actor_id: str,
        source_card_id: str,
        source_card_kind: str,
    ) -> dict[str, Any]:
        """Validate a commitment before its action economy is consumed."""

        if not isinstance(raw_commitment, dict):
            raise CombatEngineError("agent_ruling_commitment must be an object")
        required_fields = {
            "application_id",
            "source_card_id",
            "source_card_kind",
            "target_ids",
            "save_ability",
            "save_dc",
            "save_advantage",
            "save_disadvantage",
            "damage_expression",
            "damage_type",
            "half_on_success",
            "mechanic_source_excerpt",
            "agent_ruling",
        }
        target_ids = raw_commitment.get("target_ids")
        if set(raw_commitment) != required_fields or not isinstance(target_ids, list):
            raise CombatEngineError(
                "agent_ruling_commitment requires the exact save-damage contract"
            )
        normalized_target_ids = [str(target_id or "").strip() for target_id in target_ids]
        normalized_ruling = validate_current_scene_agent_ruling(
            campaign_id,
            raw_commitment.get("agent_ruling"),
            encounter=encounter,
            field="save-damage commitment",
            allowed_ruling_kinds={"agent_dm_adjudication"},
        )
        normalized = agent_save_damage_commitment(
            application_id=str(raw_commitment.get("application_id") or "").strip(),
            source_card_id=str(raw_commitment.get("source_card_id") or "").strip(),
            source_card_kind=str(raw_commitment.get("source_card_kind") or "")
            .strip()
            .casefold()
            .replace("-", "_"),
            target_ids=normalized_target_ids,
            save_ability=str(raw_commitment.get("save_ability") or "").strip().casefold(),
            save_dc=raw_commitment.get("save_dc"),
            save_advantage=raw_commitment.get("save_advantage"),
            save_disadvantage=raw_commitment.get("save_disadvantage"),
            damage_expression="".join(
                str(raw_commitment.get("damage_expression") or "").split()
            ).casefold(),
            damage_type=str(raw_commitment.get("damage_type") or "").strip().casefold(),
            half_on_success=raw_commitment.get("half_on_success"),
            mechanic_source_excerpt=" ".join(
                str(raw_commitment.get("mechanic_source_excerpt") or "").split()
            ),
            agent_ruling=normalized_ruling,
        )
        if (
            normalized != raw_commitment
            or not normalized["application_id"]
            or not normalized["source_card_id"]
            or normalized["source_card_kind"] != "scene_procedure"
            or normalized["application_id"] != normalized_ruling["application_id"]
            or normalized["source_card_id"] != source_card_id
            or normalized["source_card_kind"] != source_card_kind
            or not normalized_target_ids
            or source_actor_id in normalized_target_ids
            or any(not target_id for target_id in normalized_target_ids)
            or len(normalized_target_ids) != len(set(normalized_target_ids))
            or normalized["save_ability"]
            not in {
                "strength",
                "dexterity",
                "constitution",
                "intelligence",
                "wisdom",
                "charisma",
            }
            or isinstance(normalized["save_dc"], bool)
            or not isinstance(normalized["save_dc"], int)
            or not 1 <= normalized["save_dc"] <= 40
            or not isinstance(normalized["save_advantage"], bool)
            or not isinstance(normalized["save_disadvantage"], bool)
            or (normalized["save_advantage"] and normalized["save_disadvantage"])
            or re.fullmatch(
                r"[1-9]\d*d[1-9]\d*(?:[+-]\d+)?",
                normalized["damage_expression"],
            )
            is None
            or not normalized["damage_type"]
            or not isinstance(normalized["half_on_success"], bool)
            or not normalized["mechanic_source_excerpt"]
        ):
            raise CombatEngineError(
                "agent_ruling_commitment is not a canonical source-bound save-damage contract"
            )
        for target_id in normalized_target_ids:
            require_campaign_actor(campaign_id, target_id)
            require_encounter_combatant(
                encounter,
                target_id,
                role="committed save-damage target",
            )
        return normalized

    def require_agent_save_damage_payment(
        encounter: dict[str, Any],
        *,
        source_actor_id: str,
        source_card_id: str,
        source_card_kind: str,
        commitment: dict[str, Any],
    ) -> dict[str, Any]:
        """Require the exact current-turn action commitment before settlement."""

        current = current_combatant(encounter)
        current_round = int(encounter.get("round", 1) or 1)
        current_turn_index = int(encounter.get("turn_index", 0) or 0)
        if current is None or str(current.get("actor_id") or "") != source_actor_id:
            raise CombatEngineError("save damage must settle during the source actor's paid action")
        for entry in reversed(list(encounter.get("log") or [])):
            if not isinstance(entry, dict):
                continue
            entry_round = entry.get("round")
            entry_turn_index = entry.get("turn_index")
            if (
                int(entry_round if entry_round is not None else -1) != current_round
                or int(entry_turn_index if entry_turn_index is not None else -1)
                != current_turn_index
                or str(entry.get("actor_id") or "") != source_actor_id
            ):
                continue
            paid_commitment: Any = None
            if (
                source_card_kind == "scene_procedure"
                and entry.get("type") == "common_action"
                and entry.get("action") == "improvise"
                and str(dict(entry.get("payload") or {}).get("procedure_id") or "")
                == source_card_id
            ):
                paid_commitment = dict(entry.get("payload") or {}).get("agent_ruling_commitment")
            if paid_commitment == commitment:
                return deepcopy(entry)
        raise CombatEngineError(
            "save damage requires the exact current-turn Agent ruling commitment "
            "to be paid by its scene procedure"
        )

    def validate_agent_attack_context(
        campaign_id: str,
        action: dict[str, Any],
        *,
        encounter: dict[str, Any],
    ) -> None:
        """Validate source rulings on a grid or dynamic spatial facts in Agent mode."""

        context = action.get("context")
        if context is None:
            return
        if not isinstance(context, dict):
            raise CombatEngineError("attack context must be an object")
        positioning_mode = str(encounter.get("positioning_mode") or "grid")
        raw_spatial_facts = context.get("spatial_facts")
        if positioning_mode == "agent":
            if not isinstance(raw_spatial_facts, dict):
                raise NeedsRulingError(
                    "agent-positioned attacks require an Agent spatial decision",
                    missing=("attack.spatial_facts",),
                    ruling_kind="agent_dm_adjudication",
                )
            allowed_spatial_fields = {
                "decision_id",
                "reason",
                "targetable",
                "in_range",
                "long_range",
                "cover_degree",
                "attacker_can_see_target",
                "target_can_see_attacker",
                "target_within_5_ft",
                "close_threat_actor_ids",
                "helper_actor_ids",
                "target_adjacent_ally_actor_ids",
                "cleave_secondary_eligible",
            }
            required_spatial_fields = {
                "decision_id",
                "reason",
                "targetable",
                "in_range",
                "cover_degree",
                "attacker_can_see_target",
                "target_can_see_attacker",
            }
            unknown = set(raw_spatial_facts) - allowed_spatial_fields
            missing = required_spatial_fields - set(raw_spatial_facts)
            decision_id = str(raw_spatial_facts.get("decision_id") or "").strip()
            reason = " ".join(str(raw_spatial_facts.get("reason") or "").split())
            if unknown or missing or not decision_id or not reason:
                raise CombatEngineError(
                    "Agent spatial facts require one decision_id, reason, and the attack "
                    "facts needed to determine targetability"
                )
            for field in {
                "targetable",
                "in_range",
                "attacker_can_see_target",
                "target_can_see_attacker",
            }:
                if not isinstance(raw_spatial_facts.get(field), bool):
                    raise CombatEngineError(f"Agent spatial fact {field} must be boolean")
            for field in {"long_range", "target_within_5_ft"}:
                if field in raw_spatial_facts and not isinstance(raw_spatial_facts[field], bool):
                    raise CombatEngineError(f"Agent spatial fact {field} must be boolean")
            if "cleave_secondary_eligible" in raw_spatial_facts and not isinstance(
                raw_spatial_facts["cleave_secondary_eligible"], bool
            ):
                raise CombatEngineError(
                    "Agent spatial fact cleave_secondary_eligible must be boolean"
                )
            cover_degree = (
                str(raw_spatial_facts.get("cover_degree") or "")
                .strip()
                .casefold()
                .replace("-", "_")
            )
            if cover_degree not in {"none", "half", "three_quarters", "total"}:
                raise CombatEngineError(
                    "Agent spatial fact cover_degree must be none, half, three_quarters, or total"
                )
            participant_ids = {
                str(item.get("actor_id") or "") for item in encounter.get("combatants", [])
            }
            normalized_lists: dict[str, list[str]] = {}
            for field in {
                "close_threat_actor_ids",
                "helper_actor_ids",
                "target_adjacent_ally_actor_ids",
            }:
                raw_ids = raw_spatial_facts.get(field, [])
                if (
                    not isinstance(raw_ids, list)
                    or any(not isinstance(item, str) for item in raw_ids)
                    or len(set(raw_ids)) != len(raw_ids)
                    or set(raw_ids) - participant_ids
                ):
                    raise CombatEngineError(
                        f"Agent spatial fact {field} must contain unique current combatant IDs"
                    )
                normalized_lists[field] = list(raw_ids)
            context["spatial_facts"] = {
                **dict(raw_spatial_facts),
                **normalized_lists,
                "decision_id": decision_id,
                "reason": reason,
                "cover_degree": cover_degree,
                "long_range": bool(raw_spatial_facts.get("long_range", False)),
                "target_within_5_ft": bool(raw_spatial_facts.get("target_within_5_ft", False)),
                "cleave_secondary_eligible": bool(
                    raw_spatial_facts.get("cleave_secondary_eligible", False)
                ),
            }
            action["context"] = context
            return
        if raw_spatial_facts is not None:
            raise CombatEngineError("grid attacks derive spatial facts from encounter coordinates")
        cover = context.get("cover")
        if cover is not None:
            if not isinstance(cover, dict) or set(cover) != {"degree"}:
                raise CombatEngineError(
                    "attack cover context accepts only one rules-defined degree"
                )
            degree = str(cover.get("degree") or "").strip().casefold().replace("-", "_")
            if degree not in {"half", "three_quarters", "total"}:
                raise CombatEngineError("Agent cover degree must be half, three_quarters, or total")
            if not isinstance(context.get("agent_ruling"), dict):
                raise CombatEngineError(
                    "Agent cover context requires an exact source-bound Agent ruling"
                )
        raw_ruling = context.get("agent_ruling")
        if raw_ruling is None:
            return
        validate_current_scene_agent_ruling(
            campaign_id,
            raw_ruling,
            encounter=encounter,
            field="attack context",
            allowed_ruling_kinds={
                "agent_dm_adjudication",
                "source_or_scene_fact",
            },
        )

    def validate_agent_movement_facts(
        encounter: dict[str, Any],
        spatial_facts: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Validate the Agent's coordinate-free movement judgment."""

        positioning_mode = str(encounter.get("positioning_mode") or "grid")
        if positioning_mode == "grid":
            if spatial_facts is not None:
                raise CombatEngineError(
                    "grid movement derives spatial facts from encounter coordinates"
                )
            return None
        if not isinstance(spatial_facts, dict):
            raise NeedsRulingError(
                "agent-positioned movement requires an Agent spatial decision",
                missing=("movement.spatial_facts",),
                ruling_kind="agent_dm_adjudication",
            )
        allowed_fields = {
            "decision_id",
            "reason",
            "destination_legal",
            "distance_ft",
            "difficult_terrain_extra_ft",
            "moves_farther_from_turn_source",
            "enters_turn_source_30_ft",
            "moves_closer_to_visible_fear_source",
            "opportunity_attack_actor_ids",
        }
        required_fields = {"decision_id", "reason", "destination_legal", "distance_ft"}
        if set(spatial_facts) - allowed_fields or required_fields - set(spatial_facts):
            raise CombatEngineError(
                "Agent movement spatial facts require decision_id, reason, destination_legal, "
                "and distance_ft"
            )
        decision_id = str(spatial_facts.get("decision_id") or "").strip()
        reason = " ".join(str(spatial_facts.get("reason") or "").split())
        if not decision_id or not reason:
            raise CombatEngineError("Agent movement facts require decision_id and reason")
        for field in {
            "destination_legal",
            "moves_farther_from_turn_source",
            "enters_turn_source_30_ft",
            "moves_closer_to_visible_fear_source",
        }:
            if not isinstance(spatial_facts.get(field, False), bool):
                raise CombatEngineError(f"Agent movement spatial fact {field} must be boolean")
        for field in {"distance_ft", "difficult_terrain_extra_ft"}:
            value = spatial_facts.get(field, 0)
            if isinstance(value, bool) or not isinstance(value, int) or value < 0 or value % 5:
                raise CombatEngineError(
                    f"Agent movement spatial fact {field} must be a non-negative "
                    "five-foot increment"
                )
        participant_ids = {
            str(item.get("actor_id") or "") for item in encounter.get("combatants", [])
        }
        threat_ids = spatial_facts.get("opportunity_attack_actor_ids", [])
        if (
            not isinstance(threat_ids, list)
            or any(not isinstance(item, str) for item in threat_ids)
            or len(set(threat_ids)) != len(threat_ids)
            or set(threat_ids) - participant_ids
        ):
            raise CombatEngineError(
                "Agent movement opportunity_attack_actor_ids must contain unique current "
                "combatant IDs"
            )
        return {
            **dict(spatial_facts),
            "decision_id": decision_id,
            "reason": reason,
            "difficult_terrain_extra_ft": int(spatial_facts.get("difficult_terrain_extra_ft", 0)),
            "moves_farther_from_turn_source": bool(
                spatial_facts.get("moves_farther_from_turn_source", False)
            ),
            "enters_turn_source_30_ft": bool(spatial_facts.get("enters_turn_source_30_ft", False)),
            "moves_closer_to_visible_fear_source": bool(
                spatial_facts.get("moves_closer_to_visible_fear_source", False)
            ),
            "opportunity_attack_actor_ids": list(threat_ids),
        }

    def sync_combatant_conditions(
        encounter: dict[str, Any], actor_id: str, sheet: dict[str, Any]
    ) -> None:
        for combatant in encounter.get("combatants", []):
            if combatant.get("actor_id") == actor_id:
                combatant["conditions"] = list(sheet.get("conditions") or [])
                combatant["condition_sources"] = timed_condition_sources(sheet)
                combatant["speed_multiplier"] = source_speed_multiplier(sheet)
                if "turned" not in {str(item).casefold() for item in combatant["conditions"]}:
                    combatant.pop("turned", None)
                reconcile_actor_witch_bolt_concentration(
                    encounter,
                    actor_id,
                    sheet,
                )
                return

    def combatant_zero_hp_buffered(combatant: dict[str, Any]) -> bool:
        return bool(combatant.get("death_saves", False) or combatant.get("zero_hp_recovery", False))

    def source_participant_rules(
        campaign_id: str,
        scene_id: str | None,
        character: Any,
        config_entry: dict[str, Any],
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any] | None]:
        """Normalize scene-authored conditions for initial and joining combatants."""

        actor_id_value = str(character.id)
        condition_records: list[dict[str, Any]] = []
        sheet = deepcopy(character.sheet)
        for raw_condition in config_entry.get("source_conditions") or []:
            allowed_condition_fields = {
                "condition",
                "source_ref",
                "source_excerpt",
                "duration",
            }
            unknown_condition_fields = set(raw_condition) - allowed_condition_fields
            if unknown_condition_fields:
                raise ValueError(
                    f"unsupported source condition fields: {sorted(unknown_condition_fields)}"
                )
            condition = str(raw_condition.get("condition") or "").strip().casefold()
            duration = str(raw_condition.get("duration") or "encounter").strip().casefold()
            excerpt = str(raw_condition.get("source_excerpt") or "").strip()
            source_ref = raw_condition.get("source_ref")
            if condition not in STANDARD_BINARY_CONDITION_IDS:
                raise ValueError(
                    f"unsupported source-declared combat condition: {condition or '<empty>'}"
                )
            if duration != "encounter":
                raise ValueError("source-declared combat condition duration must be encounter")
            if scene_id is None:
                raise ValueError("source-declared combat conditions require an encounter scene_id")
            _, normalized_source_ref, expanded = managed_module_source_ref(
                campaign_id,
                source_ref,
                require_exact=True,
                expected_scene_id=scene_id,
            )
            if normalized_source_ref is None or expanded is None:
                raise AssertionError("exact source conditions always resolve to a managed chunk")
            normalized_excerpt = managed_module_source_excerpt(
                expanded,
                excerpt,
                field="source condition source_excerpt",
            )
            existing_conditions = condition_ids(sheet.get("conditions"))
            apply_condition_change(sheet, condition_id=condition, add=True)
            applied_conditions = condition_ids(sheet.get("conditions"))
            added_by_encounter = (
                condition not in existing_conditions and condition in applied_conditions
            )
            if added_by_encounter:
                end_concentration_for_incapacitating_conditions(sheet)
            condition_records.append(
                {
                    "actor_id": actor_id_value,
                    "condition": condition,
                    "duration": duration,
                    "source_ref": normalized_source_ref,
                    "source_excerpt": normalized_excerpt,
                    "added_by_encounter": added_by_encounter,
                    "resisted_by_immunity": condition not in applied_conditions,
                    "active": True,
                }
            )
        return (
            [],
            condition_records,
            sheet if sheet != character.sheet else None,
        )

    def add_attack_on_hit_window(
        encounter: dict[str, Any],
        *,
        result: dict[str, Any],
        attacker_id: str,
        target_id: str,
        weapon_id: str,
    ) -> dict[str, Any] | None:
        on_hit_ruling = dict(result.get("on_hit_ruling") or {})
        effect = str(on_hit_ruling.get("effect") or "").strip()
        if not result.get("hit") or not effect:
            return None
        next_value = add_choice_window(
            encounter,
            kind="ruling",
            actor_id_value=target_id,
            event="attack.on_hit.effect",
            candidates=[
                {
                    "id": "execute_plan",
                    "name": "Compile, persist, and execute a source-bound plan",
                },
                {
                    "id": "dismiss",
                    "name": "Agent confirms that no structured effect applies",
                },
            ],
        )
        encounter.clear()
        encounter.update(next_value)
        window = encounter["pending"][-1]
        window.update(
            trigger="attack_on_hit_effect",
            attacker_id=attacker_id,
            target_id=target_id,
            weapon_id=weapon_id,
            effect=effect,
        )
        result["pending_on_hit_ruling_id"] = window["id"]
        return window

    def encounter_turn_token(encounter: dict[str, Any]) -> str:
        current = current_combatant(encounter)
        return (
            f"{int(encounter.get('round', 1) or 1)}:"
            f"{int(encounter.get('turn_index', 0) or 0)}:"
            f"{str((current or {}).get('actor_id') or '')}"
        )

    def apply_standard_spell_on_hit_mechanics(
        encounter: dict[str, Any],
        *,
        result: dict[str, Any],
        attacker_id: str,
        target_id: str,
    ) -> list[dict[str, Any]]:
        """Commit locked standard-spell effects without interpreting source prose."""

        mechanics = list(result.pop("standard_on_hit_mechanics", []) or [])
        if not result.get("hit") or not mechanics:
            return []
        allowed = {
            "next_attack_advantage_until_source_turn_end",
            "healing_prevention_until_source_turn_start",
            "healing_prevention_until_source_turn_end",
            "undead_attack_disadvantage_against_source_until_source_turn_start",
        }
        unknown = set(mechanics) - allowed
        if unknown:
            raise CombatEngineError(
                f"unsupported locked standard spell on-hit mechanics: {sorted(unknown)}"
            )
        target_sheet = combat_actor_snapshot(target_id)["sheet"]
        creature_type = str(
            dict(target_sheet.get("progression") or {}).get("species") or ""
        ).casefold()
        activated_turn_token = encounter_turn_token(encounter)
        committed: list[dict[str, Any]] = []
        for mechanic in mechanics:
            if (
                mechanic == "undead_attack_disadvantage_against_source_until_source_turn_start"
                and "undead" not in creature_type
            ):
                continue
            effect: dict[str, Any] = {
                "id": f"standard-spell-on-hit-{uuid4().hex}",
                "mechanic_id": SPELL_RESOLUTION_MECHANIC_ID,
                "standard_on_hit_mechanic": mechanic,
                "source_actor_id": attacker_id,
                "target_id": target_id,
                "active": True,
                "activated_turn_token": activated_turn_token,
            }
            if mechanic == "next_attack_advantage_until_source_turn_end":
                effect.update(
                    kind="next_attack_advantage",
                    expires_on_actor_id=attacker_id,
                    expires_at="source_turn_end",
                )
            elif mechanic.startswith("healing_prevention_until_source_turn_"):
                effect.update(
                    kind="healing_prevention",
                    expires_on_actor_id=attacker_id,
                    expires_at=(
                        "source_turn_start" if mechanic.endswith("_start") else "source_turn_end"
                    ),
                )
            else:
                effect.update(
                    kind="attack_disadvantage_against_source",
                    protected_actor_id=attacker_id,
                    expires_on_actor_id=attacker_id,
                    expires_at="source_turn_start",
                )
            encounter.setdefault("ongoing_effects", []).append(effect)
            committed.append(deepcopy(effect))
        if committed:
            result["standard_on_hit_effects"] = committed
        return committed

    def expire_standard_source_turn_effects(
        encounter: dict[str, Any],
        *,
        actor_id: str,
        phase: Literal["source_turn_start", "source_turn_end"],
        turn_token: str,
    ) -> list[str]:
        expired: list[str] = []
        for effect in encounter.get("ongoing_effects", []):
            if (
                isinstance(effect, dict)
                and effect.get("active", True)
                and effect.get("mechanic_id") == SPELL_RESOLUTION_MECHANIC_ID
                and bool(effect.get("standard_on_hit_mechanic"))
                and str(effect.get("expires_on_actor_id") or "") == actor_id
                and effect.get("expires_at") == phase
                and str(effect.get("activated_turn_token") or "") != turn_token
            ):
                effect["active"] = False
                effect["resolution"] = {
                    "kind": "duration_expired",
                    "actor_id": actor_id,
                    "phase": phase,
                    "turn_token": turn_token,
                }
                expired.append(str(effect.get("id") or ""))
        return expired

    def require_healing_not_prevented(
        encounter: dict[str, Any] | None,
        *,
        target_id: str,
    ) -> None:
        if not isinstance(encounter, dict) or not encounter.get("active", False):
            return
        blocked = next(
            (
                effect
                for effect in encounter.get("ongoing_effects", [])
                if isinstance(effect, dict)
                and effect.get("active", True)
                and effect.get("kind") == "healing_prevention"
                and str(effect.get("target_id") or "") == target_id
            ),
            None,
        )
        if blocked is not None:
            raise CombatEngineError(
                "target cannot regain hit points while a locked standard spell effect is active"
            )

    def consume_next_attack_advantage(
        encounter: dict[str, Any],
        plan: dict[str, Any],
        *,
        attacker_id: str,
        target_id: str,
    ) -> str | None:
        effect_id = str(plan.get("next_attack_advantage_effect_id") or "")
        if not effect_id:
            return None
        effect = next(
            (
                item
                for item in encounter.get("ongoing_effects", [])
                if isinstance(item, dict)
                and str(item.get("id") or "") == effect_id
                and item.get("active", True)
                and item.get("kind") == "next_attack_advantage"
                and str(item.get("target_id") or "") == target_id
            ),
            None,
        )
        if effect is None:
            raise CombatEngineError(
                "next-attack advantage plan does not match an active target effect"
            )
        effect["active"] = False
        effect["resolution"] = {
            "kind": "attack_roll",
            "attacker_id": attacker_id,
            "target_id": target_id,
        }
        return effect_id

    def expire_next_attack_advantage(
        encounter: dict[str, Any],
        *,
        actor_id: str,
        ended_round: int,
    ) -> list[str]:
        expired: list[str] = []
        for effect in encounter.get("ongoing_effects", []):
            if (
                isinstance(effect, dict)
                and effect.get("active", True)
                and effect.get("kind") == "next_attack_advantage"
                and not (
                    effect.get("mechanic_id") == SPELL_RESOLUTION_MECHANIC_ID
                    and bool(effect.get("standard_on_hit_mechanic"))
                )
                and str(effect.get("expires_on_actor_id") or "") == actor_id
                and ended_round >= int(effect.get("expires_on_round", 0) or 0)
            ):
                effect["active"] = False
                effect["resolution"] = {
                    "kind": "duration_expired",
                    "actor_id": actor_id,
                    "round": ended_round,
                }
                expired.append(str(effect.get("id") or ""))
        return expired

    def reveal_attacker_to_target(
        encounter: dict[str, Any], attacker_id: str, target_id: str
    ) -> None:
        """Reveal a hidden attacker to the creature it attacked, hit or miss."""
        attacker = next(
            item for item in encounter.get("combatants", []) if item.get("actor_id") == attacker_id
        )
        attacker["hidden"] = False
        current_visibility = attacker.get("visible_to_actor_ids")
        if current_visibility is None:
            return
        visible_to = {str(item) for item in list(current_visibility or [])} | {
            attacker_id,
            target_id,
        }
        participant_ids = {str(item.get("actor_id")) for item in encounter.get("combatants", [])}
        attacker["visible_to_actor_ids"] = (
            None if participant_ids <= visible_to else sorted(visible_to)
        )

    def apply_cast_visibility_ruling(
        encounter: dict[str, Any],
        campaign_id: str,
        actor_id: str,
        spell: dict[str, Any],
        component_ruling: dict[str, Any] | None,
        principal_id: str,
    ) -> None:
        """Apply an Agent-as-DM observer matrix when casting can break hiding."""
        caster = next(
            item for item in encounter.get("combatants", []) if item.get("actor_id") == actor_id
        )
        if not caster.get("hidden", False):
            return
        components = dict(dict(spell.get("definition") or {}).get("components") or {})
        source_unknown = (
            dict(spell.get("custom_definition") or {}).get("component_details")
            == "not_repeated_in_statblock"
        )
        if not (components.get("verbal") or components.get("somatic") or source_unknown):
            return
        visible_to = {str(item) for item in list(caster.get("visible_to_actor_ids") or [])}
        observers = {
            str(item.get("actor_id"))
            for item in encounter.get("combatants", [])
            if str(item.get("actor_id")) != actor_id
            and "dead" not in {str(value).casefold() for value in item.get("conditions", [])}
            and str(item.get("actor_id")) not in visible_to
        }
        if not observers:
            return
        if not is_dm(campaign_id, principal_id):
            raise NeedsRulingError(
                "a hidden caster's perceivable components require "
                "Agent-as-DM observer adjudication",
                missing=("spell_casting_perception",),
            )
        ruling = dict(component_ruling or {})
        entries = ruling.get("casting_perception")
        if not isinstance(entries, list):
            raise NeedsRulingError(
                "perceivable casting while hidden requires casting_perception",
                missing=("spell_casting_perception",),
            )
        normalized: dict[str, dict[str, Any]] = {}
        for entry in entries:
            if not isinstance(entry, dict) or set(entry) - {
                "observer_id",
                "perceived",
                "reason",
            }:
                raise CombatEngineError(
                    "each casting_perception entry requires observer_id, perceived, "
                    "and optional reason"
                )
            observer_id = str(entry.get("observer_id") or "")
            if observer_id not in observers or observer_id in normalized:
                raise CombatEngineError(
                    "casting_perception observers must be unique hidden-state observers"
                )
            perceived = entry.get("perceived")
            if not isinstance(perceived, bool):
                raise CombatEngineError("casting_perception perceived must be boolean")
            reason = str(entry.get("reason") or "").strip()
            if not perceived and not reason:
                raise CombatEngineError(
                    "an observer that did not perceive casting requires a reason"
                )
            normalized[observer_id] = {
                "observer_id": observer_id,
                "perceived": perceived,
                "reason": reason,
            }
        if set(normalized) != observers:
            raise CombatEngineError(
                "casting_perception must adjudicate every observer that cannot see the caster"
            )
        visible_to.update(
            observer_id for observer_id, entry in normalized.items() if entry["perceived"]
        )
        all_other_ids = {
            str(item.get("actor_id"))
            for item in encounter.get("combatants", [])
            if str(item.get("actor_id")) != actor_id
        }
        if all_other_ids <= visible_to:
            caster["hidden"] = False
            caster["visible_to_actor_ids"] = None
        else:
            caster["visible_to_actor_ids"] = sorted(visible_to | {actor_id})
        encounter["log"] = [
            *list(encounter.get("log") or []),
            {
                "type": "spell_casting_perception",
                "actor_id": actor_id,
                "spell_id": spell.get("id"),
                "observers": list(normalized.values()),
            },
        ][-100:]

    def add_concentration_window(
        encounter: dict[str, Any],
        target_id: str,
        concentration: dict[str, Any] | None,
        *,
        next_revision: int,
    ) -> None:
        """Persist one immediate concentration save without silently replacing another."""
        if not concentration:
            return
        if any(
            item.get("status", "pending") == "pending"
            and item.get("kind") == "concentration"
            and item.get("actor_id") == target_id
            for item in encounter.get("pending", [])
        ):
            raise CombatEngineError(
                "the actor already has a pending concentration save; resolve it first"
            )
        pending = dict(concentration)
        pending.update(
            {
                "id": f"concentration:{target_id}:{next_revision}",
                "kind": "concentration",
                "actor_id": target_id,
            }
        )
        encounter["pending"] = [*list(encounter.get("pending") or []), pending]

    def require_no_blocking_pending(encounter: dict[str, Any]) -> None:
        if any(item.get("status", "pending") == "pending" for item in encounter.get("pending", [])):
            raise CombatEngineError("resolve the pending save or choice before another action")

    def require_combat_spell_turn_legal(
        encounter: dict[str, Any],
        *,
        actor_id: str,
        payment: str,
        spell_level: int,
        casting_time: str,
        spent_slot: bool,
    ) -> list[dict[str, Any]]:
        """Enforce the edition's per-turn spell limit before any resource is spent."""
        turn_casts = list(dict(encounter.get("turn_spell_casts") or {}).get(actor_id, []))
        ruleset = str(encounter.get("ruleset") or "2014")
        if ruleset == "2024" and spent_slot and any(item.get("spent_slot") for item in turn_casts):
            raise CombatEngineError("2024 rules allow only one expended spell slot per turn")
        if ruleset == "2014":
            current_is_bonus = payment == "bonus_action"
            previous_bonus = any(item.get("payment") == "bonus_action" for item in turn_casts)
            if current_is_bonus or previous_bonus:
                casts = [
                    *turn_casts,
                    {
                        "payment": payment,
                        "spell_level": spell_level,
                        "casting_time": casting_time,
                    },
                ]
                if any(
                    item.get("payment") != "bonus_action"
                    and not (
                        int(item.get("spell_level", 1)) == 0
                        and str(item.get("casting_time") or "").startswith("1 action")
                    )
                    for item in casts
                ):
                    raise CombatEngineError(
                        "2014 bonus-action spell rule permits only a 1-action cantrip "
                        "as another spell on the same turn"
                    )
        return turn_casts

    def record_combat_spell_cast(
        encounter: dict[str, Any],
        *,
        actor_id: str,
        spell_id: str,
        spell_level: int,
        payment: str,
        casting_time: str,
        spent_slot: bool,
        **extra: Any,
    ) -> None:
        casts_by_actor = dict(encounter.get("turn_spell_casts") or {})
        casts_by_actor[actor_id] = [
            *list(casts_by_actor.get(actor_id, [])),
            {
                "spell_id": spell_id,
                "spell_level": spell_level,
                "payment": payment,
                "casting_time": casting_time,
                "spent_slot": spent_slot,
                **extra,
            },
        ]
        encounter["turn_spell_casts"] = casts_by_actor

    def post_hit_attack_defenses(
        campaign_id: str,
        target: dict[str, Any],
        *,
        plan: dict[str, Any],
        attack: dict[str, Any],
        encounter: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Combine card activities with legal source-bound spell reactions."""
        spell_options: list[dict[str, Any]] = []
        for discovered in available_shield_attack_defenses(target["sheet"]):
            spell_id = str(discovered.get("spell_id") or discovered.get("id") or "")
            candidate = next(
                (
                    item
                    for item in available_shield_attack_defenses(
                        target["sheet"],
                        rules=effective_rule_context(
                            campaign_id,
                            facts={
                                "actor_id": str(plan["target_id"]),
                                "spell_id": spell_id,
                                "kind": "spell",
                            },
                        ),
                    )
                    if str(item.get("id") or "") == str(discovered.get("id") or "")
                ),
                None,
            )
            if candidate is None:
                continue
            legal_casts = []
            for option in candidate.get("cast_options", []):
                payment = dict(option.get("payment") or {})
                try:
                    require_combat_spell_turn_legal(
                        encounter,
                        actor_id=str(plan["target_id"]),
                        payment="reaction",
                        spell_level=1,
                        casting_time="reaction",
                        spent_slot=payment.get("economy") in SLOT_PAYMENT_ECONOMIES,
                    )
                except CombatEngineError:
                    continue
                legal_casts.append(deepcopy(option))
            if legal_casts:
                spell_options.append(
                    {
                        **candidate,
                        "cast_levels": [int(item["cast_level"]) for item in legal_casts],
                        "cast_options": legal_casts,
                    }
                )
        return available_attack_defenses(
            target,
            plan=plan,
            attack=attack,
            encounter=encounter,
            extra_defenses=spell_options,
        )

    def magic_missile_shield_defenses(
        campaign_id: str,
        target_id: str,
        encounter: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Return Shield casts legal for this exact targeting reaction."""
        combatant = next(
            (
                item
                for item in encounter.get("combatants", [])
                if str(item.get("actor_id") or "") == target_id
            ),
            None,
        )
        if combatant is None:
            raise CombatEngineError(f"combatant not found: {target_id}")
        budget = dict(combatant.get("turn_budget") or {})
        if int(budget.get("reaction", 0) or 0) <= 0 or INCAPACITATING_STATE_IDS & {
            str(item).casefold() for item in combatant.get("conditions", [])
        }:
            return []
        target = combat_actor_snapshot(target_id)
        result: list[dict[str, Any]] = []
        for candidate in available_shield_magic_missile_defenses(
            target["sheet"],
            rules=effective_rule_context(
                campaign_id,
                facts={
                    "actor_id": target_id,
                    "spell_id": "",
                    "kind": "spell_magic_missile_immunity",
                },
            ),
        ):
            legal_casts: list[dict[str, Any]] = []
            for option in candidate.get("cast_options", []):
                payment = dict(option.get("payment") or {})
                try:
                    require_combat_spell_turn_legal(
                        encounter,
                        actor_id=target_id,
                        payment="reaction",
                        spell_level=1,
                        casting_time="reaction",
                        spent_slot=payment.get("economy") in SLOT_PAYMENT_ECONOMIES,
                    )
                except CombatEngineError:
                    continue
                legal_casts.append(deepcopy(option))
            if legal_casts:
                result.append(
                    {
                        **candidate,
                        "cast_levels": [int(item["cast_level"]) for item in legal_casts],
                        "cast_options": legal_casts,
                    }
                )
        return result

    def combat_coordinates(position: Any) -> tuple[float, float] | None:
        if isinstance(position, dict) and "x" in position and "y" in position:
            return float(position["x"]), float(position["y"])
        if isinstance(position, (list, tuple)) and len(position) == 2:
            return float(position[0]), float(position[1])
        return None

    def combat_distance(
        left: Any,
        right: Any,
        *,
        cell_ft: int = 5,
    ) -> int | None:
        left_coordinates = combat_coordinates(left)
        right_coordinates = combat_coordinates(right)
        if left_coordinates is None or right_coordinates is None:
            return None
        return int(
            max(
                abs(left_coordinates[0] - right_coordinates[0]),
                abs(left_coordinates[1] - right_coordinates[1]),
            )
            * int(cell_ft)
        )

    def reconcile_actor_witch_bolt_concentration(
        encounter: dict[str, Any],
        actor_id_value: str,
        sheet: dict[str, Any],
    ) -> list[dict[str, Any]]:
        """Synchronize a caster tether with its exact character concentration."""

        active_ids = {
            str(effect.get("id") or "")
            for effect in sheet.get("effects", [])
            if effect.get("active") and effect.get("concentration")
        }
        reconciled = reconcile_witch_bolt_concentration(
            encounter,
            actor_id_value=actor_id_value,
            active_concentration_effect_ids=active_ids,
        )
        if reconciled["ended"]:
            encounter.clear()
            encounter.update(reconciled["encounter"])
        return list(reconciled["ended"])

    def validate_spell_creature_target(
        encounter: dict[str, Any],
        *,
        caster_id: str,
        target_id: str,
        spell: dict[str, Any],
        resolution: dict[str, Any],
    ) -> dict[str, Any]:
        combatants = {
            str(item.get("actor_id") or ""): item for item in encounter.get("combatants", [])
        }
        caster = combatants.get(caster_id)
        target = combatants.get(target_id)
        if caster is None:
            raise CombatEngineError("spell caster is not in this encounter")
        if target is None:
            raise CombatEngineError(f"spell target is not in this encounter: {target_id}")
        conditions = {str(item).casefold() for item in target.get("conditions", [])}
        if "dead" in conditions:
            raise CombatEngineError("a dead combatant is not a creature target")
        distance = combat_distance(caster.get("position"), target.get("position"))
        if distance is None:
            raise CombatEngineError("spell targeting requires recorded map positions")
        spell_range = dict(dict(spell.get("definition") or {}).get("range") or {})
        range_kind = str(spell_range.get("kind") or "special")
        maximum = 5 if range_kind == "touch" else int(spell_range.get("normal_ft", 0) or 0)
        attack = dict(resolution.get("attack") or {})
        if attack.get("range_ft_override") is not None:
            maximum = int(attack["range_ft_override"])
        if range_kind == "self" and target_id != caster_id:
            raise CombatEngineError("self-range spell must target its caster")
        if range_kind not in {"self", "touch"} and maximum <= 0:
            raise CombatEngineError("spell has no executable target range")
        if range_kind != "self" and distance > maximum:
            raise CombatEngineError("spell target is outside range")
        targeting = dict(resolution.get("targeting") or {})
        concealed = bool(target.get("hidden", False)) or "invisible" in conditions
        visible_to = {str(item) for item in target.get("visible_to_actor_ids") or []}
        if targeting.get("requires_sight") and concealed and caster_id not in visible_to:
            raise CombatEngineError("spell requires a target the caster can see")
        creature_type = str(
            characters.get(target_id).sheet.get("progression", {}).get("species") or ""
        ).casefold()
        for excluded in targeting.get("excluded_creature_types", []):
            if str(excluded).casefold() in creature_type:
                raise CombatEngineError(
                    f"spell has no effect on the target creature type: {excluded}"
                )
        return {"target_id": target_id, "distance_ft": distance}

    def normalize_single_target_declaration(
        encounter: dict[str, Any],
        *,
        caster_id: str,
        spell: dict[str, Any],
        resolution: dict[str, Any],
        declaration: dict[str, Any] | None,
        cover_required: bool = False,
    ) -> dict[str, Any]:
        value = dict(declaration or {})
        if set(value) != {"target_id"} and set(value) != {"target_id", "cover"}:
            raise CombatEngineError("spell declaration requires target_id and optional cover")
        target_id = str(value.get("target_id") or "")
        if not target_id:
            raise CombatEngineError("spell declaration target_id is required")
        target = validate_spell_creature_target(
            encounter,
            caster_id=caster_id,
            target_id=target_id,
            spell=spell,
            resolution=resolution,
        )
        cover = str(value.get("cover") or "").strip().casefold().replace("-", "_")
        if cover_required and cover not in {"none", "half", "three_quarters"}:
            raise CombatEngineError(
                "a Dexterity-save spell requires cover: none, half, or three_quarters"
            )
        if not cover_required and cover:
            raise CombatEngineError("this spell declaration does not accept cover")
        if cover:
            target["cover"] = cover
        return target

    def normalize_area_declaration(
        encounter: dict[str, Any],
        *,
        source_id: str,
        area: dict[str, Any],
        declaration: dict[str, Any] | None,
        origin_range_ft: int = 0,
    ) -> dict[str, Any]:
        value = dict(declaration or {})
        if set(value) != {"origin", "target_contexts"}:
            raise CombatEngineError("area spell declaration requires origin and target_contexts")
        origin = value.get("origin")
        if not isinstance(origin, dict) or set(origin) != {"x", "y"}:
            raise CombatEngineError("area spell origin requires x and y")
        if isinstance(encounter.get("battle_map"), dict):
            validate_position(dict(encounter["battle_map"]), origin)
        combatants = {
            str(item.get("actor_id") or ""): item for item in encounter.get("combatants", [])
        }
        source = combatants.get(source_id)
        if source is None:
            raise CombatEngineError("area source is not in this encounter")
        source_position = source.get("position")
        if not isinstance(source_position, dict):
            raise CombatEngineError("area resolution requires a source position")
        distance_to_origin = combat_distance(source_position, origin)
        if distance_to_origin is None:
            raise CombatEngineError("area resolution requires an executable origin")
        area = dict(area or {})
        shape = str(area.get("shape") or "")
        radius = int(area.get("radius_ft", 0) or 0)
        length = int(area.get("length_ft", 0) or 0)
        width = int(area.get("width_ft", 0) or 0)
        if shape == "sphere":
            if origin_range_ft <= 0:
                raise CombatEngineError("sphere spell requires an executable casting range")
            if distance_to_origin > origin_range_ft:
                raise CombatEngineError("area spell origin is outside range")
        elif shape == "line":
            if distance_to_origin <= 0 or length <= 0 or width <= 0:
                raise CombatEngineError("line spell requires a direction, length, and width")
        elif shape == "cone":
            if distance_to_origin <= 0 or length <= 0:
                raise CombatEngineError("cone area requires a direction and length")
        else:
            raise CombatEngineError("unsupported structured area shape")
        cell_ft = int(
            dict(dict(encounter.get("battle_map") or {}).get("grid") or {}).get("cell_ft", 5) or 5
        )

        def inside_area(position: dict[str, Any]) -> tuple[bool, float]:
            if shape == "sphere":
                distance = combat_distance(origin, position)
                return distance is not None and distance <= radius, float(distance or 0)
            start_x = float(source_position["x"])
            start_y = float(source_position["y"])
            direction_x = float(origin["x"]) - start_x
            direction_y = float(origin["y"]) - start_y
            direction_length = math.hypot(direction_x, direction_y)
            target_x = float(position["x"]) - start_x
            target_y = float(position["y"]) - start_y
            projection_cells = (target_x * direction_x + target_y * direction_y) / direction_length
            perpendicular_cells = (
                abs(target_x * direction_y - target_y * direction_x) / direction_length
            )
            projection_ft = projection_cells * cell_ft
            perpendicular_ft = perpendicular_cells * cell_ft
            maximum_half_width = (
                perpendicular_ft <= width / 2
                if shape == "line"
                else perpendicular_ft <= projection_ft / 2
            )
            return 0 < projection_ft <= length and maximum_half_width, projection_ft

        affected: dict[str, dict[str, Any]] = {}
        for target_id, combatant in combatants.items():
            conditions = {str(item).casefold() for item in combatant.get("conditions", [])}
            if "dead" in conditions:
                continue
            position = combatant.get("position")
            if not isinstance(position, dict):
                raise CombatEngineError(
                    "area resolution cannot enumerate all living combatants without positions"
                )
            included, distance = inside_area(position)
            if included:
                affected[target_id] = {
                    "target_id": target_id,
                    "distance_ft": distance,
                }
        contexts = value.get("target_contexts")
        if not isinstance(contexts, list):
            raise CombatEngineError("area target_contexts must be a list")
        normalized_contexts: dict[str, str] = {}
        for item in contexts:
            if not isinstance(item, dict) or set(item) != {"target_id", "cover"}:
                raise CombatEngineError(
                    "each area target context requires only target_id and cover"
                )
            target_id = str(item.get("target_id") or "")
            cover = str(item.get("cover") or "").casefold().replace("-", "_")
            if (
                not target_id
                or target_id in normalized_contexts
                or cover not in {"none", "half", "three_quarters"}
            ):
                raise CombatEngineError(
                    "area target contexts require unique targets and valid cover"
                )
            normalized_contexts[target_id] = cover
        if set(normalized_contexts) != set(affected):
            raise CombatEngineError(
                "area target_contexts must cover every living combatant in the area"
            )
        for target_id, cover in normalized_contexts.items():
            affected[target_id]["cover"] = cover
        return {
            "shape": shape,
            "origin": {"x": float(origin["x"]), "y": float(origin["y"])},
            "distance_ft": distance_to_origin,
            **({"radius_ft": radius} if shape == "sphere" else {}),
            **(
                {"length_ft": length, **({"width_ft": width} if shape == "line" else {})}
                if shape in {"line", "cone"}
                else {}
            ),
            "targets": list(affected.values()),
        }

    def normalize_hypnotic_pattern_declaration(
        encounter: dict[str, Any],
        *,
        caster_id: str,
        spell: dict[str, Any],
        declaration: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Validate one grid-aligned 30-foot cube and enumerate its creatures."""

        value = dict(declaration or {})
        if set(value) != {"origin", "cube"}:
            raise CombatEngineError("Hypnotic Pattern declaration requires exactly origin and cube")
        origin = value.get("origin")
        cube = value.get("cube")
        if (
            not isinstance(origin, dict)
            or set(origin) != {"x", "y"}
            or not isinstance(cube, dict)
            or set(cube) != {"min", "max"}
        ):
            raise CombatEngineError(
                "Hypnotic Pattern origin and cube min/max must be grid positions"
            )
        minimum = cube.get("min")
        maximum = cube.get("max")
        if (
            not isinstance(minimum, dict)
            or set(minimum) != {"x", "y"}
            or not isinstance(maximum, dict)
            or set(maximum) != {"x", "y"}
        ):
            raise CombatEngineError("Hypnotic Pattern cube requires min and max x/y")
        coordinates = [
            origin["x"],
            origin["y"],
            minimum["x"],
            minimum["y"],
            maximum["x"],
            maximum["y"],
        ]
        if any(
            isinstance(coordinate, bool) or not isinstance(coordinate, int)
            for coordinate in coordinates
        ):
            raise CombatEngineError("Hypnotic Pattern cube positions must use integer grid cells")
        battle_map = dict(encounter.get("battle_map") or {})
        cell_ft = int(dict(battle_map.get("grid") or {}).get("cell_ft", 5) or 5)
        if cell_ft <= 0 or 30 % cell_ft:
            raise CombatEngineError(
                "Hypnotic Pattern requires a grid that divides its 30-foot cube"
            )
        cells = 30 // cell_ft
        if (
            maximum["x"] < minimum["x"]
            or maximum["y"] < minimum["y"]
            or maximum["x"] - minimum["x"] + 1 != cells
            or maximum["y"] - minimum["y"] + 1 != cells
        ):
            raise CombatEngineError(
                f"Hypnotic Pattern cube must cover exactly {cells} by {cells} grid cells"
            )
        if not (
            minimum["x"] <= origin["x"] <= maximum["x"]
            and minimum["y"] <= origin["y"] <= maximum["y"]
            and (
                origin["x"] in {minimum["x"], maximum["x"]}
                or origin["y"] in {minimum["y"], maximum["y"]}
            )
        ):
            raise CombatEngineError(
                "Hypnotic Pattern origin must lie on a face of the declared cube"
            )
        if battle_map:
            for position in (origin, minimum, maximum):
                validate_position(battle_map, position)
        combatants = {
            str(item.get("actor_id") or ""): item for item in encounter.get("combatants", [])
        }
        caster = combatants.get(caster_id)
        if caster is None:
            raise CombatEngineError("Hypnotic Pattern caster is not in this encounter")
        range_ft = int(
            dict(dict(spell.get("definition") or {}).get("range") or {}).get("normal_ft", 0) or 0
        )
        distance_to_origin = combat_distance(
            caster.get("position"),
            origin,
            cell_ft=cell_ft,
        )
        if distance_to_origin is None or range_ft <= 0:
            raise CombatEngineError(
                "Hypnotic Pattern requires caster position and executable range"
            )
        if distance_to_origin > range_ft:
            raise CombatEngineError("Hypnotic Pattern origin is outside range")
        targets: list[dict[str, Any]] = []
        for target_id, combatant in combatants.items():
            conditions = condition_ids(combatant.get("conditions", []))
            if "dead" in conditions:
                continue
            position = combat_coordinates(combatant.get("position"))
            if position is None:
                raise CombatEngineError(
                    "Hypnotic Pattern cannot enumerate living combatants without grid positions"
                )
            x, y = position
            if minimum["x"] <= x <= maximum["x"] and minimum["y"] <= y <= maximum["y"]:
                targets.append(
                    {
                        "target_id": target_id,
                        "position": {"x": x, "y": y},
                        "saw_pattern": "blinded" not in conditions,
                    }
                )
        return {
            "origin": deepcopy(origin),
            "cube": {
                "min": deepcopy(minimum),
                "max": deepcopy(maximum),
                "size_ft": 30,
            },
            "distance_ft": distance_to_origin,
            "targets": targets,
        }

    def advance_spell_attack_resolution(
        encounter: dict[str, Any],
        *,
        resolution_id: str,
        result: dict[str, Any],
    ) -> dict[str, Any]:
        resolutions = dict(encounter.get("spell_resolutions") or {})
        resolution = deepcopy(dict(resolutions.get(resolution_id) or {}))
        if resolution.get("kind") != "spell_attack":
            raise CombatEngineError("spell attack resolution is unavailable")
        remaining = int(resolution.get("remaining_attacks", 0) or 0)
        if remaining < 1:
            raise CombatEngineError("spell attack resolution has no attacks remaining")
        resolution["remaining_attacks"] = remaining - 1
        resolution["results"] = [
            *list(resolution.get("results") or []),
            deepcopy(result),
        ]
        if resolution["remaining_attacks"] == 0:
            resolutions.pop(resolution_id, None)
            encounter["pending"] = [
                item
                for item in encounter.get("pending", [])
                if str(item.get("id") or "") != resolution_id
            ]
        else:
            resolutions[resolution_id] = resolution
            for item in encounter.get("pending", []):
                if str(item.get("id") or "") == resolution_id:
                    item["remaining_attacks"] = resolution["remaining_attacks"]
        if resolutions:
            encounter["spell_resolutions"] = resolutions
        else:
            encounter.pop("spell_resolutions", None)
        return {
            "id": resolution_id,
            "remaining_attacks": resolution["remaining_attacks"],
            "completed": resolution["remaining_attacks"] == 0,
        }

    def validate_magic_missile_targets(
        encounter: dict[str, Any],
        *,
        caster_id: str,
        allocations: list[dict[str, Any]],
        cast_level: int,
    ) -> list[dict[str, Any]]:
        """Validate source-rule targeting against current map and visibility facts."""
        normalized = validate_magic_missile_allocations(allocations, cast_level=cast_level)
        combatants = {
            str(item.get("actor_id") or ""): item for item in encounter.get("combatants", [])
        }
        caster = combatants.get(caster_id)
        if caster is None:
            raise CombatEngineError("Magic Missile caster is not in this encounter")

        caster_position = combat_coordinates(caster.get("position"))
        if caster_position is None:
            raise CombatEngineError("Magic Missile range requires the caster's map position")
        for allocation in normalized:
            target_id = str(allocation["target_id"])
            target = combatants.get(target_id)
            if target is None:
                raise CombatEngineError(
                    f"Magic Missile target is not in this encounter: {target_id}"
                )
            conditions = {str(item).casefold() for item in target.get("conditions", [])}
            if "dead" in conditions:
                raise CombatEngineError("Magic Missile cannot target a dead creature")
            target_position = combat_coordinates(target.get("position"))
            if target_position is None:
                raise CombatEngineError("Magic Missile range requires every target's map position")
            distance = int(
                max(
                    abs(float(caster_position[0]) - float(target_position[0])),
                    abs(float(caster_position[1]) - float(target_position[1])),
                )
                * 5
            )
            if distance > 120:
                raise CombatEngineError("Magic Missile target is outside its 120-foot range")
            concealed = bool(target.get("hidden", False)) or "invisible" in conditions
            visible_to = {str(item) for item in target.get("visible_to_actor_ids") or []}
            if concealed and caster_id not in visible_to:
                raise CombatEngineError("Magic Missile requires a target the caster can see")
            allocation["distance_ft"] = distance
        return normalized

    def settle_magic_missile_damage(
        campaign_id: str,
        encounter: dict[str, Any],
        resolution: dict[str, Any],
        *,
        next_revision: int,
        sheet_overrides: dict[str, dict[str, Any]] | None = None,
    ) -> tuple[dict[str, Any], dict[str, dict[str, Any]], dict[str, Any]]:
        """Roll and apply every dart separately after all target reactions settle."""
        value = deepcopy(encounter)
        sheets = {str(key): deepcopy(item) for key, item in (sheet_overrides or {}).items()}
        shielded = {str(item) for item in resolution.get("shielded_target_ids", [])}
        target_results: list[dict[str, Any]] = []
        concentration_windows: list[dict[str, Any]] = []
        resolution_id = str(resolution["id"])
        spell_id = str(resolution["spell_id"])
        for allocation in resolution.get("allocations", []):
            target_id = str(allocation["target_id"])
            if target_id in shielded:
                target_results.append(
                    {
                        "target_id": target_id,
                        "darts": int(allocation["darts"]),
                        "shielded": True,
                        "dart_results": [],
                    }
                )
                continue
            sheet = sheets.get(target_id)
            if sheet is None:
                sheet = deepcopy(characters.get(target_id).sheet)
            combatant = next(
                item
                for item in value.get("combatants", [])
                if str(item.get("actor_id") or "") == target_id
            )
            dart_results: list[dict[str, Any]] = []
            for dart_index in range(int(allocation["darts"])):
                dice = asdict(roll("1d4+1"))
                applied = apply_damage_to_sheet(
                    sheet,
                    amount=int(dice["total"]),
                    damage_type="force",
                    source=spell_id,
                    ruleset=str(value.get("ruleset") or "2014"),
                    death_saves=combatant_zero_hp_buffered(combatant),
                )
                sheet = applied["sheet"]
                concentration = applied.get("concentration")
                if concentration:
                    concentration_windows.append(
                        {
                            **deepcopy(concentration),
                            "id": (
                                f"concentration:{target_id}:{next_revision}:"
                                f"{resolution_id}:{dart_index}"
                            ),
                            "kind": "concentration",
                            "actor_id": target_id,
                            "source_resolution_id": resolution_id,
                            "dart_index": dart_index,
                        }
                    )
                dart_results.append(
                    {
                        "dart_index": dart_index,
                        "roll": dice,
                        **{key: item for key, item in applied.items() if key != "sheet"},
                    }
                )
            sheets[target_id] = sheet
            sync_combatant_conditions(value, target_id, sheet)
            reconcile_readied_spells(value, target_id, sheet)
            target_results.append(
                {
                    "target_id": target_id,
                    "darts": int(allocation["darts"]),
                    "shielded": False,
                    "dart_results": dart_results,
                }
            )
        value["pending"] = [
            item
            for item in value.get("pending", [])
            if str(item.get("spell_resolution_id") or "") != resolution_id
        ]
        value["pending"] = [*list(value.get("pending") or []), *concentration_windows]
        resolutions = dict(value.get("spell_resolutions") or {})
        resolutions.pop(resolution_id, None)
        if resolutions:
            value["spell_resolutions"] = resolutions
        else:
            value.pop("spell_resolutions", None)
        result = {
            "kind": "magic_missile",
            "spell_id": spell_id,
            "caster_id": str(resolution["caster_id"]),
            "cast_level": int(resolution["cast_level"]),
            "dart_count": sum(int(item["darts"]) for item in resolution["allocations"]),
            "targets": target_results,
            "concentration_windows": len(concentration_windows),
        }
        value["log"] = [
            *list(value.get("log") or []),
            {"type": "magic_missile", "result": deepcopy(result)},
        ][-100:]
        return value, sheets, result

    def record_character_revision(before: Any, after: Any, operation: str) -> None:
        if before.campaign_id is None:
            return
        fields = ("name", "player_name", "summary", "sheet", "notes", "revision")
        revisions.record(
            before.campaign_id,
            operation=operation,
            entity_type="character",
            entity_id=before.id,
            before={field: getattr(before, field) for field in fields},
            after={field: getattr(after, field) for field in fields},
            actor="mcp",
        )

    def narrative_followup_for_mutation(
        campaign: Any,
        *,
        branch_id: str,
        campaign_state: dict[str, Any] | None,
        character_updates: list[CharacterStateUpdate] | None,
    ) -> dict[str, Any] | None:
        """Describe generic named-NPC changes that need an Agent narrative pass."""

        anchored_actor_refs = {
            str(ref)
            for fact in memories.list(
                campaign.id,
                kind="context_anchor",
                branch_id=branch_id,
            )
            for ref in list(dict(fact.metadata or {}).get("related_refs") or [])
            if str(ref).startswith("actor:")
        }
        narrative_actor_changes: dict[str, set[str]] = {}
        for update in character_updates or []:
            before = characters.get(update.character_id)
            actor_ref = f"actor:{before.id}"
            if (
                before.character_type not in NON_PLAYER_CHARACTER_TYPES
                or actor_ref not in anchored_actor_refs
            ):
                continue
            before_sheet = validate_character_sheet(before.sheet)
            after_sheet = validate_character_sheet(update.sheet)
            reasons: set[str] = set()
            if dict(before_sheet.get("combat") or {}).get("hp") != dict(
                after_sheet.get("combat") or {}
            ).get("hp"):
                reasons.add("named_npc_hp_changed")
            if list(before_sheet.get("conditions") or []) != list(
                after_sheet.get("conditions") or []
            ):
                reasons.add("named_npc_conditions_changed")
            before_status = list(
                dict(before_sheet.get("adventure_state") or {}).get("status_tags") or []
            )
            after_status = list(
                dict(after_sheet.get("adventure_state") or {}).get("status_tags") or []
            )
            if before_status != after_status:
                reasons.add("named_npc_status_changed")
            if list(before_sheet.get("effects") or []) != list(after_sheet.get("effects") or []):
                reasons.add("named_npc_effects_changed")
            before_inventory = dict(before_sheet.get("inventory") or {})
            after_inventory = dict(after_sheet.get("inventory") or {})
            if any(
                canonical_json(before_inventory.get(key))
                != canonical_json(after_inventory.get(key))
                for key in ("items", "wallet", "equipment_slots")
            ):
                reasons.add("named_npc_inventory_changed")
            if reasons:
                narrative_actor_changes.setdefault(before.id, set()).update(reasons)
        if campaign_state is not None:
            before_combat = dict(dict(campaign.state or {}).get("combat") or {})
            after_combat = dict(dict(campaign_state or {}).get("combat") or {})

            def combat_actor_positions(value: dict[str, Any]) -> dict[str, tuple[Any, ...]]:
                result: dict[str, tuple[Any, ...]] = {}
                for item in [
                    *list(value.get("combatants") or []),
                    *list(value.get("reinforcements") or []),
                ]:
                    actor_id_value = str(dict(item or {}).get("actor_id") or "")
                    if not actor_id_value:
                        continue
                    actor_ref = f"actor:{actor_id_value}"
                    if actor_ref not in anchored_actor_refs:
                        continue
                    data = dict(item or {})
                    result[actor_id_value] = tuple(
                        canonical_json(data.get(key))
                        for key in ("position", "location", "x", "y", "zone", "status")
                    )
                return result

            before_positions = combat_actor_positions(before_combat)
            after_positions = combat_actor_positions(after_combat)
            for changed_actor_id in sorted(set(before_positions) | set(after_positions)):
                if before_positions.get(changed_actor_id) != after_positions.get(changed_actor_id):
                    narrative_actor_changes.setdefault(changed_actor_id, set()).add(
                        "named_npc_position_changed"
                    )
        if not narrative_actor_changes:
            return None
        scene = npc_turn_scene_projection(modules.current_scene(campaign.id, scope_id="party"))
        related_refs = {
            *(f"actor:{actor_id}" for actor_id in narrative_actor_changes),
            *(
                [f"scene:{scene['scene_id']}"]
                if scene is not None and scene.get("scene_id")
                else []
            ),
        }
        return {
            "status": "agent_review_required",
            "default_resolver": "agent",
            "blocking": False,
            "actor_ids": sorted(narrative_actor_changes),
            "reasons": sorted(
                {reason for reasons in narrative_actor_changes.values() for reason in reasons}
            ),
            "related_refs": sorted(related_refs),
            "recommended_operation": "continuity_context:npc_turn",
        }

    def update_character(
        before: Any,
        *,
        operation: str,
        sheet: dict[str, Any] | None = None,
        notes: dict[str, Any] | None = None,
        name: str | None = None,
        player_name: str | None = None,
        summary: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
        payload: dict[str, Any] | None = None,
        response_extra: dict[str, Any] | None = None,
        flatten_response_extra: bool = False,
        rule_receipts: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        def response_for(character: dict[str, Any]) -> dict[str, Any]:
            if response_extra is None:
                return character
            if flatten_response_extra:
                return {**character, **response_extra}
            return {"character": character, **response_extra}

        if before.campaign_id is None:
            updated = characters.update(
                before.id,
                sheet=sheet,
                notes=notes,
                name=name,
                player_name=player_name,
                summary=summary,
                expected_revision=expected_revision,
            )
            record_character_revision(before, updated, operation)
            return response_for(character_view(updated))
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for character writes"
            )
        branch_id = require_current_branch(before.campaign_id, None)
        request_payload = {
            "operation": operation,
            "character_id": before.id,
            **(payload or {}),
        }
        scope = f"character-write:{before.campaign_id}:{branch_id}:{principal_id}:{before.id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        normalized_sheet = validate_character_sheet(sheet if sheet is not None else before.sheet)
        normalized_notes = (
            validate_character_notes(
                canonical_character_notes(
                    notes,
                    character_type=before.character_type,
                    name=name if name is not None else before.name,
                    summary=summary if summary is not None else before.summary,
                ),
                character_type=before.character_type,
            )
            if notes is not None
            else canonical_character_notes(
                before.notes,
                character_type=before.character_type,
                name=name if name is not None else before.name,
                summary=summary if summary is not None else before.summary,
            )
        )
        character_update = CharacterStateUpdate(
            character_id=before.id,
            sheet=normalized_sheet,
            notes=normalized_notes,
            expected_revision=expected_revision,
            name=name,
            player_name=player_name,
            summary=summary,
        )
        response = response_for(
            character_view(
                replace(
                    before,
                    name=name if name is not None else before.name,
                    player_name=(player_name if player_name is not None else before.player_name),
                    summary=summary if summary is not None else before.summary,
                    sheet=normalized_sheet,
                    notes=normalized_notes,
                    revision=before.revision + 1,
                )
            )
        )
        followup = narrative_followup_for_mutation(
            campaigns.get(before.campaign_id),
            branch_id=branch_id,
            campaign_state=None,
            character_updates=[character_update],
        )
        if followup is not None:
            response = {**response, "narrative_followup": followup}
        stream = active_random_stream()
        if stream is not None and stream.draw_count > 0:
            response = deepcopy(response)
            response.setdefault("random_stream_receipt", stream.receipt())
        StateMutationService(storage.database).replace(
            before.campaign_id,
            character_updates=[character_update],
            operation=operation,
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=response,
            ),
            rule_receipts=rule_receipts,
        )
        return response

    def reconcile_actor_effect_dependencies(
        campaign: Any,
        campaign_state: dict[str, Any] | None,
        character_updates: list[CharacterStateUpdate] | None,
        response_fields: dict[str, Any],
    ) -> tuple[
        dict[str, Any] | None,
        list[CharacterStateUpdate],
        dict[str, Any],
    ]:
        """Apply active encounter effect dependencies before one atomic commit."""

        source_state = (
            deepcopy(campaign_state)
            if campaign_state is not None
            else deepcopy(dict(campaign.state or {}))
        )
        encounter = source_state.get("combat")
        if (
            not isinstance(encounter, dict)
            or not isinstance(encounter.get("dependent_effects"), list)
            or not encounter["dependent_effects"]
        ):
            return campaign_state, list(character_updates or []), response_fields
        active_links = [
            item
            for item in encounter["dependent_effects"]
            if isinstance(item, dict) and item.get("active", True)
        ]
        if not active_links:
            return campaign_state, list(character_updates or []), response_fields
        updates = list(character_updates or [])
        by_actor_id = {item.character_id: item for item in updates}
        actor_ids = {
            str(link.get(field) or "")
            for link in active_links
            for field in ("source_actor_id", "target_actor_id")
        }
        actor_ids.discard("")
        current_records = {
            actor_id_value: characters.get(actor_id_value) for actor_id_value in actor_ids
        }
        sheets = {
            actor_id_value: deepcopy(
                by_actor_id[actor_id_value].sheet
                if actor_id_value in by_actor_id
                else current_records[actor_id_value].sheet
            )
            for actor_id_value in actor_ids
        }
        reconciled = reconcile_effect_dependencies(encounter, sheets)
        if reconciled["encounter"] == encounter and not reconciled["changed_actor_ids"]:
            return campaign_state, updates, response_fields
        next_encounter = reconciled["encounter"]
        for actor_id_value in reconciled["changed_actor_ids"]:
            sheet = reconciled["sheets"][actor_id_value]
            sync_combatant_conditions(next_encounter, actor_id_value, sheet)
            sheet = validate_character_sheet(sheet)
            existing = by_actor_id.get(actor_id_value)
            if existing is not None:
                replacement = replace(existing, sheet=sheet)
                updates[updates.index(existing)] = replacement
                by_actor_id[actor_id_value] = replacement
            else:
                current = current_records[actor_id_value]
                replacement = CharacterStateUpdate(
                    character_id=actor_id_value,
                    sheet=sheet,
                    notes=validate_character_notes(current.notes),
                    expected_revision=current.revision,
                )
                updates.append(replacement)
                by_actor_id[actor_id_value] = replacement
        if reconciled["ended_links"]:
            next_encounter["log"] = [
                *list(next_encounter.get("log") or []),
                *[
                    {
                        "type": "dependent_effect_ended",
                        "dependency_id": str(link.get("id") or ""),
                        "mechanic_id": str(link.get("mechanic_id") or ""),
                        "source_actor_id": str(link.get("source_actor_id") or ""),
                        "target_actor_id": str(link.get("target_actor_id") or ""),
                        "target_effect_id": str(link.get("target_effect_id") or ""),
                        "reason": str(link.get("ended_reason") or ""),
                    }
                    for link in reconciled["ended_links"]
                ],
            ][-100:]
        source_state["combat"] = next_encounter
        next_response_fields = dict(response_fields)
        if "combat" in next_response_fields:
            next_response_fields["combat"] = next_encounter
        result = next_response_fields.get("result")
        if isinstance(result, dict) and isinstance(result.get("targets"), list):
            ended_by_target_effect_id = {
                str(link.get("target_effect_id") or ""): str(link.get("ended_reason") or "")
                for link in reconciled["ended_links"]
            }
            result = deepcopy(result)
            for target_result in result["targets"]:
                if not isinstance(target_result, dict):
                    continue
                effect_id = str(target_result.get("effect_id") or "")
                if effect_id in ended_by_target_effect_id:
                    target_result["effect_active_after_commit"] = False
                    target_result["ended_reason"] = ended_by_target_effect_id[effect_id]
            next_response_fields["result"] = result
        return source_state, updates, next_response_fields

    def commit_campaign_state(
        campaign: Any,
        campaign_state: dict[str, Any] | None,
        *,
        operation: str,
        principal_id: str,
        branch_id: str,
        idempotency_key: str,
        scope: str,
        payload: dict[str, Any],
        response_fields: dict[str, Any],
        character_updates: list[CharacterStateUpdate] | None = None,
        actor_knowledge_transfers: list[ActorKnowledgeTransfer] | None = None,
        rule_receipts: list[dict[str, Any]] | None = None,
        include_campaign_revision: bool = True,
        include_revisions: bool = True,
        expected_campaign_revision: int | None = None,
    ) -> dict[str, Any]:
        """Commit one public state result and its exact retry response atomically."""

        (
            campaign_state,
            character_updates,
            response_fields,
        ) = reconcile_actor_effect_dependencies(
            campaign,
            campaign_state,
            character_updates,
            response_fields,
        )
        if "narrative_followup" not in response_fields:
            followup = narrative_followup_for_mutation(
                campaign,
                branch_id=branch_id,
                campaign_state=campaign_state,
                character_updates=character_updates,
            )
            if followup is not None:
                response_fields = {
                    **response_fields,
                    "narrative_followup": followup,
                }
        stream_before_commit = active_random_stream()
        persists_campaign = campaign_state is not None or (
            stream_before_commit is not None
            and stream_before_commit.campaign_id == campaign.id
            and stream_before_commit.has_unpersisted_draws
        )

        def response_for(revisions: list[Any]) -> dict[str, Any]:
            stream = active_random_stream()
            response = dict(response_fields)
            if include_campaign_revision:
                response["campaign_revision"] = campaign.revision + (1 if persists_campaign else 0)
            if include_revisions:
                response["revisions"] = [asdict(item) for item in revisions]
            if stream is not None and stream.draw_count > 0:
                response["random_stream_receipt"] = stream.receipt()
            return response

        revisions_result = StateMutationService(storage.database).replace(
            campaign.id,
            campaign_state=(
                validate_party_state(campaign_state) if campaign_state is not None else None
            ),
            character_updates=character_updates,
            actor_knowledge_transfers=actor_knowledge_transfers,
            expected_campaign_revision=(
                campaign.revision
                if expected_campaign_revision is None
                else expected_campaign_revision
            ),
            operation=operation,
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=response_for,
            ),
            rule_receipts=rule_receipts,
        )
        return response_for(list(revisions_result or []))

    def party_sheet(state: dict[str, Any]) -> dict[str, Any]:
        value = validate_party_state(state)
        sheet = default_character_sheet()
        sheet["inventory"] = value["party"]["inventory"]
        return validate_character_sheet(sheet)

    def party_state(state: dict[str, Any], sheet: dict[str, Any]) -> dict[str, Any]:
        value = validate_party_state(state)
        value["party"]["inventory"] = sheet["inventory"]
        return validate_party_state(value)

    def party_view_from_state(state: dict[str, Any]) -> dict[str, Any]:
        value = validate_party_state(state)
        sheet = party_sheet(value)
        return {
            "inventory": sheet["inventory"],
            "derived": derive_character_sheet(sheet)["inventory"],
            "notes": value["party"]["notes"],
        }

    def advance_state_game_time(
        state: dict[str, Any],
        *,
        period: str | None = None,
        count: int = 1,
        elapsed_ticks: int | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        """Advance the campaign's sole chronology and optional calendar view."""

        next_state = validate_party_state(deepcopy(state))
        transition = advance_game_time(
            next_state["game_time"],
            world_time=next_state.get("world_time"),
            period=period,
            count=count,
            elapsed_ticks=elapsed_ticks,
        )
        next_state["game_time"] = transition["after"]
        if transition["world_time_after"] is not None:
            next_state["world_time"] = transition["world_time_after"]
        return next_state, transition

    def advance_world_effect_clocks(
        state: dict[str, Any],
        *,
        elapsed_ticks: int = 0,
        period_steps: dict[str, int] | None = None,
    ) -> dict[str, Any]:
        """Advance every world-effect clock through one shared settlement path."""

        next_state = state
        advanced: list[str] = []
        expired: list[str] = []
        if elapsed_ticks:
            elapsed = advance_elapsed_world_effect_durations(
                next_state,
                elapsed_ticks=elapsed_ticks,
            )
            next_state = elapsed["state"]
            advanced.extend(elapsed["advanced"])
            expired.extend(elapsed["expired"])
        for period, amount in dict(period_steps or {}).items():
            if not amount:
                continue
            stepped = advance_world_effect_durations(
                next_state,
                period=period,
                amount=amount,
            )
            next_state = stepped["state"]
            advanced.extend(stepped["advanced"])
            expired.extend(stepped["expired"])
        return {
            "state": next_state,
            "advanced": list(dict.fromkeys(advanced)),
            "expired": list(dict.fromkeys(expired)),
        }

    def completed_spell_cast_ticks(
        spell: dict[str, Any],
        *,
        ritual: bool,
    ) -> int:
        """Resolve common source casting times onto the canonical 6-second scale."""

        casting_time = str(
            dict(spell.get("definition") or {}).get("casting_time") or "1 action"
        ).strip()
        normalized = casting_time.casefold()
        if normalized in {
            "action",
            "1 action",
            "bonus action",
            "1 bonus action",
            "reaction",
            "1 reaction",
        }:
            ticks = 1
        else:
            match = re.fullmatch(r"(\d+)\s+(minute|minutes|hour|hours)", normalized)
            if match is None:
                raise NeedsRulingError(
                    "this spell's casting time needs an Agent ruling before time can advance",
                    missing=("casting_time",),
                    ruling_kind="source_or_scene_fact",
                )
            amount = int(match.group(1))
            unit = "minute" if match.group(2).startswith("minute") else "hour"
            ticks = game_time_ticks(unit, amount)
        if ritual:
            ticks += game_time_ticks("minute", 10)
        return ticks

    def inventory_item_for_receipt(
        target_sheet: dict[str, Any],
        item: dict[str, Any],
    ) -> dict[str, Any]:
        """Detach inventory-local links that do not exist at the destination."""
        received = deepcopy(item)
        if str(received.get("kind") or "") != "weapon":
            return received
        mechanics = dict(received.get("mechanics") or {})
        ammunition_item_id = str(mechanics.get("ammunition_item_id") or "").strip()
        if not ammunition_item_id:
            return received
        target_ammunition = next(
            (
                candidate
                for candidate in dict(target_sheet.get("inventory") or {}).get("items", [])
                if str(candidate.get("id") or "") == ammunition_item_id
                and str(candidate.get("kind") or "") == "ammunition"
            ),
            None,
        )
        if target_ammunition is None:
            mechanics["ammunition_item_id"] = None
            received["mechanics"] = mechanics
        return received

    def replay_idempotent(
        scope: str, key: str | None, payload: dict[str, Any]
    ) -> dict[str, Any] | None:
        if not key:
            return None
        result = idempotency.lookup(scope, key, payload)
        if result is not None:
            return result.response
        campaign_id = next(
            (
                component
                for component in scope.split(":")
                if re.fullmatch(
                    r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-"
                    r"[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}",
                    component,
                )
            ),
            "",
        )
        if campaign_id:
            bind_idempotency_request(
                campaign_id,
                current_branch_id(campaign_id),
                key,
                payload,
            )
        if campaign_id and idempotency.mutation_committed(
            campaign_id,
            key,
            payload,
            branch_id=current_branch_id(campaign_id),
        ):
            return {
                "status": "committed",
                "idempotency_replayed": True,
                "response_recovery": "read_current_state",
            }
        return None

    def remember_idempotent(
        scope: str,
        key: str | None,
        payload: dict[str, Any],
        response: dict[str, Any],
        campaign_id: str | None = None,
    ) -> dict[str, Any]:
        stream = active_random_stream()
        if stream is not None and stream.draw_count > 0 and not stream.has_unpersisted_draws:
            response = deepcopy(response)
            response.setdefault("random_stream_receipt", stream.receipt())
        if key:
            idempotency.remember(scope, key, payload, response, campaign_id=campaign_id)
        return response

