    def character_inventory_add(
        character_id: str,
        item: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Add a normalized inventory item and return its assigned item id."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "inventory changes")
        campaign = campaigns.get(current.campaign_id) if current.campaign_id else None
        phase = authoritative_phase(current.campaign_id) if campaign is not None else PROFILE_LOBBY
        if item.get("attunement") == "attuned" and phase != PROFILE_LOBBY:
            raise CombatEngineError(
                "an item can enter Play as required, but attunement must be "
                "completed through a short rest"
            )
        sheet, item_id = add_inventory_item(current.sheet, item)
        return update_sheet(
            character_id,
            sheet,
            operation="character.inventory.add",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"item": item},
            response_extra={"item_id": item_id},
        )

    def character_inventory_update(
        character_id: str,
        item_id: str,
        patch: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Update one structured inventory item without bypassing D&D validation."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "inventory changes")
        normalized_patch = deepcopy(patch)
        patched_mechanics = normalized_patch.get("mechanics")
        if (
            isinstance(patched_mechanics, dict)
            and dict(patched_mechanics).get("spellcasting") is not None
        ):
            if current.campaign_id is None:
                raise ValueError("magic item spell hydration requires a campaign-bound character")
            current_item = next(
                (
                    item
                    for item in current.sheet.get("inventory", {}).get("items", [])
                    if str(item.get("id") or "") == item_id
                ),
                None,
            )
            if current_item is None:
                raise LookupError(item_id)
            hydrated = hydrate_magic_item_spell_artifacts(
                current.campaign_id,
                {**deepcopy(current_item), **normalized_patch, "id": item_id},
            )
            normalized_patch["mechanics"] = deepcopy(hydrated["mechanics"])
        if "attunement" in normalized_patch:
            campaign = campaigns.get(current.campaign_id) if current.campaign_id else None
            phase = (
                authoritative_phase(current.campaign_id) if campaign is not None else PROFILE_LOBBY
            )
            current_item = next(
                (
                    item
                    for item in current.sheet.get("inventory", {}).get("items", [])
                    if str(item.get("id") or "") == item_id
                ),
                None,
            )
            if (
                phase != PROFILE_LOBBY
                and current_item is not None
                and normalized_patch["attunement"] != current_item.get("attunement")
            ):
                raise CombatEngineError(
                    "attunement cannot be patched during Play; use a short rest"
                )
        return update_sheet(
            character_id,
            update_inventory_item(current.sheet, item_id, normalized_patch),
            operation="character.inventory.update",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"item_id": item_id, "patch": normalized_patch},
        )

