    def character_level_advance(
        character_id: str,
        class_name: str,
        hp_method: str,
        reason: str,
        source_ref: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Advance one existing 2014 class level during the lobby phase."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "level advancement")
        if current.campaign_id is None:
            raise ValueError("level advancement requires a campaign-bound character")
        if not is_dm(current.campaign_id, principal_id):
            raise PermissionError("level advancement requires the campaign DM")
        campaign = campaigns.get(current.campaign_id)
        advancement_mode = campaign_advancement_mode(campaign)
        if authoritative_phase(current.campaign_id) != PROFILE_LOBBY:
            raise CombatEngineError("switch to lobby before advancing a character level")
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for level advancement"
            )
        normalized_reason = str(reason).strip()
        if not normalized_reason:
            raise ValueError("reason and source_ref are required for audited level advancement")
        if len(normalized_reason) > 1000:
            raise ValueError("level advancement reason must not exceed 1000 characters")
        branch_id = require_current_branch(current.campaign_id, None)
        normalized_source_ref = advancement_source_ref(
            current.campaign_id,
            source_ref,
            branch_id=branch_id,
        )
        mutation_payload = {
            "class_name": class_name,
            "hp_method": hp_method,
            "reason": normalized_reason,
            "source_ref": normalized_source_ref,
        }
        request_payload = {
            "operation": "character.level.advance",
            "character_id": character_id,
            **mutation_payload,
        }
        scope = f"character-write:{current.campaign_id}:{branch_id}:{principal_id}:{character_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        if current.revision != expected_revision:
            raise ValueError(f"character revision conflict: {character_id}")
        old_level = int(current.sheet.get("progression", {}).get("level", 0) or 0)
        experience_before = experience_status(current.sheet)
        if advancement_mode == "xp" and not experience_before["eligible"]:
            raise CombatEngineError("character has not reached the XP threshold for the next level")
        context = level_advancement_content_context(
            current.campaign_id,
            current.sheet,
            class_name=class_name,
            new_level=old_level + 1,
            branch_id=branch_id,
        )
        rules = effective_rule_context(
            current.campaign_id,
            facts={
                "actor_id": character_id,
                "class_name": class_name,
                "old_level": old_level,
                "new_level": old_level + 1,
                "source_ref": normalized_source_ref,
                "advancement_mode": advancement_mode,
                "experience": experience_before["xp"],
            },
        )
        applied = advance_single_class_level(
            current.sheet,
            class_name=class_name,
            hp_method=hp_method,
            hp_per_level_bonus=int(context["hp_per_level_bonus"]),
            source=f"{class_name} level {old_level + 1}",
            source_ref=normalized_source_ref,
            reason=normalized_reason,
        )
        applied["species_feature_grants"] = refresh_level_unlocked_species_features(
            applied["sheet"]
        )
        applied["subclass_spell_grants"] = refresh_level_unlocked_subclass_spells(
            current.campaign_id,
            applied["sheet"],
            class_name=class_name,
            branch_id=branch_id,
        )
        receipts = core_receipts(
            rules,
            [
                "dnd5e.core.progression.hp_hit_dice",
                "dnd5e.core.progression.spellcasting",
            ],
            "character.level.advance",
        )
        follow_up = {
            "feature_artifacts": context["feature_options"],
            "subclass_options": context["subclass_options"],
            "spell_choices": applied["spell_choices"],
            # In 2014, gaining a level can add cantrips, known spells, or
            # wizard spellbook entries.  A prepared list itself changes only
            # when the character finishes a long rest.
            "prepared_spell_event": None,
            "complete": not (
                context["feature_options"]
                or context["subclass_options"]
                or any(int(value) for value in applied["spell_choices"].values())
            ),
        }
        result = {key: value for key, value in applied.items() if key != "sheet"}
        result["mode"] = advancement_mode
        result["experience_before"] = experience_before
        result["experience_after"] = experience_status(applied["sheet"])
        result["hp_bonus_sources"] = context["hp_bonus_sources"]
        result["follow_up"] = follow_up
        return update_sheet(
            character_id,
            applied["sheet"],
            operation="character.level.advance",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload=mutation_payload,
            response_extra={
                "status": "committed",
                "advancement": result,
                "rule_receipts": receipts,
            },
            rule_receipts=receipts,
        )

    def character_class_resources_synchronize(
        character_id: str,
        reason: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Reconcile deterministic class-card resources during lobby maintenance."""

        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "class resource synchronization")
        if current.campaign_id is None:
            raise ValueError("class resource synchronization requires a campaign-bound character")
        if not is_dm(current.campaign_id, principal_id):
            raise PermissionError("class resource synchronization requires the campaign DM")
        if authoritative_phase(current.campaign_id) != PROFILE_LOBBY:
            raise CombatEngineError("switch to lobby before synchronizing class feature resources")
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for "
                "class resource synchronization"
            )
        normalized_reason = str(reason).strip()
        if not normalized_reason:
            raise ValueError("class resource synchronization requires a reason")
        if len(normalized_reason) > 1000:
            raise ValueError(
                "class resource synchronization reason must not exceed 1000 characters"
            )
        synchronized = synchronize_class_feature_resources(current.sheet)
        return update_sheet(
            character_id,
            synchronized["sheet"],
            operation="character.resources.synchronize",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"reason": normalized_reason},
            response_extra={
                "status": "committed",
                "reason": normalized_reason,
                "changes": synchronized["changes"],
            },
        )

    def character_level_advancement_plan(
        character_id: str,
        class_name: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Preview all source-bound follow-up work without committing a level."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "level advancement planning")
        if current.campaign_id is None:
            raise ValueError("level advancement planning requires a campaign-bound character")
        if not is_dm(current.campaign_id, principal_id):
            raise PermissionError("level advancement planning requires the campaign DM")
        campaign = campaigns.get(current.campaign_id)
        if authoritative_phase(current.campaign_id) != PROFILE_LOBBY:
            raise CombatEngineError("switch to lobby before planning a character level")
        branch_id = require_current_branch(current.campaign_id, None)
        old_level = int(current.sheet.get("progression", {}).get("level", 0) or 0)
        experience = experience_status(current.sheet)
        advancement_mode = campaign_advancement_mode(campaign)
        context = level_advancement_content_context(
            current.campaign_id,
            current.sheet,
            class_name=class_name,
            new_level=old_level + 1,
            branch_id=branch_id,
        )
        preview = advance_single_class_level(
            current.sheet,
            class_name=class_name,
            hp_method="fixed",
            hp_per_level_bonus=int(context["hp_per_level_bonus"]),
            source="read-only advancement plan",
        )
        spellcasting = dict(preview["sheet"].get("spellcasting") or {})
        preparation = dict(spellcasting.get("preparation") or {})
        maximum_spell_level = max(
            [
                int(level)
                for level, resource in dict(spellcasting.get("spell_slots") or {}).items()
                if int(dict(resource).get("max", 0) or 0) > 0
            ]
            + [int(dict(spellcasting.get("pact_magic") or {}).get("slot_level", 0) or 0)]
        )
        follow_up = {
            "feature_artifacts": context["feature_options"],
            "subclass_options": context["subclass_options"],
            "spell_choices": preview["spell_choices"],
            "prepared_spell_event": None,
        }
        follow_up["complete"] = not (
            follow_up["feature_artifacts"]
            or follow_up["subclass_options"]
            or any(int(value) for value in dict(follow_up["spell_choices"]).values())
            or follow_up["prepared_spell_event"]
        )
        return {
            "status": (
                "ready" if advancement_mode != "xp" or experience["eligible"] else "ineligible"
            ),
            "character_id": current.id,
            "character_revision": current.revision,
            "campaign_id": current.campaign_id,
            "campaign_revision": campaign.revision,
            "branch_id": branch_id,
            "class_name": str(class_name).strip(),
            "old_level": old_level,
            "new_level": old_level + 1,
            "mode": advancement_mode,
            "experience": experience,
            "hp_bonus_sources": context["hp_bonus_sources"],
            "follow_up": follow_up,
            "spellcasting": {
                "mode": str(preview["spellcasting"].get("mode") or ""),
                "preparation_mode": str(preparation.get("mode") or "known"),
                "maximum_spell_level": maximum_spell_level,
            },
        }

    @_agent_ruling_boundary
    def character_cast_spell(
        character_id: str,
        spell_id: str,
        cast_level: int | None = None,
        ritual: bool = False,
        signature_free_cast: bool = False,
        feature_cast_source: str | None = None,
        component_ruling: dict[str, Any] | None = None,
        source_item_id: str | None = None,
        target_character_ids: list[str] | None = None,
        willing_target_ids: list[str] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Pay canonical spell resources and start concentration from a v2 spell card."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "spell casting")
        if current.campaign_id is None:
            raise ValueError("spell casting requires a campaign-bound character")
        if expected_revision is None or not idempotency_key:
            raise ValueError("expected_revision and idempotency_key are required for spell casting")
        branch_id = require_current_branch(current.campaign_id, None)
        payload = {
            "character_id": character_id,
            "spell_id": spell_id,
            "cast_level": cast_level,
            "ritual": ritual,
            "signature_free_cast": signature_free_cast,
            "feature_cast_source": feature_cast_source,
            "component_ruling": component_ruling or {},
            "source_item_id": source_item_id,
            "target_character_ids": target_character_ids,
            "willing_target_ids": willing_target_ids,
        }
        scope = f"character-cast:{current.campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if current.revision != expected_revision:
            raise ValueError(
                f"character revision conflict: expected {expected_revision}, "
                f"found {current.revision}"
            )
        if source_item_id and (signature_free_cast or feature_cast_source):
            raise CombatEngineError(
                "a magic item spell cannot use a character feature casting source"
            )
        campaign = campaigns.get(current.campaign_id)
        next_state = validate_party_state(deepcopy(campaign.state or {}))
        spell_entry = (
            magic_item_spell_card(
                current.sheet,
                source_item_id=source_item_id,
                spell_id=spell_id,
            )
            if source_item_id
            else next(
                item
                for item in current.sheet.get("content", {}).get("spells", [])
                if item.get("id") == spell_id
            )
        )
        fly = is_core_fly_spell(spell_entry)
        invisibility = is_core_invisibility_spell(spell_entry)
        normalized_fly_targets: list[str] = []
        normalized_willing_targets: list[str] = []
        normalized_invisibility_targets: list[str] = []
        if fly:
            if str(current.sheet.get("edition") or "") != "2014":
                raise CombatEngineError("the source-bound Fly mechanic is a 2014 rule")
            if spell_id not in CORE_FLY_SPELL_IDS:
                raise CombatEngineError(
                    "the Core Fly path requires its exact source-bound SRD spell id"
                )
            normalized_fly_targets = [str(item).strip() for item in (target_character_ids or [])]
            normalized_willing_targets = [str(item).strip() for item in (willing_target_ids or [])]
            resolved_fly_level = int(
                cast_level if cast_level is not None else spell_entry.get("level", 0) or 0
            )
            if (
                not normalized_fly_targets
                or any(not item for item in normalized_fly_targets)
                or len(normalized_fly_targets) != len(set(normalized_fly_targets))
                or set(normalized_willing_targets) != set(normalized_fly_targets)
                or len(normalized_willing_targets) != len(set(normalized_willing_targets))
                or len(normalized_fly_targets) > fly_target_limit(resolved_fly_level)
            ):
                raise CombatEngineError(
                    "Fly requires unique willing targets within its cast-level limit"
                )
            for target_id in normalized_fly_targets:
                target = characters.get(target_id)
                if target.campaign_id != current.campaign_id:
                    raise CombatEngineError("every Fly target must belong to the caster's campaign")
                access.require_actor(
                    current.campaign_id,
                    target_id,
                    principal_id,
                    control=True,
                )
        elif invisibility:
            if source_item_id is not None:
                raise CombatEngineError("the Core Invisibility path requires its actor spell card")
            if str(current.sheet.get("edition") or "") != "2014":
                raise CombatEngineError("the source-bound Invisibility mechanic is a 2014 rule")
            if spell_id not in CORE_INVISIBILITY_SPELL_IDS:
                raise CombatEngineError(
                    "the Core Invisibility path requires its exact source-bound SRD spell id"
                )
            if willing_target_ids is not None:
                raise CombatEngineError("Invisibility does not use willing_target_ids")
            normalized_invisibility_targets = [
                str(item).strip() for item in (target_character_ids or [])
            ]
            resolved_invisibility_level = int(
                cast_level if cast_level is not None else spell_entry.get("level", 0) or 0
            )
            if (
                not normalized_invisibility_targets
                or any(not item for item in normalized_invisibility_targets)
                or len(normalized_invisibility_targets) != len(set(normalized_invisibility_targets))
                or len(normalized_invisibility_targets)
                > invisibility_target_limit(resolved_invisibility_level)
            ):
                raise CombatEngineError(
                    "Invisibility requires unique targets within its cast-level limit"
                )
            for target_id in normalized_invisibility_targets:
                target = characters.get(target_id)
                if target.campaign_id != current.campaign_id:
                    raise CombatEngineError(
                        "every Invisibility target must belong to the caster's campaign"
                    )
        elif target_character_ids is not None or willing_target_ids is not None:
            raise CombatEngineError(
                "target_character_ids and willing_target_ids are currently "
                "reserved for engine-settled target mechanics"
            )
        compiled_spell_plan = None
        if source_item_id is None and isinstance(spell_entry.get("resolution_plan"), dict):
            _spell_card, compiled_spell_plan = character_resolution_plan(
                current.sheet,
                spell_id,
                "spell",
            )
        elif (
            source_item_id is None
            and str(
                spell_entry.get("effect")
                or dict(spell_entry.get("definition") or {}).get("effect")
                or ""
            ).strip()
            and not fly
            and not invisibility
            and not source_card_has_executable_mechanic(
                current.campaign_id,
                spell_entry,
            )
        ):
            return {
                **_ruling_status(
                    "pending_ruling",
                    "generic_spell_effect",
                ),
                "result": {
                    "spell_id": spell_id,
                    "semantic_solution": unresolved_content_solution(
                        spell_entry,
                        source_card_id=spell_id,
                        source_card_kind="spell",
                        character_revision=current.revision,
                    ),
                    "payment_required": False,
                },
                "character": character_view(current),
                "campaign_revision": campaign.revision,
            }
        elapsed_ticks = completed_spell_cast_ticks(spell_entry, ritual=ritual)
        next_state, time_transition = advance_state_game_time(
            next_state,
            elapsed_ticks=elapsed_ticks,
        )
        elapsed_minutes = int(time_transition["elapsed_minutes"])
        world_duration = advance_world_effect_clocks(
            next_state,
            elapsed_ticks=elapsed_ticks,
            period_steps={"round": elapsed_ticks},
        )
        next_state = world_duration["state"]
        world_advanced = world_duration["advanced"]
        world_expired = world_duration["expired"]
        rules = effective_rule_context(
            current.campaign_id,
            facts={
                "actor_id": character_id,
                "spell_id": spell_id,
                "cast_level": cast_level,
                "source_item_id": source_item_id,
                "feature_cast_source": feature_cast_source,
            },
        )
        timed_sheets: dict[str, dict[str, Any]] = {}
        advanced: dict[str, list[str]] = {}
        expired: dict[str, list[str]] = {}
        rule_receipts: list[dict[str, Any]] = []
        all_characters = characters.list(campaign_id=current.campaign_id)
        for character in all_characters:
            round_duration = advance_effect_durations(
                character.sheet,
                period="round",
                amount=elapsed_ticks,
            )
            sheet = round_duration["sheet"]
            actor_advanced = list(round_duration["advanced"])
            actor_expired = list(round_duration["expired"])
            elapsed_duration = advance_elapsed_effect_durations(
                sheet,
                elapsed_ticks=elapsed_ticks,
            )
            sheet = elapsed_duration["sheet"]
            actor_advanced.extend(elapsed_duration["advanced"])
            actor_expired.extend(elapsed_duration["expired"])
            duration_extension = apply_rule_event(
                sheet,
                "duration.advance",
                context_with_facts(
                    rules,
                    actor_id=character.id,
                    period="round",
                    amount=elapsed_ticks,
                    elapsed_ticks=elapsed_ticks,
                    elapsed_minutes=elapsed_minutes,
                ),
            )
            timed_sheets[character.id] = duration_extension.sheet
            rule_receipts.extend(duration_extension.receipts)
            if actor_advanced:
                advanced[character.id] = list(dict.fromkeys(actor_advanced))
            if actor_expired:
                expired[character.id] = list(dict.fromkeys(actor_expired))
        applied = (
            consume_magic_item_spell_cast(
                timed_sheets[current.id],
                source_item_id=source_item_id,
                spell_id=spell_id,
                cast_level=cast_level,
                ritual=ritual,
                rules=rules,
            )
            if source_item_id
            else consume_spell_cast(
                timed_sheets[current.id],
                spell_id=spell_id,
                cast_level=cast_level,
                ritual=ritual,
                signature_free_cast=signature_free_cast,
                feature_cast_source=feature_cast_source,
                component_ruling=component_ruling,
                rules=rules,
            )
        )
        applied = settle_magic_item_last_charge(
            applied,
            source_item_id=source_item_id,
            rules=rules,
        )
        if applied.get("status") in PENDING_RULE_RESULT_STATUSES:
            pending_result = {key: value for key, value in applied.items() if key != "sheet"}
            if compiled_spell_plan is not None:
                pending_result["resolution_plan_contract"] = resolution_plan_contract(
                    compiled_spell_plan
                )
            return {
                **_ruling_status(
                    applied["status"],
                    _pending_result_ruling_kind(applied),
                ),
                "result": pending_result,
                "character": character_view(current),
            }
        timed_sheets[current.id] = applied["sheet"]
        if fly:
            concentration_effect = next(
                (
                    effect
                    for effect in applied["sheet"].get("effects", [])
                    if effect.get("active")
                    and effect.get("concentration")
                    and str(effect.get("source_spell_id") or "") in CORE_FLY_SPELL_IDS
                ),
                None,
            )
            if concentration_effect is None:
                raise CombatEngineError("Fly did not create its required concentration effect")
            fly_result = apply_core_fly_effects(
                timed_sheets,
                caster_id=current.id,
                target_ids=normalized_fly_targets,
                willing_target_ids=normalized_willing_targets,
                spell_id=spell_id,
                cast_level=int(applied.get("cast_level", cast_level or 3) or 3),
                concentration_effect_id=str(concentration_effect["id"]),
            )
            reconciled = reconcile_source_effect_dependencies(fly_result["sheets"])
            timed_sheets = reconciled["sheets"]
            applied["sheet"] = timed_sheets[current.id]
            applied["automatic_effect"] = "fly"
            applied["effect_ids"] = fly_result["effect_ids"]
            applied["target_ids"] = fly_result["target_ids"]
            applied["target_limit"] = fly_result["target_limit"]
            applied["concentration_effect_id"] = fly_result["concentration_effect_id"]
            applied["ruling_required"] = [
                item
                for item in applied.get("ruling_required") or []
                if item != "targets_and_effect"
            ]
            applied["ruling_requirements"] = [
                item
                for item in applied.get("ruling_requirements") or []
                if item.get("kind") != "targets_and_effect"
            ]
            rule_receipts.extend(
                core_receipts(
                    rules,
                    [CORE_FLY_MECHANIC_ID],
                    "spell.fly",
                )
            )
        if invisibility:
            concentration_effect = next(
                (
                    effect
                    for effect in applied["sheet"].get("effects", [])
                    if effect.get("active")
                    and effect.get("concentration")
                    and str(effect.get("source_spell_id") or "") in CORE_INVISIBILITY_SPELL_IDS
                ),
                None,
            )
            if concentration_effect is None:
                raise CombatEngineError(
                    "Invisibility did not create its required concentration effect"
                )
            invisibility_result = apply_core_invisibility_effects(
                timed_sheets,
                caster_id=current.id,
                target_ids=normalized_invisibility_targets,
                spell_id=spell_id,
                cast_level=int(applied.get("cast_level", cast_level or 2) or 2),
                concentration_effect_id=str(concentration_effect["id"]),
            )
            timed_sheets = invisibility_result["sheets"]
            applied["sheet"] = timed_sheets[current.id]
            applied["automatic_effect"] = "invisibility"
            applied["effect_ids"] = invisibility_result["effect_ids"]
            applied["target_ids"] = invisibility_result["target_ids"]
            applied["target_limit"] = invisibility_result["target_limit"]
            applied["concentration_effect_id"] = invisibility_result["concentration_effect_id"]
            applied["ruling_required"] = [
                item
                for item in applied.get("ruling_required") or []
                if item != "targets_and_effect"
            ]
            applied["ruling_requirements"] = [
                item
                for item in applied.get("ruling_requirements") or []
                if item.get("kind") != "targets_and_effect"
            ]
            rule_receipts.extend(
                core_receipts(
                    rules,
                    [CORE_INVISIBILITY_MECHANIC_ID],
                    "spell.invisibility",
                )
            )
        reconciled_dependencies = reconcile_source_effect_dependencies(timed_sheets)
        timed_sheets = reconciled_dependencies["sheets"]
        applied["sheet"] = timed_sheets[current.id]
        rule_receipts.extend(applied.get("rule_receipts") or [])
        updates = [
            CharacterStateUpdate(
                character_id=character.id,
                sheet=validate_character_sheet(timed_sheets[character.id]),
                notes=validate_character_notes(character.notes),
                expected_revision=(
                    expected_revision if character.id == current.id else character.revision
                ),
            )
            for character in all_characters
            if timed_sheets[character.id] != character.sheet
        ]
        current_after = replace(
            current,
            sheet=validate_character_sheet(timed_sheets[current.id]),
            notes=validate_character_notes(current.notes),
            revision=current.revision + 1,
        )
        current_after_view = character_view(current_after)

        applied_result = {key: value for key, value in applied.items() if key != "sheet"}
        if compiled_spell_plan is not None:
            applied_result["resolution_plan_contract"] = resolution_plan_contract(
                compiled_spell_plan
            )
            applied_result["semantic_solution"] = {
                "status": "compiled",
                "payment_recorded": True,
            }

        def cast_response(revisions: list[Any]) -> dict[str, Any]:
            return {
                **_ruling_status(
                    "committed" if applied.get("automatic_effect") else "pending_ruling",
                    "generic_spell_effect",
                ),
                "result": deepcopy(applied_result),
                "character": current_after_view,
                "game_time": time_transition["after"],
                "world_time": time_transition["world_time_after"],
                "elapsed_ticks": elapsed_ticks,
                "elapsed_minutes": elapsed_minutes,
                "advanced": advanced,
                "expired": expired,
                "world_advanced": list(dict.fromkeys(world_advanced)),
                "world_expired": list(dict.fromkeys(world_expired)),
                "campaign_revision": campaign.revision + 1,
                "revisions": [asdict(item) for item in revisions],
            }

        revisions_result = StateMutationService(storage.database).replace(
            current.campaign_id,
            campaign_state=next_state,
            character_updates=updates,
            expected_campaign_revision=campaign.revision,
            operation=(
                "character.magic_item.spell.cast" if source_item_id else "character.spell.cast"
            ),
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=cast_response,
            ),
            rule_receipts=rule_receipts,
        )
        return cast_response(list(revisions_result or []))

    @_agent_ruling_boundary
    def campaign_party_rest(
        campaign_id: str,
        members: list[dict[str, Any]],
        duration_minutes: int = LONG_REST_MINIMUM_MINUTES,
        rest_type: str = "long_rest",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Advance one short or long rest and settle every member atomically."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        normalized_rest_type = str(rest_type).strip().lower().replace("-", "_")
        if normalized_rest_type not in REST_TYPES:
            raise CombatEngineError("rest_type must be short_rest or long_rest")
        if isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int):
            raise ValueError("duration_minutes must be an integer")
        minimum_possible_minutes = minimum_rest_minutes(
            normalized_rest_type,
            allows_trance=True,
        )
        if duration_minutes < minimum_possible_minutes:
            raise CombatEngineError(
                f"{normalized_rest_type} requires at least {minimum_possible_minutes} minutes"
            )
        if not isinstance(members, list) or not members:
            raise ValueError("party rest requires at least one member")
        allowed_member_fields = {
            "character_id",
            "expected_revision",
            "prepared_spell_ids",
            "hit_dice_recovery",
            "rest_activity_minutes",
            "food_and_drink",
            "hit_dice_spends",
            "arcane_recovery",
            "natural_recovery",
            "sorcerous_restoration_points",
            "song_of_rest_source_actor_id",
            "attune_item_id",
            "attunement_prerequisite_confirmed",
        }
        long_rest_fields = {
            "prepared_spell_ids",
            "hit_dice_recovery",
            "food_and_drink",
        }
        short_rest_fields = {
            "hit_dice_spends",
            "arcane_recovery",
            "natural_recovery",
            "sorcerous_restoration_points",
            "song_of_rest_source_actor_id",
            "attune_item_id",
            "attunement_prerequisite_confirmed",
        }
        normalized_members: list[dict[str, Any]] = []
        member_ids: list[str] = []
        for index, raw_member in enumerate(members):
            if not isinstance(raw_member, dict):
                raise ValueError(f"members[{index}] must be an object")
            unknown = sorted(set(raw_member) - allowed_member_fields)
            if unknown:
                raise ValueError(f"members[{index}] has unsupported fields: {unknown}")
            disallowed = (
                short_rest_fields if normalized_rest_type == "long_rest" else long_rest_fields
            )
            wrong_rest_fields = sorted(set(raw_member) & disallowed)
            if wrong_rest_fields:
                raise ValueError(
                    f"members[{index}] fields are invalid for {normalized_rest_type}: "
                    f"{wrong_rest_fields}"
                )
            character_id = str(raw_member.get("character_id") or "").strip()
            if not character_id:
                raise ValueError(f"members[{index}].character_id is required")
            character_revision = raw_member.get("expected_revision")
            if isinstance(character_revision, bool) or not isinstance(character_revision, int):
                raise ValueError(f"members[{index}].expected_revision is required")
            current_member = characters.get(character_id)
            if current_member.campaign_id != campaign_id:
                raise ValueError(f"party rest actor is not in this campaign: {character_id}")
            prepared_ids = raw_member.get("prepared_spell_ids")
            if prepared_ids is not None and not isinstance(prepared_ids, list):
                raise ValueError(f"members[{index}].prepared_spell_ids must be an array")
            recovery = raw_member.get("hit_dice_recovery")
            if recovery is not None and not isinstance(recovery, dict):
                raise ValueError(f"members[{index}].hit_dice_recovery must be an object")
            hit_dice_spends = raw_member.get("hit_dice_spends")
            if hit_dice_spends is not None and not isinstance(hit_dice_spends, list):
                raise ValueError(f"members[{index}].hit_dice_spends must be an array")
            arcane_recovery = raw_member.get("arcane_recovery")
            if arcane_recovery is not None and not isinstance(arcane_recovery, dict):
                raise ValueError(f"members[{index}].arcane_recovery must be an object")
            natural_recovery = raw_member.get("natural_recovery")
            if natural_recovery is not None and not isinstance(natural_recovery, dict):
                raise ValueError(f"members[{index}].natural_recovery must be an object")
            sorcerous_restoration_points = raw_member.get("sorcerous_restoration_points")
            if sorcerous_restoration_points is not None and (
                isinstance(sorcerous_restoration_points, bool)
                or not isinstance(sorcerous_restoration_points, int)
            ):
                raise ValueError(
                    f"members[{index}].sorcerous_restoration_points must be an integer"
                )
            song_source_id = (
                str(raw_member.get("song_of_rest_source_actor_id") or "").strip() or None
            )
            attune_item_id = str(raw_member.get("attune_item_id") or "").strip() or None
            attunement_confirmed = raw_member.get("attunement_prerequisite_confirmed")
            if attune_item_id and attunement_confirmed is not True:
                raise NeedsRulingError(
                    "attunement requires explicit DM confirmation that the actor "
                    "satisfies every source-defined prerequisite",
                    missing=("attunement_prerequisite",),
                    ruling_kind="source_or_scene_fact",
                )
            if not attune_item_id and attunement_confirmed is not None:
                raise ValueError("attunement_prerequisite_confirmed requires attune_item_id")
            food_and_drink = raw_member.get("food_and_drink", False)
            if not isinstance(food_and_drink, bool):
                raise ValueError(f"members[{index}].food_and_drink must be a boolean")
            rest_activities = validate_rest_activity_minutes(
                raw_member.get("rest_activity_minutes")
            )
            derived_rest_timing = validate_rest_schedule(
                rest_type=normalized_rest_type,
                duration_minutes=duration_minutes,
                allows_trance=(
                    allows_trance_rest(current_member.sheet)
                    if normalized_rest_type == "long_rest"
                    else False
                ),
            )
            normalized_member = {
                "character_id": character_id,
                "expected_revision": character_revision,
                "rest_activity_minutes": rest_activities,
                "derived_rest_timing": derived_rest_timing,
            }
            if normalized_rest_type == "long_rest":
                normalized_member.update(
                    {
                        "prepared_spell_ids": prepared_ids,
                        "hit_dice_recovery": recovery,
                        "food_and_drink": food_and_drink,
                    }
                )
            else:
                normalized_member.update(
                    {
                        "hit_dice_spends": list(hit_dice_spends or []),
                        "arcane_recovery": deepcopy(arcane_recovery or {}),
                        "natural_recovery": deepcopy(natural_recovery or {}),
                        "sorcerous_restoration_points": (sorcerous_restoration_points),
                        "song_of_rest_source_actor_id": song_source_id,
                        "attune_item_id": attune_item_id,
                        "attunement_prerequisite_confirmed": attunement_confirmed,
                    }
                )
            normalized_members.append(normalized_member)
            member_ids.append(character_id)
        if len(member_ids) != len(set(member_ids)):
            raise ValueError("party rest member ids must be unique")
        if normalized_rest_type == "short_rest":
            song_source_ids = {
                str(item["song_of_rest_source_actor_id"])
                for item in normalized_members
                if item["song_of_rest_source_actor_id"] is not None
            }
            if song_source_ids - set(member_ids):
                raise CombatEngineError(
                    "every Song of Rest source must participate in the same party rest"
                )
        request_payload = {
            "members": normalized_members,
            "duration_minutes": duration_minutes,
            "branch_id": resolved_branch_id,
        }
        if normalized_rest_type != "long_rest":
            request_payload["rest_type"] = normalized_rest_type
        scope = f"campaign-party-rest:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        campaign = campaigns.get(campaign_id)
        if campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        next_state = validate_party_state(deepcopy(campaign.state or {}))
        if bool(dict(next_state.get("combat") or {}).get("active")):
            raise CombatEngineError("rest is not allowed while combat is active")
        started_elapsed_ticks = int(next_state["game_time"]["elapsed_ticks"])
        next_state, time_transition = advance_state_game_time(
            next_state,
            period="minute",
            count=duration_minutes,
        )
        completed_clock = time_transition["world_time_after"]
        completed_elapsed_ticks = int(time_transition["after"]["elapsed_ticks"])
        elapsed_ticks = int(time_transition["elapsed_ticks"])
        completed_game_day = rules_day_from_ticks(completed_elapsed_ticks)
        all_characters = {item.id: item for item in characters.list(campaign_id=campaign_id)}
        for member in normalized_members:
            current = all_characters.get(member["character_id"])
            if current is None:
                raise ValueError(
                    f"party rest actor is not in this campaign: {member['character_id']}"
                )
            if current.revision != member["expected_revision"]:
                raise ValueError(f"character revision conflict: {current.id}")
            record_rest_completion(
                current.sheet,
                rest_type=normalized_rest_type,
                started_elapsed_ticks=started_elapsed_ticks,
                completed_elapsed_ticks=completed_elapsed_ticks,
            )
            if normalized_rest_type == "long_rest" and member["prepared_spell_ids"] is not None:
                preparation_hydration = hydrate_class_prepared_spell_cards(
                    campaign_id,
                    current.sheet,
                    spell_ids=member["prepared_spell_ids"],
                    branch_id=resolved_branch_id,
                )
                replace_prepared_spells(
                    preparation_hydration["sheet"],
                    spell_ids=member["prepared_spell_ids"],
                    event="long_rest",
                )
            if normalized_rest_type == "short_rest":
                validate_rest_hit_dice_requests(
                    current.sheet,
                    member["hit_dice_spends"],
                )
                validate_arcane_recovery_choice(
                    current.sheet,
                    member["arcane_recovery"],
                    game_day=completed_game_day,
                )
                validate_natural_recovery_choice(
                    current.sheet,
                    member["natural_recovery"],
                    rest_activity_minutes=member["rest_activity_minutes"],
                )
                validate_sorcerous_restoration_choice(
                    current.sheet,
                    member["sorcerous_restoration_points"],
                )
                song_source_id = member["song_of_rest_source_actor_id"]
                if song_source_id is not None:
                    validate_song_of_rest_source(all_characters[str(song_source_id)].sheet)
                if member["attune_item_id"] is not None:
                    attune_inventory_item(
                        current.sheet,
                        str(member["attune_item_id"]),
                    )

        world_duration = advance_world_effect_clocks(
            next_state,
            elapsed_ticks=elapsed_ticks,
            period_steps={"round": elapsed_ticks},
        )
        next_state = world_duration["state"]
        world_advanced = world_duration["advanced"]
        world_expired = world_duration["expired"]

        member_by_id = {item["character_id"]: item for item in normalized_members}
        updates: list[CharacterStateUpdate] = []
        recovered: dict[str, Any] = {}
        preparations: dict[str, Any] = {}
        advanced: dict[str, list[str]] = {}
        expired: dict[str, list[str]] = {}
        rule_receipts: list[dict[str, Any]] = []
        rule_context = effective_rule_context(campaign_id)
        for current in all_characters.values():
            sheet = current.sheet
            actor_advanced: list[str] = []
            actor_expired: list[str] = []
            duration = advance_elapsed_effect_durations(
                sheet,
                elapsed_ticks=elapsed_ticks,
            )
            round_duration = advance_effect_durations(
                duration["sheet"],
                period="round",
                amount=int(time_transition["elapsed_ticks"]),
            )
            extension = apply_rule_event(
                round_duration["sheet"],
                "duration.advance",
                context_with_facts(
                    rule_context,
                    actor_id=current.id,
                    period="minute",
                    amount=duration_minutes,
                ),
            )
            if extension.status != "committed":
                raise CombatEngineError(
                    f"party rest duration for {current.id} requires an unresolved rule choice"
                )
            sheet = extension.sheet
            actor_advanced.extend(duration["advanced"])
            actor_expired.extend(duration["expired"])
            actor_advanced.extend(round_duration["advanced"])
            actor_expired.extend(round_duration["expired"])
            rule_receipts.extend(extension.receipts)
            member = member_by_id.get(current.id)
            if member is not None:
                rest_rules = effective_rule_context(
                    campaign_id,
                    facts={
                        "actor_id": current.id,
                        "rest_type": normalized_rest_type,
                    },
                )
                rest_arguments: dict[str, Any] = {
                    "rest_type": normalized_rest_type,
                    "rest_activity_minutes": member["rest_activity_minutes"],
                    "rules": rest_rules,
                    "game_day": completed_game_day,
                }
                if normalized_rest_type == "long_rest":
                    rest_arguments.update(
                        {
                            "hit_dice_recovery": member["hit_dice_recovery"],
                            "food_and_drink": member["food_and_drink"],
                        }
                    )
                else:
                    song_source_id = member["song_of_rest_source_actor_id"]
                    rest_arguments.update(
                        {
                            "hit_dice_spends": member["hit_dice_spends"],
                            "arcane_recovery": member["arcane_recovery"],
                            "natural_recovery": member["natural_recovery"],
                            "sorcerous_restoration_points": member["sorcerous_restoration_points"],
                            "song_of_rest_source_sheet": (
                                all_characters[str(song_source_id)].sheet
                                if song_source_id is not None
                                else None
                            ),
                        }
                    )
                applied = apply_rest(sheet, **rest_arguments)
                if applied.get("status") != "committed":
                    raise CombatEngineError(
                        f"party rest for {current.id} requires an unresolved rule choice"
                    )
                if normalized_rest_type == "short_rest" and member["attune_item_id"] is not None:
                    applied["sheet"] = attune_inventory_item(
                        applied["sheet"],
                        str(member["attune_item_id"]),
                    )
                    applied["attuned_item_id"] = str(member["attune_item_id"])
                sheet = record_rest_completion(
                    applied["sheet"],
                    rest_type=normalized_rest_type,
                    started_elapsed_ticks=started_elapsed_ticks,
                    completed_elapsed_ticks=completed_elapsed_ticks,
                )
                preparation_result = None
                if normalized_rest_type == "long_rest" and member["prepared_spell_ids"] is not None:
                    preparation_hydration = hydrate_class_prepared_spell_cards(
                        campaign_id,
                        sheet,
                        spell_ids=member["prepared_spell_ids"],
                        branch_id=resolved_branch_id,
                    )
                    preparation_result = replace_prepared_spells(
                        preparation_hydration["sheet"],
                        spell_ids=member["prepared_spell_ids"],
                        event="long_rest",
                    )
                    preparation_result["materialized_spell_ids"] = preparation_hydration[
                        "materialized_spell_ids"
                    ]
                    sheet = preparation_result["sheet"]
                    preparations[current.id] = {
                        key: value for key, value in preparation_result.items() if key != "sheet"
                    }
                recovered[current.id] = {
                    key: value
                    for key, value in applied.items()
                    if key not in {"sheet", "rule_receipts"}
                }
                rule_receipts.extend(applied.get("rule_receipts") or [])
                if normalized_rest_type == "long_rest":
                    rule_receipts.extend(
                        core_receipts(
                            rest_rules,
                            ["dnd5e.core.rest.long_rest_timing"],
                            "party.rest.long_rest",
                        )
                    )
                if preparation_result is not None:
                    rule_receipts.extend(
                        core_receipts(
                            rest_rules,
                            ["dnd5e.core.spell.preparation"],
                            "spell.prepare.long_rest",
                        )
                    )
            if sheet != current.sheet:
                updates.append(
                    CharacterStateUpdate(
                        character_id=current.id,
                        sheet=validate_character_sheet(sheet),
                        notes=validate_character_notes(current.notes),
                        expected_revision=current.revision,
                    )
                )
            if actor_advanced:
                advanced[current.id] = list(dict.fromkeys(actor_advanced))
            if actor_expired:
                expired[current.id] = list(dict.fromkeys(actor_expired))
        stream = active_random_stream()
        base_response = {
            "status": "committed",
            "rest_type": normalized_rest_type,
            "duration_minutes": duration_minutes,
            "member_ids": member_ids,
            "game_time": time_transition["after"],
            "world_time": completed_clock,
            "recovered": recovered,
            "preparations": preparations,
            "advanced": advanced,
            "expired": expired,
            "world_advanced": list(dict.fromkeys(world_advanced)),
            "world_expired": list(dict.fromkeys(world_expired)),
            "campaign_revision": campaign.revision + 1,
            "rule_receipts": rule_receipts,
            "ruleset_fingerprint": rule_context.fingerprint,
            **(
                {"random_stream_receipt": stream.receipt()}
                if stream is not None and stream.draw_count > 0
                else {}
            ),
        }

        def party_rest_response(revisions: list[Any]) -> dict[str, Any]:
            return {
                **base_response,
                "revisions": [asdict(item) for item in revisions],
            }

        revisions_result = StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=validate_party_state(next_state),
            character_updates=updates,
            expected_campaign_revision=campaign.revision,
            operation=f"campaign.party.rest.{normalized_rest_type}",
            actor=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=party_rest_response,
            ),
            rule_receipts=rule_receipts,
        )
        return party_rest_response(list(revisions_result or []))

    def character_use_activity(
        character_id: str,
        activity_id: str,
        declaration: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Consume one non-combat structured card use without fabricating its narrative result."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "activity use")
        if current.campaign_id is None:
            raise ValueError("activity use requires a campaign-bound character")
        if expected_revision is None or not idempotency_key:
            raise ValueError("expected_revision and idempotency_key are required for activity use")
        branch_id = require_current_branch(current.campaign_id, None)
        payload = {
            "character_id": character_id,
            "activity_id": activity_id,
            "declaration": declaration or {},
        }
        scope = f"character-activity:{current.campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if current.revision != expected_revision:
            raise ValueError(
                f"character revision conflict: expected {expected_revision}, "
                f"found {current.revision}"
            )
        campaign = campaigns.get(current.campaign_id)
        activity_card, activity_source_card_kind = character_activity_source_card(
            current.sheet,
            activity_id,
            character_type=current.character_type,
        )
        compiled_activity_plan = None
        if isinstance(activity_card.get("resolution_plan"), dict):
            _activity_card, compiled_activity_plan = character_resolution_plan(
                current.sheet,
                activity_id,
                activity_source_card_kind,
            )
        elif str(
            activity_card.get("description") or ""
        ).strip() and not source_card_has_executable_mechanic(
            current.campaign_id,
            activity_card,
        ):
            return {
                **_ruling_status(
                    "pending_ruling",
                    "module_specific_procedure",
                ),
                "result": {
                    "activity_id": activity_id,
                    "semantic_solution": unresolved_content_solution(
                        activity_card,
                        source_card_id=activity_id,
                        source_card_kind=activity_source_card_kind,
                        character_revision=current.revision,
                    ),
                    "payment_required": False,
                },
                "character": character_view(current),
                "campaign_revision": campaign.revision,
            }
        preserve_life = str(activity_id).endswith(
            "life-domain-channel-divinity-preserve-life"
        ) or str(activity_id).endswith("life-domain-preserve-life")
        if preserve_life:
            if not is_dm(current.campaign_id, principal_id):
                raise PermissionError(
                    "Preserve Life multi-actor settlement requires the Agent in the DM role"
                )
            if current.revision != expected_revision:
                raise ValueError(f"character revision conflict: {character_id}")
            declared = dict(declaration or {})
            if set(declared) != {"allocations"}:
                raise CombatEngineError(
                    "Preserve Life declaration requires only an allocations list"
                )
            raw_allocations = declared.get("allocations")
            if not isinstance(raw_allocations, list) or not raw_allocations:
                raise CombatEngineError("Preserve Life requires at least one allocation")
            target_records: dict[str, Any] = {}
            target_revisions: dict[str, int] = {}
            mechanical_allocations: list[dict[str, Any]] = []
            for allocation in raw_allocations:
                if not isinstance(allocation, dict) or set(allocation) != {
                    "target_id",
                    "amount",
                    "expected_revision",
                    "within_30_ft",
                }:
                    raise CombatEngineError(
                        "each Preserve Life allocation requires target_id, amount, "
                        "expected_revision, and within_30_ft"
                    )
                target_id = str(allocation.get("target_id") or "")
                if allocation.get("within_30_ft") is not True:
                    raise CombatEngineError(
                        "Preserve Life requires Agent-as-DM confirmation that the target "
                        "is within 30 feet"
                    )
                target = characters.get(target_id)
                if target.campaign_id != current.campaign_id:
                    raise CombatEngineError("Preserve Life targets must share the campaign")
                access.require_actor(
                    current.campaign_id,
                    target_id,
                    principal_id,
                    control=True,
                )
                target_revision = allocation.get("expected_revision")
                if isinstance(target_revision, bool) or not isinstance(target_revision, int):
                    raise ValueError("Preserve Life target expected_revision must be an integer")
                if target_id == character_id and target_revision != expected_revision:
                    raise ValueError("source and target revisions disagree for Preserve Life")
                if target.revision != target_revision:
                    raise ValueError(f"character revision conflict: {target_id}")
                target_records[target_id] = target
                target_revisions[target_id] = target_revision
                mechanical_allocations.append(
                    {"target_id": target_id, "amount": allocation.get("amount")}
                )
            preflight_sheets = {
                target_id: target.sheet for target_id, target in target_records.items()
            }
            resolve_preserve_life_to_sheets(
                current.sheet,
                preflight_sheets,
                allocations=mechanical_allocations,
            )
            activity_rules = effective_rule_context(
                current.campaign_id,
                facts={"actor_id": character_id, "activity_id": activity_id},
            )
            try:
                applied = consume_activity(
                    current.sheet,
                    activity_id=activity_id,
                    rules=activity_rules,
                )
            except ActivityError as exc:
                raise ValueError(str(exc)) from exc
            settled_inputs = {
                target_id: (applied["sheet"] if target_id == character_id else target.sheet)
                for target_id, target in target_records.items()
            }
            settled = resolve_preserve_life_to_sheets(
                applied["sheet"],
                settled_inputs,
                allocations=mechanical_allocations,
            )
            updates: list[CharacterStateUpdate] = []
            updated_ids = {character_id, *target_records}
            for updated_id in updated_ids:
                before = current if updated_id == character_id else target_records[updated_id]
                updated_sheet = (
                    settled["sheets"].get(updated_id, applied["sheet"])
                    if updated_id == character_id
                    else settled["sheets"][updated_id]
                )
                updates.append(
                    CharacterStateUpdate(
                        character_id=updated_id,
                        sheet=validate_character_sheet(updated_sheet),
                        notes=validate_character_notes(before.notes),
                        expected_revision=(
                            expected_revision
                            if updated_id == character_id
                            else target_revisions[updated_id]
                        ),
                    )
                )
            receipts = [
                *list(applied.get("rule_receipts") or []),
                *core_receipts(
                    activity_rules,
                    ["dnd5e.core.activity.preserve_life"],
                    "activity.preserve_life",
                ),
            ]
            updates_by_id = {item.character_id: item for item in updates}

            def projected_character(record: Any) -> dict[str, Any]:
                update = updates_by_id[record.id]
                return character_view(
                    replace(
                        record,
                        sheet=update.sheet,
                        notes=update.notes,
                        revision=record.revision + 1,
                    )
                )

            response = commit_campaign_state(
                campaign,
                None,
                operation="character.activity.preserve_life",
                principal_id=principal_id,
                branch_id=branch_id,
                idempotency_key=idempotency_key,
                scope=scope,
                payload=payload,
                response_fields={
                    "status": "committed",
                    "result": {
                        "activity_id": activity_id,
                        "payment": applied.get("payment"),
                        "pool": settled["pool"],
                        "allocated": settled["allocated"],
                        "remaining_unallocated": settled["remaining_unallocated"],
                        "targets": settled["targets"],
                        "rule_receipts": receipts,
                    },
                    "character": projected_character(current),
                    "targets": [
                        projected_character(target_records[target_id])
                        for target_id in target_records
                    ],
                },
                character_updates=updates,
                rule_receipts=receipts,
                include_campaign_revision=False,
                include_revisions=False,
            )
            return response
        divine_spark = (
            activity_id == "dnd5e.content.srd2024.feature.cleric-channel-divinity"
            and str(dict(declaration or {}).get("option") or "")
            .strip()
            .casefold()
            .replace(" ", "_")
            == "divine_spark"
        )
        if divine_spark:
            if not is_dm(current.campaign_id, principal_id):
                raise PermissionError(
                    "Divine Spark multi-actor settlement requires the Agent in the DM role"
                )
            declared = dict(declaration or {})
            mode = str(declared.get("mode") or "").strip().casefold()
            expected_fields = {
                "option",
                "target_id",
                "mode",
                "expected_revision",
                "within_30_ft",
                "can_see",
            }
            if mode == "damage":
                expected_fields.add("damage_type")
            if set(declared) != expected_fields:
                raise CombatEngineError(
                    "noncombat Divine Spark requires option, target_id, mode, "
                    "expected_revision, within_30_ft, can_see, and damage_type only "
                    "for damage"
                )
            target_id = str(declared.get("target_id") or "").strip()
            if not target_id or target_id == character_id:
                raise CombatEngineError("Divine Spark targets one other creature")
            if declared.get("within_30_ft") is not True or declared.get("can_see") is not True:
                raise CombatEngineError(
                    "noncombat Divine Spark requires Agent-as-DM confirmation of range "
                    "and visibility"
                )
            target = require_campaign_actor(current.campaign_id, target_id)
            access.require_actor(
                current.campaign_id,
                target_id,
                principal_id,
                control=True,
            )
            target_revision = declared.get("expected_revision")
            if isinstance(target_revision, bool) or not isinstance(target_revision, int):
                raise ValueError("Divine Spark target expected_revision must be an integer")
            if target.revision != target_revision:
                raise ValueError(f"character revision conflict: {target_id}")
            activity_rules = effective_rule_context(
                current.campaign_id,
                facts={"actor_id": character_id, "activity_id": activity_id},
            )
            try:
                applied = consume_activity(
                    current.sheet,
                    activity_id=activity_id,
                    rules=activity_rules,
                )
            except ActivityError as exc:
                raise ValueError(str(exc)) from exc
            source_actor = combat_actor_snapshot(character_id)
            source_actor["sheet"] = applied["sheet"]
            source_actor["derived"] = derive_character_sheet(applied["sheet"])
            target_actor = combat_actor_snapshot(target_id)
            settled_spark = resolve_divine_spark_to_sheet(
                source_actor,
                target_actor,
                mode=mode,
                damage_type=declared.get("damage_type"),
                rules=activity_rules,
            )
            target_sheet = validate_character_sheet(settled_spark.pop("sheet"))
            source_sheet = validate_character_sheet(applied["sheet"])
            updates = [
                CharacterStateUpdate(
                    character_id=character_id,
                    sheet=source_sheet,
                    notes=validate_character_notes(current.notes),
                    expected_revision=expected_revision,
                ),
                CharacterStateUpdate(
                    character_id=target_id,
                    sheet=target_sheet,
                    notes=validate_character_notes(target.notes),
                    expected_revision=target_revision,
                ),
            ]
            receipts = [
                *list(applied.get("rule_receipts") or []),
                *core_receipts(
                    activity_rules,
                    ["dnd5e.core.activity.divine_spark"],
                    "activity.divine_spark",
                ),
            ]
            source_projected = replace(
                current,
                sheet=source_sheet,
                revision=current.revision + 1,
            )
            target_projected = replace(
                target,
                sheet=target_sheet,
                revision=target.revision + 1,
            )
            response = commit_campaign_state(
                campaign,
                None,
                operation="character.activity.divine_spark",
                principal_id=principal_id,
                branch_id=branch_id,
                idempotency_key=idempotency_key,
                scope=scope,
                payload=payload,
                response_fields={
                    "status": "committed",
                    "result": {
                        "activity_id": activity_id,
                        "payment": applied.get("payment"),
                        "core_effect": settled_spark,
                        "requires_ruling": False,
                        "rule_receipts": receipts,
                    },
                    "character": character_view(source_projected),
                    "target": character_view(target_projected),
                },
                character_updates=updates,
                rule_receipts=receipts,
                include_campaign_revision=False,
                include_revisions=False,
            )
            return response
        try:
            applied = consume_activity(
                current.sheet,
                activity_id=activity_id,
                rules=effective_rule_context(
                    current.campaign_id,
                    facts={"actor_id": character_id, "activity_id": activity_id},
                ),
            )
        except ActivityError as exc:
            raise ValueError(str(exc)) from exc
        if applied.get("status") in PENDING_RULE_RESULT_STATUSES:
            return {
                **_ruling_status(
                    applied["status"],
                    _pending_result_ruling_kind(applied),
                ),
                "result": {key: value for key, value in applied.items() if key != "sheet"},
                "character": character_view(current),
            }
        if activity_id in SECOND_WIND_ACTIVITY_IDS:
            rule_context = effective_rule_context(
                current.campaign_id,
                facts={"actor_id": character_id, "activity_id": activity_id},
            )
            second_wind = resolve_second_wind_to_sheet(applied["sheet"])
            applied["sheet"] = second_wind.pop("sheet")
            applied["requires_ruling"] = False
            applied["core_effect"] = second_wind
            applied["rule_receipts"] = [
                *list(applied.get("rule_receipts") or []),
                *core_receipts(
                    rule_context,
                    ["dnd5e.core.activity.second_wind"],
                    "activity.second_wind",
                ),
            ]
        activation_type = str(applied["activation"].get("type") or "")
        if activation_type in {"reaction", "special"} and not is_dm(
            current.campaign_id, principal_id
        ):
            raise PermissionError("reaction and special activity triggers require a DM resolution")
        updated_character = replace(
            current,
            sheet=validate_character_sheet(applied["sheet"]),
            notes=validate_character_notes(current.notes),
            revision=current.revision + 1,
        )
        result = {key: value for key, value in applied.items() if key != "sheet"}
        if compiled_activity_plan is not None:
            result["resolution_plan_contract"] = resolution_plan_contract(compiled_activity_plan)
            result["semantic_solution"] = {
                "status": "compiled",
                "payment_recorded": True,
            }
        result["declaration"] = declaration or {}
        response = commit_campaign_state(
            campaign,
            None,
            operation="character.activity.use",
            principal_id=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                **_ruling_status(
                    "pending_ruling" if applied["requires_ruling"] else "committed",
                    "descriptive_activity",
                ),
                "result": result,
                "character": character_view(updated_character),
            },
            character_updates=[
                CharacterStateUpdate(
                    character_id=current.id,
                    sheet=validate_character_sheet(applied["sheet"]),
                    notes=validate_character_notes(current.notes),
                    expected_revision=expected_revision,
                )
            ],
            rule_receipts=list(applied.get("rule_receipts") or []),
            include_campaign_revision=False,
            include_revisions=False,
        )
        return response

    def character_resource_set(
        character_id: str,
        resource: str,
        value: int,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Set a named character resource, enforcing its schema-defined maximum."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "resource changes")
        return update_sheet(
            character_id,
            set_resource_value(current.sheet, resource, value),
            operation="character.resource.set",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"resource": resource, "value": value},
        )

