    def character_stabilize(
        character_id: str,
        *,
        source_actor_id: str,
        reason: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Commit an Agent-adjudicated stabilization after combat."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "post-combat stabilization")
        if current.campaign_id is None:
            raise CombatEngineError("stabilization requires a campaign-bound actor")
        access.require_campaign(current.campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        source = require_campaign_actor(current.campaign_id, source_actor_id)
        source_conditions = condition_ids(source.sheet.get("conditions", []))
        if source.id == current.id or source_conditions & {"dead", "incapacitated", "unconscious"}:
            raise CombatEngineError("stabilization requires a conscious assisting actor")
        normalized_reason = " ".join(str(reason or "").split())
        if not normalized_reason or len(normalized_reason) > 1000:
            raise CombatEngineError(
                "post-combat stabilization reason must contain 1 to 1000 characters"
            )
        applied = stabilize_sheet(current.sheet)
        result = {key: value for key, value in applied.items() if key != "sheet"}
        result["source_actor_id"] = source.id
        result["reason"] = normalized_reason
        return update_sheet(
            character_id,
            applied["sheet"],
            operation="character.stabilize",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"source_actor_id": source.id, "reason": normalized_reason},
            response_extra={"result": result},
        )

    def character_apply_raise_dead(
        character_id: str,
        *,
        elapsed_days: int,
        soul_willing: bool,
        body_intact: bool,
        source_ref: str,
        reason: str,
        source_actor_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Apply a source-backed 2014 Raise Dead transition outside combat."""

        current = characters.get(character_id)
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "revival")
        if current.campaign_id is None:
            raise CombatEngineError("revival requires a campaign-bound actor")
        access.require_campaign(current.campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        exact_source_ref = str(source_ref).strip()
        exact_reason = str(reason).strip()
        if not exact_source_ref or not exact_reason:
            raise CombatEngineError("revival requires source_ref and reason")
        if source_actor_id is not None:
            require_campaign_actor(current.campaign_id, source_actor_id)
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for character writes"
            )
        operation = "character.revival.raise_dead"
        mutation_payload = {
            "elapsed_days": elapsed_days,
            "soul_willing": soul_willing,
            "body_intact": body_intact,
            "source_ref": exact_source_ref,
            "reason": exact_reason,
            "source_actor_id": source_actor_id,
        }
        branch_id = require_current_branch(current.campaign_id, None)
        request_payload = {
            "operation": operation,
            "character_id": current.id,
            **mutation_payload,
        }
        scope = f"character-write:{current.campaign_id}:{branch_id}:{principal_id}:{current.id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        applied = apply_raise_dead_to_sheet(
            current.sheet,
            elapsed_days=elapsed_days,
            soul_willing=soul_willing,
            body_intact=body_intact,
            source_ref=exact_source_ref,
            source_actor_id=source_actor_id,
        )
        result = {key: value for key, value in applied.items() if key != "sheet"}
        rule_receipts = core_receipts(
            effective_rule_context(current.campaign_id),
            ["dnd5e.core.spell.raise_dead"],
            "character.revival.raise_dead",
        )
        return update_sheet(
            character_id,
            applied["sheet"],
            operation=operation,
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload=mutation_payload,
            response_extra={"result": result, "rule_receipts": rule_receipts},
            rule_receipts=rule_receipts,
        )

    def character_spell_prepare(
        character_id: str,
        spell_id: str,
        prepared: bool,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Prepare or unprepare a spell under the D&D spellcasting constraints."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        if current.campaign_id is not None:
            campaign = campaigns.get(current.campaign_id)
            phase = authoritative_phase(current.campaign_id)
            if phase == PROFILE_COMBAT:
                raise CombatEngineError("prepared spells cannot be changed during combat")
            if phase != PROFILE_LOBBY:
                raise CombatEngineError(
                    "live prepared-spell changes must be submitted atomically with party_rest"
                )
            if preparation_setup_closed(campaign) and not initial_preparation_allowed_for_new_actor(
                campaign, current
            ):
                raise CombatEngineError(
                    "individual preparation edits are initial setup only; after play starts, "
                    "submit the complete list with the edition's legal timing event"
                )
        preparation_rules = (
            effective_rule_context(current.campaign_id) if current.campaign_id else None
        )
        hydrated = (
            hydrate_class_prepared_spell_cards(
                current.campaign_id,
                current.sheet,
                spell_ids=[spell_id],
                branch_id=require_current_branch(current.campaign_id, None),
            )
            if prepared and current.campaign_id is not None
            else {"sheet": current.sheet, "materialized_spell_ids": []}
        )
        return update_sheet(
            character_id,
            set_spell_prepared(hydrated["sheet"], spell_id, prepared),
            operation="character.spell.prepare" if prepared else "character.spell.unprepare",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"spell_id": spell_id, "prepared": prepared},
            response_extra={
                "materialized_spell_ids": hydrated["materialized_spell_ids"],
            },
            rule_receipts=core_receipts(
                preparation_rules,
                ["dnd5e.core.spell.preparation"],
                "spell.prepare.setup",
            ),
        )

    def character_spell_prepare_list(
        character_id: str,
        spell_ids: list[str],
        event: str = "setup",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Set the complete prepared list atomically under the edition timing rules."""
        current = characters.get(character_id)
        require_character_control(current, principal_id)
        normalized_event = str(event).strip().lower().replace("-", "_")
        if current.campaign_id is not None:
            campaign = campaigns.get(current.campaign_id)
            phase = authoritative_phase(current.campaign_id)
            if phase == PROFILE_COMBAT:
                raise CombatEngineError("prepared spells cannot be changed during combat")
            if phase != PROFILE_LOBBY:
                raise CombatEngineError("switch to lobby for setup or level-up preparation changes")
            if (
                normalized_event == "setup"
                and preparation_setup_closed(campaign)
                and not initial_preparation_allowed_for_new_actor(campaign, current)
            ):
                raise CombatEngineError(
                    "prepared-spell setup is closed after live play starts; use the edition's "
                    "legal long-rest or level-up workflow"
                )
        if normalized_event not in {"setup", "level_up"}:
            raise CombatEngineError(
                "this tool accepts setup or level_up; long-rest changes belong in party_rest"
            )
        hydrated = (
            hydrate_class_prepared_spell_cards(
                current.campaign_id,
                current.sheet,
                spell_ids=list(spell_ids),
                branch_id=require_current_branch(current.campaign_id, None),
            )
            if current.campaign_id is not None
            else {"sheet": current.sheet, "materialized_spell_ids": []}
        )
        result = replace_prepared_spells(
            hydrated["sheet"],
            spell_ids=list(spell_ids),
            event=normalized_event,
        )
        preparation_rules = (
            effective_rule_context(current.campaign_id) if current.campaign_id else None
        )
        return update_sheet(
            character_id,
            validate_character_sheet(result["sheet"]),
            operation=f"character.spell.prepare.{normalized_event}",
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload={"spell_ids": list(spell_ids), "event": normalized_event},
            response_extra={
                "preparation": {
                    **{key: value for key, value in result.items() if key != "sheet"},
                    "materialized_spell_ids": hydrated["materialized_spell_ids"],
                }
            },
            rule_receipts=core_receipts(
                preparation_rules,
                ["dnd5e.core.spell.preparation"],
                f"spell.prepare.{normalized_event}",
            ),
        )

    @public_tool()
    def character_ability_apply(
        character_id: str,
        method: str,
        assignments: dict[str, int] | None = None,
        rolls: None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Apply manual, standard-array, point-buy, or engine-rolled ability scores."""
        current = characters.get(character_id)
        if rolls is not None:
            raise ValueError(
                "caller-supplied rolls are not accepted; use manual for entered scores"
            )
        require_character_control(current, principal_id)
        require_outside_active_combat(current, "ability generation")
        if current.campaign_id is None:
            raise ValueError("ability generation requires a campaign-bound lobby character")
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for ability generation"
            )
        normalized_method = str(method).strip().casefold().replace("-", "_")
        rolling = normalized_method == "roll_4d6_drop_lowest" and assignments is None
        operation = "character.ability.roll" if rolling else "character.ability.apply"
        mutation_payload = {
            "method": normalized_method,
            "assignments": assignments,
        }
        branch_id = require_current_branch(current.campaign_id, None)
        scope = f"character-write:{current.campaign_id}:{branch_id}:{principal_id}:{character_id}"
        request_payload = {
            "operation": operation,
            "character_id": character_id,
            **mutation_payload,
        }
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        if current.revision != expected_revision:
            raise ValueError(f"character revision conflict: {character_id}")
        ability_rules = effective_rule_context(current.campaign_id)
        if rolling:
            generated = begin_rolled_ability_generation(current.sheet)
            sheet = generated["sheet"]
            status = generated["status"]
            generated_rolls = generated["rolls"]
        elif normalized_method == "roll_4d6_drop_lowest":
            sheet = apply_pending_rolled_ability_generation(
                current.sheet,
                assignments=assignments or {},
            )
            status = "committed"
            generated_rolls = list(sheet["ability_generation"]["rolls"])
        else:
            if assignments is None:
                raise ValueError(
                    "assignments are required for manual, standard_array, and point_buy"
                )
            sheet = apply_ability_generation(
                current.sheet,
                method=normalized_method,
                assignments=assignments,
            )
            status = "committed"
            generated_rolls = []
        ability_receipts = core_receipts(
            ability_rules,
            ["dnd5e.core.ability_generation"],
            operation,
        )
        return update_sheet(
            character_id,
            sheet,
            operation=operation,
            principal_id=principal_id,
            expected_revision=expected_revision,
            idempotency_key=idempotency_key,
            payload=mutation_payload,
            response_extra={"status": status, "rolls": generated_rolls},
            rule_receipts=ability_receipts,
        )

    def party_show(
        campaign_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any]:
        """Read the campaign shared stash, wallet, derived load, and party notes."""
        access.require_campaign(campaign_id, principal_id)
        return party_view_from_state(campaigns.get(campaign_id).state)

    def party_inventory_add(
        campaign_id: str,
        item: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Add an item to the campaign shared inventory."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for party inventory writes"
            )
        before = campaigns.get(campaign_id)
        branch_id = require_current_branch(campaign_id, None)
        payload = {"item": item, "expected_revision": expected_revision, "branch_id": branch_id}
        scope = f"party-inventory:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        sheet, item_id = add_inventory_item(party_sheet(before.state), item)
        after = campaigns.update_audited(
            campaign_id,
            state=party_state(before.state, sheet),
            expected_revision=expected_revision,
            operation="party.inventory.add",
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "inventory": sheet["inventory"],
                    "item_id": item_id,
                    "campaign": asdict(result),
                },
            ),
        )
        return {
            "inventory": sheet["inventory"],
            "item_id": item_id,
            "campaign": asdict(after),
        }

    def party_inventory_remove(
        campaign_id: str,
        item_id: str,
        quantity: int | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Remove an item or partial stack from the campaign shared inventory."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for party inventory writes"
            )
        before = campaigns.get(campaign_id)
        branch_id = require_current_branch(campaign_id, None)
        payload = {
            "item_id": item_id,
            "quantity": quantity,
            "expected_revision": expected_revision,
            "branch_id": branch_id,
        }
        scope = f"party-inventory:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        sheet, removed = remove_inventory_item(party_sheet(before.state), item_id, quantity)
        after = campaigns.update_audited(
            campaign_id,
            state=party_state(before.state, sheet),
            expected_revision=expected_revision,
            operation="party.inventory.remove",
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "inventory": sheet["inventory"],
                    "removed": removed,
                    "campaign": asdict(result),
                },
            ),
        )
        return {
            "inventory": sheet["inventory"],
            "removed": removed,
            "campaign": asdict(after),
        }

    def party_inventory_transfer(
        campaign_id: str,
        character_id: str,
        item_id: str,
        direction: str,
        quantity: int | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_campaign_revision: int | None = None,
        expected_character_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Deposit an actor item to, or withdraw one from, the party shared inventory."""
        if direction not in {"deposit", "withdraw"}:
            raise ValueError("direction must be deposit or withdraw")
        if (
            expected_campaign_revision is None
            or expected_character_revision is None
            or not idempotency_key
        ):
            raise ValueError(
                "expected campaign/character revisions and idempotency_key are required"
            )
        campaign = campaigns.get(campaign_id)
        character = characters.get(character_id)
        if character.campaign_id != campaign_id:
            raise ValueError("character must belong to the campaign")
        access.require_actor(campaign_id, character_id, principal_id, control=True)
        branch_id = require_current_branch(campaign_id, None)
        payload = {
            "campaign_id": campaign_id,
            "character_id": character_id,
            "item_id": item_id,
            "direction": direction,
            "quantity": quantity,
            "expected_campaign_revision": expected_campaign_revision,
            "expected_character_revision": expected_character_revision,
            "branch_id": branch_id,
        }
        scope = f"party-inventory:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        shared = party_sheet(campaign.state)
        if direction == "deposit":
            character_sheet, moved = remove_inventory_item(character.sheet, item_id, quantity)
            moved = inventory_item_for_receipt(shared, moved)
            shared_sheet = receive_inventory_item(shared, moved)
        else:
            shared_sheet, moved = remove_inventory_item(shared, item_id, quantity)
            moved = inventory_item_for_receipt(character.sheet, moved)
            character_sheet = receive_inventory_item(character.sheet, moved)
        updated_state = party_state(campaign.state, shared_sheet)
        normalized_character_sheet = validate_character_sheet(
            finalize_actor_sheet_rulings(character_sheet, campaign_id),
            rules=effective_rule_context(campaign_id),
        )
        response = {
            "party": party_view_from_state(updated_state),
            "character": character_view(
                replace(
                    character,
                    sheet=normalized_character_sheet,
                    revision=character.revision + 1,
                )
            ),
            "item": moved,
        }
        StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=updated_state,
            character_updates=[
                CharacterStateUpdate(
                    character.id,
                    normalized_character_sheet,
                    character.notes,
                    expected_character_revision,
                )
            ],
            operation=f"party.inventory.{direction}",
            actor=principal_id,
            branch_id=branch_id,
            expected_campaign_revision=expected_campaign_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=response,
            ),
        )
        return response

    def party_wallet_adjust(
        campaign_id: str,
        denomination: str,
        amount: int,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Credit or debit one denomination in the shared party wallet."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for party wallet writes"
            )
        before = campaigns.get(campaign_id)
        branch_id = require_current_branch(campaign_id, None)
        payload = {
            "denomination": denomination,
            "amount": amount,
            "expected_revision": expected_revision,
            "branch_id": branch_id,
        }
        scope = f"party-wallet:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        sheet = adjust_wallet(party_sheet(before.state), denomination, amount)
        after = campaigns.update_audited(
            campaign_id,
            state=party_state(before.state, sheet),
            expected_revision=expected_revision,
            operation="party.wallet.adjust",
            actor=principal_id,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "wallet": sheet["inventory"]["wallet"],
                    "campaign": asdict(result),
                },
            ),
        )
        return {
            "wallet": sheet["inventory"]["wallet"],
            "campaign": asdict(after),
        }

    def party_wallet_transfer(
        campaign_id: str,
        character_id: str,
        denomination: str,
        amount: int,
        direction: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_campaign_revision: int | None = None,
        expected_character_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Deposit currency to, or withdraw currency from, the shared party wallet."""
        if amount <= 0:
            raise ValueError("amount must be positive")
        if direction not in {"deposit", "withdraw"}:
            raise ValueError("direction must be deposit or withdraw")
        if (
            expected_campaign_revision is None
            or expected_character_revision is None
            or not idempotency_key
        ):
            raise ValueError(
                "expected campaign/character revisions and idempotency_key are required"
            )
        campaign = campaigns.get(campaign_id)
        character = characters.get(character_id)
        if character.campaign_id != campaign_id:
            raise ValueError("character must belong to the campaign")
        access.require_actor(campaign_id, character_id, principal_id, control=True)
        branch_id = require_current_branch(campaign_id, None)
        payload = {
            "campaign_id": campaign_id,
            "character_id": character_id,
            "denomination": denomination,
            "amount": amount,
            "direction": direction,
            "expected_campaign_revision": expected_campaign_revision,
            "expected_character_revision": expected_character_revision,
            "branch_id": branch_id,
        }
        scope = f"party-wallet:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if campaign.revision != expected_campaign_revision:
            raise ValueError(f"campaign revision conflict: {campaign_id}")
        shared = party_sheet(campaign.state)
        delta = amount if direction == "deposit" else -amount
        shared_sheet = adjust_wallet(shared, denomination, delta)
        character_sheet = adjust_wallet(character.sheet, denomination, -delta)
        updated_state = party_state(campaign.state, shared_sheet)
        normalized_character_sheet = validate_character_sheet(character_sheet)
        response = {
            "party": party_view_from_state(updated_state),
            "character": character_view(
                replace(
                    character,
                    sheet=normalized_character_sheet,
                    revision=character.revision + 1,
                )
            ),
        }
        StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=updated_state,
            character_updates=[
                CharacterStateUpdate(
                    character.id,
                    normalized_character_sheet,
                    character.notes,
                    expected_character_revision
                    if expected_character_revision is not None
                    else character.revision,
                )
            ],
            operation=f"party.wallet.{direction}",
            actor=principal_id,
            branch_id=branch_id,
            expected_campaign_revision=expected_campaign_revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=response,
            ),
        )
        return response

    def settle_campaign_randomness(
        campaign_id: str,
        *,
        principal_id: str,
        branch_id: str | None,
        expected_campaign_revision: int | None,
        idempotency_key: str | None,
        operation: str,
        payload: dict[str, Any],
        resolver: Any,
    ) -> dict[str, Any]:
        access.require_campaign(campaign_id, principal_id)
        if expected_campaign_revision is None or not idempotency_key:
            raise ValueError(
                "expected_campaign_revision and idempotency_key are required for random resolution"
            )
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        scope = f"campaign-random:{campaign_id}:{resolved_branch_id}:{principal_id}"
        request_payload = {"operation": operation, **deepcopy(payload)}
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        campaign = campaigns.get(campaign_id)
        if campaign.revision != expected_campaign_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_campaign_revision}, found {campaign.revision}"
            )
        inherited_stream = active_random_stream()
        if inherited_stream is not None and inherited_stream.campaign_id != campaign_id:
            raise ValueError("active random stream belongs to another campaign")
        stream = inherited_stream or CampaignRandomStream.from_campaign_state(
            campaign_id,
            campaign.state,
            operation=operation,
            idempotency_key=idempotency_key,
        )
        context_manager = nullcontext(stream) if inherited_stream else use_random_stream(stream)
        with context_manager:
            result = resolver()
            if stream.draw_count == 0:
                raise ValueError("random resolution must consume at least one random draw")
            resolution_id = "resolution-" + hashlib.sha256(
                (
                    f"{campaign_id}:{resolved_branch_id}:{operation}:"
                    f"{idempotency_key}"
                ).encode("utf-8")
            ).hexdigest()[:32]
            membership = access.require_campaign(campaign_id, principal_id)
            audience = (
                {"scope": "dm", "actor_refs": [], "disclosure": "hidden"}
                if membership.role in CAMPAIGN_DM_ROLES
                else {"scope": "principal", "actor_refs": [], "disclosure": "private"}
            )
            receipt = stream.receipt()
            response = {
                **dict(result),
                "resolution_id": resolution_id,
                "thread_id": resolution_id,
                "event_sequence": 1,
                "campaign_revision": campaign.revision + 1,
                "random_stream_receipt": receipt,
            }
            next_state = deepcopy(dict(campaign.state or {}))
            next_state["resolution_presentation_log"] = [
                *list(next_state.get("resolution_presentation_log") or []),
                {
                    "id": resolution_id,
                    "thread_id": resolution_id,
                    "event_sequence": 1,
                    "operation": operation,
                    "status": "settled",
                    "audience": audience,
                    "principal_id": principal_id if audience["scope"] == "principal" else None,
                    "branch_id": resolved_branch_id,
                    "campaign_revision": campaign.revision + 1,
                    "result": deepcopy(dict(result)),
                    "random_stream_receipt": receipt,
                },
            ][-200:]
            StateMutationService(storage.database).replace(
                campaign_id,
                campaign_state=validate_party_state(next_state),
                expected_campaign_revision=expected_campaign_revision,
                operation=operation,
                actor=principal_id,
                branch_id=resolved_branch_id,
                idempotency_key=idempotency_key,
                idempotency_write=IdempotencyWrite(
                    scope=scope,
                    payload=request_payload,
                    response=response,
                ),
            )
        return response

    @public_tool()
    def dnd_dice_roll(
        campaign_id: str,
        expression: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        branch_id: str | None = None,
        expected_campaign_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Roll a validated expression and atomically advance the campaign random stream."""
        return settle_campaign_randomness(
            campaign_id,
            principal_id=principal_id,
            branch_id=branch_id,
            expected_campaign_revision=expected_campaign_revision,
            idempotency_key=idempotency_key,
            operation="dnd.dice.roll",
            payload={"expression": expression},
            resolver=lambda: asdict(roll(expression)),
        )

