    @public_tool()
    def combat_map_patch(
        campaign_id: str,
        patches: list[dict[str, Any]],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Record Agent-as-DM-confirmed changes from a temporary battle map."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        normalized: list[dict[str, Any]] = []
        for patch in patches:
            if not isinstance(patch, dict) or not isinstance(patch.get("key"), str):
                raise ValueError("each map patch needs a string key")
            normalized.append({"key": patch["key"], "value": deepcopy(patch.get("value"))})
        payload = {"patches": normalized, "branch_id": resolved_branch_id}
        scope = f"combat-map-patch:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        campaign, encounter = active_encounter(campaign_id)
        if campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        battle_map = dict(encounter.get("battle_map") or {})
        if not battle_map:
            raise CombatEngineError("active encounter has no temporary battle map")
        next_encounter = deepcopy(encounter)
        next_map = patch_battle_map(dict(next_encounter["battle_map"]), normalized)
        next_encounter["battle_map"] = next_map
        participant_ids = {
            str(item.get("actor_id")) for item in next_encounter.get("combatants", [])
        }
        seen_visibility_actors: set[str] = set()
        seen_departure_actors: set[str] = set()
        for patch in normalized:
            if patch["key"] == "combatant_departure":
                departure = patch.get("value")
                if not isinstance(departure, dict) or set(departure) - {
                    "actor_id",
                    "reason",
                    "destination_location_key",
                }:
                    raise ValueError(
                        "combatant_departure requires actor_id, reason, and optional "
                        "destination_location_key"
                    )
                target_id = str(departure.get("actor_id") or "")
                if target_id not in participant_ids or target_id in seen_departure_actors:
                    raise ValueError(
                        "combatant_departure actor_id must be a unique encounter participant"
                    )
                seen_departure_actors.add(target_id)
                reason = str(departure.get("reason") or "").strip()
                if not reason:
                    raise ValueError(
                        "combatant_departure requires a source or Agent-as-DM ruling reason"
                    )
                destination = str(departure.get("destination_location_key") or "").strip()
                combatant = next(
                    item
                    for item in next_encounter["combatants"]
                    if str(item.get("actor_id")) == target_id
                )
                combatant["departed"] = {
                    "reason": reason,
                    "destination_location_key": destination,
                }
                combatant["hidden"] = True
                continue
            if patch["key"] != "combatant_visibility":
                continue
            visibility = patch.get("value")
            if not isinstance(visibility, dict) or set(visibility) - {
                "actor_id",
                "hidden",
                "visible_to_actor_ids",
                "reason",
            }:
                raise ValueError(
                    "combatant_visibility requires actor_id, reason, and optional "
                    "hidden/visible_to_actor_ids"
                )
            target_id = str(visibility.get("actor_id") or "")
            if target_id not in participant_ids or target_id in seen_visibility_actors:
                raise ValueError(
                    "combatant_visibility actor_id must be a unique encounter participant"
                )
            seen_visibility_actors.add(target_id)
            if not str(visibility.get("reason") or "").strip():
                raise ValueError("combatant_visibility requires an Agent-as-DM ruling reason")
            if "hidden" not in visibility and "visible_to_actor_ids" not in visibility:
                raise ValueError("combatant_visibility must change hidden or visible_to_actor_ids")
            if "hidden" in visibility and not isinstance(visibility["hidden"], bool):
                raise ValueError("combatant_visibility hidden must be boolean")
            visible_to = visibility.get("visible_to_actor_ids")
            if "visible_to_actor_ids" in visibility and visible_to is not None:
                if (
                    not isinstance(visible_to, list)
                    or len({str(item) for item in visible_to}) != len(visible_to)
                    or any(str(item) not in participant_ids for item in visible_to)
                ):
                    raise ValueError(
                        "combatant_visibility visible_to_actor_ids must be unique participants"
                    )
            combatant = next(
                item
                for item in next_encounter["combatants"]
                if str(item.get("actor_id")) == target_id
            )
            if "hidden" in visibility:
                combatant["hidden"] = visibility["hidden"]
            if "visible_to_actor_ids" in visibility:
                combatant["visible_to_actor_ids"] = (
                    None if visible_to is None else [str(item) for item in visible_to]
                )
        state = dict(campaign.state or {})
        state["combat"] = next_encounter
        runtime = dict(state.get("scene_runtime") or {})
        scene_id = str(dict(next_map.get("source") or {}).get("scene_id") or "")
        if scene_id:
            scene_state = dict(runtime.get(scene_id) or {})
            for patch in normalized:
                scene_state[patch["key"]] = patch["value"]
            runtime[scene_id] = scene_state
        state["scene_runtime"] = runtime
        response = commit_campaign_state(
            campaign,
            state,
            operation="combat.map.patch",
            principal_id=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                "battle_map": next_map,
                "world_patches": normalized,
                "combat": next_encounter,
            },
            include_revisions=False,
        )
        return response

    @public_tool()
    def combat_end(
        campaign_id: str,
        outcome: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Close an encounter atomically while preserving its final audit state."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_write_contract(expected_revision, idempotency_key)
        campaign = campaigns.get(campaign_id)
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        outcome_value = dict(outcome or {})
        if outcome_value:
            allowed = {"status", "summary"}
            unknown = set(outcome_value) - allowed
            if unknown:
                raise ValueError(f"unsupported combat outcome fields: {sorted(unknown)}")
            status = str(outcome_value.get("status") or "").strip().lower()
            if status not in COMBAT_OUTCOME_STATUSES:
                raise ValueError("combat outcome status is invalid")
            summary = str(outcome_value.get("summary") or "").strip()
            if not summary or len(summary) > 2000:
                raise ValueError("combat outcome summary must contain 1 to 2000 characters")
            outcome_value = {"status": status, "summary": summary}
        payload = {"branch_id": resolved_branch_id, "outcome": outcome_value}
        scope = f"combat-end:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return combat_response(campaign_id, principal_id, replay)
        if expected_revision is not None and campaign.revision != expected_revision:
            raise ValueError(
                "campaign revision conflict: "
                f"expected {expected_revision}, found {campaign.revision}"
            )
        retained_combat = dict(campaign.state or {}).get("combat")
        if not isinstance(retained_combat, dict) or not retained_combat:
            raise CombatEngineError("campaign has no retained combat")
        combat = deepcopy(retained_combat)
        encounter_rules_edition(campaign_id, combat)
        if not combat.get("active", False):
            raise CombatEngineError("combat is already closed")
        require_no_blocking_pending(combat)
        ending_actor_ids = list(
            dict.fromkeys(
                str(item.get("actor_id") or "")
                for item in [
                    *list(combat.get("combatants") or []),
                    *list(combat.get("reinforcements") or []),
                ]
                if isinstance(item, dict) and str(item.get("actor_id") or "")
            )
        )
        ending_actors = {
            actor_id_value: characters.get(actor_id_value) for actor_id_value in ending_actor_ids
        }
        post_combat_recovery: list[dict[str, Any]] = []
        for combatant in combat.get("combatants", []):
            if not combatant.get("death_saves", False):
                continue
            actor = ending_actors[str(combatant["actor_id"])]
            actor_combat = dict(actor.sheet.get("combat") or {})
            hp = int(dict(actor_combat.get("hp") or {}).get("value", 0) or 0)
            conditions = condition_ids(actor.sheet.get("conditions", []))
            if hp == 0 and not conditions & DEATH_SAVE_SETTLED_CONDITIONS:
                post_combat_recovery.append(
                    {
                        "actor_id": actor.id,
                        "status": "dying",
                        "unresolved_at_end": True,
                        "death_saves": deepcopy(dict(actor_combat.get("death_saves") or {})),
                        "resolution_actions": ["heal", "stabilize", "death_save"],
                    }
                )
        combat["active"] = False
        combat["post_combat_recovery"] = post_combat_recovery
        if outcome_value:
            combat["outcome"] = outcome_value
        ending_readied = list(combat.get("readied", []))
        combat["readied"] = []
        updated_state = dict(campaign.state or {})
        updated_state["combat"] = combat
        updated_state["game_phase"] = PROFILE_PLAY
        updated_state = _with_combat_mutation_lock(updated_state, active=False)
        character_updates: list[CharacterStateUpdate] = []
        expired_effects: set[str] = set()
        for actor_id_value in ending_actor_ids:
            actor = ending_actors[actor_id_value]
            sheet = deepcopy(actor.sheet)
            for source_condition in combat.get("source_conditions", []):
                if str(source_condition.get("actor_id") or "") != actor.id or not (
                    source_condition.get("active", True)
                    and source_condition.get("added_by_encounter", False)
                ):
                    continue
                condition = str(source_condition.get("condition") or "").casefold()
                apply_condition_change(sheet, condition_id=condition, add=False)
            holding_ids = {
                str(item.get("holding_effect_id"))
                for item in ending_readied
                if item.get("kind") == "spell" and item.get("actor_id") == actor.id
            }
            for effect in sheet.get("effects", []):
                if str(effect.get("id")) in holding_ids:
                    effect["active"] = False
            advanced = expire_combat_bound_effects(sheet)
            expired_effects.update(advanced["expired"])
            sheet = advanced["sheet"]
            normalized_sheet = validate_character_sheet(sheet)
            sync_combatant_conditions(combat, actor_id_value, normalized_sheet)
            character_updates.append(
                CharacterStateUpdate(
                    character_id=actor.id,
                    sheet=normalized_sheet,
                    notes=validate_character_notes(actor.notes),
                    expected_revision=actor.revision,
                )
            )
        updated_state["combat"] = combat
        response = commit_campaign_state(
            campaign,
            updated_state,
            operation="combat.end",
            principal_id=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            scope=scope,
            payload=payload,
            response_fields={
                "ended": True,
                "combat": combat,
                "outcome": outcome_value or None,
                "tool_profile": PROFILE_PLAY,
                "post_combat_recovery": post_combat_recovery,
                "effects_expired": sorted(expired_effects),
                "readied_spells_expired": sorted(
                    str(item.get("id")) for item in ending_readied if item.get("kind") == "spell"
                ),
            },
            character_updates=character_updates,
        )
        return combat_response(campaign_id, principal_id, response)

    @public_tool()
    def continuity_context(
        campaign_id: str,
        query: str = "",
        actor_id: str | None = None,
        scope_id: str = "party",
        audience: str = "dm",
        purpose: Literal[
            "general",
            "npc_turn",
            "actor_turn",
            "audience_render",
            "faction_turn",
            "source_interpretation",
            "bounded_ruling",
        ] = "general",
        subject_ref: str | None = None,
        evaluation_target_refs: list[str] | None = None,
        interlocutor_actor_ids: list[str] | None = None,
        stimulus: dict[str, Any] | None = None,
        conversation_limit: int = 8,
        branch_id: str | None = None,
        limit: int = 8,
        budget_chars: int = 12_000,
        related_refs: list[str] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Retrieve current continuity plus pinned, source-exact DM module context."""
        continuity_purposes = NPC_TURN_PURPOSES | BOUNDED_EVALUATION_PURPOSES
        if purpose not in continuity_purposes:
            raise ValueError(f"unsupported continuity context purpose: {purpose}")
        live_turn_purposes = {
            "npc_turn",
            "actor_turn",
            "audience_render",
            "faction_turn",
        }
        if purpose in live_turn_purposes and authoritative_phase(campaign_id) not in {
            PROFILE_PLAY,
            PROFILE_COMBAT,
        }:
            raise ValueError(f"{purpose} context is available only during Play or Combat")
        membership = access.require_campaign(campaign_id, principal_id)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        if audience not in {"dm", "player"}:
            raise ValueError("audience must be dm or player")
        dm_only_purposes = {
            "npc_turn",
            "actor_turn",
            "faction_turn",
            "source_interpretation",
            "bounded_ruling",
        }
        if purpose in dm_only_purposes and membership.role not in CAMPAIGN_DM_ROLES:
            raise ValueError(f"{purpose} context is available only to Owner/DM")
        if purpose in {"npc_turn", "actor_turn"} and not actor_id:
            raise ValueError(f"actor_id is required for {purpose} context")
        if membership.role not in CAMPAIGN_DM_ROLES:
            audience = "player"
            scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
            if actor_id:
                access.require_actor(
                    campaign_id,
                    actor_id,
                    principal_id,
                    private=True,
                    branch_id=branch_id,
                )
        elif actor_id:
            access.require_actor(
                campaign_id,
                actor_id,
                principal_id,
                private=True,
                branch_id=branch_id,
            )
        if purpose == "audience_render" and audience != "player":
            raise ValueError("audience_render requires audience='player'")
        resolved_related_refs = {
            normalize_context_entity_ref(item, field="related_refs[]")
            for item in list(related_refs or [])
        }
        if actor_id:
            resolved_related_refs.add(f"actor:{actor_id}")
        normalized_interlocutor_ids: list[str] = []
        for item in interlocutor_actor_ids or []:
            value = str(item).strip()
            if not value:
                raise ValueError("interlocutor_actor_ids must not contain blank ids")
            if value in normalized_interlocutor_ids:
                raise ValueError("interlocutor_actor_ids must be unique")
            normalized_interlocutor_ids.append(value)
            resolved_related_refs.add(f"actor:{value}")
        normalized_target_refs: list[str] = []
        for item in evaluation_target_refs or []:
            value = normalize_context_entity_ref(item, field="evaluation_target_refs[]")
            if value in normalized_target_refs:
                raise ValueError("evaluation_target_refs must be unique")
            normalized_target_refs.append(value)
            resolved_related_refs.add(value)
        normalized_subject_ref: str | None = None
        if subject_ref is not None:
            normalized_subject_ref = normalize_context_entity_ref(subject_ref, field="subject_ref")
            resolved_related_refs.add(normalized_subject_ref)
        if membership.role in CAMPAIGN_DM_ROLES:
            campaign = campaigns.get(campaign_id)
            state = dict(campaign.state or {})
            combat = dict(state.get("combat") or {})
            if combat.get("active", False):
                for combatant in [
                    *list(combat.get("combatants") or []),
                    *list(combat.get("reinforcements") or []),
                ]:
                    combat_actor_id = str(dict(combatant or {}).get("actor_id") or "").strip()
                    if combat_actor_id:
                        resolved_related_refs.add(f"actor:{combat_actor_id}")
            manifest = dict(state.get("playthrough_manifest") or {})
            current = dict(manifest.get("current") or {})
            if current_scene_id := str(current.get("scene_id") or "").strip():
                resolved_related_refs.add(f"scene:{current_scene_id}")
            if current_module_id := str(current.get("module_id") or "").strip():
                resolved_related_refs.add(f"module:{current_module_id}")
            for quest in list(manifest.get("quests") or []):
                quest_value = dict(quest or {})
                if str(quest_value.get("status") or "") != "active":
                    continue
                quest_id = str(quest_value.get("id") or "").strip()
                if quest_id:
                    resolved_related_refs.add(f"quest:{quest_id}")
        result = continuity.context(
            campaign_id,
            query=query,
            actor_id=actor_id,
            scope_id=scope_id,
            audience=audience,
            branch_id=branch_id,
            limit=limit,
            budget_chars=budget_chars,
            related_refs=sorted(resolved_related_refs),
        )
        if purpose in BOUNDED_EVALUATION_PURPOSES:
            return bounded_evaluation_bundle(
                purpose=purpose,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                role=membership.role,
                audience=audience,
                actor_id=actor_id,
                subject_ref=normalized_subject_ref,
                target_refs=normalized_target_refs,
                query=query,
                result=result,
                related_refs=resolved_related_refs,
                interlocutor_actor_ids=normalized_interlocutor_ids,
                stimulus=stimulus,
            )
        if purpose == "npc_turn":
            assert actor_id is not None
            actor = characters.get(actor_id)
            if actor.campaign_id != campaign_id:
                raise ValueError("NPC turn actor belongs to another campaign")
            if actor.character_type not in NON_PLAYER_CHARACTER_TYPES:
                raise ValueError("NPC turn actor must be an NPC or monster")
            if actor_id in normalized_interlocutor_ids:
                raise ValueError("NPC turn actor cannot also be an interlocutor")
            interlocutors: list[dict[str, Any]] = []
            for interlocutor_id in normalized_interlocutor_ids:
                interlocutor = characters.get(interlocutor_id)
                if interlocutor.campaign_id != campaign_id:
                    raise ValueError("every NPC interlocutor must belong to the campaign")
                interlocutors.append(
                    {
                        "id": interlocutor.id,
                        "name": interlocutor.name,
                        "character_type": interlocutor.character_type,
                    }
                )
            normalized_stimulus = normalize_npc_stimulus(stimulus)
            stimulus_actor_ids = {
                str(normalized_stimulus.get("speaker_actor_id") or ""),
                *normalized_stimulus.get("target_actor_ids", []),
            } - {""}
            allowed_stimulus_actor_ids = {actor_id, *normalized_interlocutor_ids}
            if unknown_stimulus_actors := sorted(stimulus_actor_ids - allowed_stimulus_actor_ids):
                raise ValueError(
                    "stimulus actor ids must identify the NPC or an interlocutor: "
                    + ", ".join(unknown_stimulus_actors)
                )
            scene = npc_turn_scene_projection(result.get("scoped_scene"))
            perception = npc_turn_perception_projection(
                campaigns.get(campaign_id),
                actor_id=actor_id,
                interlocutors=interlocutors,
                scene=scene,
            )
            actor_state, fact_heads, knowledge_heads = npc_turn_actor_state(
                campaign_id,
                branch_id,
                actor_id,
            )
            relationships = [
                item for item in actor_state if item.get("predicate") == "relationship_to"
            ]
            goals = [item for item in actor_state if item.get("predicate") == "goal"]
            actor_knowledge = list(result.get("actor_knowledge") or [])
            common_context = [
                item
                for item in list(result.get("facts") or [])
                if item.get("disclosure_scope") == "public"
            ]
            relevant_anchor_heads = {
                str(item.id): str(item.revision_id)
                for item in memories.list(
                    campaign_id,
                    kind="context_anchor",
                    branch_id=branch_id,
                )
                if resolved_related_refs
                & {str(ref) for ref in list(dict(item.metadata or {}).get("related_refs") or [])}
            }
            context_fact_heads = {
                **relevant_anchor_heads,
                **{str(item["id"]): str(item["revision_id"]) for item in common_context},
            }
            raw_conversation = events.list_for_actor(
                campaign_id,
                actor_id=actor_id,
                branch_id=branch_id,
                limit=max(1, min(int(conversation_limit), 30)),
            )
            conversation_events = []
            for event in raw_conversation:
                payload = dict(event.payload or {})
                if event.event_type == "npc_conversation":
                    for transcript_event in list(payload.get("transcript") or []):
                        overall = dict(transcript_event.get("audience_facts") or {})
                        segments = list(transcript_event.get("utterance_segments") or [])
                        segment_facts = list(
                            transcript_event.get("segment_audience_facts") or []
                        )
                        visible_parts: list[str] = []
                        if segments and len(segment_facts) == len(segments):
                            for segment, facts in zip(segments, segment_facts, strict=True):
                                understood = set(facts.get("understood_actor_ids") or [])
                                perceived = set(facts.get("perceived_actor_ids") or [])
                                partial = dict(facts.get("partial_renditions") or {})
                                if actor_id in understood:
                                    visible_parts.append(str(segment.get("text") or ""))
                                elif actor_id in partial:
                                    visible_parts.append(str(partial[actor_id]))
                                elif actor_id in perceived:
                                    visible_parts.append("[Perceived but not understood]")
                        else:
                            understood = set(overall.get("understood_actor_ids") or [])
                            perceived = set(overall.get("perceived_actor_ids") or [])
                            partial = dict(overall.get("partial_renditions") or {})
                            if actor_id in understood:
                                visible_parts.append(str(transcript_event.get("content") or ""))
                            elif actor_id in partial:
                                visible_parts.append(str(partial[actor_id]))
                            elif actor_id in perceived:
                                visible_parts.append("[Perceived but not understood]")
                        visible_text = " ".join(item for item in visible_parts if item).strip()
                        if not visible_text:
                            continue
                        conversation_events.append(
                            {
                                "event_id": str(transcript_event.get("event_id") or event.id),
                                "sequence": int(transcript_event.get("sequence") or event.sequence),
                                "event_type": "npc_conversation_turn",
                                "summary": visible_text,
                                "speaker_actor_id": str(
                                    transcript_event.get("speaker_actor_id") or ""
                                ),
                                "listener_actor_ids": [
                                    str(item.get("actor_id") or "")
                                    for item in event.participants
                                    if str(item.get("actor_id") or "")
                                    != str(transcript_event.get("speaker_actor_id") or "")
                                ],
                                "utterance": visible_text,
                                "language": str(transcript_event.get("language") or ""),
                                "delivery": str(transcript_event.get("delivery") or ""),
                                "visible_action": str(
                                    transcript_event.get("visible_action") or ""
                                ),
                                "public_speech_acts": [],
                                "visible_portrayal_cues": [
                                    str(item)
                                    for item in transcript_event.get("visible_cues") or []
                                ],
                                "participants": [dict(item) for item in event.participants],
                            }
                        )
                    continue
                conversation_events.append(
                    {
                        "event_id": event.id,
                        "sequence": event.sequence,
                        "event_type": event.event_type,
                        "summary": event.summary,
                        "speaker_actor_id": str(payload.get("speaker_actor_id") or ""),
                        "listener_actor_ids": list(payload.get("listener_actor_ids") or []),
                        "utterance": str(payload.get("utterance") or ""),
                        "language": str(payload.get("language") or ""),
                        "delivery": str(payload.get("delivery") or ""),
                        "visible_action": str(payload.get("visible_action") or ""),
                        "public_speech_acts": [
                            dict(item) for item in list(payload.get("public_speech_acts") or [])
                        ],
                        "visible_portrayal_cues": [
                            str(item) for item in list(payload.get("visible_portrayal_cues") or [])
                        ],
                        "participants": [dict(item) for item in event.participants],
                    }
                )
            conversation_events = conversation_events[
                -max(1, min(int(conversation_limit), 30)) :
            ]
            conversation = {
                "schema_version": 1,
                "campaign_id": campaign_id,
                "branch_id": branch_id,
                "scope_id": scope_id,
                "scene_id": str((scene or {}).get("scene_id") or ""),
                "cursor": {
                    "latest_event_sequence": max(
                        (int(item["sequence"]) for item in conversation_events),
                        default=0,
                    ),
                    "event_count": len(conversation_events),
                },
                "participants": [
                    {
                        "actor_id": actor_id,
                        "name": actor.name,
                        "role": "speaker",
                    },
                    *(
                        {
                            "actor_id": str(item["id"]),
                            "name": str(item["name"]),
                            "role": "interlocutor",
                        }
                        for item in interlocutors
                    ),
                ],
                "events": conversation_events,
            }
            stimulus_ref = (
                "stimulus:"
                + hashlib.sha256(canonical_json(normalized_stimulus).encode("utf-8")).hexdigest()
            )
            allowed_basis_refs = {
                f"actor:{actor_id}:identity",
                f"actor:{actor_id}:self_state",
                *([stimulus_ref] if normalized_stimulus.get("kind") != "none" else []),
                *(f"knowledge:{item['id']}:{item['revision_id']}" for item in actor_knowledge),
                *(f"fact:{item['id']}:{item['revision_id']}" for item in actor_state),
                *(str(item["basis_ref"]) for item in perception),
                *(f"event:{item['event_id']}" for item in conversation_events),
            }
            portrayal_context = [
                {
                    **dict(item),
                    "context_role": "dm_portrayal_context",
                    "disclosure_policy": "not_speakable_without_actor_basis",
                }
                for item in list(result.get("module_evidence") or [])
            ]
            branch = dict(result.get("branch") or {})
            bundle: dict[str, Any] = {
                "schema_version": NPC_TURN_BUNDLE_SCHEMA_VERSION,
                "bundle_id": str(uuid4()),
                "purpose": "npc_turn",
                "authority": {
                    "campaign_id": campaign_id,
                    "branch_id": branch_id,
                    "head_snapshot_id": branch.get("head_snapshot_id"),
                    "campaign_revision": campaigns.get(campaign_id).revision,
                    "latest_event_sequence": npc_turn_latest_event_sequence(campaign_id, branch_id),
                    "actor_revision": actor.revision,
                    "scene_state_version": int((scene or {}).get("state_version") or 0),
                    "host_context_binding": host_context_binding(
                        campaign_id=campaign_id,
                        branch_id=branch_id,
                        principal_id=principal_id,
                        role=membership.role,
                        audience=audience,
                    ),
                },
                "actor": npc_turn_actor_projection(actor),
                "interlocutors": interlocutors,
                "stimulus": {**normalized_stimulus, "basis_ref": stimulus_ref},
                "perception": perception,
                "actor_knowledge": actor_knowledge,
                "common_context": common_context,
                "relationships": relationships,
                "goals": goals,
                "conversation": conversation,
                "scene": scene,
                "portrayal_context": portrayal_context,
                "constraints": {
                    "allowed_basis_refs": sorted(allowed_basis_refs),
                    "allowed_target_actor_ids": sorted({actor_id, *normalized_interlocutor_ids}),
                    "module_evidence_is_actor_knowledge": False,
                    "common_context_is_actor_knowledge": False,
                    "may_roll_dice": False,
                    "may_call_tools": False,
                    "may_write_state": False,
                    "output_contract": "npc-turn-proposal.v1",
                },
                "delegation": {
                    "schema_version": 1,
                    "contract": "sagasmith.delegation.v1",
                    "task": "propose_npc_turn",
                    "execution": "awaited_fresh_context",
                    "inherit_agent_history": False,
                    "tools_exposed": False,
                    "persist_worker_session": False,
                    "authoritative_result": False,
                    "output_contract": "npc-turn-proposal.v1",
                },
                "retrieval": {
                    **dict(result.get("retrieval") or {}),
                    "actor_state_count": len(actor_state),
                    "conversation_event_count": len(conversation_events),
                },
            }
            receipt = issue_npc_turn_receipt(
                bundle=bundle,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                actor_id=actor_id,
                actor_revision=actor.revision,
                interlocutor_actor_ids=normalized_interlocutor_ids,
                scene=scene,
                fact_heads=fact_heads,
                context_fact_heads=context_fact_heads,
                knowledge_heads=knowledge_heads,
                allowed_basis_refs=sorted(allowed_basis_refs),
                stimulus=normalized_stimulus,
                module_evidence=portrayal_context,
            )
            bundle["bundle_receipt"] = receipt
            return bundle
        result["host_context_binding"] = host_context_binding(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            role=membership.role,
            audience=audience,
        )
        result["context_receipt"] = issue_context_receipt(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            audience=audience,
            actor_id=actor_id,
            scope_id=scope_id,
            related_refs=sorted(resolved_related_refs),
            context=result,
        )
        return result

    def npc_conversation_require_fresh(session: dict[str, Any]) -> None:
        if session.get("status") == "stale":
            raise ValueError("SESSION_STALE: close or abort and open a new conversation")
        if session.get("status") not in ACTIVE_CONVERSATION_STATUSES:
            raise ValueError(f"conversation is not active: {session.get('status')}")
        authority = dict(session["authority"])
        reasons = []
        current_branch_id = readable_branch(
            str(session["campaign_id"]), str(session["branch_id"]), str(session["principal_id"])
        )
        if current_branch_id != session["branch_id"]:
            reasons.append("branch_id")
        scene = npc_turn_scene_projection(
            modules.current_scene(str(session["campaign_id"]), scope_id=str(session["scope_id"]))
        )
        if str((scene or {}).get("scene_id") or "") != str(session.get("scene_id") or ""):
            reasons.append("scene_id")
        elif int((scene or {}).get("state_version") or 0) != int(
            authority.get("scene_state_version") or 0
        ):
            reasons.append("scene_state_version")
        refreshed_actor_ids: list[str] = []
        for actor_id, expected_revision in dict(authority["actor_revisions"]).items():
            try:
                actor = characters.get(str(actor_id))
            except LookupError:
                reasons.append(f"actor:{actor_id}:missing")
                continue
            runtime = session["actor_runtimes"].get(str(actor_id))
            if runtime is None:
                continue
            lock = dict(dict(authority.get("actor_context_locks") or {}).get(actor_id) or {})
            current_lock = npc_conversation_context_lock(
                {
                    "authority": {
                        "campaign_id": session["campaign_id"],
                        "branch_id": session["branch_id"],
                    },
                    "actor": {"id": actor_id},
                }
            )
            fact_changed = dict(lock.get("fact_heads") or {}) != dict(
                current_lock["fact_heads"]
            )
            knowledge_changed = dict(lock.get("knowledge_heads") or {}) != dict(
                current_lock["knowledge_heads"]
            )
            if actor.revision != int(expected_revision) or fact_changed or knowledge_changed:
                old_runtime_id = str(runtime["actor_runtime_id"])
                bundle = continuity_context(
                    campaign_id=str(session["campaign_id"]),
                    query="",
                    actor_id=str(actor_id),
                    scope_id=str(session["scope_id"]),
                    audience="dm",
                    purpose="npc_turn",
                    interlocutor_actor_ids=[
                        item for item in session["participant_ids"] if item != actor_id
                    ],
                    stimulus=None,
                    branch_id=str(session["branch_id"]),
                    principal_id=str(session["principal_id"]),
                )
                runtime["context"] = npc_conversation_private_context(bundle)
                runtime["actor_runtime_id"] = (
                    f"{session['conversation_id']}:{actor_id}:r{actor.revision}:"
                    f"c{int(session['conversation_revision']) + 1}"
                )
                runtime["working_state_revision"] += 1
                for activation in session["activations"].values():
                    if activation["actor_id"] == actor_id and activation["status"] in {
                        "pending",
                        "claimed",
                    }:
                        activation["status"] = "invalidated"
                        activation["lease"] = None
                invalidated_activation_ids = {
                    str(activation["activation_id"])
                    for activation in session["activations"].values()
                    if activation["actor_id"] == actor_id
                    and str(activation.get("actor_runtime_id") or "") == old_runtime_id
                }
                for publication in session.get("publications") or []:
                    if (
                        publication.get("status") == "pending_audience"
                        and str(publication.get("activation_id") or "")
                        in invalidated_activation_ids
                    ):
                        publication["status"] = "invalidated"
                for resolution in session.get("pending_resolutions") or []:
                    if (
                        resolution.get("status") == "pending"
                        and str(resolution.get("activation_id") or "")
                        in invalidated_activation_ids
                    ):
                        resolution["status"] = "invalidated"
                for candidate in session.get("memory_candidates") or []:
                    if (
                        str(candidate.get("source_activation_id") or "")
                        in invalidated_activation_ids
                        and not candidate.get("source_event_id")
                    ):
                        candidate["status"] = "invalidated"
                authority["actor_revisions"][actor_id] = actor.revision
                authority.setdefault("actor_context_locks", {})[actor_id] = (
                    npc_conversation_context_lock(runtime["context"])
                )
                refreshed_actor_ids.append(str(actor_id))
        if reasons:
            session["status"] = "stale"
            session["stale_reasons"] = reasons
            session["updated_at_ns"] = time.time_ns()
            npc_conversations.save(session)
            raise ValueError("SESSION_STALE: authoritative state changed: " + ", ".join(reasons))
        if refreshed_actor_ids:
            session["authority"] = authority
            session["refreshed_actor_ids"] = refreshed_actor_ids
            session["conversation_revision"] = int(session["conversation_revision"]) + 1
            session["updated_at_ns"] = time.time_ns()
            npc_conversations.save(session)

    def npc_conversation_private_context(bundle: dict[str, Any]) -> dict[str, Any]:
        context = {key: deepcopy(value) for key, value in bundle.items() if key != "bundle_receipt"}
        context["purpose"] = "npc_conversation"
        bundle_authority = dict(context["authority"])
        context["authority"] = {
            key: deepcopy(bundle_authority[key])
            for key in ("campaign_id", "branch_id", "actor_revision", "scene_state_version")
        }
        context["constraints"] = {
            **dict(context["constraints"]),
            "output_contract": "npc-conversation-proposal.v4",
        }
        context["delegation"] = {
            "schema_version": 1,
            "contract": "sagasmith.delegation.v1",
            "task": "propose_npc_conversation_turn",
            "execution": "persistent_actor_worker",
            "inherit_agent_history": False,
            "tools_exposed": False,
            "persist_worker_session": True,
            "authoritative_result": False,
            "output_contract": "npc-conversation-proposal.v4",
        }
        actor_id = str(dict(context["actor"])["id"])
        commitments = [
            asdict(item)
            for item in memories.list_for_subject_refs(
                str(dict(context["authority"])["campaign_id"]),
                subject_refs={f"actor:{actor_id}"},
                predicates={"commitment"},
                kinds={"actor_state"},
                branch_id=str(dict(context["authority"])["branch_id"]),
            )
        ]
        context["commitments"] = commitments
        return context

    def npc_conversation_context_lock(context: dict[str, Any]) -> dict[str, Any]:
        authority = dict(context["authority"])
        actor_id = str(dict(context["actor"])["id"])
        campaign_id = str(authority["campaign_id"])
        branch_id = str(authority["branch_id"])
        actor_facts = [
            asdict(item)
            for item in memories.list_for_subject_refs(
                campaign_id,
                subject_refs={f"actor:{actor_id}"},
                predicates={"relationship_to", "goal", "commitment"},
                kinds={"actor_state"},
                branch_id=branch_id,
                include_inactive=True,
            )
        ]
        actor_knowledge = knowledge.list(
            campaign_id,
            actor_id=actor_id,
            branch_id=branch_id,
            include_inactive=True,
        )
        return {
            "fact_heads": {
                str(item["fact_key"]): str(item["revision_id"])
                for item in actor_facts
            },
            "knowledge_heads": {
                str(item.knowledge_key): str(item.revision_id)
                for item in actor_knowledge
            },
        }

    def npc_conversation_open_impl(
        campaign_id: str,
        participant_actor_ids: list[str],
        idempotency_key: str,
        scope_id: str = "party",
        query: str = "",
        branch_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Open one Play conversation and materialize each NPC's private runtime once."""

        membership = access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        require_facade_phase(campaign_id, "npc_conversation", PROFILE_PLAY)
        branch_id = require_current_branch(campaign_id, branch_id)
        campaign = campaigns.get(campaign_id)
        if dict(campaign.state.get("chase") or {}).get("active", False):
            raise CombatEngineError("end the active chase before opening an NPC conversation")
        actor_ids = [str(item).strip() for item in participant_actor_ids]
        if not actor_ids or any(not item for item in actor_ids):
            raise ValueError("participant_actor_ids must contain at least one actor")
        if len(actor_ids) != len(set(actor_ids)):
            raise ValueError("participant_actor_ids must be unique")
        if len(actor_ids) > 20:
            raise ValueError("a conversation supports at most 20 participants")
        actors = []
        for actor_id in actor_ids:
            actor = characters.get(actor_id)
            if actor.campaign_id != campaign_id:
                raise ValueError("every conversation participant must belong to the campaign")
            actors.append(actor)
        npc_actors = [
            actor for actor in actors if actor.character_type in NON_PLAYER_CHARACTER_TYPES
        ]
        if not npc_actors:
            raise ValueError(
                "conversation requires at least one NPC or monster campaign runtime id "
                "inside payload.participant_actor_ids"
            )

        actor_contexts: dict[str, dict[str, Any]] = {}
        first_bundle: dict[str, Any] | None = None
        for actor in npc_actors:
            bundle = continuity_context(
                campaign_id=campaign_id,
                query=query,
                actor_id=actor.id,
                scope_id=scope_id,
                audience="dm",
                purpose="npc_turn",
                interlocutor_actor_ids=[item for item in actor_ids if item != actor.id],
                stimulus=None,
                branch_id=branch_id,
                principal_id=principal_id,
            )
            first_bundle = first_bundle or bundle
            actor_contexts[actor.id] = npc_conversation_private_context(bundle)
        assert first_bundle is not None
        first_authority = dict(first_bundle["authority"])
        scene = dict(first_bundle.get("scene") or {})
        authority = {
            "scene_state_version": int(first_authority.get("scene_state_version") or 0),
            "actor_revisions": {actor.id: actor.revision for actor in actors},
            "actor_context_locks": {
                actor_id: npc_conversation_context_lock(context)
                for actor_id, context in actor_contexts.items()
            },
            "principal_fingerprint": dict(first_authority["host_context_binding"])[
                "principal_fingerprint"
            ],
        }
        opened = npc_conversations.open(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
            scope_id=scope_id,
            scene_id=str(scene.get("scene_id") or ""),
            authority=authority,
            participants=[
                {
                    "actor_id": actor.id,
                    "name": actor.name,
                    "kind": actor.character_type,
                    "npc_runtime": actor.id in actor_contexts,
                }
                for actor in actors
            ],
            actor_contexts=actor_contexts,
            idempotency_key=idempotency_key,
        )
        opened["role"] = membership.role
        opened["next_step"] = (
            "Call npc_conversation(action='ingest') with Agent-resolved audience_facts, "
            "then let the authenticated Host dispatch only the returned activation_refs."
        )
        return opened

    def npc_conversation_status_impl(
        campaign_id: str,
        conversation_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read public orchestration state without exposing any NPC private capsule."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        session = npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        if session.get("status") == "open":
            npc_conversation_require_fresh(session)
        result = npc_conversations.public_status(session)
        if session.get("status") == "stale":
            result["stale_reasons"] = list(session.get("stale_reasons") or [])
        result["activations"] = npc_conversations.list_activations(session)
        result["pending_publications"] = [
            {key: deepcopy(value) for key, value in item.items() if key not in {"speaker_actor_id"}}
            for item in session["publications"]
            if item.get("status") == "pending_audience"
        ]
        result["pending_resolutions"] = [
            deepcopy(item)
            for item in session.get("pending_resolutions") or []
            if item.get("status") == "pending"
        ]
        result["memory_candidates"] = npc_conversations.memory_candidates(session)
        result["refreshed_actor_ids"] = list(session.get("refreshed_actor_ids") or [])
        return result

    def npc_conversation_list_impl(
        campaign_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """List this principal's active public conversation recovery handles."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        branch_id = require_current_branch(campaign_id, None)
        conversations = npc_conversations.active_public_statuses(
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
        )
        return {
            "campaign_id": campaign_id,
            "branch_id": branch_id,
            "count": len(conversations),
            "conversations": conversations,
        }

    def npc_conversation_ingest_impl(
        campaign_id: str,
        conversation_id: str,
        event: dict[str, Any],
        audience_facts: dict[str, Any],
        expected_conversation_revision: int,
        idempotency_key: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Append one stimulus using explicit Agent-resolved audience facts."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        session = npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        npc_conversation_require_fresh(session)
        raw = dict(event or {})
        allowed_fields = {
            "type",
            "speaker_actor_id",
            "content",
            "language",
            "delivery",
            "declared_target_actor_ids",
            "resolved_resolution_ids",
        }
        if unknown := set(raw) - allowed_fields:
            raise ValueError(f"conversation event has unknown fields: {sorted(unknown)}")
        event_type = str(raw.get("type") or "speech").strip()
        if event_type not in {"speech", "action", "scene_prompt", "resolution"}:
            raise ValueError(
                "conversation event type must be speech, action, scene_prompt, or resolution"
            )
        speaker_actor_id = str(raw.get("speaker_actor_id") or "").strip()
        if speaker_actor_id and speaker_actor_id not in session["participant_ids"]:
            raise ValueError("conversation speaker must be a participant")
        if event_type in {"speech", "action"} and not speaker_actor_id:
            raise ValueError("speech and action events require a participant speaker")
        content = str(raw.get("content") or "").strip()
        if not content or len(content) > 6_000:
            raise ValueError("conversation event content must contain 1 to 6000 characters")
        target_actor_ids = [
            str(item).strip() for item in raw.get("declared_target_actor_ids") or []
        ]
        if len(target_actor_ids) != len(set(target_actor_ids)) or any(
            item not in session["participant_ids"] for item in target_actor_ids
        ):
            raise ValueError("declared conversation targets must be unique participants")
        language = str(raw.get("language") or "").strip()
        delivery = str(raw.get("delivery") or "").strip()
        resolved_resolution_ids = [
            str(item).strip() for item in raw.get("resolved_resolution_ids") or []
        ]
        if len(resolved_resolution_ids) != len(set(resolved_resolution_ids)) or any(
            not item for item in resolved_resolution_ids
        ):
            raise ValueError("resolved_resolution_ids must contain unique non-empty ids")
        if event_type == "resolution" and not resolved_resolution_ids:
            raise ValueError("resolution events must identify at least one resolved resolution")
        if event_type != "resolution" and resolved_resolution_ids:
            raise ValueError("only resolution events may include resolved_resolution_ids")
        audience = normalize_audience_facts(
            audience_facts,
            participant_ids=set(session["participant_ids"]),
            response_actor_ids=set(session["actor_runtimes"]),
        )
        result = npc_conversations.append_event(
            session,
            event={
                "type": event_type,
                "speaker_actor_id": speaker_actor_id,
                "content": content,
                "language": language,
                "delivery": delivery,
                "declared_target_actor_ids": target_actor_ids,
                "resolved_resolution_ids": resolved_resolution_ids,
            },
            audience_facts=audience,
            expected_revision=expected_conversation_revision,
            idempotency_key=idempotency_key,
        )
        return result

    def npc_activation_claim_impl(
        campaign_id: str,
        conversation_id: str,
        activation_ref: str,
        expected_conversation_revision: int,
        idempotency_key: str,
        cursor: int = 0,
        include_bootstrap: bool = True,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Lease one private actor capsule to the matching isolated NPC subagent."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        session = npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        npc_conversation_require_fresh(session)
        return npc_conversations.checkout(
            session,
            activation_ref=activation_ref,
            cursor=cursor,
            include_bootstrap=include_bootstrap,
            expected_revision=expected_conversation_revision,
            idempotency_key=idempotency_key,
        )

