    def npc_conversation_publish_impl(
        campaign_id: str,
        conversation_id: str,
        publication_id: str,
        audience_facts: dict[str, Any],
        segment_audience_facts: list[dict[str, Any]] | None,
        expected_conversation_revision: int,
        idempotency_key: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        session = npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        npc_conversation_require_fresh(session)
        audience = normalize_audience_facts(
            audience_facts,
            participant_ids=set(session["participant_ids"]),
            response_actor_ids=set(session["actor_runtimes"]),
        )
        segment_audience = [
            normalize_audience_facts(
                item,
                participant_ids=set(session["participant_ids"]),
                response_actor_ids=set(session["actor_runtimes"]),
            )
            for item in list(segment_audience_facts or [])
        ]
        return npc_conversations.publish(
            session,
            publication_id=publication_id,
            audience_facts=audience,
            segment_audience_facts=segment_audience,
            expected_revision=expected_conversation_revision,
            idempotency_key=idempotency_key,
        )

    def npc_conversation_close_impl(
        campaign_id: str,
        conversation_id: str,
        expected_conversation_revision: int,
        accepted_candidate_ids: list[str] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Atomically commit the exact public transcript and accepted long-term deltas."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for npc_conversation(close)")
        npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        session, replay = npc_conversations.begin_mutation(
            conversation_id,
            expected_revision=expected_conversation_revision,
            idempotency_key=idempotency_key,
            operation="close",
            payload={"accepted_candidate_ids": accepted_candidate_ids or []},
        )
        if replay is not None:
            return replay
        npc_conversation_require_fresh(session)
        if session.get("status") != "open":
            raise ValueError("conversation must be open before closing")
        if any(
            item.get("status") in {"pending", "claimed"} for item in session["activations"].values()
        ):
            raise ValueError("conversation has unfinished NPC activations")
        if any(
            item.get("status") == "pending_audience"
            for item in session.get("publications") or []
        ):
            raise ValueError("conversation has unpublished NPC output")
        if any(
            item.get("status") == "pending"
            for item in session.get("pending_resolutions") or []
        ):
            raise ValueError("conversation has unresolved mechanic requests")
        candidate_ids = list(accepted_candidate_ids or [])
        if (
            any(not isinstance(item, str) or not item for item in candidate_ids)
            or len(candidate_ids) != len(set(candidate_ids))
        ):
            raise ValueError("accepted_candidate_ids must be a unique non-empty string list")
        candidates = {
            str(item["candidate_id"]): item
            for item in npc_conversations.memory_candidates(session)
        }
        if unknown := sorted(set(candidate_ids) - set(candidates)):
            raise ValueError(f"accepted_candidate_ids contains unavailable candidates: {unknown}")
        facts_data: list[dict[str, Any]] = []
        knowledge_data: list[dict[str, Any]] = []
        accepted_commitments: list[dict[str, Any]] = []
        for candidate_id in candidate_ids:
            candidate = candidates[candidate_id]
            if candidate["status"] != "available":
                raise ValueError(f"memory candidate is not available: {candidate_id}")
            actor_id = str(candidate["actor_id"])
            value = deepcopy(candidate["value"])
            if candidate["kind"] == "fact":
                facts_data.append(value)
            elif candidate["kind"] == "actor_knowledge":
                knowledge_data.append(value)
            elif candidate["kind"] == "commitment":
                commitment = value
                commitment_key = str(commitment["commitment_key"])
                facts_data.append(
                    {
                        "action": "upsert",
                        "fact_key": f"actor:{actor_id}:commitment:{commitment_key}",
                        "content": str(commitment["content"]),
                        "kind": "actor_state",
                        "subject": actor_id,
                        "subject_ref": f"actor:{actor_id}",
                        "predicate": "commitment",
                        "metadata": dict(commitment.get("metadata") or {}),
                        "importance": int(commitment.get("importance", 3)),
                        "disclosure_scope": "dm",
                    }
                )
                accepted_commitments.append(deepcopy(commitment))
            else:
                raise ValueError(f"unsupported memory candidate kind: {candidate['kind']}")
        participants = {str(item) for item in session["participant_ids"]}
        current_facts = {
            item.fact_key: item
            for item in memories.list(
                campaign_id, branch_id=session["branch_id"], include_inactive=True
            )
        }
        for index, fact in enumerate(facts_data):
            actor_ref = str(fact.get("subject_ref") or "")
            if actor_ref.removeprefix("actor:") not in participants:
                raise ValueError(f"accepted fact[{index}] belongs outside the conversation")
            if str(fact.get("kind") or "") != "actor_state" or str(
                fact.get("predicate") or ""
            ) not in {"relationship_to", "goal", "commitment"}:
                raise ValueError("accepted conversation facts must be actor-state continuity")
            fact["disclosure_scope"] = "dm"
            current = current_facts.get(str(fact.get("fact_key") or ""))
            if current is not None and str(fact.get("action") or "upsert") == "upsert":
                fact.setdefault("expected_revision_id", current.revision_id)
        for index, item in enumerate(knowledge_data):
            if str(item.get("actor_id") or "") not in participants:
                raise ValueError(
                    f"accepted ActorKnowledge[{index}] belongs outside the conversation"
                )
            item["disclosure_scope"] = str(item.get("disclosure_scope") or "dm")

        transcript = [
            {
                key: deepcopy(event.get(key))
                for key in (
                    "event_id",
                    "sequence",
                    "type",
                    "speaker_actor_id",
                    "content",
                    "language",
                    "delivery",
                    "declared_target_actor_ids",
                    "publication_id",
                    "utterance_segments",
                    "visible_cues",
                    "visible_action",
                    "resolved_resolution_ids",
                    "audience_facts",
                    "segment_audience_facts",
                )
                if key in event
            }
            for event in session["events"]
        ]
        names = {str(item["actor_id"]): str(item["name"]) for item in session["participants"]}
        retrieval_lines = []
        for event in transcript[-12:]:
            content = str(event.get("content") or "").strip()
            if content:
                retrieval_lines.append(
                    f"{names.get(str(event.get('speaker_actor_id')), 'Scene')}: {content[:300]}"
                )
        event_summary = (
            f"Conversation among {', '.join(names.values())}; "
            f"{len(transcript)} public events and {len(session['publications'])} NPC publications."
        )
        commit = continuity_commit(
            campaign_id,
            {
                "branch_id": session["branch_id"],
                "event": {
                    "event_type": "npc_conversation",
                    "summary": event_summary,
                    "retrieval_text": "\n".join(retrieval_lines),
                    "audience_scope": "dm",
                    "participants": [
                        {"actor_id": actor_id, "role": "witness"}
                        for actor_id in session["participant_ids"]
                    ],
                    "payload": {
                        "schema_version": 2,
                        "conversation_id": conversation_id,
                        "scene_id": session["scene_id"],
                        "scope_id": session["scope_id"],
                        "transcript": transcript,
                        "accepted_commitments": accepted_commitments,
                        "unresolved_resolution_requests": deepcopy(
                            [
                                item
                                for item in session.get("pending_resolutions") or []
                                if item.get("status") == "pending"
                            ]
                        ),
                        "authority_at_open": deepcopy(session["authority"]),
                    },
                },
                "facts": facts_data,
                "actor_knowledge": knowledge_data,
            },
            principal_id,
            campaigns.get(campaign_id).revision,
            idempotency_key,
        )
        session["status"] = "closed"
        for runtime in session["actor_runtimes"].values():
            runtime["status"] = "closed"
            runtime["context"] = {}
        return npc_conversations.finish_mutation(session, commit)

    def npc_conversation_abort_impl(
        campaign_id: str,
        conversation_id: str,
        expected_conversation_revision: int,
        idempotency_key: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Discard an uncommitted conversation draft and every private actor capsule."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        session = npc_conversations.require_owner(
            conversation_id, campaign_id=campaign_id, principal_id=principal_id
        )
        if session.get("status") == "closed":
            raise ValueError("a committed conversation cannot be aborted")
        session, replay = npc_conversations.begin_mutation(
            conversation_id,
            expected_revision=expected_conversation_revision,
            idempotency_key=idempotency_key,
            operation="abort",
            payload={},
        )
        if replay is not None:
            return replay
        session["status"] = "aborted"
        for runtime in session["actor_runtimes"].values():
            runtime["context"] = {}
        for candidate in session.get("memory_candidates") or []:
            candidate["status"] = "invalidated"
        return npc_conversations.finish_mutation(
            session,
            {"conversation_id": conversation_id, "status": "aborted", "recoverable": False},
        )

    @public_tool()
    def npc_conversation(
        campaign_id: str,
        action: Literal["open", "list", "get", "ingest", "publish", "close", "abort"],
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Run the complete public NPC conversation workflow through one facade."""

        data = dict(payload or {})
        if action == "open":
            if not isinstance(data.get("participant_actor_ids"), list):
                raise ValueError(
                    "npc_conversation open requires payload.participant_actor_ids: "
                    "put every PC and NPC campaign runtime id in that one array; "
                    "there are no npc_actor_ids or npc_ids fields"
                )
            if not str(data.get("idempotency_key") or "").strip():
                raise ValueError("npc_conversation open requires payload.idempotency_key")
            return npc_conversation_open_impl(
                campaign_id=campaign_id,
                participant_actor_ids=list(data["participant_actor_ids"]),
                idempotency_key=str(data["idempotency_key"]),
                scope_id=str(data.get("scope_id") or "party"),
                query=str(data.get("query") or ""),
                branch_id=data.get("branch_id"),
                principal_id=principal_id,
            )
        if action == "list":
            return npc_conversation_list_impl(campaign_id, principal_id)
        conversation_id = str(data["conversation_id"])
        if action == "get":
            return npc_conversation_status_impl(campaign_id, conversation_id, principal_id)
        if action == "ingest":
            return npc_conversation_ingest_impl(
                campaign_id,
                conversation_id,
                dict(data["event"]),
                dict(data["audience_facts"]),
                int(data["expected_conversation_revision"]),
                str(data["idempotency_key"]),
                principal_id,
            )
        if action == "publish":
            return npc_conversation_publish_impl(
                campaign_id,
                conversation_id,
                str(data["publication_id"]),
                dict(data["audience_facts"]),
                [dict(item) for item in data.get("segment_audience_facts") or []],
                int(data["expected_conversation_revision"]),
                str(data["idempotency_key"]),
                principal_id,
            )
        if action == "close":
            allowed = {
                "conversation_id",
                "expected_conversation_revision",
                "accepted_candidate_ids",
                "idempotency_key",
            }
            if unknown := sorted(set(data) - allowed):
                raise ValueError(f"npc_conversation close has unknown fields: {unknown}")
            accepted_candidate_ids = data.get("accepted_candidate_ids") or []
            if not isinstance(accepted_candidate_ids, list):
                raise ValueError("accepted_candidate_ids must be a list")
            return npc_conversation_close_impl(
                campaign_id,
                conversation_id,
                int(data["expected_conversation_revision"]),
                accepted_candidate_ids,
                principal_id,
                str(data["idempotency_key"]),
            )
        if action == "abort":
            return npc_conversation_abort_impl(
                campaign_id,
                conversation_id,
                int(data["expected_conversation_revision"]),
                str(data["idempotency_key"]),
                principal_id,
            )
        raise ValueError(f"unsupported npc_conversation action: {action}")

    @public_tool()
    def npc_conversation_transport(
        campaign_id: str,
        conversation_id: str,
        action: Literal["claim_activation", "submit_proposal", "cancel_activation"],
        payload: dict[str, Any],
        host_token: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Host-private activation transport; never exposed to a model tool profile."""

        if not config.npc_host_token or not secrets.compare_digest(
            host_token, config.npc_host_token
        ):
            raise PermissionError("NPC host transport authentication failed")
        data = dict(payload or {})
        common = {
            "campaign_id": campaign_id,
            "conversation_id": conversation_id,
            "activation_ref": str(data["activation_ref"]),
            "expected_conversation_revision": int(data["expected_conversation_revision"]),
            "idempotency_key": str(data["idempotency_key"]),
            "principal_id": principal_id,
        }
        if action == "claim_activation":
            return npc_activation_claim_impl(
                **common,
                cursor=int(data.get("cursor") or 0),
                include_bootstrap=bool(data.get("include_bootstrap", True)),
            )
        if action == "submit_proposal":
            return npc_proposal_submit_impl(
                **common,
                lease_id=str(data["lease_id"]),
                proposal=dict(data["proposal"]),
            )
        if action == "cancel_activation":
            return npc_activation_cancel_impl(
                **common,
                lease_id=str(data["lease_id"]),
            )
        raise ValueError(f"unsupported NPC host transport action: {action}")

    @public_tool()
    def bounded_evaluation(
        campaign_id: str,
        action: Literal["validate"],
        proposal: dict[str, Any],
        bundle_receipt: dict[str, Any],
        branch_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Validate one isolated proposal against its live signed context receipt."""

        if action != "validate":
            raise ValueError("bounded_evaluation action must be validate")
        membership = access.require_campaign(campaign_id, principal_id)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        receipt = verify_bounded_evaluation_receipt(
            bundle_receipt,
            campaign_id=campaign_id,
            branch_id=branch_id,
            principal_id=principal_id,
        )
        purpose = str(receipt["purpose"])
        if membership.role not in CAMPAIGN_DM_ROLES and purpose != "audience_render":
            raise ValueError(
                "players may validate only audience_render proposals issued to themselves"
            )
        normalized = normalize_bounded_proposal(purpose, proposal)
        if normalized["bundle_id"] != receipt.get("bundle_id"):
            raise ValueError("bounded proposal belongs to another context bundle")
        if purpose == "source_interpretation" and hashlib.sha256(
            str(normalized["question"]).strip().encode("utf-8")
        ).hexdigest() != str(receipt.get("question_digest") or ""):
            raise ValueError("source interpretation question does not match its signed bundle")
        validate_bounded_proposal_refs(
            normalized,
            subject_ref=str(receipt["subject_ref"]),
            allowed_basis_refs={str(item) for item in receipt.get("allowed_basis_refs") or []},
            allowed_claim_basis_refs={
                str(item) for item in receipt.get("allowed_claim_basis_refs") or []
            },
            allowed_target_refs={str(item) for item in receipt.get("allowed_target_refs") or []},
        )
        proposal_digest = hashlib.sha256(canonical_json(normalized).encode("utf-8")).hexdigest()
        validation_payload = {
            "schema_version": 1,
            "purpose": purpose,
            "bundle_id": str(receipt["bundle_id"]),
            "bundle_digest": str(receipt["bundle_digest"]),
            "proposal_digest": proposal_digest,
            "campaign_id": campaign_id,
            "branch_id": branch_id,
            "campaign_revision": campaigns.get(campaign_id).revision,
            "principal_fingerprint": receipt_principal_fingerprint(principal_id),
            "expires_monotonic_ns": int(receipt["expires_monotonic_ns"]),
        }
        validation_receipt = sign_receipt(validation_payload, context_receipt_secret)
        result: dict[str, Any] = {
            "validated": True,
            "authoritative_state_changed": False,
            "purpose": purpose,
            "proposal": normalized,
            "validation_receipt": validation_receipt,
            "next_step": (
                "relay publication.text exactly"
                if purpose == "audience_render"
                else "resolve mechanics and select any writes through public MCP tools"
            ),
        }
        if purpose == "audience_render":
            result["publication"] = {
                "text": str(normalized["text"]),
                "validation_receipt": validation_receipt,
            }
        return result

    def continuity_diagnostics(
        campaign_id: str,
        branch_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Inspect continuity health without returning secret narrative content."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        branch_id = readable_branch(campaign_id, branch_id, principal_id)
        result = continuity.diagnostics(campaign_id, branch_id=branch_id)
        current_manifest = catalog.manifest()
        latest_manifest = None
        for item in reversed(events.list(campaign_id, limit=500, branch_id=branch_id)):
            candidate = item.payload.get("_sagasmith_skill_manifest")
            if isinstance(candidate, list):
                latest_manifest = candidate
                break
        result["skill_manifest"] = {
            "current": current_manifest,
            "latest_event": latest_manifest,
            "drift": (latest_manifest != current_manifest if latest_manifest is not None else None),
        }
        latest_slot = result["snapshots"]["latest_slot"]
        recap = snapshots.get(campaign_id, latest_slot).get("recap") if latest_slot else None
        provenance = dict(recap.get("provenance") or {}) if isinstance(recap, dict) else {}
        result["recap"] = {
            "schema_version": recap.get("schema_version") if isinstance(recap, dict) else None,
            "source": recap.get("source") if isinstance(recap, dict) else None,
            "has_presentation": bool(
                isinstance(recap, dict) and recap.get("presentation") is not None
            ),
            "evidence_event_count": len(provenance.get("evidence_event_ids") or []),
        }
        return result

    def continuity_commit(
        campaign_id: str,
        payload: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Atomically save a scene event, fact changes, actor knowledge, and snapshot."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for continuity commits")
        data = facade_payload(payload)
        branch_id = require_current_branch(campaign_id, data.get("branch_id"))
        raw_event = required(data, "event")
        raw_facts = data.get("facts") or []
        raw_knowledge = data.get("actor_knowledge") or []
        if not isinstance(raw_event, dict):
            raise ValueError("payload.event must be an object")
        if not isinstance(raw_facts, list) or not all(isinstance(item, dict) for item in raw_facts):
            raise ValueError("payload.facts must be a list of objects")
        if not isinstance(raw_knowledge, list) or not all(
            isinstance(item, dict) for item in raw_knowledge
        ):
            raise ValueError("payload.actor_knowledge must be a list of objects")
        event_data = dict(raw_event)
        facts_data = [dict(item) for item in raw_facts]
        knowledge_data = [dict(item) for item in raw_knowledge]
        context_receipt = data.get("context_receipt")
        npc_turn_data = data.get("npc_turn")
        npc_turn_receipt: dict[str, Any] | None = None
        npc_turn_trace: dict[str, Any] | None = None
        if npc_turn_data is not None:
            if not isinstance(npc_turn_data, dict):
                raise ValueError("payload.npc_turn must be an object")
            unknown_npc_fields = set(npc_turn_data) - {
                "bundle_receipt",
                "proposal",
                "accepted_fact_indexes",
                "accepted_actor_knowledge_indexes",
                "accepted_action",
                "isolation_level",
            }
            if unknown_npc_fields:
                raise ValueError(
                    f"payload.npc_turn has unknown fields: {sorted(unknown_npc_fields)}"
                )
            if facts_data or knowledge_data:
                raise ValueError(
                    "NPC turn facts and ActorKnowledge must come from accepted proposal indexes"
                )
            proposal = normalize_npc_turn_proposal(npc_turn_data.get("proposal"))
            npc_turn_receipt = verify_npc_turn_receipt(
                npc_turn_data.get("bundle_receipt"),
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                require_fresh=False,
            )
            if proposal["bundle_id"] != npc_turn_receipt.get("bundle_id"):
                raise ValueError("NPC proposal belongs to another context bundle")
            if proposal["speaker_actor_id"] != npc_turn_receipt.get("actor_id"):
                raise ValueError("NPC proposal speaker does not match its context bundle")
            validate_npc_basis_refs(
                proposal,
                allowed_basis_refs={
                    str(item) for item in npc_turn_receipt.get("allowed_basis_refs") or []
                },
            )
            validate_npc_targets(
                proposal,
                allowed_actor_ids={
                    str(npc_turn_receipt["actor_id"]),
                    *(str(item) for item in npc_turn_receipt.get("interlocutor_actor_ids") or []),
                },
            )
            if proposal["resolution_requests"]:
                raise ValueError(
                    "NPC proposal requires resolution; use public rules tools and read a new bundle"
                )
            fact_indexes = npc_turn_data.get("accepted_fact_indexes") or []
            knowledge_indexes = npc_turn_data.get("accepted_actor_knowledge_indexes") or []
            if not isinstance(fact_indexes, list) or not isinstance(knowledge_indexes, list):
                raise ValueError("accepted NPC proposal indexes must be lists")
            facts_data, knowledge_data = accepted_proposal_deltas(
                proposal,
                fact_indexes=fact_indexes,
                actor_knowledge_indexes=knowledge_indexes,
            )
            speaker_actor_id = str(npc_turn_receipt["actor_id"])
            listener_actor_ids = [
                str(item) for item in npc_turn_receipt.get("interlocutor_actor_ids") or []
            ]
            allowed_delta_actor_ids = {speaker_actor_id, *listener_actor_ids}
            allowed_fact_fields = {
                "action",
                "fact_key",
                "memory_id",
                "content",
                "kind",
                "subject",
                "metadata",
                "subject_ref",
                "predicate",
                "status",
                "valid_from",
                "valid_to",
                "source_event_ids",
                "importance",
                "disclosure_scope",
                "expected_revision_id",
            }
            for index, fact in enumerate(facts_data):
                if unknown := set(fact) - allowed_fact_fields:
                    raise ValueError(
                        f"accepted NPC fact[{index}] has unknown fields: {sorted(unknown)}"
                    )
                if str(fact.get("kind") or "") != "actor_state":
                    raise ValueError("accepted NPC facts must use kind='actor_state'")
                if str(fact.get("subject_ref") or "") != f"actor:{speaker_actor_id}":
                    raise ValueError("accepted NPC facts must belong to the speaking actor")
                if str(fact.get("predicate") or "") not in {"relationship_to", "goal"}:
                    raise ValueError("accepted NPC facts may update only relationships or goals")
                if str(fact.get("disclosure_scope") or "dm") != "dm":
                    raise ValueError("accepted NPC actor-state facts must remain DM-only")
                fact["disclosure_scope"] = "dm"
            allowed_knowledge_fields = {
                "action",
                "actor_id",
                "knowledge_key",
                "knowledge_id",
                "proposition",
                "subject_ref",
                "epistemic_status",
                "confidence",
                "cause",
                "disclosure_scope",
                "expected_revision_id",
            }
            for index, item in enumerate(knowledge_data):
                if unknown := set(item) - allowed_knowledge_fields:
                    raise ValueError(
                        "accepted NPC ActorKnowledge"
                        f"[{index}] has unknown fields: {sorted(unknown)}"
                    )
                if str(item.get("actor_id") or "") not in allowed_delta_actor_ids:
                    raise ValueError(
                        "accepted NPC ActorKnowledge may target only the speaker or listeners"
                    )
            raw_accepted_action = npc_turn_data.get("accepted_action", False)
            if not isinstance(raw_accepted_action, bool):
                raise ValueError("payload.npc_turn.accepted_action must be boolean")
            accepted_action = raw_accepted_action
            action_kind = str(proposal["proposed_action"]["kind"])
            if accepted_action and action_kind not in NPC_NARRATIVE_ACTION_KINDS:
                raise ValueError(
                    "mechanical NPC actions require public engine tools before continuity commit"
                )
            action_target_ref = str(proposal["proposed_action"].get("target_ref") or "")
            if accepted_action and action_target_ref:
                allowed_action_targets = {
                    f"actor:{actor_id_value}" for actor_id_value in allowed_delta_actor_ids
                }
                if action_target_ref not in allowed_action_targets:
                    raise ValueError(
                        "accepted narrative NPC action target must be the speaker or listener"
                    )
            isolation_level = str(npc_turn_data.get("isolation_level") or "logical")
            if isolation_level not in {"isolated", "logical"}:
                raise ValueError("NPC turn isolation_level must be isolated or logical")
            audience_scope = str(event_data.get("audience_scope") or "actor")
            if audience_scope not in {"actor", "party", "public"}:
                raise ValueError("NPC dialogue audience_scope must be actor, party, or public")
            summary = str(event_data.get("summary") or "").strip()
            if not summary:
                raise ValueError("payload.event.summary is required")
            proposal_digest = hashlib.sha256(canonical_json(proposal).encode("utf-8")).hexdigest()
            visible_action = ""
            if accepted_action and action_kind != "none":
                visible_action = str(proposal["proposed_action"].get("summary") or action_kind)
            npc_turn_trace = {
                "bundle_digest": str(npc_turn_receipt["bundle_digest"]),
                "proposal_digest": proposal_digest,
                "isolation_level": isolation_level,
            }
            event_data = {
                "event_type": "npc_dialogue_turn",
                "summary": summary,
                "audience_scope": audience_scope,
                "participants": [
                    {"actor_id": speaker_actor_id, "role": "speaker"},
                    *(
                        {"actor_id": listener_id, "role": "listener"}
                        for listener_id in listener_actor_ids
                    ),
                ],
                "payload": {
                    "schema_version": NPC_TURN_SCHEMA_VERSION,
                    "speaker_actor_id": speaker_actor_id,
                    "listener_actor_ids": listener_actor_ids,
                    "scene_id": str(npc_turn_receipt.get("scene_id") or ""),
                    "language": str(proposal["utterance"].get("language") or ""),
                    "utterance": str(proposal["utterance"].get("text") or ""),
                    "delivery": str(proposal["utterance"].get("delivery") or ""),
                    "visible_action": visible_action,
                    "public_speech_acts": [
                        {
                            "kind": str(item.get("kind") or ""),
                            "content": str(item.get("content") or ""),
                            "targets": [str(target) for target in item.get("targets") or []],
                        }
                        for item in proposal["speech_acts"]
                    ],
                    "visible_portrayal_cues": [
                        str(item) for item in proposal["portrayal"].get("visible_cues") or []
                    ],
                    "turn_trace": npc_turn_trace,
                },
            }
            context_receipt = npc_turn_data.get("bundle_receipt")
        snapshot_data = dict(data["snapshot"]) if data.get("snapshot") is not None else None
        validate_embedded_module_source_refs(
            campaign_id,
            event_data.get("payload") or {},
            field="payload.event.payload",
        )
        validate_embedded_module_source_refs(
            campaign_id,
            facts_data,
            field="payload.facts",
        )
        validate_embedded_module_source_refs(
            campaign_id,
            knowledge_data,
            field="payload.actor_knowledge",
        )
        if (
            event_data.get("audience_scope") == "actor"
            and not knowledge_data
            and not event_data.get("participants")
        ):
            raise ValueError(
                "actor-scoped continuity events require ActorKnowledge or event participants"
            )
        manifest = catalog.manifest()
        for fact in facts_data:
            validate_subject_context_fact(
                kind=fact.get("kind"),
                subject_ref=fact.get("subject_ref"),
            )
        event_payload = dict(event_data.get("payload") or {})
        event_payload["_sagasmith_skill_manifest"] = manifest
        event_data["payload"] = event_payload
        # A response-lost retry normally carries the current post-commit
        # revision. Keep concurrency tokens out of the logical request hash so
        # the original atomic response can be replayed without duplicating it.
        request_payload = {
            "event": event_data,
            "facts": facts_data,
            "actor_knowledge": knowledge_data,
            "snapshot": snapshot_data,
            "branch_id": branch_id,
            "skill_manifest": manifest,
            "npc_turn_trace": npc_turn_trace,
        }
        scope = f"continuity-commit:{campaign_id}:{branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        embedded_source_digests = managed_module_source_digests(
            [event_data.get("payload") or {}, facts_data, knowledge_data]
        )
        required_source_digests = embedded_source_digests & anchored_source_digests(
            campaign_id,
            branch_id,
        )
        if npc_turn_receipt is not None:
            npc_turn_receipt = verify_npc_turn_receipt(
                context_receipt,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                required_source_digests=required_source_digests,
            )
        elif required_source_digests:
            verify_context_receipt(
                context_receipt,
                campaign_id=campaign_id,
                branch_id=branch_id,
                principal_id=principal_id,
                required_source_digests=required_source_digests,
            )
        current_facts = {
            item.fact_key: item
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        for index, fact in enumerate(facts_data):
            action = str(fact.get("action", "upsert"))
            if action == "upsert" and current_facts.get(str(fact.get("fact_key", ""))):
                if fact.get("expected_revision_id") is None:
                    raise ValueError(
                        f"payload.facts[{index}].expected_revision_id is required "
                        "when upsert revises a fact"
                    )
            if action == "revise" and fact.get("expected_revision_id") is None:
                raise ValueError(
                    f"payload.facts[{index}].expected_revision_id is required for revisions"
                )
            if "valid_from" in fact:
                fact["valid_from"] = optional_datetime(
                    fact.get("valid_from"), f"facts[{index}].valid_from"
                )
            if "valid_to" in fact:
                fact["valid_to"] = optional_datetime(
                    fact.get("valid_to"), f"facts[{index}].valid_to"
                )
        for index, item in enumerate(knowledge_data):
            if (
                str(item.get("action", "add")) == "revise"
                and item.get("expected_revision_id") is None
            ):
                raise ValueError(
                    "payload.actor_knowledge"
                    f"[{index}].expected_revision_id is required for revisions"
                )
        campaign = campaigns.get(campaign_id)
        if expected_revision is not None and campaign.revision != expected_revision:
            raise ValueError(
                f"campaign revision conflict: expected {expected_revision}, "
                f"found {campaign.revision}"
            )
        response = continuity_commits.commit(
            campaign_id,
            event=event_data,
            facts=facts_data,
            actor_knowledge=knowledge_data,
            snapshot=snapshot_data,
            branch_id=branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=lambda result: {
                    **result,
                    "skill_manifest": manifest,
                },
            ),
        )
        response["skill_manifest"] = manifest
        return response

    def module_import_job_create(
        campaign_id: str,
        artifact: str,
        title: str | None = None,
        source_key: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Create a staged module package job before parsing or activating a revision."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for an import job")
        path = storage.artifact_module_path(artifact)
        logical_key = str(source_key or artifact).strip()
        payload = {
            "artifact": artifact,
            "title": title or path.stem,
            "source_key": logical_key,
        }
        scope = f"import-job-create:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        document = normalize_document(
            path,
            ocr_provider=storage.module_document_ocr_provider(),
            cache_dir=config.normalized_modules_dir,
            layout_profile=DND5E_DOCUMENT_LAYOUT_PROFILE,
        )
        document_inspection = inspect_character_document(
            document,
            source_name=path.name,
        )
        if document_inspection["document_kind"] != "unknown":
            raise ValueError(
                "character sheets and ability-score option documents are not modules; "
                "use character_query(view='document')"
            )
        preview = modules.preview_path(
            path,
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(document.checksum),
        )
        job = import_jobs.create(
            campaign_id=campaign_id,
            kind="module",
            artifact=artifact,
            artifact_checksum=str(preview.get("checksum") or ""),
            payload=payload,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {"job": import_job_view(result)},
            ),
        )
        return {"job": import_job_view(job)}

    def module_import_job_inspect(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Persist parser preview, stable scene keys, and space evidence for a module job."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module inspection")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "inspect"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        preview = modules.preview_path(
            storage.artifact_module_path(job.artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(
                job.artifact_checksum,
                import_page_revisions(job),
            ),
        )
        updated = import_jobs.record_inspection(
            job_id,
            preview,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "preview": preview,
                },
            ),
        )
        return {"job": import_job_view(updated), "preview": preview}

    def module_import_job_validate(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Validate a staged module and preview scene/progress impact before importing it."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module validation")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "validate"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"inspected", "validated", "failed"}:
            raise ValueError("module import job must be inspected before validation")
        preview = dict(job.inspection)
        diff = modules.diff_preview(
            campaign_id,
            source_key=str(job.payload.get("source_key") or job.artifact),
            preview=preview,
        )
        diff_ruling_requirements: list[dict[str, Any]] = []
        for impact in diff.get("progress_impact", []):
            if impact.get("action") != "needs_dm_review":
                continue
            reason = (
                "The active module revision removed the scene referenced by "
                f"progress scope {impact.get('scope_id')}; decide its source-backed remap."
            )
            requirement = _ruling_requirement(reason, "source_or_scene_fact")
            impact["ruling_requirement"] = requirement
            diff_ruling_requirements.append(
                {
                    "scope_id": impact.get("scope_id"),
                    "scene_id": impact.get("scene_id"),
                    **requirement,
                }
            )
        validation = {
            "valid": bool(preview.get("valid")),
            "errors": list(preview.get("errors") or []),
            "warnings": list(preview.get("warnings") or []),
            "preview": preview,
            "diff": diff,
            "ruling_requirements": diff_ruling_requirements,
        }
        updated = import_jobs.record_validation(
            job_id,
            validation,
            state="validated" if validation["valid"] else "failed",
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda result: {
                    "job": import_job_view(result),
                    "validation": validation,
                },
            ),
        )
        return {"job": import_job_view(updated), "validation": validation}

    def module_import_job_import(
        campaign_id: str,
        job_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Ingest a validated module inactive, preserving the current active module."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module import")
        job = require_import_job(campaign_id, job_id, "module")
        payload = {"job_id": job_id, "operation": "import"}
        scope = f"import-job:{campaign_id}:{job_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        if job.state not in {"validated", "imported"} or not job.validation.get("valid"):
            raise ValueError("module import job must pass validation before import")
        values = dict(job.payload)
        embedder, vectors = storage.dense_components()
        result = modules.ingest_path(
            campaign_id=campaign_id,
            path=storage.artifact_module_path(job.artifact),
            source_key=str(values.get("source_key") or job.artifact),
            title=str(values.get("title") or job.artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            embedder=embedder,
            vector_store=vectors,
            activate=False,
            logical_source_key=str(values.get("source_key") or job.artifact),
            **module_document_options(
                job.artifact_checksum,
                import_page_revisions(job),
            ),
        )
        updated = import_jobs.record_result(
            job_id,
            {**dict(job.result), "module_draft": asdict(result)},
            state="imported",
            module_id=result.module_id,
            expected_revision=job.revision,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda updated_job: {
                    "job": import_job_view(updated_job),
                    **asdict(result),
                },
            ),
        )
        return {"job": import_job_view(updated), **asdict(result)}

    def module_write(
        name: str, content: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, str]:
        """Write generated Markdown to the managed artifact directory before importing it."""
        if not principal_id:
            raise PermissionError("authenticated caller identity is required for module artifacts")
        path = storage.write_module(name, content)
        return {"artifact": path.name, "path": str(path)}

    def module_inspect(
        artifact: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any]:
        """Inspect a managed PDF/Markdown/text artifact before campaign import."""
        if not principal_id:
            raise PermissionError("authenticated caller identity is required for module artifacts")
        return modules.inspect_path(
            storage.artifact_module_path(artifact),
            parser=MarkdownModuleParser(profile=DndModuleProfile()),
            **module_document_options(),
        )

    def module_list(
        campaign_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> list[dict[str, Any]]:
        """List a campaign's imported modules."""
        membership = access.require_campaign(campaign_id, principal_id)
        rows = modules.list(campaign_id)
        if membership.role in CAMPAIGN_DM_ROLES:
            return rows
        return [
            {key: value for key, value in row.items() if key not in {"source_path", "metadata"}}
            for row in rows
        ]

    def module_index(
        campaign_id: str,
        module_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Return a stable scene index for scene selection and safe progression."""
        membership = access.require_campaign(campaign_id, principal_id)
        index = modules.scene_index(campaign_id, module_id=module_id)
        if membership.role in CAMPAIGN_DM_ROLES:
            return index
        return [
            item
            for item in index
            if item.get("visibility", "restricted") in PLAYER_MODULE_VISIBILITY_SCOPES
        ]

    @public_tool()
    def module_expand(
        chunk_id: str, principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID
    ) -> dict[str, Any]:
        """Read a complete module chunk after it was selected by search."""
        result = modules.expand(chunk_id)
        membership = access.require_campaign(result["campaign_id"], principal_id)
        visibility = result.get("scene", {}).get("visibility", "restricted")
        if membership.role in CAMPAIGN_DM_ROLES or visibility in PLAYER_MODULE_VISIBILITY_SCOPES:
            return result
        return {
            "chunk_id": result["chunk_id"],
            "campaign_id": result["campaign_id"],
            "redacted": True,
            "content": "[DM-only module content hidden]",
        }

    def module_assets(
        campaign_id: str,
        module_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        return modules.list_assets(campaign_id, module_id)

    def module_asset_attach(
        campaign_id: str,
        module_id: str,
        source_path: str,
        *,
        asset_kind: str,
        scene_id: str | None = None,
        location_key: str | None = None,
        title: str | None = None,
        metadata: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Attach an allowlisted image or support document to an imported module."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module asset attachment")
        kind = str(asset_kind).strip()
        if not kind or len(kind) > 80:
            raise ValueError("asset_kind must be a non-empty string of at most 80 characters")
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be an object")
        metadata_value = dict(metadata or {})
        modules.list_assets(campaign_id, module_id)
        if scene_id:
            scene = modules.read_scene(campaign_id, scene_id)
            if scene["module_id"] != module_id:
                raise ValueError("scene_id does not belong to module_id")
        staged = storage.stage_module_asset(module_id, source_path)
        payload = {
            "module_id": module_id,
            "source_checksum": staged["checksum"],
            "asset_kind": kind,
            "scene_id": scene_id,
            "location_key": location_key,
            "title": title,
            "metadata": metadata_value,
        }
        scope = f"module-asset-attach:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        asset_metadata = {
            **metadata_value,
            "kind": kind,
            "source_name": Path(source_path).name,
        }
        if title:
            asset_metadata["title"] = str(title)
        if scene_id:
            asset_metadata["scene_id"] = scene_id
        if location_key:
            asset_metadata["location_key"] = str(location_key)
        asset = modules.register_asset(
            campaign_id=campaign_id,
            module_id=module_id,
            source_path=staged["path"],
            media_type=staged["media_type"],
            checksum=staged["checksum"],
            metadata=asset_metadata,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda value: {
                    "campaign_id": campaign_id,
                    "module_id": module_id,
                    "asset": value,
                    "artifact": {
                        key: item for key, item in staged.items() if key not in {"path", "staged"}
                    },
                },
            ),
        )
        response = {
            "campaign_id": campaign_id,
            "module_id": module_id,
            "asset": asset,
            "artifact": {
                key: value for key, value in staged.items() if key not in {"path", "staged"}
            },
        }
        return response

    def module_pdf_asset(
        campaign_id: str,
        module_id: str,
        source_asset_id: str | None = None,
    ) -> dict[str, Any]:
        """Resolve the one checksum-bound PDF used by module page workflows."""

        assets = modules.list_assets(campaign_id, module_id)
        if source_asset_id:
            source_asset = modules.get_asset(campaign_id, source_asset_id)
            if source_asset["module_id"] != module_id:
                raise ValueError("source asset does not belong to module")
        else:
            candidates = [item for item in assets if item["media_type"] == "application/pdf"]
            if len(candidates) != 1:
                raise ValueError("source_asset_id is required unless the module has one PDF asset")
            source_asset = candidates[0]
        if source_asset["media_type"] != "application/pdf":
            raise ValueError("module page workflow requires a PDF source asset")
        if file_sha256(source_asset["source_path"]) != source_asset["checksum"]:
            raise RuntimeError("module PDF no longer matches its imported checksum")
        return source_asset

    def module_page_render(
        campaign_id: str,
        module_id: str,
        page_number: int,
        source_asset_id: str | None = None,
        scale: float = 1.5,
        include_ocr_text: bool = True,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> Any:
        """Render one imported PDF page as visual evidence for maps or handouts."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        source_asset = module_pdf_asset(campaign_id, module_id, source_asset_id)
        rendered = render_pdf_page(source_asset["source_path"], page_number, scale=scale)
        if rendered.source_checksum != source_asset["checksum"]:
            raise RuntimeError("module PDF no longer matches its imported checksum")
        if not isinstance(include_ocr_text, bool):
            raise ValueError("include_ocr_text must be a boolean")
        ocr_evidence = (
            local_ocr_page_evidence(
                source_asset["source_path"],
                page_number,
                scope="module",
            )
            if include_ocr_text
            else {"included": False}
        )
        target = storage.store_rendered_module_page(
            module_id=module_id,
            source_checksum=rendered.source_checksum,
            page_number=rendered.page_number,
            scale=rendered.scale,
            checksum=rendered.checksum,
            content=rendered.content,
        )
        asset = modules.register_asset(
            campaign_id=campaign_id,
            module_id=module_id,
            source_path=str(target),
            media_type=rendered.media_type,
            checksum=rendered.checksum,
            metadata={
                "kind": "rendered_page",
                "derived_from_asset_id": source_asset["id"],
                "source_checksum": rendered.source_checksum,
                "source_page": rendered.page_number,
                "page_count": rendered.page_count,
                "width": rendered.width,
                "height": rendered.height,
                "scale": rendered.scale,
            },
        )
        return [
            {
                "campaign_id": campaign_id,
                "module_id": module_id,
                "asset": asset,
                "source_asset_id": source_asset["id"],
                "ocr": ocr_evidence,
            },
            Image(path=target),
        ]

    def module_statblock_ocr_recover(
        campaign_id: str,
        module_id: str,
        scene_id: str,
        content_key: str,
        name: str,
        page_number: int,
        source_asset_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
        agent_fill: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Recover and review one module statblock without requiring model vision."""

        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        campaign_edition = campaign_rules_edition(campaign_id)
        if campaign_edition != "2014":
            raise ValueError(
                "layout OCR statblock recovery currently supports only D&D 2014; "
                "submit an evidence-bound 2024 transcription through module_draft(edit)"
            )
        if not idempotency_key:
            raise ValueError("idempotency_key is required for OCR statblock recovery")
        target_name = str(name or "").strip()
        if not 2 <= len(target_name) <= 200:
            raise ValueError("name must contain 2 to 200 characters")
        if isinstance(page_number, bool) or not isinstance(page_number, int) or page_number < 1:
            raise ValueError("page_number must be a positive integer")
        scene = modules.read_scene(campaign_id, scene_id)
        if str(scene.get("module_id") or "") != module_id:
            raise ValueError("OCR statblock recovery scene must belong to the module")
        source_asset = module_pdf_asset(campaign_id, module_id, source_asset_id)
        provider = storage.module_ocr_provider()
        if provider is None or not hasattr(provider, "extract_layout"):
            raise RuntimeError("layout OCR recovery requires the configured RapidOCR provider")

        request_payload = {
            "module_id": module_id,
            "scene_id": scene_id,
            "content_key": content_key,
            "name": target_name,
            "page_number": page_number,
            "source_asset_id": source_asset["id"],
            "source_asset_checksum": source_asset["checksum"],
            "agent_fill": deepcopy(agent_fill),
        }
        scope = f"module-statblock-ocr-recover:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay

        recovered_result = recover_pdf_statblock_layout(
            source_path=source_asset["source_path"],
            target_name=target_name,
            candidate_pages=[page_number],
            provider=provider,
        )
        recovered_page = int(recovered_result["page_number"])
        recovered = dict(recovered_result["recovery"])
        normalized_content = str(recovered["normalized_content"])
        parsed = parse_2014_statblock(
            normalized_content,
            source_key=f"module-review:{module_id}:{content_key}",
            name=None,
        )
        agent_fill_requirements = statblock_agent_fill_requirements(parsed.sheet)
        if agent_fill_requirements["required"] and agent_fill is None:
            response = {
                "campaign_id": campaign_id,
                "module_id": module_id,
                "scene_id": scene_id,
                "source_asset_id": source_asset["id"],
                **{key: value for key, value in recovered_result.items() if key != "observation"},
                "review": None,
                "requires_agent_fill": True,
                "validation": {
                    "name": parsed.name,
                    "challenge_rating": parsed.challenge_rating,
                    "experience_points": parsed.experience_points,
                    **statblock_settlement(parsed.warnings),
                    "agent_fill": None,
                    "resolved_warnings": [],
                    "agent_fill_requirements": agent_fill_requirements,
                },
            }
            return remember_idempotent(
                scope,
                idempotency_key,
                request_payload,
                response,
                campaign_id=campaign_id,
            )
        reviewed = module_content_review(
            campaign_id,
            module_id,
            scene_id,
            content_key,
            normalized_content,
            str(recovered_result["observation"]),
            source_asset_id=str(source_asset["id"]),
            page_number=recovered_page,
            content_kind="dnd5e_2014_statblock",
            metadata={
                "text_layout_recovery": {
                    "profile": (
                        f"rapidocr-layout-v{int(dict(recovered['evidence'])['recovery_version'])}"
                    ),
                    "provider": str(recovered_result["provider"]),
                    "corroboration_mode": str(recovered_result["corroboration_mode"]),
                    "corroboration_scales": list(recovered_result["corroboration_scales"]),
                    "text_only": True,
                }
            },
            principal_id=principal_id,
            idempotency_key=idempotency_key,
            agent_fill=agent_fill,
        )
        response = {
            "campaign_id": campaign_id,
            "module_id": module_id,
            "scene_id": scene_id,
            "source_asset_id": source_asset["id"],
            **{key: value for key, value in recovered_result.items() if key != "observation"},
            "requires_agent_fill": False,
            **reviewed,
        }
        return remember_idempotent(
            scope,
            idempotency_key,
            request_payload,
            response,
            campaign_id=campaign_id,
        )

    def module_content_review(
        campaign_id: str,
        module_id: str,
        scene_id: str,
        content_key: str,
        normalized_content: str,
        observation: str,
        source_asset_id: str | None = None,
        page_number: int | None = None,
        source_chunk_ids: list[str] | None = None,
        content_kind: Literal[
            "dnd5e_2014_statblock",
            "dnd5e_2024_statblock",
        ] = "dnd5e_2014_statblock",
        metadata: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
        agent_fill: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Validate an executable transcription and optional Agent semantic fill."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not idempotency_key:
            raise ValueError("idempotency_key is required for module content review")
        campaign_edition = campaign_rules_edition(campaign_id)
        expected_content_kind = statblock_content_kind(campaign_edition)
        if content_kind != expected_content_kind:
            raise ValueError(f"content_kind must be {expected_content_kind} for this campaign")
        parsed = parse_edition_statblock(
            normalized_content,
            edition=campaign_edition,
            source_key=f"module-review:{module_id}:{content_key}",
            name=None,
        )
        agent_fill_requirements = statblock_agent_fill_requirements(parsed.sheet)
        if agent_fill_requirements["required"] and agent_fill is None:
            return {
                "review": None,
                "requires_agent_fill": True,
                "validation": {
                    "name": parsed.name,
                    "challenge_rating": parsed.challenge_rating,
                    "experience_points": parsed.experience_points,
                    **statblock_settlement(parsed.warnings),
                    "agent_fill": None,
                    "resolved_warnings": [],
                    "agent_fill_requirements": agent_fill_requirements,
                },
            }
        agent_fill_requirements = require_complete_statblock_agent_fill(
            parsed.sheet,
            agent_fill,
        )
        agent_fill_evidence = reviewed_statblock_fill_evidence(
            campaign_id,
            agent_fill,
            module_id=module_id,
            page_number=page_number,
        )
        metadata_value = deepcopy(dict(metadata or {}))
        if "agent_statblock_fill" in metadata_value:
            raise ValueError("metadata.agent_statblock_fill is reserved; use payload.agent_fill")
        filled = (
            apply_reviewed_statblock_fill(parsed.sheet, agent_fill)
            if agent_fill is not None
            else None
        )
        if filled is not None:
            metadata_value["agent_statblock_fill"] = filled["fill"]
            metadata_value["agent_statblock_fill_evidence"] = agent_fill_evidence
        resolved_warnings = set((filled or {}).get("resolved_warnings") or [])
        retained_warnings = [
            warning for warning in parsed.warnings if warning not in resolved_warnings
        ]
        retained_warnings = list(
            dict.fromkeys(
                [
                    *retained_warnings,
                    *((filled or {}).get("added_warnings") or []),
                ]
            )
        )
        payload = {
            "module_id": module_id,
            "scene_id": scene_id,
            "content_key": content_key,
            "content_kind": content_kind,
            "normalized_content": normalized_content,
            "source_asset_id": source_asset_id,
            "page_number": page_number,
            "source_chunk_ids": source_chunk_ids,
            "observation": observation,
            "metadata": metadata_value,
            "agent_fill": (filled or {}).get("fill"),
        }
        scope = f"module-content-review:{campaign_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, payload)
        if replay is not None:
            return replay
        review = modules.review_content(
            campaign_id=campaign_id,
            module_id=module_id,
            scene_id=scene_id,
            content_key=content_key,
            content_kind=content_kind,
            normalized_content=normalized_content,
            source_asset_id=source_asset_id,
            page_number=page_number,
            source_chunk_ids=source_chunk_ids,
            reviewer=principal_id,
            observation=observation,
            metadata=metadata_value,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=payload,
                response=lambda value: {
                    "review": value,
                    "validation": {
                        "name": parsed.name,
                        "challenge_rating": parsed.challenge_rating,
                        "experience_points": parsed.experience_points,
                        **statblock_settlement(retained_warnings),
                        "agent_fill": (filled or {}).get("fill"),
                        "resolved_warnings": sorted(resolved_warnings),
                        "agent_fill_requirements": agent_fill_requirements,
                    },
                },
            ),
        )
        response = {
            "review": review,
            "validation": {
                "name": parsed.name,
                "challenge_rating": parsed.challenge_rating,
                "experience_points": parsed.experience_points,
                **statblock_settlement(retained_warnings),
                "agent_fill": (filled or {}).get("fill"),
                "resolved_warnings": sorted(resolved_warnings),
                "agent_fill_requirements": agent_fill_requirements,
            },
        }
        return response

    def module_content_candidates(
        campaign_id: str,
        module_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Recover review-only statblock candidates from imported text chunks."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        module = next(
            (
                item
                for item in modules.list(campaign_id, include_retired=True)
                if str(item.get("id")) == module_id
            ),
            None,
        )
        if module is None:
            raise LookupError(module_id)
        chunks = modules.list_chunks(campaign_id, module_id)
        campaign_edition = campaign_rules_edition(campaign_id)
        candidates = module_statblock_review_candidates(
            chunks,
            source_title=str(module.get("title") or ""),
        )
        for candidate in candidates:
            local_candidate_id = str(candidate["id"])
            candidate["id"] = (
                "candidate:"
                + hashlib.sha256(
                    f"{module_id}\x1f{local_candidate_id}".encode("utf-8")
                ).hexdigest()[:20]
            )
            candidate["review_tool"] = "module_draft"
            candidate["review_action"] = "edit"
            candidate["review_operation"] = "content"
            candidate["module_id"] = module_id
            candidate["content_kind"] = statblock_content_kind(campaign_edition)
            if candidate.get("execution_state") == "review_ready":
                parsed_candidate = parse_edition_statblock(
                    str(candidate.get("normalized_content") or ""),
                    edition=campaign_edition,
                    source_key=f"module-candidate:{candidate['id']}",
                    name=None,
                )
                candidate["agent_fill_requirements"] = statblock_agent_fill_requirements(
                    parsed_candidate.sheet
                )
            if candidate.get("review_status") == "manual_review_required":
                candidate["ruling_requirement"] = _ruling_requirement(
                    str(candidate.get("review_error") or "statblock source needs review"),
                    "missing_or_conflicting_source_review",
                )
            elif candidate.get("execution_state") == "review_ready":
                candidate["ruling_requirement"] = _ruling_requirement(
                    "Review the normalized statblock against its exact module chunks.",
                    "source_or_scene_fact",
                )
            if len(candidate.get("source_scene_ids") or []) != 1:
                candidate["execution_state"] = "blocked"
                candidate["review_status"] = "manual_review_required"
                candidate["review_error"] = (
                    "statblock candidate source chunks must belong to one scene"
                )
                candidate["ruling_requirement"] = _ruling_requirement(
                    candidate["review_error"],
                    "missing_or_conflicting_source_review",
                )
                continue
            candidate["scene_id"] = candidate["source_scene_ids"][0]
        return candidates

    def module_read_scene(
        campaign_id: str,
        scene_id: str,
        scope_id: str = "party",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read one full scene, including its structured rooms and visibility metadata."""
        membership = access.require_campaign(campaign_id, principal_id)
        resolved_scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
        result = modules.read_scene(campaign_id, scene_id, scope_id=resolved_scope_id)
        if membership.role in CAMPAIGN_DM_ROLES:
            return result
        return player_module_scene_view(campaign_id, result)

    def module_scene_preflight(
        campaign_id: str,
        scene_id: str,
        participant_manifest: dict[str, Any],
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Validate source-grounded combatants and reserves before an encounter starts."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if not isinstance(participant_manifest, dict):
            raise ValueError("participant_manifest must be an object")
        manifest_fields = {"schema_version", "groups", "notes"}
        unknown_manifest = set(participant_manifest) - manifest_fields
        if unknown_manifest:
            raise ValueError(
                f"unsupported participant manifest fields: {sorted(unknown_manifest)}; "
                f"allowed fields: {sorted(manifest_fields)}"
            )
        schema_version = participant_manifest.get("schema_version", 1)
        if schema_version != 1:
            raise ValueError("participant_manifest schema_version must be 1")
        groups = participant_manifest.get("groups")
        if not isinstance(groups, list):
            raise ValueError("participant_manifest.groups must be a list")
        encounter_scene = modules.read_scene(campaign_id, scene_id)
        module_id = str(encounter_scene["module_id"])
        normalized_groups: list[dict[str, Any]] = []
        group_keys: set[str] = set()
        used_actor_ids: set[str] = set()
        initial_actor_ids: list[str] = []
        reinforcement_actor_ids: list[str] = []
        optional_actor_ids: list[str] = []

        for index, raw_group in enumerate(groups):
            if not isinstance(raw_group, dict):
                raise ValueError("each participant manifest group must be an object")
            allowed = {
                "key",
                "label",
                "role",
                "required_count",
                "actor_ids",
                "source_scene_id",
                "source_excerpt",
            }
            unknown = set(raw_group) - allowed
            if unknown:
                raise ValueError(
                    f"unsupported participant group fields: {sorted(unknown)}; "
                    f"allowed fields: {sorted(allowed)}"
                )
            key = str(raw_group.get("key") or "").strip()
            if not key or key in group_keys:
                raise ValueError("participant manifest group keys must be non-empty and unique")
            group_keys.add(key)
            role = str(raw_group.get("role") or "").strip()
            if role not in {"combatant", "reinforcement", "optional"}:
                raise ValueError(
                    "participant manifest role must be combatant, reinforcement, or optional"
                )
            required_count = raw_group.get("required_count")
            if (
                isinstance(required_count, bool)
                or not isinstance(required_count, int)
                or required_count < 1
            ):
                raise ValueError("participant group required_count must be a positive integer")
            actor_ids_value = raw_group.get("actor_ids", [])
            if not isinstance(actor_ids_value, list):
                raise ValueError("participant group actor_ids must be a list")
            actor_ids = [str(item).strip() for item in actor_ids_value]
            if any(not item for item in actor_ids) or len(actor_ids) != len(set(actor_ids)):
                raise ValueError("participant group actor_ids must be non-empty and unique")
            overlap = used_actor_ids & set(actor_ids)
            if overlap:
                raise ValueError(
                    "actors cannot appear in multiple participant groups: "
                    + ", ".join(sorted(overlap))
                )
            if len(actor_ids) > required_count:
                raise ValueError(f"participant group {key!r} exceeds required_count")
            used_actor_ids.update(actor_ids)

            source_scene_id = str(raw_group.get("source_scene_id") or scene_id)
            source_scene = (
                encounter_scene
                if source_scene_id == scene_id
                else modules.read_scene(campaign_id, source_scene_id)
            )
            if str(source_scene.get("module_id")) != module_id:
                raise ValueError("participant evidence must belong to the encounter module")
            source_excerpt = " ".join(str(raw_group.get("source_excerpt") or "").split()).strip()
            if len(source_excerpt) < 8 or len(source_excerpt) > 4000:
                raise ValueError("participant source_excerpt must contain 8 to 4000 characters")
            normalized_excerpt = _normalize_source_evidence_text(source_excerpt)
            normalized_content = _normalize_source_evidence_text(source_scene.get("content"))
            if normalized_excerpt not in normalized_content:
                raise ValueError(
                    f"participant group {key!r} source_excerpt is not present in its scene"
                )

            actor_views = []
            for actor_id in actor_ids:
                actor = require_campaign_actor(campaign_id, actor_id)
                actor_views.append(
                    {
                        "id": actor.id,
                        "name": actor.name,
                        "character_type": actor.character_type,
                        "combat_card": combat_card_analysis(actor),
                    }
                )
            invalid_actor_ids = [
                str(item["id"])
                for item in actor_views
                if not dict(item.get("combat_card") or {}).get("card_valid", False)
            ]
            missing_count = required_count - len(actor_ids)
            blocking = role != "optional"
            normalized_groups.append(
                {
                    "key": key,
                    "label": str(raw_group.get("label") or key).strip(),
                    "role": role,
                    "required_count": required_count,
                    "actor_ids": actor_ids,
                    "actors": actor_views,
                    "missing_count": missing_count,
                    "invalid_count": len(invalid_actor_ids),
                    "invalid_actor_ids": invalid_actor_ids,
                    "blocking": blocking,
                    "source_scene_id": source_scene_id,
                    "source_excerpt": source_excerpt,
                    "ordinal": index,
                }
            )
            target = (
                initial_actor_ids
                if role == "combatant"
                else reinforcement_actor_ids
                if role == "reinforcement"
                else optional_actor_ids
            )
            target.extend(actor_ids)

        ready = all(
            not item["blocking"] or (item["missing_count"] == 0 and item["invalid_count"] == 0)
            for item in normalized_groups
        )
        normalized_manifest = {
            "schema_version": 1,
            "scene_id": scene_id,
            "module_id": module_id,
            "groups": normalized_groups,
            "notes": str(participant_manifest.get("notes") or "").strip(),
        }
        return {
            **normalized_manifest,
            "checksum": request_hash(normalized_manifest),
            "ready": ready,
            "initial_actor_ids": initial_actor_ids,
            "reinforcement_actor_ids": reinforcement_actor_ids,
            "optional_actor_ids": optional_actor_ids,
        }

    def module_current(
        campaign_id: str,
        scope_id: str = "party",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any] | None:
        """Read the current scene for party, group, or player scope with party fallback."""
        membership = access.require_campaign(campaign_id, principal_id)
        resolved_scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
        result = modules.current_scene(campaign_id, scope_id=resolved_scope_id)
        if result is None or membership.role in CAMPAIGN_DM_ROLES:
            return result
        return player_module_scene_view(campaign_id, result)

    def module_progress_index(
        campaign_id: str,
        scope_id: str = "party",
        module_id: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Project ordered scene progress without adding another public MCP tool."""
        membership = access.require_campaign(campaign_id, principal_id)
        resolved_scope_id = readable_scene_scope(campaign_id, scope_id, principal_id)
        result = modules.scene_progress_index(
            campaign_id,
            scope_id=resolved_scope_id,
            module_id=module_id,
        )
        if membership.role in CAMPAIGN_DM_ROLES:
            return result
        visible_scene_ids = {
            item["scene_id"] for item in module_index(campaign_id, module_id, principal_id)
        }
        return [item for item in result if item["scene_id"] in visible_scene_ids]

    @public_tool()
    def module_set_progress(
        campaign_id: str,
        scene_id: str,
        scope_id: str = "party",
        status: str | None = None,
        progress: int | None = None,
        state: dict[str, Any] | None = None,
        current_room: str | None = None,
        current_location_key: str | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_state_version: int | None = None,
        idempotency_key: str | None = None,
        spatial_review: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Persist scoped progress or a source-backed visual atlas review."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        if expected_state_version is None or not idempotency_key:
            raise ValueError(
                "expected_state_version and idempotency_key are required for scene progress"
            )
        validate_embedded_module_source_refs(
            campaign_id,
            state or {},
            field="state",
        )
        validate_embedded_module_source_refs(
            campaign_id,
            spatial_review or {},
            field="spatial_review",
        )
        branch_id = current_branch_id(campaign_id)
        require_no_active_npc_conversation(
            campaign_id,
            branch_id=branch_id,
            operation="changing scene progress",
        )
        request_payload = {
            "scene_id": scene_id,
            "scope_id": scope_id,
            "status": status,
            "progress": progress,
            "state": state,
            "current_room": current_room,
            "current_location_key": current_location_key,
            "expected_state_version": expected_state_version,
            "branch_id": branch_id,
            "spatial_review": spatial_review,
        }
        scope = f"module-progress:{campaign_id}:{branch_id}:{principal_id}:{scope_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        response = modules.set_scene_progress(
            campaign_id=campaign_id,
            scene_id=scene_id,
            scope_id=scope_id,
            status=status,
            progress=progress,
            state=state,
            current_room=current_room,
            current_location_key=current_location_key,
            expected_state_version=expected_state_version,
            spatial_review=(
                {
                    **dict(spatial_review),
                    "reviewer": principal_id,
                    "branch_id": branch_id,
                }
                if spatial_review is not None
                else None
            ),
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=lambda result: result,
            ),
        )
        return response

    @public_tool()
    def module_search(
        campaign_id: str,
        query: str,
        top_k: int = 8,
        module_ids: list[str] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Search adventure content, optionally scoped to exact active module revisions."""
        membership = access.require_campaign(campaign_id, principal_id)
        embedder, vectors = storage.dense_components()
        hits = modules.search(
            campaign_id=campaign_id,
            query=query,
            query_hints=DND5E_QUERY_HINTS,
            top_k=top_k,
            module_ids=module_ids,
            embedder=embedder,
            vector_store=vectors,
        )
        if membership.role in CAMPAIGN_DM_ROLES:
            return [asdict(hit) for hit in hits]
        return [
            asdict(hit)
            for hit in hits
            if hit.metadata.get("visibility", "restricted") in PLAYER_MODULE_VISIBILITY_SCOPES
        ]

    def campaign_rule_source_ids(campaign_id: str) -> set[str]:
        """Resolve the indexed sources visible to this campaign and branch."""

        profile = rule_profiles.get(campaign_id)
        if profile is None:
            raise RulesetUnavailableError("campaign has no authoritative rule profile")
        bundled_root = config.dnd_skills_dir / "full" / "skills" / "dnd-dm" / "srd"
        bundled_identities = (
            {
                (source.source_key, source.checksum)
                for source in build_bundled_rule_sources(bundled_root)
            }
            if bundled_root.is_dir()
            else set()
        )
        allowed = {
            str(source["id"])
            for source in rules.sources(system_id=DND5E.id)
            if (str(source.get("source_key") or ""), str(source.get("checksum") or ""))
            in bundled_identities
            and str(source.get("edition") or "") == str(profile.edition)
        }

        def collect(value: Any) -> None:
            if isinstance(value, dict):
                source_id = value.get("source_id")
                if isinstance(source_id, str) and source_id:
                    allowed.add(source_id)
                for child in value.values():
                    collect(child)
            elif isinstance(value, list):
                for child in value:
                    collect(child)

        effective = rule_packs.effective_ruleset(campaign_id)
        for locked in effective.lock:
            version = rule_packs.get_version(
                str(locked["pack_id"]),
                str(locked["version"]),
            )
            collect(asdict(version))

        if authoritative_phase(campaign_id) == PROFILE_LOBBY:
            allowed.update(
                str(job.source_id)
                for job in import_jobs.list(campaign_id, kind="rulebook")
                if job.source_id
            )
        return allowed

    @public_tool()
    def rule_search(
        campaign_id: str,
        query: str,
        filters: Annotated[
            dict[str, Any] | None,
            Field(
                description=(
                    "Optional exact evidence-backed filters: edition, locale, publications, "
                    "source_ids, source_keys, or positive page. Omit for the first lookup; "
                    "an empty object means unfiltered."
                )
            ),
        ] = None,
        top_k: int = 8,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> list[dict[str, Any]]:
        """Search rules visible to the campaign; first lookup needs only id and query."""
        access.require_campaign(campaign_id, principal_id)
        if not str(query or "").strip():
            raise ValueError("rule_search query is required")
        if not 1 <= top_k <= 200:
            raise ValueError("rule_search top_k must be between 1 and 200")
        filter_data = dict(filters or {})
        allowed_filter_fields = {
            "edition",
            "locale",
            "publications",
            "source_ids",
            "source_keys",
            "page",
        }
        if unknown_fields := sorted(set(filter_data) - allowed_filter_fields):
            raise ValueError(
                "rule_search filters contain unsupported fields: " + ", ".join(unknown_fields)
            )

        def optional_text(field_name: str) -> str | None:
            value = filter_data.get(field_name)
            if value is None:
                return None
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"rule_search filters.{field_name} must be a non-empty string")
            return value.strip()

        def optional_text_list(field_name: str) -> list[str] | None:
            value = filter_data.get(field_name)
            if value is None:
                return None
            if (
                not isinstance(value, list)
                or not value
                or any(not isinstance(item, str) or not item.strip() for item in value)
            ):
                raise ValueError(
                    f"rule_search filters.{field_name} must be a non-empty string list"
                )
            return [item.strip() for item in value]

        edition = optional_text("edition")
        locale = optional_text("locale")
        if locale is None:
            profile = rule_profiles.get(campaign_id)
            if profile is None:
                raise RulesetUnavailableError("campaign has no authoritative rule profile")
            locale = str(profile.locale)
        publications = optional_text_list("publications")
        source_ids = optional_text_list("source_ids")
        source_keys = optional_text_list("source_keys")
        page_value = filter_data.get("page")
        if page_value is not None and (
            not isinstance(page_value, int) or isinstance(page_value, bool) or page_value < 1
        ):
            raise ValueError("rule_search filters.page must be a positive integer")
        page = int(page_value) if page_value is not None else None
        allowed_source_ids = campaign_rule_source_ids(campaign_id)
        allowed_sources = {
            str(source["id"]): source
            for source in rules.sources(system_id=DND5E.id)
            if str(source["id"]) in allowed_source_ids
        }
        if source_ids:
            requested = {str(item) for item in source_ids}
            if unknown := sorted(requested - allowed_source_ids):
                raise ValueError(
                    "rule_search source_ids are outside the current campaign ruleset: "
                    + ", ".join(unknown)
                )
            allowed_source_ids &= requested
        allowed_publications = {
            str(source.get("publication_id") or "")
            for source in allowed_sources.values()
            if str(source.get("publication_id") or "")
        }
        if publications:
            requested_publications = {str(item) for item in publications}
            if unknown := sorted(requested_publications - allowed_publications):
                raise ValueError(
                    "rule_search publications are outside the current campaign ruleset: "
                    + ", ".join(unknown)
                    + "; omit publications unless exact source evidence supplies one"
                )
        allowed_source_keys = {
            str(source.get("source_key") or "")
            for source in allowed_sources.values()
            if str(source.get("source_key") or "")
        }
        if source_keys:
            requested_source_keys = {str(item) for item in source_keys}
            if unknown := sorted(requested_source_keys - allowed_source_keys):
                raise ValueError(
                    "rule_search source_keys are outside the current campaign ruleset: "
                    + ", ".join(unknown)
                    + "; omit source_keys unless exact source evidence supplies one"
                )
        if not allowed_source_ids:
            return []
        embedder, vectors = storage.dense_components()
        hits = rules.search(
            system_id=DND5E.id,
            query=query,
            query_hints=DND5E_QUERY_HINTS,
            edition=edition,
            locale=locale,
            publications=publications,
            source_ids=sorted(allowed_source_ids),
            source_keys=source_keys,
            top_k=top_k,
            embedder=embedder,
            vector_store=vectors,
        )
        values = [asdict(hit) for hit in hits]
        if page is not None:
            values = [
                item
                for item in values
                if int(dict(item.get("metadata") or {}).get("page_start") or 0)
                <= page
                <= int(dict(item.get("metadata") or {}).get("page_end") or 0)
            ]
        return values

    @public_tool()
    def rule_expand(
        campaign_id: str,
        chunk_id: str,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read one indexed chunk only when its source belongs to this campaign ruleset."""
        access.require_campaign(campaign_id, principal_id)
        expanded = rules.expand(chunk_id)
        source_id = str(dict(expanded.get("source") or {}).get("id") or "")
        if source_id not in campaign_rule_source_ids(campaign_id):
            raise PermissionError("rule chunk is outside the current campaign ruleset")
        return expanded

