    @public_tool()
    def campaign_query(
        view: Literal["list", "get", "party", "resume", "binding"] = "list",
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read campaigns, party state, or one complete resume bundle."""
        data = facade_payload(payload)
        if view == "binding":
            data = facade_payload(payload)
            campaign_id = required(data, "campaign_id")
            result = authoritative_host_context_binding(
                campaign_id,
                principal_id,
            )
            if result is None:
                raise LookupError("campaign has no active branch context")
        elif view == "resume":
            data = facade_payload(payload)
            campaign_id = required(data, "campaign_id")
            membership = access.require_campaign(campaign_id, principal_id)
            branch_values = branch_list(campaign_id, principal_id)
            current_branch = next(
                (item for item in branch_values if item.get("is_current")),
                None,
            )
            manifest_result = None
            if membership.role in CAMPAIGN_DM_ROLES:
                try:
                    manifest_result = playthrough_manifest(
                        campaign_id,
                        "get",
                        principal_id=principal_id,
                    )
                except LookupError:
                    manifest_result = None
            context = continuity_context(
                campaign_id,
                query=str(data.get("query") or ""),
                actor_id=data.get("actor_id"),
                scope_id=str(data.get("scope_id") or "party"),
                audience=str(data.get("audience") or "dm"),
                branch_id=(str(current_branch["id"]) if current_branch is not None else None),
                limit=int(data.get("limit", 8)),
                budget_chars=int(data.get("budget_chars", 12_000)),
                related_refs=data.get("related_refs"),
                principal_id=principal_id,
            )
            result = {
                "campaign": campaign_get(campaign_id, principal_id),
                "branches": branch_values,
                "current_branch": current_branch,
                "manifest": manifest_result,
                "current_scene": module_current(
                    campaign_id,
                    scope_id=str(data.get("scope_id") or "party"),
                    principal_id=principal_id,
                ),
                "continuity": context,
                "host_context_binding": context["host_context_binding"],
                "resume_invariants": {
                    "discard_pre_restore_context": True,
                    "context_receipt_revision": context["context_receipt"]["campaign_revision"],
                    "reuse_bound_exposure_after_restore": True,
                    "refresh_tools_after_phase_or_checkout_change": True,
                },
            }
        elif view == "get":
            result = campaign_get(required(data, "campaign_id"), principal_id)
        elif view == "party":
            result = party_show(required(data, "campaign_id"), principal_id)
        else:
            result = campaign_list(data.get("status"), principal_id)
        return facade_result(view, result)

    @public_tool()
    def campaign_change(
        campaign_id: str,
        payload: dict[str, Any],
        action: Literal[
            "update",
            "clock_set",
            "clock_advance",
            "party_rest",
            "stable_recovery",
            "effect_add",
            "effect_remove",
            "advancement_configure",
            "experience_award",
            "loot_acquire",
            "currency_spend",
            "item_spend",
            "consumable_use",
        ] = "update",
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Update campaign state, advancement, clock, or structured campaign-space effects."""
        action_contracts: dict[str, tuple[set[str], tuple[str, ...]]] = {
            "update": (
                {"name", "status", "description", "settings", "state"},
                (),
            ),
            "clock_set": (
                {"day", "hour", "minute", "label"},
                ("day",),
            ),
            "clock_advance": (
                {
                    "period",
                    "count",
                    "expected_elapsed_ticks",
                },
                ("period",),
            ),
            "party_rest": (
                {"members", "duration_minutes", "rest_type"},
                ("members",),
            ),
            "stable_recovery": (
                {"members", "resting_members"},
                ("members",),
            ),
            "effect_add": ({"effect"}, ("effect",)),
            "effect_remove": ({"effect_id", "reason"}, ("effect_id",)),
            "advancement_configure": ({"mode"}, ("mode",)),
            "experience_award": (
                {"awards", "reason", "source_ref"},
                ("awards", "reason", "source_ref"),
            ),
            "loot_acquire": (
                {"acquisition_id", "coins", "items", "reason", "source_ref"},
                ("acquisition_id", "reason", "source_ref"),
            ),
            "currency_spend": (
                {"spend_id", "coins", "reason", "source_ref", "rule_ref"},
                ("spend_id", "coins", "reason", "source_ref", "rule_ref"),
            ),
            "item_spend": (
                {
                    "spend_id",
                    "item_id",
                    "quantity",
                    "reason",
                    "source_ref",
                    "character_id",
                    "expected_character_revision",
                },
                ("spend_id", "item_id", "quantity", "reason", "source_ref"),
            ),
            "consumable_use": (
                {
                    "use_id",
                    "item_id",
                    "target_character_id",
                    "expected_character_revision",
                    "reason",
                },
                (
                    "use_id",
                    "item_id",
                    "target_character_id",
                    "expected_character_revision",
                    "reason",
                ),
            ),
        }
        if action not in action_contracts:
            raise ValueError(f"unsupported campaign_change action: {action}")
        allowed_fields, required_fields = action_contracts[action]
        data = facade_payload(payload)
        if action == "clock_set":
            result = campaign_clock_set_impl(
                campaign_id,
                required(data, "day"),
                data.get("hour", 0),
                data.get("minute", 0),
                data.get("label", ""),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "clock_advance":
            result = campaign_advance_effects_impl(
                campaign_id,
                required(data, "period"),
                data.get("count", 1),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
                data.get("expected_elapsed_ticks"),
            )
        elif action == "party_rest":
            result = campaign_party_rest(
                campaign_id=campaign_id,
                members=required(data, "members"),
                duration_minutes=data.get(
                    "duration_minutes",
                    LONG_REST_MINIMUM_MINUTES,
                ),
                rest_type=data.get("rest_type", "long_rest"),
                principal_id=principal_id,
                expected_revision=expected_revision,
                branch_id=branch_id,
                idempotency_key=idempotency_key,
            )
        elif action == "stable_recovery":
            result = campaign_stable_recovery(
                campaign_id=campaign_id,
                members=required(data, "members"),
                resting_members=data.get("resting_members"),
                principal_id=principal_id,
                expected_revision=expected_revision,
                branch_id=branch_id,
                idempotency_key=idempotency_key,
            )
        elif action in {"effect_add", "effect_remove"}:
            result = campaign_world_effect_change(
                campaign_id,
                action,
                data,
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "advancement_configure":
            result = campaign_advancement_configure(
                campaign_id,
                required(data, "mode"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "experience_award":
            result = campaign_experience_award(
                campaign_id,
                required(data, "awards"),
                required(data, "reason"),
                required(data, "source_ref"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "loot_acquire":
            result = campaign_loot_acquire(
                campaign_id,
                required(data, "acquisition_id"),
                data.get("coins") or {},
                data.get("items") or [],
                required(data, "reason"),
                required(data, "source_ref"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "currency_spend":
            result = campaign_currency_spend(
                campaign_id,
                required(data, "spend_id"),
                required(data, "coins"),
                required(data, "reason"),
                required(data, "source_ref"),
                required(data, "rule_ref"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "item_spend":
            result = campaign_item_spend(
                campaign_id,
                required(data, "spend_id"),
                required(data, "item_id"),
                required(data, "quantity"),
                required(data, "reason"),
                required(data, "source_ref"),
                data.get("character_id"),
                data.get("expected_character_revision"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "consumable_use":
            result = campaign_consumable_use(
                campaign_id,
                required(data, "use_id"),
                required(data, "item_id"),
                required(data, "target_character_id"),
                required(data, "expected_character_revision"),
                required(data, "reason"),
                principal_id,
                expected_revision,
                branch_id,
                idempotency_key,
            )
        elif action == "update":
            result = campaign_update(
                campaign_id,
                data.get("name"),
                data.get("status"),
                data.get("description"),
                data.get("settings"),
                data.get("state"),
                principal_id,
                expected_revision,
                idempotency_key,
            )
        else:  # pragma: no cover - guarded by action_contracts above
            raise ValueError(f"unsupported campaign_change action: {action}")
        return facade_result(action, result)

    def playthrough_runtime_projection(
        campaign_id: str,
        manifest: dict[str, Any],
    ) -> dict[str, Any]:
        campaign = campaigns.get(campaign_id)
        active_branch = branches.current(campaign_id)
        snapshot_nodes = [
            {
                "id": item.id,
                "parent_id": item.parent_id or "",
                "branch_id": item.branch_id or active_branch.id,
                "slot": item.slot,
                "label": item.label,
                "checksum": item.checksum,
                "is_head": item.is_head,
            }
            for item in snapshots.list(campaign_id)
        ]
        stream = dict(campaign.state.get("random_stream") or {})

        def actor_projection(member: dict[str, Any]) -> dict[str, Any]:
            actor = characters.get(str(member["actor_id"]))
            if actor.campaign_id != campaign_id:
                raise ValueError(f"playthrough actor {actor.id!r} does not belong to this campaign")
            sheet = validate_character_sheet(actor.sheet)
            progression = dict(sheet["progression"])
            hp = dict(sheet["combat"]["hp"])
            effective_hp = dict(derive_character_sheet(sheet)["hit_points"])
            conditions = {str(item) for item in sheet.get("conditions") or []}
            narrative_status = str(member["status"])
            status = (
                "dead"
                if "dead" in conditions
                else "active"
                if narrative_status == "dead"
                else narrative_status
            )
            combat = dict(sheet["combat"])
            spellcasting = dict(sheet["spellcasting"])
            resources = {
                "character": deepcopy(dict(sheet.get("resources") or {})),
                "spell_slots": deepcopy(dict(spellcasting.get("spell_slots") or {})),
                "pact_magic": deepcopy(spellcasting.get("pact_magic")),
                "spell_points": deepcopy(spellcasting.get("spell_points")),
                "casting_economy": str(spellcasting.get("casting_economy") or "slots"),
                "hit_dice": deepcopy(dict(combat.get("hit_dice") or {})),
                "death_saves": deepcopy(dict(combat.get("death_saves") or {})),
                "exhaustion": int(combat.get("exhaustion", 0) or 0),
            }
            return {
                **deepcopy(member),
                "name": actor.name,
                "status": status,
                "level": int(progression["level"]),
                "xp": int(progression["xp"]),
                "hit_points": {
                    "current": int(effective_hp["value"]),
                    "maximum": int(effective_hp["max"]),
                    "temporary": int(hp["temp"]),
                    "conditions": sorted(conditions),
                },
                "resources": resources,
                "wallet": deepcopy(dict(sheet["inventory"]["wallet"])),
                "equipment": sorted(str(item["id"]) for item in sheet["inventory"]["items"]),
                "knowledge_scope_actor_id": actor.id,
            }

        members = [actor_projection(item) for item in manifest["party"]["members"]]
        tracked_npcs = []
        for item in manifest["npcs"]:
            actor = characters.get(str(item["actor_id"]))
            if actor.campaign_id != campaign_id:
                raise ValueError(f"playthrough NPC {actor.id!r} does not belong to this campaign")
            conditions = {str(value) for value in actor.sheet.get("conditions") or []}
            narrative_status = str(item["status"])
            tracked_npcs.append(
                {
                    **deepcopy(item),
                    "name": actor.name,
                    "status": (
                        "dead"
                        if "dead" in conditions
                        else "active"
                        if narrative_status == "dead"
                        else narrative_status
                    ),
                }
            )
        return {
            "party_members": members,
            "npcs": tracked_npcs,
            "current_scene": modules.current_scene(
                campaign_id,
                scope_id="party",
                fallback_to_party=False,
            ),
            "snapshot_dag": {
                "active_branch_id": active_branch.id,
                "head_snapshot_id": active_branch.head_snapshot_id or "",
                "nodes": snapshot_nodes,
            },
            "random_stream": {
                "algorithm": str(stream.get("algorithm") or ""),
                "seed_fingerprint": str(stream.get("seed") or "")[:16],
                "position": int(stream.get("position", 0) or 0),
            },
            "world_state": {
                "game_phase": campaign_phase(campaign.state),
                "game_time": deepcopy(dict(campaign.state.get("game_time") or {})),
                "world_time": deepcopy(dict(campaign.state.get("world_time") or {})),
                "world_effects": deepcopy(list(campaign.state.get("world_effects") or [])),
                "combat_active": bool(
                    dict(campaign.state.get("combat") or {}).get("active", False)
                ),
            },
        }

    def sync_playthrough_manifest(
        campaign_id: str,
        manifest: dict[str, Any],
    ) -> dict[str, Any]:
        updated = deepcopy(manifest)
        runtime = playthrough_runtime_projection(campaign_id, updated)
        updated["party"]["members"] = runtime["party_members"]
        updated["npcs"] = runtime["npcs"]
        updated["snapshot_dag"] = runtime["snapshot_dag"]
        updated["random_stream"] = runtime["random_stream"]
        current_scene = runtime["current_scene"]
        if current_scene is not None:
            updated["current"] = {
                **deepcopy(updated["current"]),
                "module_id": str(current_scene["module_id"]),
                "chapter_id": str(current_scene["chapter_id"]),
                "chapter_title": str(current_scene["chapter"]),
                "scene_id": str(current_scene["scene_id"]),
                "scene_title": str(current_scene["title"]),
            }
        world_state = deepcopy(updated["world_state"])
        world_state["_canonical"] = runtime["world_state"]
        updated["world_state"] = world_state
        active_members = [
            item for item in updated["party"]["members"] if item["status"] == "active"
        ]
        blocking_reviews = [
            item
            for item in updated["review_blocks"]
            if item.get("kind") != "recommended_party_size"
        ]
        if updated["status"] == "lobby" and not blocking_reviews and active_members:
            updated["status"] = "ready"
        return validate_playthrough_manifest(updated)

    def playthrough_path_value(document: Any, path: str) -> Any:
        value = document
        normalized = str(path).strip().strip("/").replace("/", ".")
        for token in (item for item in normalized.split(".") if item):
            if isinstance(value, dict):
                if token not in value:
                    raise LookupError(f"manifest verification path not found: {path}")
                value = value[token]
            elif isinstance(value, list) and token.isdigit():
                value = value[int(token)]
            else:
                raise LookupError(f"manifest verification path not found: {path}")
        return deepcopy(value)

    def compare_playthrough_value(actual: Any, operator: str, expected: Any) -> bool:
        if operator == "equals":
            return actual == expected
        if operator == "not_equals":
            return actual != expected
        if operator == "in":
            return isinstance(expected, list) and actual in expected
        if operator == "at_least":
            return actual >= expected
        if operator == "at_most":
            return actual <= expected
        if operator == "truthy":
            return bool(actual)
        raise ValueError(f"unsupported playthrough ending operator: {operator}")

    def verify_playthrough_ending(
        campaign_id: str,
        manifest: dict[str, Any],
        condition_id: str,
        branch_id: str,
    ) -> list[dict[str, Any]]:
        condition = next(
            (item for item in manifest["ending"]["conditions"] if item["id"] == condition_id),
            None,
        )
        if condition is None:
            raise LookupError(f"unknown ending condition: {condition_id}")
        campaign = campaigns.get(campaign_id)
        actor_cards = {item.id: asdict(item) for item in characters.list(campaign_id=campaign_id)}
        facts = {
            item.fact_key: asdict(item)
            for item in memories.list(
                campaign_id,
                branch_id=branch_id,
                include_inactive=True,
            )
        }
        results: list[dict[str, Any]] = []
        for check in condition["all_of"]:
            kind = str(check["kind"])
            if kind == "manifest_value":
                actual = playthrough_path_value(manifest, check["path"])
            elif kind == "campaign_state_value":
                actual = playthrough_path_value(campaign.state, check["path"])
            elif kind == "actor_value":
                actor = actor_cards.get(str(check["actor_id"]))
                if actor is None:
                    raise LookupError(f"ending actor not found: {check['actor_id']}")
                actual = playthrough_path_value(actor, check["path"])
            else:
                fact = facts.get(str(check["fact_key"]))
                if fact is None:
                    actual = None
                elif check["path"]:
                    actual = playthrough_path_value(fact, check["path"])
                else:
                    actual = fact["content"]
            passed = compare_playthrough_value(
                actual,
                str(check["operator"]),
                check.get("value"),
            )
            results.append(
                {
                    "kind": kind,
                    "path": str(check.get("path") or ""),
                    "actor_id": str(check.get("actor_id") or ""),
                    "fact_key": str(check.get("fact_key") or ""),
                    "operator": str(check["operator"]),
                    "expected": deepcopy(check.get("value")),
                    "actual": actual,
                    "passed": passed,
                }
            )
        results.append(
            {
                "kind": "runtime",
                "path": "combat",
                "operator": "not_active",
                "expected": False,
                "actual": bool(dict(campaign.state.get("combat") or {}).get("active", False)),
                "passed": not bool(dict(campaign.state.get("combat") or {}).get("active", False)),
            }
        )
        return results

    @public_tool()
    def playthrough_manifest(
        campaign_id: str,
        action: Literal[
            "get",
            "initialize",
            "replace",
            "extend_modules",
            "configure_ending",
            "sync",
            "verify_ending",
        ],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        expected_revision: int | None = None,
        branch_id: str | None = None,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Read or atomically maintain the snapshot-managed full-playthrough manifest."""
        access.require_campaign(campaign_id, principal_id, roles=CAMPAIGN_DM_ROLES)
        campaign = campaigns.get(campaign_id)
        current_manifest = dict(campaign.state.get("playthrough_manifest") or {})
        if action == "get":
            if not current_manifest:
                raise LookupError("campaign has no full-playthrough manifest")
            validated = validate_playthrough_manifest(current_manifest)
            projected = sync_playthrough_manifest(campaign_id, validated)
            validate_playthrough_source_bindings(campaign_id, projected)
            return {
                "manifest": projected,
                "runtime": playthrough_runtime_projection(campaign_id, projected),
                "campaign_revision": campaign.revision,
            }
        if expected_revision is None or not idempotency_key:
            raise ValueError(
                "expected_revision and idempotency_key are required for manifest mutations"
            )
        resolved_branch_id = require_current_branch(campaign_id, branch_id)
        request_payload = {
            "action": action,
            "payload": deepcopy(payload or {}),
        }
        scope = f"playthrough-manifest:{campaign_id}:{resolved_branch_id}:{principal_id}"
        replay = replay_idempotent(scope, idempotency_key, request_payload)
        if replay is not None:
            return replay
        if campaign.revision != expected_revision:
            raise ValueError(
                f"campaign revision conflict: expected {expected_revision}, "
                f"found {campaign.revision}"
            )
        data = facade_payload(payload)
        if action == "initialize":
            if current_manifest:
                raise ValueError("campaign already has a full-playthrough manifest")
            next_manifest = validate_playthrough_manifest(required(data, "manifest"))
            known_module_ids = {str(item["id"]) for item in modules.list(campaign_id)}
            missing = sorted(set(next_manifest["module_ids"]) - known_module_ids)
            if missing:
                raise ValueError(
                    "playthrough manifest references modules outside the campaign: "
                    + ", ".join(missing)
                )
            next_manifest = sync_playthrough_manifest(campaign_id, next_manifest)
        else:
            if not current_manifest:
                raise LookupError("campaign has no full-playthrough manifest")
            current_manifest = validate_playthrough_manifest(current_manifest)
            if action == "configure_ending":
                if current_manifest["status"] == "completed":
                    raise RuntimeError("completed playthrough ending conditions cannot be changed")
                condition = deepcopy(required(data, "condition"))
                if not isinstance(condition, dict):
                    raise ValueError("payload.condition must be an object")
                condition = validate_source_defined_ending_condition(condition)
                condition_id = str(condition.get("id") or "").strip()
                existing = next(
                    (
                        item
                        for item in current_manifest["ending"]["conditions"]
                        if item["id"] == condition_id
                    ),
                    None,
                )
                if existing is not None:
                    if existing == condition:
                        raise ValueError(f"ending condition {condition_id} is already configured")
                next_manifest = deepcopy(current_manifest)
                next_manifest["ending"]["conditions"] = [
                    condition if item["id"] == condition_id else item
                    for item in next_manifest["ending"]["conditions"]
                ]
                if existing is None:
                    next_manifest["ending"]["conditions"].append(condition)
                next_manifest = validate_playthrough_manifest(next_manifest)
            elif action == "replace":
                next_manifest = validate_playthrough_manifest(required(data, "manifest"))
                immutable = ("run_id", "campaign_line_id", "module_ids")
                if any(next_manifest[key] != current_manifest[key] for key in immutable):
                    raise ValueError(
                        "replace cannot change run_id, campaign_line_id, or module_ids"
                    )
            elif action == "extend_modules":
                next_manifest = validate_playthrough_manifest(required(data, "manifest"))
                immutable = ("run_id", "campaign_line_id")
                if any(next_manifest[key] != current_manifest[key] for key in immutable):
                    raise ValueError("extend_modules cannot change run_id or campaign_line_id")
                current_module_ids = set(current_manifest["module_ids"])
                next_module_ids = set(next_manifest["module_ids"])
                if not current_module_ids < next_module_ids:
                    raise ValueError(
                        "extend_modules must retain every module and add at least one module"
                    )
                known_module_ids = {
                    str(item["id"]) for item in modules.list(campaign_id, include_retired=True)
                }
                missing = sorted(next_module_ids - known_module_ids)
                if missing:
                    raise ValueError(
                        "playthrough manifest references modules outside the campaign: "
                        + ", ".join(missing)
                    )
            elif action == "sync":
                next_manifest = sync_playthrough_manifest(campaign_id, current_manifest)
            else:
                condition_id = str(required(data, "condition_id"))
                next_manifest = sync_playthrough_manifest(campaign_id, current_manifest)
                verification = verify_playthrough_ending(
                    campaign_id,
                    next_manifest,
                    condition_id,
                    resolved_branch_id,
                )
                next_manifest["ending"]["verification"] = verification
                if all(item["passed"] for item in verification):
                    next_manifest["ending"]["status"] = "completed"
                    next_manifest["ending"]["achieved_condition_id"] = condition_id
                    next_manifest["status"] = "completed"
                else:
                    next_manifest["ending"]["status"] = "pending"
                    next_manifest["ending"]["achieved_condition_id"] = ""
                    if next_manifest["status"] == "completed":
                        next_manifest["status"] = "in_progress"
                next_manifest = validate_playthrough_manifest(next_manifest)
        # Party resources, NPC life state, Snapshot DAG, random-stream position,
        # and the canonical world projection are owned by their runtime stores.
        # Never persist a caller's stale copy through replace/extend_modules.
        next_manifest = sync_playthrough_manifest(campaign_id, next_manifest)
        validate_playthrough_source_bindings(campaign_id, next_manifest)
        persisted_manifest = deepcopy(next_manifest)
        # Snapshot nodes are authoritative in core tables and are projected on
        # every public manifest read. Persisting the full derived DAG inside
        # campaign state makes each revision and snapshot recursively repeat
        # all prior checkpoint metadata.
        persisted_manifest["snapshot_dag"]["nodes"] = []
        next_state = validate_party_state(
            {
                **deepcopy(campaign.state),
                "playthrough_manifest": validate_playthrough_manifest(persisted_manifest),
            }
        )
        response = {
            "manifest": next_manifest,
            "runtime": playthrough_runtime_projection(campaign_id, next_manifest),
            "campaign_revision": campaign.revision + 1,
        }
        StateMutationService(storage.database).replace(
            campaign_id,
            campaign_state=next_state,
            expected_campaign_revision=expected_revision,
            operation=f"playthrough.manifest.{action}",
            actor=principal_id,
            branch_id=resolved_branch_id,
            idempotency_key=idempotency_key,
            idempotency_write=IdempotencyWrite(
                scope=scope,
                payload=request_payload,
                response=response,
            ),
        )
        return response

    @public_tool()
    def access_grant(
        scope: Literal["campaign", "actor"],
        campaign_id: str,
        principal_id: str,
        payload: dict[str, Any] | None = None,
        by_principal_id: str | None = None,
    ) -> dict[str, Any]:
        """Grant campaign membership or actor-level authority without exposing unrelated edits."""
        data = facade_payload(payload)
        if scope == "campaign":
            result = campaign_member_grant(
                campaign_id, principal_id, data.get("role", "player"), by_principal_id
            )
        else:
            allowed_fields = {"actor_id", "can_control", "can_view_private"}
            unsupported_fields = sorted(set(data) - allowed_fields)
            permission_fields = {"can_control", "can_view_private"} & set(data)
            if unsupported_fields or not permission_fields:
                details = []
                if unsupported_fields:
                    details.append("unsupported fields: " + ", ".join(unsupported_fields))
                if not permission_fields:
                    details.append("provide can_control and/or can_view_private")
                raise ValueError("actor access grant has " + "; ".join(details))
            for field in permission_fields:
                if not isinstance(data[field], bool):
                    raise ValueError(f"actor access grant {field} must be a boolean")
            result = actor_grant(
                campaign_id,
                principal_id,
                required(data, "actor_id"),
                data.get("can_control"),
                data.get("can_view_private"),
                by_principal_id,
            )
        return facade_result(scope, result)

