    @public_tool()
    def state_revision(
        campaign_id: str,
        action: Literal["history", "receipt", "undo", "redo"],
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
        idempotency_key: str | None = None,
    ) -> dict[str, Any]:
        """Read revision history or perform guarded undo/redo."""
        data = facade_payload(payload)
        if action == "history":
            result = state_history(campaign_id, data.get("limit", 100), principal_id)
        elif action == "receipt":
            receipt_key = str(required(data, "idempotency_key")).strip()
            if not receipt_key:
                raise ValueError("idempotency_key is required")
            result = state_idempotency_receipt(
                campaign_id,
                receipt_key,
                data.get("branch_id"),
                principal_id,
            )
        elif action == "undo":
            result = state_undo(
                campaign_id, principal_id, data.get("expected_history_sequence"), idempotency_key
            )
        else:
            result = state_redo(
                campaign_id, principal_id, data.get("expected_history_sequence"), idempotency_key
            )
        return facade_result(action, result)

    @public_tool()
    def combat_query(
        campaign_id: str,
        view: Literal[
            "status",
            "available_actions",
            "reactions",
            "render",
            "transaction_history",
            "transaction_receipt",
        ] = "status",
        actor_id: str | None = None,
        payload: dict[str, Any] | None = None,
        principal_id: str = LOCAL_SYSTEM_PRINCIPAL_ID,
    ) -> dict[str, Any]:
        """Read combat state, render a safe snapshot, or inspect DM-only transactions."""
        data = facade_payload(payload)
        if view == "status":
            result = combat_status(campaign_id, principal_id)
        elif view == "available_actions":
            result = combat_available_actions(
                campaign_id, required({"actor_id": actor_id}, "actor_id"), principal_id
            )
        elif view == "reactions":
            result = combat_reactions(
                campaign_id, required({"actor_id": actor_id}, "actor_id"), principal_id
            )
        elif view == "render":
            audience_projection = str(data.get("audience_projection") or "caller")
            if audience_projection not in {"caller", "party_public"}:
                raise ValueError("audience_projection must be caller or party_public")
            return facade_render_result(
                render_combat_snapshot(
                    campaign_id,
                    principal_id,
                    audience_projection,
                )
            )
        elif view == "transaction_history":
            result = state_history(campaign_id, data.get("limit", 100), principal_id)
        else:
            receipt_key = str(required(data, "idempotency_key")).strip()
            if not receipt_key:
                raise ValueError("idempotency_key is required")
            result = state_idempotency_receipt(
                campaign_id,
                receipt_key,
                data.get("branch_id"),
                principal_id,
            )
        return facade_result(view, result)

